// Nome antigo mantido: import.js e o parser de linguagem natural o citam, e
// quebrar a referência por estética não paga o risco.
const CATEGORY_RULES = BUILTIN_CATEGORY_RULES;

// ------------------------------------------------------------------------------
// FORMA DO DADO
// ------------------------------------------------------------------------------
function defaultCategoryRules() {
  return { custom: [], builtin: {} };
}

function clampRuleWeight(n) {
  const v = Math.round(Number(n));
  if (!Number.isFinite(v)) return RULE_WEIGHT_DEFAULT;
  return Math.max(RULE_WEIGHT_MIN, Math.min(RULE_WEIGHT_MAX, v));
}

// Saneia o que veio do disco ou de um backup. Regra sem padrão ou sem categoria
// é descartada: uma regra que não casa nada só ocuparia espaço na tela.
function normalizeCategoryRules(raw) {
  const src = raw && typeof raw === "object" ? raw : {};
  const seen = new Set();
  const custom = (Array.isArray(src.custom) ? src.custom : [])
    .map((r) => {
      if (!r || typeof r !== "object") return null;
      const pattern = String(r.pattern == null ? "" : r.pattern).trim().slice(0, RULE_PATTERN_MAX);
      const rawCategoryId = String(r.categoryId == null ? "" : r.categoryId).trim();
      if (!pattern || !rawCategoryId) return null;
      const categoryId = typeof normalizeRecordId === "function"
        ? normalizeRecordId(rawCategoryId, "category")
        : (/^[A-Za-z0-9][A-Za-z0-9:_-]{0,79}$/.test(rawCategoryId) ? rawCategoryId : "outros");
      const rawId = typeof r.id === "string" && r.id ? r.id : uid();
      const id = typeof normalizeRecordId === "function"
        ? normalizeRecordId(rawId, "rule")
        : (/^[A-Za-z0-9][A-Za-z0-9:_-]{0,79}$/.test(rawId) ? rawId.slice(0, 40) : uid());
      if (seen.has(id)) return null;
      seen.add(id);
      return {
        id,
        pattern,
        matchType: isRuleMatchType(r.matchType) ? r.matchType : "contains",
        categoryId,
        weight: clampRuleWeight(r.weight),
        enabled: r.enabled !== false,
        createdAt: typeof r.createdAt === "string" ? r.createdAt : todayIso(),
        updatedAt: typeof r.updatedAt === "string" ? r.updatedAt : todayIso(),
      };
    })
    .filter(Boolean)
    .slice(0, 200);

  const builtin = {};
  const overrides = src.builtin && typeof src.builtin === "object" ? src.builtin : {};
  BUILTIN_CATEGORY_RULES.forEach((rule) => {
    const o = overrides[rule.id];
    if (!o || typeof o !== "object") return;
    const enabled = o.enabled !== false;
    const rawCategoryId = typeof o.categoryId === "string" && o.categoryId ? o.categoryId : null;
    const categoryId = rawCategoryId && typeof normalizeRecordId === "function"
      ? normalizeRecordId(rawCategoryId, "category")
      : rawCategoryId;
    // Só gravamos a DIFERENÇA. Um override que devolve o padrão é ruído.
    if (enabled && (!categoryId || categoryId === rule.categoryId)) return;
    builtin[rule.id] = { enabled, categoryId: categoryId && categoryId !== rule.categoryId ? categoryId : null };
  });

  return { custom, builtin };
}

// União das regras de dois lados (usado pelo "mesclar" do restore de backup).
// Conflito de id resolve a favor do aparelho: quem está restaurando enxerga a
// própria lista na tela e não deveria vê-la mudar sem pedir. O que só existe no
// arquivo entra; o que existe nos dois fica como está aqui.
function mergeCategoryRules(currentRaw, incomingRaw) {
  const current = normalizeCategoryRules(currentRaw);
  const incoming = normalizeCategoryRules(incomingRaw);
  const byId = new Map();
  incoming.custom.forEach((r) => byId.set(r.id, r));
  current.custom.forEach((r) => byId.set(r.id, r));

  // Padrão idêntico vindo dos dois lados com ids diferentes viraria regra
  // duplicada silenciosa; o usuário veria a mesma linha duas vezes e não teria
  // como saber qual apagar.
  const seenPattern = new Set();
  const custom = Array.from(byId.values()).filter((r) => {
    const key = r.matchType + "|" + normalizeText(r.pattern) + "|" + r.categoryId;
    if (seenPattern.has(key)) return false;
    seenPattern.add(key);
    return true;
  });

  return normalizeCategoryRules({ custom, builtin: Object.assign({}, incoming.builtin, current.builtin) });
}

function makeCategoryRule(input) {
  const now = new Date().toISOString().slice(0, 10);
  return {
    id: (input && input.id) || uid(),
    pattern: String((input && input.pattern) || "").trim().slice(0, RULE_PATTERN_MAX),
    matchType: isRuleMatchType(input && input.matchType) ? input.matchType : "contains",
    categoryId: String((input && input.categoryId) || "").trim(),
    weight: clampRuleWeight(input && input.weight),
    enabled: !(input && input.enabled === false),
    createdAt: (input && input.createdAt) || now,
    updatedAt: now,
  };
}

// ------------------------------------------------------------------------------
// COMPILAÇÃO DO PADRÃO
// ------------------------------------------------------------------------------
// O texto comparado já passou por normalizeText (minúsculo, sem acento), então o
// padrão precisa passar pela MESMA normalização; do contrário "Padaria" nunca
// casaria com "padaria" e o usuário culparia o app, com razão.
//
// Um Regex inválido não derruba nada: devolve `{ ok:false, error }`. A tela usa
// isso para mostrar o problema na hora, e o motor simplesmente pula a regra.
function escapeForRegex(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function compileRulePattern(pattern, matchType) {
  const raw = String(pattern == null ? "" : pattern).trim();
  if (!raw) return { ok: false, re: null, error: "Escreva o texto que a regra deve procurar." };

  if (matchType === "regex") {
    try {
      // Sem normalizar: quem escreve Regex está no controle da própria sintaxe.
      // Só forçamos minúsculas, porque o texto comparado sempre chega assim.
      return { ok: true, re: new RegExp(raw.toLowerCase()), error: null };
    } catch (e) {
      return { ok: false, re: null, error: "Expressão regular inválida: " + (e && e.message ? e.message : "erro de sintaxe") };
    }
  }

  const norm = normalizeText(raw);
  if (!norm) return { ok: false, re: null, error: "Escreva o texto que a regra deve procurar." };
  const esc = escapeForRegex(norm);
  try {
    if (matchType === "starts") return { ok: true, re: new RegExp("^" + esc), error: null };
    if (matchType === "word") return { ok: true, re: new RegExp("(^|[^a-z0-9])" + esc + "([^a-z0-9]|$)"), error: null };
    return { ok: true, re: new RegExp(esc), error: null };
  } catch (e) {
    return { ok: false, re: null, error: "Não foi possível montar a regra com esse texto." };
  }
}

// ------------------------------------------------------------------------------
// MONTAGEM DA LISTA EFETIVA
// ------------------------------------------------------------------------------
// Devolve as regras que realmente valem AGORA, já com override aplicado, já
// compiladas e já filtradas por categoria existente. Uma regra que aponta para
// uma categoria apagada é mantida no dado (o usuário pode recriar a categoria)
// mas fica fora do motor; categorizar para um id fantasma é pior que não
// categorizar.
function compileCategoryRules(data) {
  const cfg = normalizeCategoryRules(data && data.categoryRules);
  const categories = (data && Array.isArray(data.categories)) ? data.categories : [];
  const has = (id) => categories.some((c) => c.id === id);
  const out = [];

  cfg.custom.forEach((r) => {
    if (!r.enabled) return;
    const c = compileRulePattern(r.pattern, r.matchType);
    if (!c.ok) return;
    if (categories.length > 0 && !has(r.categoryId)) return;
    out.push({ id: r.id, source: "custom", label: r.pattern, categoryId: r.categoryId, weight: r.weight, re: c.re });
  });

  BUILTIN_CATEGORY_RULES.forEach((rule) => {
    const o = cfg.builtin[rule.id];
    if (o && o.enabled === false) return;
    const categoryId = (o && o.categoryId) || rule.categoryId;
    out.push({ id: rule.id, source: "builtin", label: rule.label, categoryId, weight: rule.weight, re: rule.re });
  });

  return out;
}

// Vence o maior peso; empate vence a regra do usuário; empate ainda, a primeira.
// A ordem importa e é estável: a mesma descrição sempre cai na mesma categoria,
// senão a revisão do importador vira loteria.
function matchCategoryRules(compiled, normalizedText) {
  if (!normalizedText) return null;
  let best = null;
  for (const rule of compiled) {
    let hit = false;
    try { hit = rule.re.test(normalizedText); } catch (e) { hit = false; }
    if (!hit) continue;
    if (!best) { best = rule; continue; }
    if (rule.weight > best.weight) { best = rule; continue; }
    if (rule.weight === best.weight && rule.source === "custom" && best.source === "builtin") best = rule;
  }
  return best;
}

// ------------------------------------------------------------------------------
// O QUE A LINHA É, ANTES DE QUAL CATEGORIA ELA TEM
// ------------------------------------------------------------------------------
// Fatura de cartão não é extrato de conta, e tratar as duas como a mesma lista
// de "entradas e saídas" produz um erro caro: na fatura do Nubank, o pagamento
// que você fez no mês passado aparece como CRÉDITO, com a descrição "Pagamento
// recebido". Lido como número positivo, o aplicativo registra receita; o mês
// fecha com uma entrada que nunca existiu, o saldo mente, a taxa de poupança
// mente e o Score sobe por causa de uma dívida paga.
//
// A mesma fatura traz "Valor pendente do mês anterior", que é o saldo rolado:
// aquele gasto já foi contado no mês em que aconteceu, e importar de novo
// cobraria a pessoa duas vezes pela mesma compra.
//
// Nenhuma das duas linhas é lixo (elas explicam a fatura), então o motor não as
// esconde: ele as MARCA, a tela de revisão desmarca por padrão e escreve o
// porquê. Quem discordar tem uma caixa de seleção do lado.
const STATEMENT_ROW_ROLES = [
  {
    id: "card-payment",
    // Só no crédito. No extrato da CONTA, "pagamento de fatura" é dinheiro
    // saindo de verdade e precisa continuar entrando como saída.
    appliesTo: "income",
    label: "Pagamento de fatura",
    detail: "É a fatura do mês passado sendo paga, não dinheiro entrando.",
    re: /\bpagamento (?:recebido|de fatura|da fatura|fatura|efetuado|realizado)\b|\bpag(?:to|amento)? ?(?:de )?fatura\b|\bfatura paga\b|\bcredito de pagamento\b|\bpagamento em \d{2}\/\d{2}\b/,
  },
  {
    id: "carryover",
    appliesTo: "any",
    label: "Saldo da fatura anterior",
    detail: "Gasto do mês passado sendo rolado; já foi contado quando aconteceu.",
    re: /\bvalor pendente do mes anterior\b|\bsaldo (?:restante|anterior|em aberto|remanescente)(?: da fatura)?\b|\b(?:total|saldo) da fatura anterior\b|\bfatura anterior\b|\bdivida do mes anterior\b|\bsaldo em atraso\b/,
  },
];

// Devolve o papel da linha (ou null). `skip` é a recomendação de não importar;
// a decisão final é sempre da pessoa, na tela de revisão.
function classifyStatementRow(description, type) {
  const text = normalizeText(description);
  if (!text) return null;
  for (const role of STATEMENT_ROW_ROLES) {
    if (role.appliesTo !== "any" && role.appliesTo !== type) continue;
    let hit = false;
    try { hit = role.re.test(text); } catch (e) { hit = false; }
    if (hit) return { id: role.id, label: role.label, detail: role.detail, skip: true };
  }
  return null;
}

// ------------------------------------------------------------------------------
// NOME DO ESTABELECIMENTO DENTRO DO RUÍDO DO BANCO
// ------------------------------------------------------------------------------
// O banco não escreve "Padaria do Zé": escreve "COMPRA CARTAO 5678 PAG*PADARIA
// DO ZE 12/08 SAO PAULO BR". Duas linhas do mesmo lugar quase nunca chegam
// iguais, porque a data, a maquininha e a cidade mudam.
//
// Esta função extrai o miolo: tira o verbo do banco, o prefixo da maquininha,
// a máscara do cartão, a parcela, a data e a UF do fim. É o que permite dizer
// "isto é o mesmo estabelecimento de novembro" e reaproveitar a categoria que a
// pessoa escolheu naquela vez.
const STATEMENT_VERB_RE = /^(?:compra(?: com)?(?: cartao| debito| credito| aprovada)?|pagamento(?: de)?|pagto|pgto|pag|debito automatico|deb aut|dda|saque|transferencia(?: enviada| recebida)?|transf|ted|doc|pix(?: enviado| recebido| qrs| qr| cp)?|cip|recebimento|credito em conta|deposito|boleto|liquidacao|compras)\b[\s:-]*/;
// A maquininha aparece grudada no nome ("PAG*PADARIA", "IFD*IFOOD") e nem
// sempre no começo: o banco costuma pôr a máscara do cartão antes dela.
const STATEMENT_MACHINE_RE = /\b[a-z0-9]{2,6}\*\s?/g;
const STATEMENT_CARD_MASK_RE = /^\d{3,6}\b/;
// Siglas que todo extrato repete e que nunca são o nome do estabelecimento.
const STATEMENT_STOPWORD_RE = /\b(?:cp|cnpj|cpf|ltda|epp|eireli|me|sa|br|bra|ec|com|comercio de|servicos de)\b/g;
const STATEMENT_TAIL_RE = [
  /\*{2,}\s?\d+/g,                                   // máscara do cartão
  /\bfinal\s+\d{3,6}\b/g,
  /\bcartao\s+\d{3,6}\b/g,
  /\bparcela\s+\d{1,2}\s?\/\s?\d{1,2}\b/g,
  /\b\d{1,2}\s?\/\s?\d{1,2}(?:\s?\/\s?\d{2,4})?\b/g, // parcela ou data solta
  /\bref\.?\s?\d+\b/g,
  /\b\d{6,}\b/g,                                     // identificadores longos
];
const STATEMENT_UF_RE = /\s(?:ac|al|ap|am|ba|ce|df|es|go|ma|mt|ms|mg|pa|pb|pr|pe|pi|rj|rn|rs|ro|rr|sc|sp|se|to|br|bra)$/;

function statementMerchantCore(description) {
  let text = normalizeText(description);
  if (!text) return "";
  // Os verbos empilham ("PAGAMENTO PIX ENVIADO ..."); por isso o laço.
  for (let i = 0; i < 3; i++) {
    const stripped = text.replace(STATEMENT_VERB_RE, "").replace(STATEMENT_CARD_MASK_RE, "").trim();
    if (stripped === text) break;
    text = stripped;
  }
  text = text.replace(STATEMENT_MACHINE_RE, " ").replace(STATEMENT_STOPWORD_RE, " ");
  STATEMENT_TAIL_RE.forEach((re) => { text = text.replace(re, " "); });
  text = text.replace(/[^a-z0-9 ]+/g, " ").replace(/\s+/g, " ").trim();
  for (let i = 0; i < 2; i++) text = text.replace(STATEMENT_UF_RE, "").trim();
  // Sobrou nada (a linha era só verbo e número): devolve o texto original
  // normalizado, que ao menos é estável para comparar com ele mesmo.
  return text || normalizeText(description);
}

// ------------------------------------------------------------------------------
// MEMÓRIA: O QUE A PESSOA JÁ CLASSIFICOU À MÃO
// ------------------------------------------------------------------------------
// O dicionário de fábrica sabe de marcas nacionais. Ele nunca vai saber que
// "MERC BOM JESUS" é o mercado da esquina de quem mora ali. Mas o histórico
// sabe: a pessoa já corrigiu essa linha uma vez.
//
// A memória vale mais quando a categoria foi ESCOLHIDA (lançamento manual ou
// categoria editada depois) do que quando ela mesma foi um palpite do
// aplicativo; senão o motor só repetiria o próprio erro com mais confiança.
// Por isso o voto manual pesa 4 e o automático pesa 1.
//
// O índice é construído uma vez por versão dos dados. `setData` sempre cria um
// array novo de transações, então o WeakMap invalida sozinho quando algo muda,
// e uma importação de 300 linhas não varre o histórico 300 vezes.
const __CATEGORY_MEMORY_CACHE = typeof WeakMap === "function" ? new WeakMap() : null;
const CATEGORY_MEMORY_MIN_CORE = 4;

function transactionCategoryChosenByUser(t) {
  if (!t) return false;
  if (t.source === "manual" || t.source === "nlp") return true;
  return (Array.isArray(t.changeLog) ? t.changeLog : []).some((entry) => (
    entry && entry.action === "edited" && Array.isArray(entry.fields) && entry.fields.includes("categoryId")
  ));
}

function buildCategoryMemory(transactions) {
  const memory = new Map();
  (Array.isArray(transactions) ? transactions : []).forEach((t) => {
    if (!t || t.type !== "expense") return;
    const categoryId = t.categoryId;
    if (!categoryId || categoryId === "outros") return;
    const core = statementMerchantCore(t.description);
    if (core.length < CATEGORY_MEMORY_MIN_CORE) return;
    const manual = transactionCategoryChosenByUser(t);
    const votes = memory.get(core) || new Map();
    const vote = votes.get(categoryId) || { weight: 0, manual: false, count: 0 };
    vote.weight += manual ? 4 : 1;
    vote.count += 1;
    vote.manual = vote.manual || manual;
    votes.set(categoryId, vote);
    memory.set(core, votes);
  });
  return memory;
}

function categoryMemoryOf(data) {
  const transactions = data && Array.isArray(data.transactions) ? data.transactions : null;
  if (!transactions) return null;
  if (!__CATEGORY_MEMORY_CACHE) return buildCategoryMemory(transactions);
  const cached = __CATEGORY_MEMORY_CACHE.get(transactions);
  if (cached) return cached;
  const memory = buildCategoryMemory(transactions);
  __CATEGORY_MEMORY_CACHE.set(transactions, memory);
  return memory;
}

// Devolve { categoryId, manual, count } do estabelecimento, ou null. Empate
// entre duas categorias devolve a de maior peso; empate real devolve null, que
// é melhor do que escolher no par ou ímpar.
function recallCategoryFromMemory(data, description) {
  const memory = categoryMemoryOf(data);
  if (!memory || memory.size === 0) return null;
  const core = statementMerchantCore(description);
  if (core.length < CATEGORY_MEMORY_MIN_CORE) return null;
  const votes = memory.get(core);
  if (!votes) return null;
  let best = null;
  let tie = false;
  votes.forEach((vote, categoryId) => {
    if (!best || vote.weight > best.weight) { best = { categoryId, ...vote }; tie = false; return; }
    if (vote.weight === best.weight) tie = true;
  });
  if (!best || tie) return null;
  const categories = (data && Array.isArray(data.categories)) ? data.categories : [];
  if (categories.length && !categories.some((c) => c.id === best.categoryId)) return null;
  return best;
}

// ------------------------------------------------------------------------------
// APLICAR ÀS TRANSAÇÕES JÁ EXISTENTES
// ------------------------------------------------------------------------------
// Criar uma regra e ver o histórico continuar errado é a queixa óbvia. Mas
// recategorizar tudo em silêncio é pior: apagaria correções feitas à mão.
//
// O meio-termo: só mexemos em despesas que estão na categoria de sobra
// ("Outros"), ou seja, exatamente naquelas em que ninguém decidiu nada. E o
// resultado é sempre mostrado ANTES de gravar.
function previewRuleApplication(data, opts) {
  const options = opts || {};
  const onlyFallback = options.onlyFallback !== false;
  const fallbackId = (data.categories || []).some((c) => c.id === "outros") ? "outros" : null;
  const compiled = compileCategoryRules(data);
  const changes = [];

  (data.transactions || []).forEach((t) => {
    if (t.type !== "expense") return;
    if (onlyFallback && t.categoryId !== fallbackId) return;
    const best = matchCategoryRules(compiled, normalizeText(t.description || ""));
    if (!best || best.categoryId === t.categoryId) return;
    changes.push({ id: t.id, description: t.description, from: t.categoryId, to: best.categoryId, ruleId: best.id, ruleLabel: best.label });
  });

  const byCategory = {};
  changes.forEach((c) => { byCategory[c.to] = (byCategory[c.to] || 0) + 1; });
  return { changes, count: changes.length, byCategory, scanned: (data.transactions || []).filter((t) => t.type === "expense").length };
}

function applyRulesToTransactions(data, changes) {
  if (!changes || changes.length === 0) return data;
  const map = {};
  changes.forEach((c) => { map[c.id] = c.to; });
  const stamp = new Date().toISOString();
  return {
    ...data,
    transactions: data.transactions.map((t) => (
      map[t.id] ? { ...t, categoryId: map[t.id], updatedAt: stamp } : t
    )),
  };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    BUILTIN_CATEGORY_RULES, CATEGORY_RULES, RULE_MATCH_TYPES,
    RULE_WEIGHT_MIN, RULE_WEIGHT_MAX, RULE_WEIGHT_DEFAULT,
    defaultCategoryRules, normalizeCategoryRules, makeCategoryRule,
    compileRulePattern, compileCategoryRules, matchCategoryRules, mergeCategoryRules,
    previewRuleApplication, applyRulesToTransactions,
    STATEMENT_ROW_ROLES, classifyStatementRow, statementMerchantCore,
    buildCategoryMemory, recallCategoryFromMemory, transactionCategoryChosenByUser,
  };
}

// source: js/layout.js
// layout.js; quais cartões aparecem no Início, e em que ordem (motor puro)
// ------------------------------------------------------------------------------
// O dashboard cresceu para vinte cartões. Vinte cartões servem bem a alguém que
// usa tudo; dívidas, carteira, conquistas, assinaturas; e sepultam a
// informação de quem só quer saber quanto sobrou este mês. A resposta não é
// cortar cartão: é deixar cada pessoa escolher.
//
// O registro abaixo é a única lista dos cartões do Início. `screens/dashboard.js`
// monta a tela a partir dela; nada é chamado direto. O preço é ter de registrar
// cartão novo aqui; e é justamente esse o ponto: um cartão que não passa pelo
// registro não pode ser desligado pelo usuário, e um cartão que não pode ser
// desligado é o problema que este arquivo existe para resolver.
//
// `monthly: true` marca o que só faz sentido no mês corrente (previsão, ritmo,
// pendências). Esses cartões somem sozinhos ao navegar para um mês passado, e a
// tela de personalização diz isso em vez de deixar o usuário achar que quebrou.
"use strict";

const DASHBOARD_CARDS = [
  { id: "hero",           label: "Saldo e resumo do mês",     hint: "Saldo em conta, receitas, despesas e economia.", locked: true },
  { id: "score",          label: "Score financeiro",          hint: "Nota de 0 a 100 com os pilares que a explicam." },
  { id: "networth",       label: "Patrimônio",                hint: "Total, composição e evolução dos últimos 6 meses." },
  { id: "reserve",        label: "Reserva de emergência",     hint: "Quantos meses de despesa a reserva já cobre." },
  { id: "goal",           label: "Meta em destaque",          hint: "A meta ativa mais próxima do prazo." },
  { id: "bills",          label: "Próximas contas",           hint: "O que vence nos próximos 30 dias.", monthly: true },
  { id: "forecast",       label: "Previsão de caixa",         hint: "Para onde o saldo caminha nas próximas semanas.", monthly: true },
  { id: "summary",        label: "Resumo inteligente",        hint: "Leitura automática dos números do mês." },
  { id: "quickEntry",     label: "Lançamento rápido",         hint: "Campo de texto livre para registrar um gasto.", monthly: true },
  { id: "advisor",        label: "Conselheiro",               hint: "Recomendações priorizadas a partir do seu mês.", monthly: true },
  { id: "assistant",      label: "Assistente financeiro",     hint: "Alertas automáticos sobre padrões de gasto.", monthly: true },
  { id: "gamification",   label: "Conquistas e nível",        hint: "Progresso das medalhas do app.", monthly: true },
  { id: "budgetHealth",   label: "Saúde financeira do mês",   hint: "Renda, fixos, esporádicos e quanto ainda cabe por dia." },
  { id: "categoryBudgets", label: "Orçamentos por categoria", hint: "Barras de consumo dos tetos que você definiu." },
  { id: "budgetSplit",    label: "Regra de orçamento",        hint: "Necessidades, Desejos e Futuro contra a sua renda." },
  { id: "creditLimit",    label: "Fatura do cartão",          hint: "Quanto já comprometeu do teto que você definiu.", monthly: true },
  { id: "leaks",          label: "Vazamentos silenciosos",    hint: "Gastos pequenos que se somam sem aparecer.", monthly: true },
  { id: "subscriptions",  label: "Assinaturas",               hint: "Cobranças recorrentes detectadas no histórico.", monthly: true },
  { id: "breakdown",      label: "Para onde foi o dinheiro",  hint: "Distribuição das despesas por categoria." },
  { id: "recent",         label: "Últimos lançamentos",       hint: "Os 6 registros mais recentes." },
];

const DASHBOARD_CARD_IDS = DASHBOARD_CARDS.map((c) => c.id);

const DASHBOARD_FOCUS_OPTIONS = [
  { id: "month", label: "Organizar o mês", hint: "Saldo, contas, orçamento e lançamentos.", icon: "calendar" },
  { id: "debt", label: "Sair das dívidas", hint: "Dívidas, caixa disponível e próximos compromissos.", icon: "arrowDownRight" },
  { id: "reserve", label: "Montar reserva", hint: "Reserva, economia mensal e meta em destaque.", icon: "shieldCheck" },
  { id: "purchase", label: "Planejar uma compra", hint: "Meta, previsão de caixa e capacidade mensal.", icon: "target" },
  { id: "wealth", label: "Acompanhar patrimônio", hint: "Patrimônio, carteira, score e evolução.", icon: "trendUp" },
];

const DASHBOARD_FOCUS_ORDER = {
  month: ["hero", "bills", "budgetHealth", "categoryBudgets", "budgetSplit", "forecast", "recent", "breakdown", "summary", "quickEntry"],
  debt: ["hero", "advisor", "bills", "forecast", "budgetHealth", "creditLimit", "recent", "summary", "leaks"],
  reserve: ["hero", "reserve", "goal", "budgetHealth", "budgetSplit", "forecast", "advisor", "recent", "breakdown"],
  purchase: ["hero", "goal", "forecast", "budgetHealth", "budgetSplit", "advisor", "recent", "breakdown", "summary"],
  wealth: ["hero", "networth", "score", "reserve", "goal", "breakdown", "summary", "advisor", "recent"],
};

function normalizeDashboardFocus(value) {
  return DASHBOARD_FOCUS_OPTIONS.some((option) => option.id === value) ? value : "month";
}

function dashboardOrderForFocus(focus) {
  const preferred = DASHBOARD_FOCUS_ORDER[normalizeDashboardFocus(focus)] || [];
  return preferred.concat(DASHBOARD_CARD_IDS.filter((id) => preferred.indexOf(id) === -1));
}

function applyDashboardFocus(layout, focus) {
  const current = normalizeDashboardLayout(layout);
  return { order: dashboardOrderForFocus(focus), hidden: current.hidden, pinned: current.pinned };
}

function dashboardCardById(id) {
  return DASHBOARD_CARDS.find((c) => c.id === id) || null;
}

function defaultDashboardLayout() {
  return { order: DASHBOARD_CARD_IDS.slice(), hidden: [], pinned: [] };
}

function isDashboardStarting(data) {
  const d = data && typeof data === "object" ? data : {};
  return (Array.isArray(d.transactions) ? d.transactions.length : 0) === 0
    && (Array.isArray(d.goals) ? d.goals.length : 0) === 0
    && (Array.isArray(d.assets) ? d.assets.length : 0) === 0;
}

// Um cartão sem dados não informa nada e ainda empurra o próximo passo para
// baixo. Esta camada não altera a personalização salva: apenas espera o assunto
// existir para mostrar o cartão na posição escolhida pela pessoa.
function isDashboardCardRelevant(data, id) {
  if (!data || typeof data !== "object" || id === "hero") return true;
  const txs = Array.isArray(data.transactions) ? data.transactions : [];
  const goals = Array.isArray(data.goals) ? data.goals : [];
  const assets = Array.isArray(data.assets) ? data.assets : [];
  const accounts = Array.isArray(data.accounts) ? data.accounts : [];
  const cards = Array.isArray(data.creditCards) ? data.creditCards : [];
  const categories = Array.isArray(data.categories) ? data.categories : [];
  const expenses = txs.filter((t) => t && t.type === "expense");
  const hasRecurring = txs.some((t) => t && (t.recurring || t.recurringId || t.installmentGroupId));
  const hasDebt = assets.some((a) => a && (a.kind === "liability" || a.class === "divida"));
  const hasHistory = txs.length > 0;

  switch (id) {
    case "score": return txs.length >= 3;
    case "networth": return hasHistory || goals.length > 0 || assets.length > 0;
    case "reserve": return hasHistory || goals.some((g) => g && (g.id === data.emergencyGoalId || g.type === "emergency"));
    case "goal": return goals.some((g) => g && !g.done && Number(g.current) < Number(g.target));
    case "bills": return hasRecurring;
    case "forecast": return txs.length >= 2;
    case "summary": return txs.length >= 3;
    case "quickEntry": return hasHistory;
    case "advisor": return txs.length >= 3 || hasDebt;
    case "assistant": return txs.length >= 5;
    case "gamification": return !!(data.achievements && data.achievements.enabled);
    case "budgetHealth": return hasHistory && Number(data.monthlyIncome) > 0;
    case "categoryBudgets": return categories.some((c) => c && Number(c.budget) > 0);
    case "budgetSplit": return hasHistory && Number(data.monthlyIncome) > 0;
    case "creditLimit": return Number(data.creditCardLimit) > 0 || cards.length > 0;
    case "leaks": return expenses.length >= 10;
    case "subscriptions": return hasRecurring;
    case "breakdown": return expenses.length > 0;
    case "recent": return hasHistory;
    default: return accounts.length > 0 || hasHistory;
  }
}

// Reconcilia o que está gravado com o registro atual. Duas situações reais:
//
//   • cartão novo numa versão nova do app; ele NÃO vai para o fim da lista.
//     Entra na posição que ocupa no registro, entre os vizinhos que o autor
//     escolheu. Empurrar novidade para o rodapé é a forma mais silenciosa de
//     nunca ser vista.
//   • cartão removido do app; o id some da ordem e da lista de ocultos, em vez
//     de virar um item fantasma na tela de personalização.
function normalizeDashboardLayout(raw) {
  const src = raw && typeof raw === "object" ? raw : {};
  const known = new Set(DASHBOARD_CARD_IDS);
  const seen = new Set();
  const order = (Array.isArray(src.order) ? src.order : [])
    .filter((id) => typeof id === "string" && known.has(id) && !seen.has(id) && (seen.add(id), true));

  DASHBOARD_CARD_IDS.forEach((id, defaultIndex) => {
    if (order.indexOf(id) !== -1) return;
    order.splice(Math.min(defaultIndex, order.length), 0, id);
  });

  const hidden = (Array.isArray(src.hidden) ? src.hidden : [])
    .filter((id) => typeof id === "string" && known.has(id))
    .filter((id) => {
      const card = dashboardCardById(id);
      return card && !card.locked;   // um cartão fixo não pode ser escondido nem por backup adulterado
    });

  const pinned = (Array.isArray(src.pinned) ? src.pinned : [])
    .filter((id) => typeof id === "string" && known.has(id))
    .filter((id) => {
      const card = dashboardCardById(id);
      return card && !card.locked && hidden.indexOf(id) === -1;
    });

  return { order, hidden: Array.from(new Set(hidden)), pinned: Array.from(new Set(pinned)) };
}

function isDashboardCardVisible(layout, id) {
  return normalizeDashboardLayout(layout).hidden.indexOf(id) === -1;
}

function toggleDashboardCard(layout, id) {
  const l = normalizeDashboardLayout(layout);
  const card = dashboardCardById(id);
  if (!card || card.locked) return l;
  const i = l.hidden.indexOf(id);
  const hidden = i === -1 ? l.hidden.concat([id]) : l.hidden.filter((x) => x !== id);
  const pinned = hidden.indexOf(id) !== -1 ? l.pinned.filter((x) => x !== id) : l.pinned;
  return { order: l.order, hidden, pinned };
}

function setDashboardCardVisibility(layout, id, visible, data) {
  const l = normalizeDashboardLayout(layout);
  const card = dashboardCardById(id);
  if (!card || card.locked) return l;
  if (!visible) {
    return {
      order: l.order,
      hidden: Array.from(new Set(l.hidden.concat([id]))),
      pinned: l.pinned.filter((x) => x !== id),
    };
  }
  const relevant = isDashboardCardRelevant(data, id);
  return {
    order: l.order,
    hidden: l.hidden.filter((x) => x !== id),
    pinned: relevant ? l.pinned.filter((x) => x !== id) : Array.from(new Set(l.pinned.concat([id]))),
  };
}

// Move de uma posição na ordem completa (não só entre os visíveis): reordenar
// olhando apenas os visíveis faria a posição de um cartão oculto mudar sozinha
// quando ele voltasse a aparecer.
function moveDashboardCard(layout, id, direction) {
  const l = normalizeDashboardLayout(layout);
  const i = l.order.indexOf(id);
  if (i === -1) return l;
  const j = direction < 0 ? i - 1 : i + 1;
  if (j < 0 || j >= l.order.length) return l;
  const order = l.order.slice();
  order[i] = l.order[j];
  order[j] = l.order[i];
  return { order, hidden: l.hidden, pinned: l.pinned };
}

// A lista pronta para a tela: na ordem escolhida, sem os ocultos e sem os que
// não valem para o mês visitado.
function visibleDashboardCards(layout, opts) {
  const isCurrentMonth = !(opts && opts.isCurrentMonth === false);
  const data = opts && opts.data;
  const l = normalizeDashboardLayout(layout);
  return l.order
    .map(dashboardCardById)
    .filter(Boolean)
    .filter((c) => l.hidden.indexOf(c.id) === -1)
    .filter((c) => (c.monthly ? isCurrentMonth : true))
    .filter((c) => isDashboardCardRelevant(data, c.id) || l.pinned.indexOf(c.id) !== -1);
}

function dashboardLayoutCounts(layout, opts) {
  const l = normalizeDashboardLayout(layout);
  const effective = opts ? visibleDashboardCards(l, opts).length : DASHBOARD_CARDS.length - l.hidden.length;
  return { total: DASHBOARD_CARDS.length, hidden: l.hidden.length, pinned: l.pinned.length, visible: effective };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    DASHBOARD_CARDS, DASHBOARD_CARD_IDS, dashboardCardById,
    DASHBOARD_FOCUS_OPTIONS, DASHBOARD_FOCUS_ORDER, normalizeDashboardFocus, dashboardOrderForFocus, applyDashboardFocus,
    defaultDashboardLayout, normalizeDashboardLayout, isDashboardCardVisible,
    toggleDashboardCard, setDashboardCardVisibility, moveDashboardCard, visibleDashboardCards, dashboardLayoutCounts,
    isDashboardStarting, isDashboardCardRelevant,
  };
}

// source: js/safe-errors.js
// safe-errors.js. Diagnóstico local sem conteúdo financeiro ou pessoal.
"use strict";

const SAFE_ERROR_STORAGE_KEY = "financas_safe_errors_v1";
const SAFE_ERROR_RETENTION_MS = 30 * 24 * 60 * 60 * 1000;
const SAFE_ERROR_LIMIT = 50;
const SAFE_ERROR_APP_VERSION = "0.30.0";
const SAFE_ERROR_AREAS = new Set(["app", "storage", "backup", "import", "sync", "ai", "qr", "events"]);
const SAFE_ERROR_CODES = new Set([
  "unexpected", "app_init", "storage_init", "storage_read", "storage_write", "storage_delete",
  "backup_read", "backup_restore", "import_read", "sync_read", "sync_write", "ai_request",
  "qr_camera", "qr_lookup", "global_error", "unhandled_rejection",
]);

function safeErrorArea(value) {
  const area = String(value || "app").toLowerCase();
  return SAFE_ERROR_AREAS.has(area) ? area : "app";
}

function safeErrorCode(value) {
  const code = String(value || "unexpected").toLowerCase();
  return SAFE_ERROR_CODES.has(code) ? code : "unexpected";
}

function safeErrorNow() { return Date.now(); }

function normalizeSafeErrorEntries(raw, now) {
  const clock = Number.isFinite(now) ? now : safeErrorNow();
  const min = clock - SAFE_ERROR_RETENTION_MS;
  return (Array.isArray(raw) ? raw : [])
    .filter((item) => item && Number(item.at) >= min && Number(item.at) <= clock + 60000)
    .map((item) => ({
      at: Math.floor(Number(item.at)),
      area: safeErrorArea(item.area),
      code: safeErrorCode(item.code),
      appVersion: SAFE_ERROR_APP_VERSION,
      schema: Number.isInteger(Number(item.schema)) ? Number(item.schema) : null,
      online: item.online === true ? true : item.online === false ? false : null,
    }))
    .sort((a, b) => a.at - b.at)
    .slice(-SAFE_ERROR_LIMIT);
}

function readSafeErrors() {
  try {
    const raw = localStorage.getItem(SAFE_ERROR_STORAGE_KEY);
    return normalizeSafeErrorEntries(raw ? JSON.parse(raw) : []);
  } catch (_error) { return []; }
}

function writeSafeErrors(entries) {
  try {
    localStorage.setItem(SAFE_ERROR_STORAGE_KEY, JSON.stringify(normalizeSafeErrorEntries(entries)));
    return true;
  } catch (_error) { return false; }
}

function reportSafeError(area, _error, code) {
  const entries = readSafeErrors();
  entries.push({
    at: safeErrorNow(),
    area: safeErrorArea(area),
    code: safeErrorCode(code),
    appVersion: SAFE_ERROR_APP_VERSION,
    schema: typeof SCHEMA_VERSION === "number" ? SCHEMA_VERSION : null,
    online: typeof navigator !== "undefined" && typeof navigator.onLine === "boolean" ? navigator.onLine : null,
  });
  writeSafeErrors(entries);
}

function clearSafeErrors() {
  try { localStorage.removeItem(SAFE_ERROR_STORAGE_KEY); return true; }
  catch (_error) { return false; }
}

function safeErrorSummary() {
  const entries = readSafeErrors();
  const byCode = {};
  entries.forEach((item) => { byCode[item.code] = (byCode[item.code] || 0) + 1; });
  return {
    generatedAt: new Date().toISOString(),
    appVersion: SAFE_ERROR_APP_VERSION,
    schema: typeof SCHEMA_VERSION === "number" ? SCHEMA_VERSION : null,
    retentionDays: 30,
    automaticUpload: false,
    total: entries.length,
    firstAt: entries.length ? new Date(entries[0].at).toISOString() : null,
    lastAt: entries.length ? new Date(entries[entries.length - 1].at).toISOString() : null,
    counts: Object.keys(byCode).sort().map((code) => ({ code, count: byCode[code] })),
  };
}

function installSafeErrorCapture() {
  if (typeof window === "undefined" || window.__safeErrorCaptureInstalled) return;
  window.__safeErrorCaptureInstalled = true;
  window.addEventListener("error", (event) => reportSafeError("events", event && event.error, "global_error"));
  window.addEventListener("unhandledrejection", (event) => reportSafeError("events", event && event.reason, "unhandled_rejection"));
}

installSafeErrorCapture();

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    SAFE_ERROR_STORAGE_KEY, SAFE_ERROR_RETENTION_MS, SAFE_ERROR_LIMIT,
    normalizeSafeErrorEntries, reportSafeError, readSafeErrors, clearSafeErrors, safeErrorSummary,
  };
}

// source: js/storage.js
// storage.js. Camada de persistência Local-First (padrão Adapter + IndexedDB)
// ------------------------------------------------------------------------------
// ARQUITETURA (pensada para virar cloud no futuro sem tocar na UI):
//
//   app.js / import.js / insights.js      (consumidores; só falam com o Façade)
//              │
//              ▼
//   FinanceStore  ....................... Façade + cache em memória + fila de escrita
//              │
//              ├── espelho síncrono (localStorage) .....; rede de segurança anti-perda
//              ▼
//   StorageAdapter (contrato)  ......... IndexedDBAdapter | LocalStorageAdapter | CloudAdapter
//
// O app inteiro continua lendo um objeto síncrono em memória (snapshot), enquanto
// a escrita acontece em IndexedDB de forma assíncrona, incremental (só o que mudou)
// e serializada. Para migrar para nuvem, basta implementar um novo adapter com os
// mesmos 5 métodos e registrá-lo em FinanceStore.use(adapter).
"use strict";

const DB_NAME = "financas_db";
const DB_VERSION = 4;   // v4. Commit atômico, metadados locais e entidades do protocolo 3
const LEGACY_KEY = "financas_pro_v2";     // storage antigo (localStorage)
const LS_FALLBACK_KEY = "financas_db_fallback";
const LS_MIRROR_KEY = "financas_db_mirror";   // espelho síncrono anti-perda
const LS_UNDO_KEY = "financas_db_undo";       // snapshot antes de um restore destrutivo

// ------------------------------------------------------------------------------
// ESCOPO DE ARMAZENAMENTO (isolamento por conta)
// ------------------------------------------------------------------------------
// Antes existia UM banco por navegador. Duas contas no mesmo aparelho liam e
// gravavam nos mesmos registros: quem entrasse depois via o extrato de quem
// entrou antes, e o logout não removia nada porque não havia nada a remover:
// os dados nunca tinham sido separados.
//
// Agora cada conta tem seu próprio banco físico, com nome derivado do `userId`
// devolvido pelo servidor. O escopo "guest" mantém o nome ANTIGO (`financas_db`)
// de propósito: é onde os dados de quem já usava o app sem conta continuam, sem
// migração nem risco de perda. Entrar numa conta NÃO importa esses dados; isso
// exige confirmação explícita (ver `FinanceStore.adoptScope`).
const GUEST_SCOPE = "guest";
const SCOPE_PATTERN = /^(guest|u_[A-Za-z0-9_-]{1,64})$/;

// O `userId` vem do servidor (uuid do Supabase). Sanitizamos porque ele vira
// nome de banco e chave de localStorage: qualquer caractere fora da lista
// abaixo seria uma porta para colidir escopos de contas diferentes.
function storageScopeFor(userId) {
  const raw = String(userId == null ? "" : userId).trim();
  if (!raw) return GUEST_SCOPE;
  const safe = raw.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 64);
  return safe ? `u_${safe}` : GUEST_SCOPE;
}

function normalizeStorageScope(scope) {
  const value = String(scope == null ? "" : scope).trim();
  return SCOPE_PATTERN.test(value) ? value : GUEST_SCOPE;
}

// Nomes físicos. O escopo visitante mantém os nomes históricos; qualquer outro
// ganha sufixo. É isso que garante compatibilidade com bases já existentes.
function scopedName(base, scope) {
  const normalized = normalizeStorageScope(scope);
  return normalized === GUEST_SCOPE ? base : `${base}__${normalized}`;
}

// O escopo da última sessão fica lembrado para o app abrir JÁ no banco certo,
// sem esperar a resposta do servidor. Sem isso, um aparelho offline abriria
// como visitante e qualquer lançamento feito antes da rede voltar cairia no
// banco errado.
const ACTIVE_SCOPE_KEY = "cofre_active_scope";

function rememberedStorageScope() {
  try { return normalizeStorageScope(localStorage.getItem(ACTIVE_SCOPE_KEY)); }
  catch (e) { return GUEST_SCOPE; }
}

function rememberStorageScope(scope) {
  const normalized = normalizeStorageScope(scope);
  try {
    if (normalized === GUEST_SCOPE) localStorage.removeItem(ACTIVE_SCOPE_KEY);
    else localStorage.setItem(ACTIVE_SCOPE_KEY, normalized);
  } catch (e) { /* armazenamento bloqueado; o escopo vale só para esta sessão */ }
  return normalized;
}

// ------------------------------------------------------------------------------
// RELÓGIO LÓGICO HÍBRIDO (HLC); ordem de escrita entre aparelhos
// ------------------------------------------------------------------------------
// O conflito era decidido por `updatedAt`, que é a hora do celular de quem
// gravou. Um aparelho com o relógio adiantado uma hora ganhava TODAS as
// disputas, inclusive contra edições feitas depois dele; um atrasado perdia
// edições que acabara de fazer. Não é um caso raro: relógio errado em celular
// é comum, e fuso/horário de verão mudam de um lado só.
//
// O HLC resolve porque ele nunca anda para trás e sempre supera o que já viu:
// se este aparelho LEU uma alteração remota, a próxima escrita dele é
// necessariamente maior que ela, mesmo com o relógio atrasado. O empate final
// sai pelo id do aparelho, então os dois lados chegam ao MESMO vencedor sem
// precisar conversar.
//
// Formato: "<ms com 15 dígitos>.<contador com 6>.<aparelho>". Largura fixa para
// que a comparação de texto simples (a < b) já seja a comparação correta.
const HLC_PATTERN = /^\d{15}\.\d{6}\.[A-Za-z0-9][A-Za-z0-9:_-]{0,79}$/;
const HLC_MAX_DRIFT_MS = 24 * 60 * 60 * 1000;   // 24h: além disso o relógio remoto é ignorado
// Largura fixa do formato. Estourar qualquer um dos dois produziria uma marca
// fora do padrão, que o app trata como "sem marca" e perde para qualquer
// lápide. São os mesmos limites do `cofre_hlc_successor` no servidor.
const HLC_MAX_COUNTER = 999999;
const HLC_MAX_MILLIS = 999999999999999;
const SYNC_WRITER_TOKEN = (() => {
  let token = "";
  try {
    if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
      token = crypto.randomUUID().replace(/[^A-Za-z0-9]/g, "");
    }
  } catch (_error) { /* usa a alternativa local abaixo */ }
  if (!token) {
    token = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 10)}`
      .replace(/[^A-Za-z0-9]/g, "");
  }
  return (token || "localwriter").padEnd(12, "0").slice(0, 12);
})();

const SyncClock = (() => {
  let lastMillis = 0;
  let counter = 0;
  let deviceId = "device";

  function setDevice(id) {
    const safe = String(id || "").replace(/[^A-Za-z0-9:_-]/g, "").slice(0, 80);
    if (safe) deviceId = safe;
    return deviceId;
  }

  function format(millis, count, device) {
    return `${String(millis).padStart(15, "0")}.${String(count).padStart(6, "0")}.${device}`;
  }

  function parse(rev) {
    if (typeof rev !== "string" || !HLC_PATTERN.test(rev)) return null;
    const dot1 = rev.indexOf(".");
    const dot2 = rev.indexOf(".", dot1 + 1);
    return {
      millis: Number(rev.slice(0, dot1)),
      counter: Number(rev.slice(dot1 + 1, dot2)),
      device: rev.slice(dot2 + 1),
    };
  }

  // Escrita local: avança o relógio e devolve a marca desta alteração.
  //
  // O contador tem SEIS dígitos. Depois de absorver uma barreira de reset com o
  // contador cheio, somar um produziria sete dígitos: marca inválida, tratada
  // como ausência de marca, que perde para as lápides que a barreira deveria
  // vencer. Ao encher, o contador vira e o milissegundo avança um, igual ao
  // `cofre_hlc_successor` do servidor.
  function tick() {
    const now = Date.now();
    if (now > lastMillis) { lastMillis = now; counter = 0; }
    else if (counter >= HLC_MAX_COUNTER) {
      // Relógio no fim da largura: mantém a última marca válida em vez de
      // devolver texto que nenhuma comparação entende. Inalcançável na prática.
      if (lastMillis < HLC_MAX_MILLIS) { lastMillis += 1; counter = 0; }
    }
    else counter += 1;
    return format(lastMillis, counter, deviceId);
  }

  // Leitura remota: absorve a marca do outro aparelho para que a PRÓXIMA
  // escrita local seja maior que ela. É este passo que torna o relógio errado
  // irrelevante. Marcas absurdamente à frente são ignoradas para que um
  // aparelho quebrado não empurre o relógio de todo mundo para 2090.
  function observe(rev) {
    const parsed = parse(rev);
    if (!parsed) return false;
    const now = Date.now();
    if (parsed.millis > now + HLC_MAX_DRIFT_MS) return false;
    if (parsed.millis > lastMillis) { lastMillis = parsed.millis; counter = parsed.counter; }
    else if (parsed.millis === lastMillis && parsed.counter > counter) counter = parsed.counter;
    return true;
  }

  // Absorção CONFIÁVEL, sem o teto de 24h. Existe só para a barreira de reset
  // confirmada pelo servidor: o RPC carimba a exclusão acima de TODA marca que a
  // conta já conhecia, inclusive a de um aparelho com o relógio muito
  // adiantado, e nesse caso ela nasce além do teto. Recusar essa marca faria o
  // primeiro lançamento criado depois de apagar nascer menor que as lápides e
  // sumir no ciclo seguinte. As operações remotas comuns continuam em
  // `observe`, onde o teto vale.
  function absorb(rev) {
    const parsed = parse(rev);
    if (!parsed) return false;
    if (parsed.millis > lastMillis) { lastMillis = parsed.millis; counter = parsed.counter; }
    else if (parsed.millis === lastMillis && parsed.counter > counter) counter = parsed.counter;
    return true;
  }

  // Estado do relógio precisa sobreviver ao fechamento da aba: sem isso, um
  // recarregamento zera o contador e a escrita seguinte perde para a anterior.
  function state() { return { millis: lastMillis, counter }; }
  function restore(raw) {
    const src = raw && typeof raw === "object" ? raw : {};
    const millis = Number(src.millis);
    const count = Number(src.counter);
    if (Number.isFinite(millis) && millis > lastMillis && millis <= Date.now() + HLC_MAX_DRIFT_MS) {
      lastMillis = millis;
      counter = Number.isFinite(count) ? Math.max(0, Math.min(999999, count)) : 0;
    }
  }

  function reset() { lastMillis = 0; counter = 0; }

  return { setDevice, tick, observe, absorb, parse, state, restore, reset, device: () => deviceId };
})();

function isSyncRev(value) { return typeof value === "string" && HLC_PATTERN.test(value); }

// Comparação total e determinística. Devolve true quando `a` é a alteração mais
// recente. Registro sem marca perde para registro com marca: quem tem marca
// passou pela versão nova do app, logo é a informação mais confiável.
function syncRevGreater(a, b) {
  const va = isSyncRev(a) ? a : "";
  const vb = isSyncRev(b) ? b : "";
  if (va && vb) return va > vb;
  return !!va && !vb;
}

// Marca de fallback para registros que vêm de bases antigas, importação ou
// backup: deriva de `updatedAt` para preservar a ordem histórica conhecida.
function syncRevFromDate(value, device) {
  const ts = Date.parse(value || "");
  if (!Number.isFinite(ts)) return "";
  const safe = String(device || "legacy").replace(/[^A-Za-z0-9:_-]/g, "").slice(0, 80) || "legacy";
  return `${String(ts).padStart(15, "0")}.${String(0).padStart(6, "0")}.${safe}`;
}

function normalizeSyncRev(value) { return isSyncRev(value) ? value : ""; }

// Mesma chave usada pelo cadastro de aparelhos (auth.js). O relógio lógico
// precisa de um identificador estável para o desempate final; se cada aba
// sorteasse o seu, duas abas do mesmo navegador nunca empatariam igual.
function syncDeviceId() {
  try {
    const value = localStorage.getItem("cofre_device_id");
    if (/^[A-Za-z0-9][A-Za-z0-9:_-]{7,79}$/.test(value || "")) return value;
  } catch (e) { /* armazenamento bloqueado */ }
  return "device-local";
}

// Duas abas compartilham o id persistente do aparelho, mas cada uma mantém o
// contador HLC em memória. Sem um desempate por aba, duas escritas no mesmo
// milissegundo podem receber exatamente a mesma revisão e representar conteúdos
// diferentes. O sufixo continua dentro do componente opaco aceito pelo servidor.
// O prefixo persistente continua identificando o dono para reenvio de lápides.
function syncWriterId() {
  const suffix = `:tab_${SYNC_WRITER_TOKEN}`;
  return `${syncDeviceId().slice(0, 80 - suffix.length)}${suffix}`;
}

function isLocalSyncWriter(value) {
  const writer = String(value || "");
  const stable = syncDeviceId();
  if (writer === stable) return true; // revisões criadas antes do sufixo por aba
  const marker = ":tab_";
  const baseLength = 80 - marker.length - SYNC_WRITER_TOKEN.length;
  return writer.startsWith(`${stable.slice(0, baseLength)}${marker}`);
}
const SCHEMA_VERSION = 22;  // v22; privacidade, consentimentos e controles do usuário
const LEGAL_REVIEW_DATE = "2026-08-18";
// A versão sobe quando o CONTEÚDO do texto muda, não quando muda a redação.
// Esta subiu porque a política passou a declarar controlador, retenção,
// direitos do titular e canal de incidentes, e porque a versão anterior ainda
// afirmava que a sincronização não estava ativa. Quem aceitou a anterior
// aceitou outra coisa, então o aceite precisa ser pedido de novo.
const LEGAL_TEXT_VERSION = "2026-08-18.1";
const MIRROR_MAX_BYTES = 3 * 1024 * 1024;
const MIRROR_THROTTLE_MS = 1200;

// Marcador dos campos que só o dono do aplicativo pode preencher. Fica visível
// de propósito: uma política que inventa controlador ou canal de atendimento é
// pior que uma que diz em voz alta o que ainda falta. `check-release.js` trata
// a presença do marcador como impedimento de oferta ao público.
const LEGAL_PENDING = "[definir antes da oferta ao público]";

// Identificação do controlador (LGPD art. 9, I e art. 41) e canais de contato.
// `responseDays` é o prazo de resposta ao titular do art. 19, II.
const LEGAL_CONTROLLER = {
  name: LEGAL_PENDING,
  document: LEGAL_PENDING,
  address: LEGAL_PENDING,
  supportEmail: LEGAL_PENDING,
  dpoName: LEGAL_PENDING,
  dpoEmail: LEGAL_PENDING,
  incidentEmail: LEGAL_PENDING,
  responseDays: 15,
};

const LEGAL_CONTROLLER_FIELDS = {
  name: "nome empresarial ou responsável",
  document: "CPF ou CNPJ",
  address: "endereço",
  supportEmail: "canal de atendimento",
  dpoName: "encarregado pelos dados",
  dpoEmail: "contato do encarregado",
  incidentEmail: "canal de comunicação de incidentes",
};

// Campos do controlador ainda em aberto. Lista vazia significa identificação
// completa, e só então o app pode parar de se declarar versão local.
function legalControllerGaps(controller) {
  const source = controller && typeof controller === "object" ? controller : LEGAL_CONTROLLER;
  return Object.keys(LEGAL_CONTROLLER_FIELDS)
    .filter((campo) => {
      const valor = String(source[campo] == null ? "" : source[campo]).trim();
      return valor === "" || valor === LEGAL_PENDING;
    })
    .map((campo) => LEGAL_CONTROLLER_FIELDS[campo]);
}

function legalControllerReady(controller) {
  return legalControllerGaps(controller).length === 0;
}

// Prazos de retenção lidos do código que os aplica, não de estimativa. O
