const ACH_TOTAL_XP = ACHIEVEMENTS.reduce((sum, a) => sum + a.xp, 0);

/* ==========================================================================
 * NÍVEIS
 * ========================================================================== */

function levelForXp(xp) {
  const points = Math.max(0, Number(xp) || 0);
  let current = ACH_LEVELS[0];
  for (let i = 0; i < ACH_LEVELS.length; i++) {
    if (points >= ACH_LEVELS[i].xp) current = ACH_LEVELS[i];
  }
  const next = ACH_LEVELS.find((l) => l.xp > points) || null;
  const span = next ? next.xp - current.xp : 0;
  const into = points - current.xp;
  return {
    ...current,
    xp: points,
    levelFloor: current.xp,
    next,
    toNext: next ? next.xp - points : 0,
    // Fração percorrida DENTRO do nível; não do total. Uma barra que anda de
    // 0 a 100 dentro de cada faixa dá sensação de avanço; uma barra sobre o
    // total geral trava perto de zero e desmotiva.
    progress: next && span > 0 ? clamp(into / span, 0, 1) : 1,
    isMax: !next,
  };
}

/* ==========================================================================
 * MODELO
 * ========================================================================== */

function achProgressOf(res) {
  const target = Number(res.target) || 0;
  if (target <= 0) return res.current > 0 ? 1 : 0;
  return clamp((Number(res.current) || 0) / target, 0, 1);
}

/**
 * @param {object} data     snapshot
 * @param {Date}   refDate  mês de referência (default: hoje)
 * @returns modelo completo de gamificação
 */
function buildAchievementsModel(data, refDate) {
  const ctx = buildAchievementContext(data, refDate);
  const record = (data.achievements && data.achievements.unlocked) || {};

  const items = ACHIEVEMENTS.map((a) => {
    let res;
    try { res = a.check(ctx) || { current: 0, target: 1 }; }
    catch (e) { res = { current: 0, target: 1 }; }
    const meetsNow = achProgressOf(res) >= 1;
    const unlockedAt = record[a.id] || null;
    // Sticky: conquista registrada permanece conquistada.
    const done = meetsNow || !!unlockedAt;
    return {
      id: a.id,
      name: a.name,
      desc: a.desc,
      icon: a.icon,
      group: a.group,
      tier: a.tier,
      tierMeta: ACH_TIERS[a.tier],
      xp: a.xp,
      unit: res.unit || a.unit || "count",
      current: Number(res.current) || 0,
      target: Number(res.target) || 0,
      progress: done ? 1 : achProgressOf(res),
      done,
      meetsNow,
      unlockedAt,
      isNew: meetsNow && !unlockedAt,
    };
  });

  const unlocked = items.filter((i) => i.done);
  const xp = unlocked.reduce((sum, i) => sum + i.xp, 0);
  const level = levelForXp(xp);

  const byGroup = ACH_GROUPS.map((g) => {
    const list = items.filter((i) => i.group === g.id);
    const doneList = list.filter((i) => i.done);
    return {
      ...g,
      items: list.sort(achSortForDisplay),
      total: list.length,
      unlocked: doneList.length,
      pct: list.length ? Math.round((doneList.length / list.length) * 100) : 0,
    };
  });

  // "Próximas": trancadas, com algum avanço, mais perto de fechar primeiro.
  // Conquistas em 0% ficam no fim; sugerir o que está longe demais não ajuda.
  const nextUp = items
    .filter((i) => !i.done)
    .sort((a, b) => (b.progress - a.progress) || (a.xp - b.xp))
    .slice(0, 3);

  const recent = unlocked
    .filter((i) => i.unlockedAt)
    .sort((a, b) => (a.unlockedAt < b.unlockedAt ? 1 : -1))
    .slice(0, 5);

  return {
    items,
    byGroup,
    nextUp,
    recent,
    pendingIds: items.filter((i) => i.isNew).map((i) => i.id),
    unlockedCount: unlocked.length,
    total: items.length,
    completionPct: items.length ? Math.round((unlocked.length / items.length) * 100) : 0,
    xp,
    maxXp: ACH_TOTAL_XP,
    level,
    streak: {
      active: ctx.activeStreak,
      saving: ctx.savingStreak,
      activeMonths: ctx.activeMonths,
      savingMonths: ctx.savingMonths,
    },
    ctx,
  };
}

// Trancadas com progresso primeiro (é o que dá o que fazer), depois as
// desbloqueadas mais valiosas, depois o resto.
function achSortForDisplay(a, b) {
  if (a.done !== b.done) return a.done ? 1 : -1;
  if (!a.done) return (b.progress - a.progress) || (a.xp - b.xp);
  return (ACH_TIERS[b.tier].weight - ACH_TIERS[a.tier].weight) || (b.xp - a.xp);
}

/* ==========================================================================
 * PERSISTÊNCIA (funções puras; quem grava é o app.js, via setData)
 * ========================================================================== */

/** Registra ids recém-conquistados; devolve NOVO objeto de conquistas. */
function withUnlockedAchievements(record, ids, iso) {
  const base = record && typeof record === "object" ? record : {};
  const unlocked = { ...(base.unlocked || {}) };
  const stamp = iso || todayIso();
  (ids || []).forEach((id) => { if (!unlocked[id]) unlocked[id] = stamp; });
  return { ...base, unlocked };
}

/** Texto curto de celebração; usado no toast e no cartão do dashboard. */
function achievementToastFor(items) {
  if (!items || items.length === 0) return null;
  if (items.length === 1) return `Conquista desbloqueada: ${items[0].name}`;
  return `${items.length} novas conquistas desbloqueadas!`;
}

function achievementById(id) {
  return ACHIEVEMENTS.find((a) => a.id === id) || null;
}

// source: js/wrapped.js
// wrapped.js. Resumo mensal visual estilo "Wrapped", desenhado via Canvas API.
// Gera uma imagem PNG pronta para salvar ou compartilhar (Web Share API), sem
// depender de nenhum serviço externo.
"use strict";

function buildWrappedData(data) {
  const now = new Date();
  const mKey = keyOfDate(now);
  const { income, expense, tx } = realizedMonthTotals(data, mKey);
  const byCategory = {};
  tx.filter((t) => t.type === "expense").forEach((t) => { byCategory[t.categoryId] = (byCategory[t.categoryId] || 0) + t.amount; });
  const topEntries = Object.entries(byCategory).sort((a, b) => b[1] - a[1]);
  const top = topEntries[0] ? categoryById(data, topEntries[0][0]) : null;
  const topValue = topEntries[0] ? topEntries[0][1] : 0;
  const saved = income - expense;
  const goalsProgress = data.goals.reduce((s, g) => s + g.current, 0);
  return {
    monthLabel: `${MONTH_NAMES[now.getMonth()]} ${now.getFullYear()}`,
    income, expense, saved,
    topCategoryName: top ? top.name : ":",
    topCategoryColor: top ? top.color : "#0E6E5D",
    topValue,
    txCount: tx.length,
    goalsProgress,
  };
}

function drawWrappedCard(canvas, w) {
  const W = 1080, H = 1350;
  canvas.width = W; canvas.height = H;
  const ctx = canvas.getContext("2d");

  const grad = ctx.createLinearGradient(0, 0, W, H);
  grad.addColorStop(0, "#0E6E5D");
  grad.addColorStop(1, "#0A5347");
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);

  // círculos decorativos
  ctx.globalAlpha = 0.08;
  ctx.fillStyle = "#FFFFFF";
  ctx.beginPath(); ctx.arc(W - 80, 140, 260, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(60, H - 160, 200, 0, Math.PI * 2); ctx.fill();
  ctx.globalAlpha = 1;

  ctx.fillStyle = "#FFFFFF";
  ctx.font = "600 34px -apple-system, Helvetica, Arial, sans-serif";
  ctx.fillText("Meu resumo financeiro", 64, 130);
  ctx.font = "800 56px -apple-system, Helvetica, Arial, sans-serif";
  ctx.fillText(w.monthLabel, 64, 195);

  const cardY = 280, cardH = 620, cardX = 64, cardW = W - 128;
  ctx.fillStyle = "rgba(255,255,255,0.96)";
  roundRect(ctx, cardX, cardY, cardW, cardH, 32);
  ctx.fill();

  ctx.fillStyle = "#10182B";
  ctx.font = "600 28px -apple-system, Helvetica, Arial, sans-serif";
  ctx.fillText("Entradas", cardX + 48, cardY + 90);
  ctx.font = "800 52px -apple-system, Helvetica, Arial, sans-serif";
  ctx.fillStyle = "#12876F";
  ctx.fillText(fmtBRL(w.income), cardX + 48, cardY + 150);

  ctx.fillStyle = "#10182B";
  ctx.font = "600 28px -apple-system, Helvetica, Arial, sans-serif";
  ctx.fillText("Gastos", cardX + 48, cardY + 230);
  ctx.font = "800 52px -apple-system, Helvetica, Arial, sans-serif";
  ctx.fillStyle = "#C8433B";
  ctx.fillText(fmtBRL(w.expense), cardX + 48, cardY + 290);

  ctx.strokeStyle = "#E7E9EC";
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(cardX + 48, cardY + 330); ctx.lineTo(cardX + cardW - 48, cardY + 330); ctx.stroke();

  ctx.fillStyle = "#10182B";
  ctx.font = "600 26px -apple-system, Helvetica, Arial, sans-serif";
  ctx.fillText("Categoria campeã", cardX + 48, cardY + 390);
  ctx.fillStyle = w.topCategoryColor;
  ctx.font = "800 42px -apple-system, Helvetica, Arial, sans-serif";
  ctx.fillText(w.topCategoryName, cardX + 48, cardY + 440);
  ctx.fillStyle = "#5B6472";
  ctx.font = "500 26px -apple-system, Helvetica, Arial, sans-serif";
  ctx.fillText(fmtBRL(w.topValue) + " no mês", cardX + 48, cardY + 480);

  ctx.fillStyle = "#10182B";
  ctx.font = "600 26px -apple-system, Helvetica, Arial, sans-serif";
  ctx.fillText(w.saved >= 0 ? "Sobrou no mês" : "Ficou no vermelho", cardX + 48, cardY + 550);
  ctx.fillStyle = w.saved >= 0 ? "#12876F" : "#C8433B";
  ctx.font = "800 46px -apple-system, Helvetica, Arial, sans-serif";
  ctx.fillText(fmtBRL(Math.abs(w.saved)), cardX + 48, cardY + 600);

  ctx.fillStyle = "rgba(255,255,255,0.85)";
  ctx.font = "500 26px -apple-system, Helvetica, Arial, sans-serif";
  ctx.fillText(`${w.txCount} lançamentos registrados este mês`, 64, cardY + cardH + 70);
  ctx.font = "700 30px -apple-system, Helvetica, Arial, sans-serif";
  ctx.fillText("Cofre; meu app financeiro", 64, H - 60);

  return canvas;
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

async function shareOrDownloadCanvas(canvas, filename) {
  const blob = await new Promise((resolve) => canvas.toBlob(resolve, "image/png"));
  if (!blob) return;
  const file = new File([blob], filename, { type: "image/png" });
  if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
    try {
      await navigator.share({ files: [file], title: "Meu resumo financeiro" });
      return;
    } catch (e) { /* usuário cancelou o compartilhamento; cai para download */ }
  }
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename; document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

// source: js/services.js
// services.js. [M8] Event Bus + camada de serviços + central de notificações.
//
// O §19 do briefing pede uma separação clara entre UI, Serviços, Lógica
// Financeira e Persistência, um Event Bus e seis serviços nomeados. Este
// arquivo entrega os três; sem reescrever nada do que já funciona.
//
// A regra que organiza o arquivo
// ------------------------------
// **Nenhum cálculo financeiro novo mora aqui.** Os motores puros dos módulos
// anteriores (`metrics.js`, `budgets.js`, `portfolio.js`, `analytics.js`,
// `advisor.js`, `goals.js`, `forecast.js`, `recurring.js`, `health.js`,
// `score.js`, `achievements.js`) continuam sendo a única fonte de verdade. Os
// serviços são **fachadas**: dão um endereço estável e um vocabulário único
// para o que já existe. Duas fontes para o mesmo número seriam duas verdades
// sobre o mesmo dinheiro; o defeito que o Módulo 3 já teve de corrigir no
// patrimônio.
//
// Por que fachada e não classe com estado
// ---------------------------------------
// O app grava de forma imutável e a UI lê um snapshot síncrono. Um serviço com
// cópia interna do dado seria uma terceira verdade e um cache para invalidar à
// mão. Aqui todo método recebe `data` explicitamente: mesma entrada, mesma
// saída, testável sem DOM e sem storage.
//
// A única regra realmente NOVA do módulo é a de notificações; e mesmo ela não
// calcula dinheiro: lê os modelos prontos e decide o que merece interromper o
// usuário.
//
// Dependências: utils.js, storage.js, budgets.js, metrics.js, score.js,
// health.js, goals.js, forecast.js, calendar.js, recurring.js, analytics.js,
// insights.js, assistant.js, advisor.js, investments.js, portfolio.js,
// achievements.js.
"use strict";

/* ==============================================================================
 * 1. EVENT BUS
 * ==============================================================================
 * Comunicação entre módulos sem que um conheça o outro. Três decisões:
 *
 *   • Um handler que estoura NÃO derruba os outros. Um `emit` é uma difusão,
 *     não uma cadeia: se o cartão de notificação quebrar, o toast ainda tem de
 *     aparecer.
 *   • `on` devolve a própria função de cancelamento. Quem assina não precisa
 *     guardar a referência do handler para conseguir desassinar depois.
 *   • Há curinga (`*`) porque diagnóstico é caso de uso real; um log de
 *     eventos em desenvolvimento não deveria exigir 12 assinaturas.
 */

const APP_EVENTS = {
  DATA_CHANGED: "data:changed",
  TAB_CHANGED: "tab:changed",
  TRANSACTION_ADDED: "transaction:added",
  ACHIEVEMENT_UNLOCKED: "achievement:unlocked",
  NOTIFICATIONS_CREATED: "notifications:created",
  NOTIFICATION_READ: "notification:read",
};

const EventBus = (function createEventBus() {
  const handlers = new Map();

  function listOf(event) {
    let list = handlers.get(event);
    if (!list) { list = []; handlers.set(event, list); }
    return list;
  }

  function on(event, handler) {
    if (typeof handler !== "function" || !event) return function noop() {};
    listOf(event).push(handler);
    return function off() { EventBus.off(event, handler); };
  }

  function once(event, handler) {
    if (typeof handler !== "function" || !event) return function noop() {};
    const wrapped = function wrapped(payload) {
      EventBus.off(event, wrapped);
      handler(payload);
    };
    return on(event, wrapped);
  }

  function off(event, handler) {
    const list = handlers.get(event);
    if (!list) return;
    const i = list.indexOf(handler);
    if (i >= 0) list.splice(i, 1);
    if (list.length === 0) handlers.delete(event);
  }

  function emit(event, payload) {
    if (!event) return 0;
    let delivered = 0;
    // Cópia antes de percorrer: um handler pode assinar/cancelar durante a
    // difusão sem embaralhar o laço.
    const direct = (handlers.get(event) || []).slice();
    const wildcard = (handlers.get("*") || []).slice();
    direct.forEach((fn) => {
      delivered++;
      try { fn(payload, event); }
      catch (e) { if (typeof console !== "undefined") console.warn(`[EventBus] handler de "${event}" falhou:`, e); }
    });
    wildcard.forEach((fn) => {
      delivered++;
      try { fn(payload, event); }
      catch (e) { if (typeof console !== "undefined") console.warn("[EventBus] handler curinga falhou:", e); }
    });
    return delivered;
  }

  function listenerCount(event) {
    return (handlers.get(event) || []).length;
  }

  function clear(event) {
    if (event) handlers.delete(event);
    else handlers.clear();
  }

  return { on, once, off, emit, listenerCount, clear, EVENTS: APP_EVENTS };
})();

/* ==============================================================================
 * 2. SERVIÇOS DE DOMÍNIO (fachadas finas sobre os motores existentes)
 * ============================================================================== */

// Dinheiro que entra, sai e sobra. Tudo que o Dashboard e o Score consomem.

const FinanceService = {
  month(data, monthKey) { return monthTotals(data, monthKey || keyOfDate(new Date())); },
  realizedMonth(data, monthKey) { return realizedMonthTotals(data, monthKey || keyOfDate(new Date())); },
  income(data, monthKey) { return effectiveIncome(data, monthKey || keyOfDate(new Date())); },
  balance(data) { return realizedBalance(data); },
  netWorth(data) { return netWorth(data); },
  netWorthSeries(data, months) { return netWorthSeries(data, months || 6); },
  emergency(data) { return emergencyFund(data); },
  upcomingBills(data, days) { return upcomingBills(data, days == null ? 30 : days); },
  pendingRecurring(data, monthKey) { return getPendingRecurring(data, monthKey || keyOfDate(new Date())); },
  forecast(data, refIso) { return buildForecast(data, refIso); },
  dashboard(data, refDate) { return buildDashboardModel(data, refDate || new Date()); },
  calendar(data, monthKey) { return buildCalendarMonth(data, monthKey || keyOfDate(new Date())); },
  annualPlan(data, year) { return buildAnnualPlan(data, year || new Date().getFullYear()); },
};

// Tetos por categoria, grupos 50/30/20 e o impacto de um gasto antes de salvá-lo.

const BudgetService = {
  status(data, monthKey) { return computeBudgetStatus(data, monthKey); },
  forCategory(data, categoryId, monthKey) { return budgetStatusFor(data, categoryId, monthKey); },
  impact(data, categoryId, amount, monthKey) { return evaluateBudgetImpact(data, categoryId, amount, monthKey); },
  alerts(data, monthKey) { return budgetAlerts(data, monthKey); },
  thresholds(data) { return budgetThresholds(data); },
  suggest(data, categoryId) { return suggestBudgetFor(data, categoryId); },
};

// Carteira (mesma coleção `assets`, classe investimento) e projeções.

const InvestmentService = {
  portfolio(data, opts) { return buildPortfolioModel(data, opts || {}); },
  items(data) { return portfolioItems(data); },
  rates(data) { return marketRatesOf(data); },
  wealth(data, months) { return buildWealthModel(data, months || 12); },
  compound(params) { return simulateCompoundInterest(params || {}); },
};

// Os onze indicadores do §11 e o motor de recorrências.

const AnalyticsService = {
  month(data, monthKey) { return buildAnalyticsModel(data, monthKey || keyOfDate(new Date())); },
  recurring(data, opts) { return buildRecurringModel(data, opts || {}); },
  proposals(data, monthKey) { return buildRecurringModel(data, { monthKey }).proposals; },
};

// Leitura interpretada: o que os números querem dizer.

const InsightService = {
  advisor(data, monthKey, models) { return buildAdvisorModel(data, monthKey || keyOfDate(new Date()), models || {}); },
  assistant(data, monthKey) { return getAssistantAlerts(data, monthKey || keyOfDate(new Date())); },
  leaks(data, monthKey) { return detectSilentLeaks(data, monthKey || keyOfDate(new Date())); },
  score(data, monthKey, ctx) { return computeFinanceScore(data, monthKey || keyOfDate(new Date()), ctx); },
  health(data, monthKey, ctx) { return buildHealthModel(data, monthKey || keyOfDate(new Date()), ctx); },
  goals(data, refDate) { return buildGoalsModel(data, refDate || new Date()); },
  achievements(data, refDate) { return buildAchievementsModel(data, refDate || new Date()); },
};

/* ==============================================================================
 * 3. NOTIFICAÇÕES; a única regra nova do módulo
 * ==============================================================================
 * O app já sabia tudo isto; só não sabia AVISAR. O Dashboard mostra a conta que
 * vence, o orçamento estourado e a assinatura reajustada; mas só para quem
 * abre a tela certa no dia certo. A central de notificações é o registro do que
 * mudou desde a última visita.
 *
 * Três decisões definem o comportamento:
 *
 *   1. **Uma notificação por fato, não por render.** A identidade é a `key` :
 *      `conta:<id>:<data>`, `orcamento:<categoria>:<mês>:over`. Enquanto o fato
 *      for o mesmo, o aviso é o mesmo, mesmo que a tela seja reconstruída mil
 *      vezes. Sem isso, cada `render()` empilharia um alerta idêntico.
 *   2. **A primeira sincronização é silenciosa.** Quem já usa o app há meses
 *      receberia trinta avisos não lidos no primeiro boot; um paredão que não
 *      informa nada. O passado entra já lido; só o que acontecer daí em diante
 *      acende o badge. É a mesma decisão tomada nas conquistas do Módulo 6.
 *   3. **Silenciar é por grupo, e não apaga histórico.** Quem não quer ser
 *      lembrado de assinaturas silencia o grupo; os avisos param de nascer, mas
 *      os lançamentos e os modelos continuam intactos.
 */

const NOTIF_MAX_ITEMS = 80;          // teto do histórico guardado
const NOTIF_RETENTION_DAYS = 60;     // aviso velho vira ruído
const NOTIF_BILL_DAYS = 3;           // "vence em até 3 dias" é acionável; 30 não é
const NOTIF_NETWORTH_DROP_PCT = 5;   // queda patrimonial que merece aviso
const NOTIF_BACKUP_MIN_TX = 15;      // abaixo disso, perder os dados custa pouco
const NOTIF_BACKUP_STALE_DAYS = 45;  // intervalo entre lembretes de backup

const NOTIF_GROUPS = [
  { id: "contas", label: "Contas e vencimentos", icon: "calendar" },
  { id: "dividas", label: "Dívidas", icon: "alertTriangle" },
  { id: "orcamento", label: "Orçamentos", icon: "pie" },
  { id: "assinaturas", label: "Assinaturas e recorrências", icon: "refresh" },
  { id: "metas", label: "Metas", icon: "target" },
  { id: "saldo", label: "Saldo e previsão", icon: "wallet" },
  { id: "patrimonio", label: "Patrimônio e reserva", icon: "shieldCheck" },
  { id: "conquistas", label: "Conquistas", icon: "star" },
  { id: "backup", label: "Backup e segurança dos dados", icon: "shieldCheck" },
];

const NOTIF_TONE_ORDER = { danger: 0, warn: 1, info: 2, positive: 3 };

function notifGroupMeta(id) {
  return NOTIF_GROUPS.find((g) => g.id === id) || { id, label: "Avisos", icon: "bell" };
}

function notifCandidate(o) {
  return {
    key: String(o.key).slice(0, 140),
    group: o.group,
    tone: o.tone || "info",
    icon: o.icon || "bell",
    title: o.title,
    message: o.message,
    tab: o.tab || "dashboard",
    amount: o.amount == null ? null : roundMoney(o.amount),
  };
}

/* ------------------------------------------------------------------ as regras */
// Cada regra recebe o mesmo contexto e devolve uma lista (possivelmente vazia).
// Assinatura uniforme para que a lista possa crescer sem tocar no orquestrador,
// e cada uma é isolada por try/catch no orquestrador: uma regra que estoure
// vira silêncio, não uma central quebrada.
const NOTIF_RULES = [
  // ---- Contas a vencer e contas atrasadas ----------------------------------
  {
    id: "contas",
    run({ data, today }) {
      const bills = upcomingBills(data, 30);
      const out = [];
      bills.items.forEach((b) => {
        if (b.kind === "late") {
          out.push(notifCandidate({
            key: `conta-atrasada:${b.id}:${b.date}`,
            group: "contas",
            tone: "danger",
            icon: "alertTriangle",
            title: "Conta em atraso",
            message: `${b.label} venceu em ${fmtDateShort(b.date)} e ainda não foi lançada. ${fmtBRL(b.amount)}.`,
            tab: "calendar",
            amount: b.amount,
          }));
          return;
        }
        if (b.daysLeft > NOTIF_BILL_DAYS) return;
        const quando = b.daysLeft <= 0 ? "hoje" : (b.daysLeft === 1 ? "amanhã" : `em ${b.daysLeft} dias`);
        out.push(notifCandidate({
          key: `conta:${b.id}:${b.date}`,
          group: "contas",
          tone: b.daysLeft <= 1 ? "warn" : "info",
          icon: "calendar",
          title: `Vence ${quando}`,
          message: `${b.label}. ${fmtBRL(b.amount)} em ${fmtDateShort(b.date)}.`,
          tab: "calendar",
          amount: b.amount,
        }));
      });
      // Evita que um mês cheio de parcelas gere vinte avisos de uma vez: os
      // mais próximos primeiro, teto de 5.
      return out
        .sort((a, b) => NOTIF_TONE_ORDER[a.tone] - NOTIF_TONE_ORDER[b.tone])
        .slice(0, 5)
        .map((c) => ({ ...c, createdAt: today }));
    },
  },

  // ---- Dívidas cadastradas: saldo desatualizado e parcela insuficiente ----
  {
    id: "dividas",
    run({ data, today }) {
      if (typeof buildDebtModel !== "function") return [];
      const model = buildDebtModel(data);
      const out = [];
      model.debts.forEach((debt) => {
        if (model.staleIds.includes(debt.id)) out.push(notifCandidate({
          key:`divida-saldo:${debt.id}:${today.slice(0,7)}`, group:"dividas", tone:"warn", icon:"refresh",
          title:"Saldo de dívida precisa ser conferido", message:`Confira o saldo atual de ${debt.name} no credor antes de confiar na projeção.`, tab:"debts", amount:debt.value,
        }));
        if (model.simulation.negativeAmortizationIds.includes(debt.id)) out.push(notifCandidate({
          key:`divida-amortizacao:${debt.id}:${today.slice(0,7)}`, group:"dividas", tone:"danger", icon:"alertTriangle",
          title:"Parcela pode não reduzir a dívida", message:`A parcela de ${debt.name} pode ser menor ou igual aos juros do mês.`, tab:"debts", amount:debt.monthlyPayment,
        }));
      });
      return out.slice(0,4);
    },
  },

  // ---- Orçamento estourado / em risco -------------------------------------
  {
    id: "orcamento",
    run({ data, monthKey }) {
      const status = computeBudgetStatus(data, monthKey);
      const out = [];
      status.items.forEach((it) => {
        if (it.level === "over") {
          out.push(notifCandidate({
            key: `orcamento:${it.id}:${monthKey}:over`,
            group: "orcamento",
            tone: "danger",
            icon: "alertTriangle",
            title: `Orçamento estourado em ${it.name}`,
            message: `${fmtBRL(it.spent)} de ${fmtBRL(it.budget)}. ${Math.round(it.pct)}% do teto do mês.`,
            tab: "settings",
            amount: it.spent,
          }));
        } else if (it.willExceed) {
          out.push(notifCandidate({
            key: `orcamento:${it.id}:${monthKey}:risco`,
            group: "orcamento",
            tone: "warn",
            icon: "trendUp",
            title: `${it.name} deve estourar o teto`,
            message: `No ritmo atual o mês fecha em ${fmtBRL(it.projected)}, acima dos ${fmtBRL(it.budget)} combinados.`,
            tab: "settings",
            amount: it.projected,
          }));
        }
      });
      return out.slice(0, 4);
    },
  },

  // ---- Assinaturas: reajuste, cobrança que parou e proposta de cadastro ----
  {
    id: "assinaturas",
    run({ data, monthKey, models }) {
      const rec = models.recurring || buildRecurringModel(data, { monthKey });
      const out = [];

      rec.increases.slice(0, 3).forEach((s) => {
        out.push(notifCandidate({
          key: `assinatura-reajuste:${s.key}:${monthKey}`,
          group: "assinaturas",
          tone: "warn",
          icon: "trendUp",
          title: `${s.name} ficou mais cara`,
          message: `Aumento de ${fmtNum(s.increasePct)}%. ${fmtBRL(s.increaseAnnualImpact)} a mais por ano se o preço se mantiver.`,
          tab: "subscriptions",
          amount: s.increaseAnnualImpact,
        }));
      });

      rec.ended.slice(0, 3).forEach((s) => {
        out.push(notifCandidate({
          key: `assinatura-parou:${s.key}`,
          group: "assinaturas",
          tone: "info",
          icon: "checkCircle",
          title: `${s.name} parou de cobrar`,
          message: `Sem cobrança desde ${fmtDateShort(s.lastDate)}. Saiu do total do mês; se voltar a aparecer, volta sozinha.`,
          tab: "subscriptions",
          amount: s.monthlyEquivalent,
        }));
      });

      (rec.proposals || []).slice(0, 2).forEach((p) => {
        out.push(notifCandidate({
          key: `recorrente-proposta:${p.key}`,
          group: "assinaturas",
          tone: "info",
          icon: "refresh",
          title: "Gasto recorrente detectado",
          message: `${p.pattern} · ${p.name}. ${fmtBRL(p.amount)}. Deseja cadastrar como gasto recorrente?`,
          tab: "subscriptions",
          amount: p.amount,
        }));
      });

      return out;
    },
  },

  // ---- Metas: atraso e conclusão ------------------------------------------
  {
    id: "metas",
    run({ data, monthKey, refDate }) {
      const gm = buildGoalsModel(data, refDate);
      const out = [];
      gm.goals.forEach((g) => {
        if (g.done) {
          out.push(notifCandidate({
            key: `meta-concluida:${g.id}`,
            group: "metas",
            tone: "positive",
            icon: "target",
            title: `Meta concluída: ${g.goal.name}`,
            message: `Você chegou aos ${fmtBRL(g.target)}. É o tipo de coisa que merece ser lembrada.`,
            tab: "goals",
            amount: g.target,
          }));
        } else if (g.status === "late") {
          out.push(notifCandidate({
            key: `meta-atrasada:${g.id}:${monthKey}`,
            group: "metas",
            tone: "warn",
            icon: "alertTriangle",
            title: `${g.goal.name} passou do prazo`,
            message: `Faltam ${fmtBRL(g.remaining)}. Vale rever o prazo ou o aporte mensal em vez de deixar a meta vencida.`,
            tab: "goals",
            amount: g.remaining,
          }));
        }
      });
      return out.slice(0, 4);
    },
  },

  // ---- Saldo projetado negativo -------------------------------------------
  {
    id: "saldo",
    run({ data, models }) {
      const fc = models.forecast || buildForecast(data);
      if (!fc.negativeDayIso) return [];
      const days = daysBetweenIso(fc.today, fc.negativeDayIso);
      if (days > 30) return [];   // além de 30 dias a previsão é média, não fato
      return [notifCandidate({
        key: `saldo-negativo:${fc.negativeDayIso}`,
        group: "saldo",
        tone: "danger",
        icon: "alertTriangle",
        title: "Saldo pode ficar negativo",
        message: `Pela previsão, o saldo cruza o zero em ${fmtDateFull(fc.negativeDayIso)}; daqui a ${days} ${days === 1 ? "dia" : "dias"}.`,
        tab: "calendar",
        amount: fc.lowest ? fc.lowest.value : null,
      })];
    },
  },

  // ---- Patrimônio e reserva -----------------------------------------------
  {
    id: "patrimonio",
    run({ data, monthKey }) {
      const out = [];
      const fund = emergencyFund(data);
      if (fund.target > 0 && moneyCompare(fund.current, fund.target) >= 0) {
        out.push(notifCandidate({
          key: `reserva-completa:${monthKey}`,
          group: "patrimonio",
          tone: "positive",
          icon: "shieldCheck",
          title: "Reserva de emergência completa",
          message: `Você alcançou ${fmtBRL(fund.current)}; os ${fund.targetMonths} ${fund.targetMonths === 1 ? "mês" : "meses"} de despesa que definiu como alvo.`,
          tab: "health",
          amount: fund.current,
        }));
      }

      const series = netWorthSeries(data, 3);
      if (series.length >= 2) {
        const last = series[series.length - 1];
        const prev = series[series.length - 2];
        if (prev.value > 0) {
          const dropPct = safePct(subMoney(prev.value, last.value), prev.value);
          if (moneyCompare(last.value, prev.value) < 0 && dropPct >= NOTIF_NETWORTH_DROP_PCT) {
            out.push(notifCandidate({
              key: `patrimonio-queda:${monthKey}`,
              group: "patrimonio",
              tone: "warn",
              icon: "arrowDownRight",
              title: "Patrimônio caiu no mês",
              message: `Queda de ${fmtNum(dropPct)}% em relação ao mês anterior (${fmtBRL(subMoney(prev.value, last.value))}).`,
              tab: "wealth",
              amount: subMoney(prev.value, last.value),
            }));
          }
        }
      }
      return out;
    },
  },

  // ---- Conquistas desbloqueadas hoje --------------------------------------
  // A fonte é o próprio registro gravado pelo Módulo 6 (`achievements.unlocked`
  // = { id: data }). A central não reavalia nenhuma regra de conquista: ela só
  // conta o que já foi desbloqueado.
  {
    id: "conquistas",
    run({ data, today }) {
      const unlocked = (data.achievements && data.achievements.unlocked) || {};
      const out = [];
      Object.keys(unlocked).forEach((id) => {
        if (unlocked[id] !== today) return;
        const def = typeof ACHIEVEMENTS !== "undefined"
          ? ACHIEVEMENTS.find((a) => a.id === id)
          : null;
        out.push(notifCandidate({
          key: `conquista:${id}`,
          group: "conquistas",
          tone: "positive",
          icon: def && def.icon ? def.icon : "star",
          title: `Conquista desbloqueada: ${def ? def.name : id}`,
          message: def && def.desc ? def.desc : "Uma nova medalha entrou na sua coleção.",
          tab: "achievements",
        }));
      });
      return out.slice(0, 5);
    },
  },

  // ---- Backup: o dado só existe neste aparelho ------------------------------
  // É o único aviso da central que não fala de dinheiro, e é o mais caro de
  // ignorar. Todo o resto do app é reconstituível a partir dos lançamentos; os
  // lançamentos, não. Limpar os dados do site, trocar de celular ou reinstalar
  // o navegador apaga tudo, e até aqui o único socorro era o usuário ter
  // lembrado sozinho de exportar.
  //
  // Dois portões para o aviso não virar ruído: só nasce quando há histórico que
  // valha a pena perder, e a chave carrega o mês, então ele se repete no
  // máximo uma vez por mês em vez de uma vez por render.
  {
    id: "backup",
    run({ data, today, monthKey }) {
      const txs = data.transactions || [];
      const temPatrimonio = (data.assets || []).length > 0 || (data.goals || []).length > 0;
      if (txs.length < NOTIF_BACKUP_MIN_TX && !temPatrimonio) return [];

      const last = data.lastBackupAt || null;

      if (!last) {
        return [notifCandidate({
          key: `backup:nunca:${monthKey}`,
          group: "backup",
          tone: "warn",
          icon: "shieldCheck",
          title: "Seus dados só existem neste aparelho",
          message: `${plural(txs.length, "lançamento", "lançamentos")} sem cópia. Trocar de celular ou limpar os dados do navegador apaga tudo. Exporte o backup em Ajustes.`,
          tab: "settings",
        })];
      }

      const dias = Math.floor((Date.parse(`${today}T12:00:00`) - Date.parse(`${last}T12:00:00`)) / 86400000);
      if (!Number.isFinite(dias) || dias < NOTIF_BACKUP_STALE_DAYS) return [];

      // Backup velho só incomoda se houve movimento depois dele. Quem parou de
      // usar o app não precisa de lembrete mensal para exportar o mesmo arquivo.
      const novos = txs.filter((t) => (t.createdAt || "").slice(0, 10) > last).length;
      if (novos === 0) return [];

      return [notifCandidate({
        key: `backup:desatualizado:${monthKey}`,
        group: "backup",
        tone: "info",
        icon: "shieldCheck",
        title: "Backup desatualizado",
        message: `Seu último backup é de ${dias} dias atrás e ${plural(novos, "lançamento entrou", "lançamentos entraram")} depois dele.`,
        tab: "settings",
      })];
    },
  },
];

// Monta as candidatas do momento. `opts.models` permite injetar modelos já
// calculados (o app memoiza forecast e recorrências por identidade do snapshot);
// sem injeção, cada regra calcula o seu.
function buildNotificationCandidates(data, opts) {
  const options = opts || {};
  const today = options.today || todayIso();
  const monthKey = options.monthKey || monthKeyOf(today);
  const refDate = options.refDate || new Date();
  const muted = (options.muted && typeof options.muted === "object") ? options.muted : {};
  const ctx = { data, today, monthKey, refDate, models: options.models || {} };

  const out = [];
  NOTIF_RULES.forEach((rule) => {
    if (muted[rule.id]) return;
    let list = [];
    try { list = rule.run(ctx) || []; }
    catch (e) {
      if (typeof console !== "undefined") console.warn(`[NotificationService] regra "${rule.id}" falhou:`, e);
      list = [];
    }
    list.forEach((c) => { if (c && c.key && c.title) out.push(c); });
  });

  return out.sort((a, b) => NOTIF_TONE_ORDER[a.tone] - NOTIF_TONE_ORDER[b.tone]);
}

// Funde as candidatas ao estado guardado. PURA: devolve um estado novo e a
// lista do que nasceu agora; quem grava é o app.
//
// `silent` (primeiro boot) registra tudo já lido.
function syncNotificationState(current, candidates, opts) {
  const options = opts || {};
  const today = options.today || todayIso();
  const state = normalizeNotifications(current);
  const known = new Set(state.items.map((n) => n.key));

  const created = [];
  (candidates || []).forEach((c) => {
    if (!c || !c.key || known.has(c.key)) return;
    known.add(c.key);
    created.push({
      id: uid(),
      key: c.key,
      group: c.group || "contas",
      tone: c.tone || "info",
      icon: c.icon || "bell",
      title: String(c.title).slice(0, 120),
      message: String(c.message || "").slice(0, 300),
      tab: c.tab || "dashboard",
      amount: c.amount == null ? null : roundMoney(c.amount),
      createdAt: c.createdAt || today,
      readAt: options.silent ? today : null,
    });
  });

  const cutoff = isoOfDate(new Date(dateFromIso(today).getTime() - NOTIF_RETENTION_DAYS * 86400000));
  const items = created.concat(state.items)
    .filter((n) => n.createdAt >= cutoff)
    .sort((a, b) => (a.createdAt < b.createdAt ? 1 : a.createdAt > b.createdAt ? -1 : NOTIF_TONE_ORDER[a.tone] - NOTIF_TONE_ORDER[b.tone]))
    .slice(0, NOTIF_MAX_ITEMS);

  return {
    state: { items, muted: { ...state.muted }, lastSyncAt: today, initialized: true },
    created: created.filter((n) => !n.readAt),
  };
}

function markNotificationRead(current, id, todayIsoStr) {
  const state = normalizeNotifications(current);
  const today = todayIsoStr || todayIso();
  return {
    ...state,
    items: state.items.map((n) => (n.id === id && !n.readAt ? { ...n, readAt: today } : n)),
  };
}

function markAllNotificationsRead(current, todayIsoStr) {
  const state = normalizeNotifications(current);
  const today = todayIsoStr || todayIso();
  return { ...state, items: state.items.map((n) => (n.readAt ? n : { ...n, readAt: today })) };
}

function removeNotification(current, id) {
  const state = normalizeNotifications(current);
  return { ...state, items: state.items.filter((n) => n.id !== id) };
}

// Limpa só o que já foi lido: o não lido é justamente o que o usuário ainda não
// viu, e apagá-lo junto seria esconder informação em vez de organizar.
function clearReadNotifications(current) {
  const state = normalizeNotifications(current);
  return { ...state, items: state.items.filter((n) => !n.readAt) };
}

function setNotificationGroupMuted(current, group, muted) {
  const state = normalizeNotifications(current);
  const next = { ...state.muted };
  if (muted) next[group] = todayIso();
  else delete next[group];
  return { ...state, muted: next };
}

function notificationCounts(current) {
  const state = normalizeNotifications(current);
  const byGroup = {};
  let unread = 0;
  let urgent = 0;
  state.items.forEach((n) => {
    byGroup[n.group] = (byGroup[n.group] || 0) + 1;
    if (!n.readAt) {
      unread++;
      if (n.tone === "danger") urgent++;
    }
  });
  return { total: state.items.length, unread, urgent, byGroup };
}

// Modelo de leitura da tela: agrupado por período, já com o rótulo pronto.

function buildNotificationsModel(current, opts) {
  const options = opts || {};
  const state = normalizeNotifications(current);
  const today = options.today || todayIso();
  const filter = options.filter || "all";

  const visible = state.items.filter((n) => {
    if (filter === "unread") return !n.readAt;
    if (filter === "all") return true;
    return n.group === filter;
  });

  const yesterday = isoOfDate(new Date(dateFromIso(today).getTime() - 86400000));
  const buckets = [
    { id: "hoje", label: "Hoje", items: [] },
    { id: "ontem", label: "Ontem", items: [] },
    { id: "antes", label: "Anteriores", items: [] },
  ];
  visible.forEach((n) => {
    const b = n.createdAt >= today ? buckets[0] : (n.createdAt === yesterday ? buckets[1] : buckets[2]);
    b.items.push({ ...n, groupLabel: notifGroupMeta(n.group).label, dateLabel: fmtDateShort(n.createdAt) });
  });

  return {
    filter,
    counts: notificationCounts(state),
    groups: NOTIF_GROUPS.map((g) => ({
      ...g,
      muted: !!state.muted[g.id],
      count: state.items.filter((n) => n.group === g.id).length,
    })),
    buckets: buckets.filter((b) => b.items.length > 0),
    hasAny: state.items.length > 0,
    visibleCount: visible.length,
    lastSyncAt: state.lastSyncAt,
  };
}

const NotificationService = {
  groups: NOTIF_GROUPS,
  build: buildNotificationCandidates,
  sync: syncNotificationState,
  model: buildNotificationsModel,
  counts: notificationCounts,
  markRead: markNotificationRead,
  markAllRead: markAllNotificationsRead,
  remove: removeNotification,
  clearRead: clearReadNotifications,
  setMuted: setNotificationGroupMuted,
};

/* ==============================================================================
 * 4. REGISTRO
 * ==============================================================================
 * Um endereço único para a camada de serviços. A UI conversa com `Services.x`;
 * os motores continuam acessíveis diretamente para quem já os usava; nada foi
 * removido nem renomeado.
 */
const Services = {
  bus: EventBus,
  finance: FinanceService,
  budget: BudgetService,
  investment: InvestmentService,
  analytics: AnalyticsService,
  insight: InsightService,
  notification: NotificationService,
};

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    EventBus, APP_EVENTS, Services,
    FinanceService, BudgetService, InvestmentService, AnalyticsService, InsightService, NotificationService,
    buildNotificationCandidates, syncNotificationState, buildNotificationsModel,
    notificationCounts, markNotificationRead, markAllNotificationsRead,
    removeNotification, clearReadNotifications, setNotificationGroupMuted,
    NOTIF_GROUPS,
  };
}

// source: js/screens/_shared.js
// js/screens/_shared.js. Peças de UI reaproveitadas por mais de uma tela. Só HTML: nenhum cálculo
// financeiro e nenhuma escrita de estado moram aqui.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

function renderCalculationButton(id, label) {
  return `<button class="calculation-link" data-action="calculation-open" data-id="${escapeHtml(id)}">${svgIcon("info", 14)} ${escapeHtml(label || "Como foi calculado")}</button>`;
}

function renderCalculationKinds(kinds) {
  return `<div class="calculation-kinds">${(kinds || []).map((id) => {
    const meta = CALCULATION_KIND[id] || CALCULATION_KIND.estimated;
    return `<span class="calculation-kind calculation-kind--${meta.id}">${svgIcon(meta.icon, 13)} ${escapeHtml(meta.label)}</span>`;
  }).join("")}</div>`;
}

// ---- Score financeiro (motor em score.js) ----
function renderScoreGauge(score, color, size) {
  const s = size || 88;
  const stroke = Math.round(s * 0.1);
  const r = s / 2 - stroke / 2 - 1;
  const c = 2 * Math.PI * r;
  const len = Math.max(0, clamp(score, 0, 100) / 100 * c);
  return `<div class="score-gauge" data-ui-css="width:${s}px;height:${s}px">
    <svg viewBox="0 0 ${s} ${s}" width="${s}" height="${s}" aria-hidden="true">
      <circle cx="${s / 2}" cy="${s / 2}" r="${r}" fill="none" stroke="var(--border)" stroke-width="${stroke}"/>
      <circle cx="${s / 2}" cy="${s / 2}" r="${r}" fill="none" stroke="${color}" stroke-width="${stroke}"
        stroke-dasharray="${len} ${c - len}" stroke-linecap="round" transform="rotate(-90 ${s / 2} ${s / 2})"/>
    </svg>
    <span class="score-gauge__value" data-ui-css="color:${color}">${score}</span>
  </div>`;
}

// ---- Mini gráfico de linha para a evolução patrimonial ----
function renderSparkline(series, color, width, height) {
  const w = width || 300;
  const h = height || 60;
  const values = series.map((p) => p.value);
  if (values.length < 2) return "";
  const min = Math.min(...values, 0);
  const max = Math.max(...values, 1);
  const span = max - min || 1;
  const pts = values.map((v, i) => {
    const x = (i / (values.length - 1)) * w;
    const y = h - ((v - min) / span) * (h - 6) - 3;
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  });
  const area = `0,${h} ${pts.join(" ")} ${w},${h}`;
  const gid = `spark-${Math.random().toString(36).slice(2, 8)}`;
  return `<svg class="sparkline" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Evolução do patrimônio">
    <defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="${color}" stop-opacity="0.28"/>
      <stop offset="100%" stop-color="${color}" stop-opacity="0"/>
    </linearGradient></defs>
    <polygon points="${area}" fill="url(#${gid})"/>
    <polyline points="${pts.join(" ")}" fill="none" stroke="${color}" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"/>
  </svg>`;
}

function renderEmptyState(icon, title, subtitle) {
  return `<div class="empty-state">
    <span class="empty-state__icon">${svgIcon(icon, 26)}</span>
    <p class="empty-state__title">${escapeHtml(title)}</p>
    ${subtitle ? `<p class="empty-state__subtitle">${escapeHtml(subtitle)}</p>` : ""}
  </div>`;
}

function renderTxRow(t) {
  if (t.type === "income") {
    return `<div class="tx-row" data-action="edit-tx" data-id="${t.id}">
      <div class="icon-bubble icon-bubble--income">${svgIcon("trendUp", 18)}</div>
      <div class="tx-info">
        <p class="tx-title">${escapeHtml(t.description || "Receita")}</p>
        <p class="tx-meta">${fmtDateShort(t.date)} · ${escapeHtml(t.payment)}</p>
      </div>
      <p class="tx-amount tx-amount--income">+${fmtBRL(t.amount)}</p>
      <button class="icon-btn" data-action="delete-tx" data-id="${t.id}" aria-label="Excluir">${svgIcon("x", 15)}</button>
    </div>`;
  }
  const cat = categoryById(state.data, t.categoryId);
  return `<div class="tx-row" data-action="edit-tx" data-id="${t.id}">
    <div class="icon-bubble" data-ui-css="background:color-mix(in srgb, ${cat.color} 14%, transparent); color:${cat.color}">${svgIcon(cat.icon, 18)}</div>
    <div class="tx-info">
      <p class="tx-title">${escapeHtml(t.description || cat.name)}</p>
      <p class="tx-meta">${escapeHtml(cat.name)} · ${fmtDateShort(t.date)} · ${escapeHtml(t.payment)}${t.recurring ? " · fixo" : ""}</p>
    </div>
    <p class="tx-amount tx-amount--expense">-${fmtBRL(t.amount)}</p>
    <button class="icon-btn" data-action="delete-tx" data-id="${t.id}" aria-label="Excluir">${svgIcon("x", 15)}</button>
  </div>`;
}

// ==================================================================
// CONTAS, CARTÕES E CONCILIAÇÃO
// ==================================================================
function moneyDraft(n) { return n ? Number(n).toFixed(2).replace(".", ",") : ""; }

function renderGoalRing(pct, color, icon, size) {
  const stroke = size * 0.1;
  const r = size / 2 - stroke / 2 - 1;
  const cx = size / 2, cy = size / 2;
  const c = 2 * Math.PI * r;
  const len = Math.max(0, clamp(pct, 0, 100) / 100 * c);
  return `<div class="goal-ring" data-ui-css="width:${size}px;height:${size}px">
    <svg viewBox="0 0 ${size} ${size}" width="${size}" height="${size}">
      <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--border)" stroke-width="${stroke}"/>
      <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${color}" stroke-width="${stroke}" stroke-dasharray="${len} ${c - len}" stroke-linecap="round" transform="rotate(-90 ${cx} ${cy})"/>
    </svg>
    <span class="goal-ring__icon" data-ui-css="color:${color}">${svgIcon(icon, size * 0.36)}</span>
  </div>`;
}

// source: js/screens/onboarding.js
// js/screens/onboarding.js; configuração inicial em 4 passos
//
// Toma a tela inteira no primeiro uso e some para sempre depois. Nada é gravado
// passo a passo: os campos vivem em `state.onboarding` e só viram dados reais
// (renda, conta, regra de orçamento) na confirmação final. Abandonar no meio,
// portanto, não deixa meia conta cadastrada.
//
// A ordem dos passos segue a dependência dos números, não a ordem do menu: a
// regra x/x/x é o último passo porque só faz sentido depois que existe uma renda
// para dividir; mostrar "50% de R$ 0,00" seria pedir uma decisão no escuro.
"use strict";

const ONB_STEPS = [
  { n: 1, label: "Boas-vindas" },
  { n: 2, label: "Renda" },
  { n: 3, label: "Conta" },
  { n: 4, label: "Orçamento" },
];

const ONB_SPLIT_PRESETS = [
  { id: "50/30/20", necessidade: 50, desejo: 30, futuro: 20, title: "50 / 30 / 20", hint: "O equilíbrio clássico. Bom ponto de partida para a maioria." },
  { id: "60/20/20", necessidade: 60, desejo: 20, futuro: 20, title: "60 / 20 / 20", hint: "Para quem tem custo fixo alto (aluguel, financiamento, filhos)." },
  { id: "40/20/40", necessidade: 40, desejo: 20, futuro: 40, title: "40 / 20 / 40", hint: "Foco agressivo em poupar. Exige custo fixo enxuto." },
];

function freshOnboarding() {
  return {
    open: false,
    // Assistente segurado: ver o bloco "O PORTÃO DO ASSISTENTE" abaixo.
    held: false,
    step: 1,
    name: "",
    income: "",
    account: { name: "", type: "corrente", balance: "" },
    skipAccount: false,
    legalAccepted: false,
    focus: "month",
    split: { necessidade: 50, desejo: 30, futuro: 20 },
  };
}

// ------------------------------------------------------------------------------
// O PORTÃO DO ASSISTENTE
// ------------------------------------------------------------------------------
// ESTE É O DEFEITO QUE DUPLICAVA A CONTA DO BANCO.
//
// Entrar numa conta troca o banco carregado por um banco NOVO e vazio: o
// conteúdo da conta só chega depois da primeira descida da nuvem. Quem decidia
// se o assistente abre olhava esse vazio e concluía "primeiro uso". O resultado
// aparecia logo depois do login: o assistente tomava a tela inteira e pedia
// nome, renda e conta do banco de novo. Quem respondia terminava com a conta do
// banco cadastrada duas vezes, a que desceu da nuvem e a que acabara de
// digitar, e sem nenhuma forma de apagar uma delas.
//
// O portão fecha o assistente enquanto a entrada na conta não termina.
// `refreshOnboardingGate` reavalia quando o conteúdo da conta chega, e só a
// liberação explícita, no fim da sequência de vínculo, pode reabrir.
function holdOnboardingGate() {
  state.onboarding.held = true;
  state.onboarding.open = false;
}

// O ASSISTENTE NUNCA TOMA UMA TELA QUE JÁ ESTÁ EM USO.
//
// Esta trava nasceu de um defeito relatado no beta, e ele era pior que o
// original. A liberação do portão espera `finishAccountBootstrap`, que roda um
// ciclo de sincronização inteiro: uma ida e volta na rede. Quem entrava numa
// conta ainda vazia via o painel carregar, navegava, e DOIS SEGUNDOS DEPOIS o
// assistente aparecia por cima, do nada, como se o aplicativo tivesse esquecido
// que a pessoa acabara de entrar. Nenhum clique provocou aquilo: foi a promessa
// da rede resolvendo tarde.
//
// Duas condições passaram a valer para o portão ABRIR o assistente:
//
//   1. A pessoa não pode ter encostado no aplicativo ainda. Um clique ou uma
//      tecla significam que a tela é dela; tomá-la depois disso é sequestro.
//   2. O banco carregado precisa ser o de VISITANTE. O assistente é a primeira
//      execução DO APARELHO, não DA CONTA. Quem entrou numa conta vazia vê o
//      aplicativo vazio, e refaz a configuração por Ajustes quando quiser; o
//      que ele não pode é ser recebido por um formulário de tela cheia toda vez
//      que a nuvem responder.
//
// Fechar continua livre, e sem `release` é a única coisa que esta função faz: o
// dado que chega da conta pode provar que a configuração já existe, nunca o
// contrário.

// Chamada do `onClick` e do `onInput`, os dois ouvintes da raiz. É o registro
// de que a tela passou para as mãos da pessoa. Mora no `state` e não numa
// variável de módulo porque é estado de sessão, igual ao `booting`.
function marcarAppEmUso() { state.appEmUso = true; }

// Devolve true quando a tela precisa ser redesenhada.
function refreshOnboardingGate(opts) {
  const liberar = !!(opts && opts.release);
  if (liberar) state.onboarding.held = false;
  const concluido = !!(state.data.onboarding && state.data.onboarding.done);
  const podeAbrir = liberar && !state.appEmUso
    && (typeof FinanceStore === "undefined" || FinanceStore.scope() === GUEST_SCOPE);
  const alvo = concluido ? false : (podeAbrir ? true : state.onboarding.open);
  if (alvo === state.onboarding.open) return false;
  state.onboarding.open = alvo;
  return true;
}

// Renda informada no passo 2, em reais. Usada pelo passo 4 para mostrar quanto
// cada grupo receberia de fato; percentual sozinho não ajuda a decidir.
function onbIncome() {
  const n = parseMoneyInput(state.onboarding.income);
  return Number.isFinite(n) && n > 0 ? roundMoney(n) : 0;
}

function onbSplitPresetId() {
  const s = state.onboarding.split;
  const found = ONB_SPLIT_PRESETS.find((p) => p.necessidade === s.necessidade && p.desejo === s.desejo && p.futuro === s.futuro);
  return found ? found.id : "";
}

// Cada passo diz por si só se pode avançar. Nenhum é obrigatório a não ser o
// segundo: sem renda, metade do app (regra x/x/x, score, previsão) fica muda.
function onbCanAdvance(step) {
  if (step === 1) return state.onboarding.legalAccepted === true;
  if (step === 2) return onbIncome() > 0;
  if (step === 3) {
    if (state.onboarding.skipAccount) return true;
    const a = state.onboarding.account;
    return !!String(a.name).trim() && Number.isFinite(parseMoneyInput(a.balance || "0"));
  }
  return true;
}

// POR QUE O MOTIVO DO BLOQUEIO PRECISA ESTAR ESCRITO NA TELA.
//
// "Continuar" e "Pular por agora" nascem desabilitados e nada dizia por quê:
// o usuário clicava, não acontecia nada, e não havia texto, title nem relação
// de acessibilidade que ligasse o botão morto ao aceite que faltava. Botão
// desabilitado sem explicação é um beco, e o passo 1 não era o único: o 2
// trava sem renda e o 3 sem nome e saldo da conta, com o mesmo silêncio.
//
// Cada passo passa a dizer em uma linha o que falta, e os botões apontam para
// essa linha por aria-describedby, para o leitor de tela anunciar a exigência
// junto do botão em vez de deixá-la solta no meio da tela.
function onbBlockReason(step) {
  if (step === 1) return "Marque o aceite da política e dos termos para continuar ou entrar na sua conta.";
  if (step === 2) return "Informe uma renda maior que zero para continuar.";
  if (step === 3) return "Dê um nome à conta e informe o saldo, ou marque a opção de cadastrar depois.";
  return "";
}

function renderOnboardingLayer() {
  const o = state.onboarding;
  const motivo = onbBlockReason(o.step);
  const travado = !onbCanAdvance(o.step);
  const body = o.step === 1 ? renderOnbWelcome()
    : o.step === 2 ? renderOnbIncome()
    : o.step === 3 ? renderOnbAccount()
    : renderOnbSplit();
  const last = o.step === 4;
  return `<div class="onb" role="dialog" aria-modal="true" aria-label="Configuração inicial">
    <div class="onb__sheet">
      <div class="onb__head">
        <div class="onb__brand">${svgIcon("wallet", 18)}<span>Cofre</span></div>
        <div class="onb__head-actions">
          <button class="btn btn--ghost btn--sm" data-action="onb-have-account" ${o.legalAccepted ? "" : `disabled aria-describedby="onb-block-reason"`}>Já tenho conta</button>
          <button class="btn btn--ghost btn--sm" data-action="onb-skip" ${o.legalAccepted ? "" : `disabled aria-describedby="onb-block-reason"`}>Pular por agora</button>
        </div>
      </div>
      ${renderOnbProgress(o.step)}
      <div class="onb__body">${body}</div>
      ${motivo ? `<p class="onb__block-hint" id="onb-block-reason" ${travado ? "" : "hidden"}>${svgIcon("info", 14)}<span>${motivo}</span></p>` : ""}
      <div class="onb__foot">
        ${o.step > 1 ? `<button class="btn btn--secondary" data-action="onb-back">${svgIcon("chevronLeft", 16)} Voltar</button>` : `<span></span>`}
        <button id="onb-advance" class="btn btn--primary" data-action="${last ? "onb-finish" : "onb-next"}" ${travado ? `disabled aria-describedby="onb-block-reason"` : ""}>
          ${last ? `${svgIcon("checkCircle", 16)} Concluir` : "Continuar"}
        </button>
      </div>
    </div>
  </div>`;
}

// O botão "Continuar" reage a cada tecla, mas re-renderizar a tela inteira
// enquanto se digita um valor com vírgula perde o cursor. Patch pontual, mesmo
// padrão de patchSubmitButton() na tela de lançamento.
function patchOnboardingFooter() {
  const pode = onbCanAdvance(state.onboarding.step);
  const btn = document.getElementById("onb-advance");
  const aviso = document.getElementById("onb-block-reason");
  if (btn) {
    btn.disabled = !pode;
    // O motivo só descreve o botão enquanto ele está travado. Um
    // aria-describedby fixo faria o leitor de tela anunciar, a cada foco, uma
    // exigência que o usuário já cumpriu.
    if (pode) btn.removeAttribute("aria-describedby");
    else btn.setAttribute("aria-describedby", "onb-block-reason");
  }
  // O aviso acompanha o botão no patch: sem isto ele continuaria na tela
  // depois de a renda ser digitada, contradizendo um botão já liberado.
  if (aviso) aviso.hidden = pode;
}

function renderOnbProgress(step) {
  return `<div class="onb__progress" role="group" aria-label="Passo ${step} de 4">
    ${ONB_STEPS.map((s) => `<div class="onb__step ${s.n === step ? "active" : ""} ${s.n < step ? "done" : ""}">
      <span class="onb__step-bar"></span>
      <span class="onb__step-label">${s.label}</span>
    </div>`).join("")}
  </div>`;
}

/* --------------------------------------------------------------- passo 1 */
function renderOnbWelcome() {
  return `<div class="onb__intro">
    <span class="onb__icon">${svgIcon("sparkles", 26)}</span>
    <h1 class="onb__title">Vamos deixar o app com a sua cara</h1>
    <p class="onb__lead">São quatro perguntas rápidas. Dá para mudar tudo depois em Ajustes.</p>
  </div>
  <label class="field">
    <span class="field__label" for="onb-name">Como você quer ser chamado?</span>
    <input id="onb-name" class="input" data-field="onb-name" value="${escapeHtml(state.onboarding.name)}" maxlength="40" placeholder="Seu primeiro nome" autocomplete="given-name" />
  </label>
  <p class="field-hint">Opcional. Serve só para a saudação da tela inicial.</p>
  <fieldset class="onb-focus">
    <legend class="field__label">Qual é seu objetivo principal agora?</legend>
    <div class="onb-focus__grid">
      ${DASHBOARD_FOCUS_OPTIONS.map((option) => `<button type="button" class="onb-focus__option ${state.onboarding.focus === option.id ? "active" : ""}" data-action="onb-focus" data-value="${option.id}" aria-pressed="${state.onboarding.focus === option.id ? "true" : "false"}">
        <span class="onb-focus__icon" aria-hidden="true">${svgIcon(option.icon, 18)}</span>
        <span><b>${escapeHtml(option.label)}</b><small>${escapeHtml(option.hint)}</small></span>
      </button>`).join("")}
    </div>
  </fieldset>
  <div class="onb__note">
    ${svgIcon("shieldCheck", 17)}
    <p>Sem conta, seus dados financeiros ficam neste aparelho. Recursos de IA só enviam o conteúdo descrito depois da sua confirmação.</p>
  </div>
  <details class="onb-legal-summary">
    <summary>Resumo da política e dos termos</summary>
    <p>O app organiza dados e produz estimativas educativas. Ele não substitui proposta, contrato, consultoria de investimentos ou análise do INSS. Sem conta, os dados ficam no navegador até você exportar ou apagar; com conta ligada, eles também são sincronizados com o servidor. IA e consulta de nota fiscal usam rede apenas quando você aciona esses recursos.</p>
    <p>A tela Privacidade traz a política inteira: controlador, prazos de retenção, seus direitos e o canal para incidentes.</p>
  </details>
  <label class="legal-consent"><input type="checkbox" data-action-select="onb-legal" ${state.onboarding.legalAccepted ? "checked" : ""} /><span>Li e aceito a política de privacidade e os termos de uso da versão ${LEGAL_TEXT_VERSION}.</span></label>`;
}

/* --------------------------------------------------------------- passo 2 */
function renderOnbIncome() {
  const income = onbIncome();
  return `<div class="onb__intro">
    <span class="onb__icon">${svgIcon("wallet", 26)}</span>
    <h1 class="onb__title">Quanto entra por mês?</h1>
    <p class="onb__lead">Some salário, pró-labore e o que for recorrente. Um valor aproximado já resolve.</p>
  </div>
  <label class="field">
    <span class="field__label" for="onb-income">Renda mensal</span>
    <input id="onb-income" class="input" data-field="onb-income" value="${escapeHtml(state.onboarding.income)}" inputmode="decimal" placeholder="0,00" />
  </label>
  ${income > 0
    ? `<p class="field-hint">Cerca de <b>${fmtBRL(mulMoney(income, 12))}</b> por ano, ou <b>${fmtBRL(mulMoney(income, 1 / 30))}</b> por dia.</p>`
    : `<p class="field-hint">É a base do orçamento, do score e da previsão. Sem ela, essas telas ficam sem referência.</p>`}
  <div class="onb__note">
    ${svgIcon("alertTriangle", 17)}
    <p>Renda variável? Use a média dos últimos meses. Dá para ajustar mês a mês depois.</p>
  </div>`;
}

/* --------------------------------------------------------------- passo 3 */
function renderOnbAccount() {
  const a = state.onboarding.account;
  const skipped = state.onboarding.skipAccount;
  return `<div class="onb__intro">
    <span class="onb__icon">${svgIcon("creditCard", 26)}</span>
    <h1 class="onb__title">Sua conta principal</h1>
    <p class="onb__lead">Com o saldo real cadastrado, o app mostra quanto você tem hoje, não só o que gastou.</p>
  </div>
  <div class="onb__fields ${skipped ? "onb__fields--off" : ""}">
    <label class="field">
      <span class="field__label" for="onb-acc-name">Nome da conta</span>
      <input id="onb-acc-name" class="input" data-field="onb-acc-name" value="${escapeHtml(a.name)}" maxlength="40" placeholder="Nubank, Itaú, carteira..." ${skipped ? "disabled" : ""} />
    </label>
    <div class="field-row">
      <label class="field">
        <span class="field__label" for="onb-acc-type">Tipo</span>
        <select id="onb-acc-type" class="input" data-action-select="onb-acc-type" ${skipped ? "disabled" : ""}>
          ${Object.keys(ACCOUNT_TYPE_LABELS).map((k) => `<option value="${k}" ${a.type === k ? "selected" : ""}>${escapeHtml(ACCOUNT_TYPE_LABELS[k])}</option>`).join("")}
        </select>
      </label>
      <label class="field">
        <span class="field__label" for="onb-acc-balance">Saldo de hoje</span>
        <input id="onb-acc-balance" class="input" data-field="onb-acc-balance" value="${escapeHtml(a.balance)}" inputmode="decimal" placeholder="0,00" ${skipped ? "disabled" : ""} />
      </label>
    </div>
  </div>
  <button class="onb__toggle ${skipped ? "active" : ""}" data-action="onb-skip-account" aria-pressed="${skipped ? "true" : "false"}">
    <span class="onb__toggle-box">${skipped ? svgIcon("check", 13) : ""}</span>
    <span>Cadastro depois. Quero só registrar gastos por enquanto.</span>
  </button>`;
}

/* --------------------------------------------------------------- passo 4 */
function renderOnbSplit() {
  const income = onbIncome();
  const active = onbSplitPresetId();
  const s = state.onboarding.split;
  return `<div class="onb__intro">
    <span class="onb__icon">${svgIcon("pie", 26)}</span>
    <h1 class="onb__title">Como dividir o que entra</h1>
    <p class="onb__lead">Necessidades são as contas que não dá para cortar. Desejos é o que melhora o mês. Futuro é o que fica.</p>
  </div>
  <div class="onb__presets">
    ${ONB_SPLIT_PRESETS.map((p) => `<button class="onb__preset ${active === p.id ? "active" : ""}" data-action="onb-split" data-value="${p.id}">
      <span class="onb__preset-title">${p.title}</span>
      <span class="onb__preset-hint">${p.hint}</span>
    </button>`).join("")}
  </div>
  ${income > 0 ? `<div class="onb__preview">
    ${BUDGET_GROUPS.map((g) => `<div class="onb__preview-row">
      <span class="onb__preview-label">${svgIcon(GROUP_ICONS[g], 15)} ${GROUP_LABELS[g]} <span class="onb__preview-pct">${s[g]}%</span></span>
      <span class="onb__preview-value">${fmtBRL(mulMoney(income, s[g] / 100))}</span>
    </div>`).join("")}
  </div>` : ""}
  ${renderOnbSeedPreview()}
  <p class="field-hint">Estourar um grupo nunca bloqueia um lançamento. O app avisa e a decisão continua sua.</p>`;
}

// POR QUE A PRÉVIA DOS TETOS EXISTE.
//
// Escolher "50 / 30 / 20" gravava só três percentuais. O motor de tetos por
// categoria (budgets.js) fica mudo enquanto nenhuma categoria tem limite, e a
// sugestão automática dele depende de histórico, que no primeiro dia não existe.
// Resultado: a pessoa escolhia um modelo de orçamento e não ganhava orçamento.
//
// Agora a conclusão semeia um teto por categoria principal a partir da regra
// escolhida. Como isso grava coisa que o usuário não digitou, ele precisa ver o
// que vai acontecer ANTES de concluir; daí a prévia ficar aberta a um toque, e
// não escondida em uma tela de ajustes que ele ainda não sabe que existe.
function renderOnbSeedPreview() {
  const income = onbIncome();
  if (!(income > 0)) return "";
  const seeds = seedBudgetsFromSplit(state.data, income, state.onboarding.split);
  if (seeds.items.length === 0 && seeds.kept.length === 0) return "";

  const n = seeds.items.length;
  const resumo = n === 0
    ? "Seus tetos atuais serão mantidos"
    : (n === 1 ? "Ver o teto sugerido para 1 categoria" : `Ver os tetos sugeridos para ${n} categorias`);

  return `<details class="onb-seed">
    <summary class="onb-seed__summary">${svgIcon("target", 14)}<span>${resumo}</span></summary>
    <div class="onb-seed__body">
      ${n > 0 ? `<div class="onb-seed__list">
        ${seeds.items.map((item) => `<div class="onb-seed__row">
          <span class="onb-seed__name">
            <span class="icon-bubble icon-bubble--sm" data-ui-css="${categoryBubbleCss(item.color)}">${svgIcon(item.icon, 13)}</span>
            ${escapeHtml(item.name)}
          </span>
          <span class="onb-seed__value">${fmtBRL(item.budget)}</span>
        </div>`).join("")}
      </div>` : ""}
      ${seeds.kept.length > 0 ? `<p class="field-hint" data-ui-css="margin:8px 0 0">${seeds.kept.length === 1
        ? "1 categoria já tem teto definido e não será alterada."
        : `${seeds.kept.length} categorias já têm teto definido e não serão alteradas.`}</p>` : ""}
      <p class="field-hint" data-ui-css="margin:8px 0 0">Ponto de partida do app, não regra de mercado. Cada teto é editável em Categorias, e passar de um deles nunca bloqueia um lançamento.</p>
    </div>
  </details>`;
}

/* ------------------------------------------------------------- conclusão */
// Uma única gravação para os quatro passos. Escrever a cada "Continuar"
// deixaria lixo no banco se o usuário fechasse a aba no meio.
function finishOnboarding() {
  const o = state.onboarding;
  const income = onbIncome();
  const name = String(o.name || "").trim().slice(0, 40);
  const wantsAccount = !o.skipAccount && !!String(o.account.name).trim();
  const balance = parseMoneyInput(o.account.balance || "0");
  // Calculado UMA vez, fora do setData, para que o texto do aviso e o que foi
  // de fato gravado venham do mesmo resultado. Recalcular dentro do reducer
  // abriria espaço para os dois divergirem.
  const seeds = seedBudgetsFromSplit(state.data, income, o.split);

  // A ordem importa: `setData` já renderiza. Fechar a camada antes evita um
  // quadro em que a tela de boas-vindas reaparece por um instante com os dados
  // novos atrás dela.
  state.onboarding.open = false;
  setData((d) => {
    const next = {
      ...d,
      userName: name,
      monthlyIncome: income,
      budgetSplit: { ...o.split },
      dashboardFocus: normalizeDashboardFocus(o.focus),
      dashboardLayout: applyDashboardFocus(d.dashboardLayout, o.focus),
      onboarding: { done: true, skipped: false, completedAt: todayIso() },
      privacy: acceptLegalTexts(d.privacy),
      categories: categoriesWithSeededBudgets(d.categories, seeds),
    };
    if (wantsAccount) {
      next.accounts = [...(d.accounts || []), makeAccount({
        name: String(o.account.name).trim(),
        type: o.account.type,
        openingBalance: Number.isFinite(balance) ? balance : 0,
        openingDate: todayIso(),
        color: "#0B6B5C",
      })];
    }
    // O snapshot do mês precisa nascer junto: budgetForCategory lê o snapshot
    // antes de olhar a categoria, então gravar teto sem atualizar o snapshot
    // deixaria o cartão de orçamentos vazio até a virada do mês.
    return withBudgetSnapshot(next);
  });

  state.form = freshTxForm();
  setState({ tab: "dashboard" });
  const saudacao = name ? `Tudo pronto, ${name}` : "Tudo pronto";
  notify(seeds.items.length > 0
    ? `${saudacao}. Tetos sugeridos em ${plural(seeds.items.length, "categoria", "categorias")}.`
    : saudacao);
}

// ------------------------------------------------------------------------------
// "JÁ TENHO CONTA": A SAÍDA QUE FALTAVA
// ------------------------------------------------------------------------------
// O assistente tomava a tela inteira e não oferecia nenhum caminho para entrar
// numa conta que já existe. Quem instalava o app num aparelho novo era obrigado
// a INVENTAR renda e conta do banco antes de conseguir chegar na tela de login,
// e o que ele inventava virava um segundo cadastro ao lado do que a conta já
// tinha. Pior: aquele conteúdo de visitante passava a exigir a confirmação de
// "juntar dados" em toda entrada, que é exatamente o botão que ninguém quer
// apertar para ver o próprio dinheiro.
//
// Nada de configuração é gravado aqui. Só o aceite legal, que é do APARELHO e
// nunca sobe para a conta (`privacy` está fora de SYNC_ALLOWED_SETTINGS), e que
// por isso não faz a base de visitante contar como conteúdo a vincular.
function openAccountFromOnboarding() {
  if (!state.onboarding.legalAccepted) { notify("Aceite a política e os termos para continuar", "warn"); return; }
  setData((d) => ({ ...d, privacy: acceptLegalTexts(d.privacy) }));
  // Segurado, não concluído: quem entrar numa conta vazia ainda precisa
  // configurar, e a liberação no fim do vínculo reabre o assistente.
  holdOnboardingGate();
  setState({ tab: "account" });
  notify("Entre com seu email e senha para trazer os dados da sua conta");
}

// Pular também é um desfecho: registramos para não perguntar de novo a cada
// abertura. `skipped` fica marcado para que Ajustes possa oferecer o assistente.
function skipOnboarding() {
  if (!state.onboarding.legalAccepted) { notify("Aceite a política e os termos para continuar", "warn"); return; }
  setData((d) => ({ ...d, onboarding: { done: true, skipped: true, completedAt: todayIso() }, privacy: acceptLegalTexts(d.privacy) }));
  state.onboarding.open = false;
  render();
}

// Reabertura manual (Ajustes). Os campos nascem preenchidos com o que já existe,
// então refazer a configuração é revisão, não digitação do zero.
function startOnboarding() {
  const d = state.data;
  const first = (d.accounts || []).find((a) => !a.archived);
  state.onboarding = {
    ...freshOnboarding(),
    open: true,
    step: 1,
    name: d.userName || "",
    income: d.monthlyIncome ? moneyDraft(d.monthlyIncome) : "",
    account: first
      ? { name: first.name, type: first.type, balance: moneyDraft(accountBalance(d, first.id, todayIso())) }
      : { name: "", type: "corrente", balance: "" },
    skipAccount: !!first,
    split: { ...d.budgetSplit },
    focus: normalizeDashboardFocus(d.dashboardFocus),
    legalAccepted: legalAccepted(d.privacy),
  };
  render();
}

// source: js/screens/dashboard.js
// js/screens/dashboard.js. Tela inicial. Montada a partir de UM modelo de leitura (`buildDashboardModel`,
// em metrics.js). Nenhum cálculo financeiro mora aqui.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// DASHBOARD
// ------------------------------------------------------------------
// A tela é montada a partir de UM modelo de leitura (`buildDashboardModel`,
// em metrics.js). Nenhum cálculo financeiro mora aqui; este bloco só
// transforma o modelo em HTML. Cartões antigos (orçamentos, vazamentos,
// assinaturas, extrato) foram preservados integralmente.
// ==================================================================
// A tela é montada a partir da ordem escolhida pelo usuário (layout.js). O
// `switch` abaixo é a ponte entre o id registrado e a função que desenha o
// cartão; nenhum cartão é chamado direto no corpo da tela. Custa uma linha por
// cartão e paga com a garantia de que tudo que aparece aqui pode ser desligado.
function renderDashboardCard(cardId, ctx) {
  switch (cardId) {
    case "hero":            return renderHeroCard(ctx.model);
    case "score":           return renderScoreCard(ctx.model);
    case "networth":        return renderNetWorthCard(ctx.model);
    case "reserve":         return renderReserveCard(ctx.model);
    case "goal":            return renderFeaturedGoalCard(ctx.model);
    case "bills":           return renderUpcomingBillsCard(ctx.model);
    case "forecast":        return renderForecastCard(null, false);
    case "summary":         return renderSmartSummaryCard(ctx.model);
    case "quickEntry":      return renderQuickEntryCard();
    case "advisor":         return renderAdvisorCard(ctx.mKey);
    case "assistant":       return renderAssistantCard(ctx.mKey);
    case "gamification":    return renderGamificationCard(achievementsModel());
    case "budgetHealth":    return renderBudgetHealth(ctx.refDate, ctx.isCurrentMonth, ctx.model.month.expense, ctx.fixedSpent, ctx.variableSpent);
    case "categoryBudgets": return renderCategoryBudgetsCard(ctx.mKey);
    case "budgetSplit":     return renderBudgetSplitCard(ctx.mKey);
    case "creditLimit":     return renderCreditLimitCard(ctx.mKey);
    case "leaks":           return renderLeakCard(ctx.mKey);
    case "subscriptions":   return renderSubscriptionsCard();
    case "breakdown":       return `<div class="card span-1">
      <p class="card-title">Para onde foi o dinheiro</p>
      ${renderCategoryBreakdown(ctx.model.ranking, ctx.model.month.expense)}
    </div>`;
    case "recent":          return `<div class="card span-2">
      <p class="card-title">Últimos lançamentos</p>
      ${ctx.recent.length === 0 ? renderEmptyState("wallet", "Nenhum lançamento ainda.", "Toque no botão + para começar.") : `<div class="tx-list">${ctx.recent.map((t) => renderTxRow(t)).join("")}</div>`}
    </div>`;
    default: return "";
  }
}

function renderDashboardScreen() {
  const refDate = addMonths(new Date(), state.monthOffset);
  const model = dashboardModel(refDate);
  const mKey = model.monthKey;
  const isCurrentMonth = model.isCurrentMonth;
  const { fixed: fixedSpent, variable: variableSpent } = realizedMonthTotals(state.data, mKey);

  const recent = [...state.data.transactions]
    .sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : (a.createdAt < b.createdAt ? 1 : -1)))
    .slice(0, 6);

  const pending = isCurrentMonth ? getPendingRecurring(state.data, mKey) : [];
  const showCarry = pending.length > 0 && state.data.dismissedCarryForwardMonth !== mKey;

  const ctx = { model, mKey, isCurrentMonth, refDate, fixedSpent, variableSpent, recent };
  const starting = isDashboardStarting(state.data);
  const cards = visibleDashboardCards(state.data.dashboardLayout, { isCurrentMonth, data: state.data });
  const body = starting
    ? `${renderHeroCard(model)}${renderDashboardStarter()}${cards.filter((c) => c.id !== "hero").map((c) => renderDashboardCard(c.id, ctx)).join("")}`
    : cards.map((c) => renderDashboardCard(c.id, ctx)).join("");

  return `<div class="screen ${starting ? "screen--starter" : ""}">
    ${renderDashboardHeader(model)}
    ${showCarry ? renderCarryBanner(pending) : ""}
    ${state.dashboardEditing ? renderDashboardCustomizer() : ""}

    <div class="grid-dashboard">
      ${body}
    </div>
  </div>`;
}

function renderDashboardStarter() {
  const hasAccount = Array.isArray(state.data.accounts) && state.data.accounts.length > 0;
  return `<div class="card card--starter span-3">
    <span class="starter-mark" aria-hidden="true">${svgIcon("arrowUpRight", 18)}</span>
    <div class="starter-copy">
      <p class="card-title">Comece pelo que aconteceu hoje</p>
      <p class="card-subtitle">${hasAccount
        ? "Registre uma receita ou despesa. Depois do primeiro lançamento, o Início passa a mostrar somente análises que já têm dados para calcular."
        : "Você pode lançar uma receita ou despesa agora. Cadastrar a conta depois deixa o saldo igual ao do banco."}</p>
    </div>
    <ol class="starter-steps" aria-label="Como começar">
      <li><b>Registre</b><span>uma movimentação</span></li>
      <li><b>Confira</b><span>o saldo do mês</span></li>
      <li><b>Planeje</b><span>com dados reais</span></li>
    </ol>
  </div>`;
}

// ==================================================================
// PERSONALIZAÇÃO DO INÍCIO
// ==================================================================
// Painel de configuração dentro da própria tela, e não escondido em Ajustes: o
// usuário decide o que mostrar olhando para o que está vendo.
//
// Reordenação por botões de subir/descer, não por arrastar. Arrastar dentro de
// uma página que também rola verticalmente é ruim no celular mesmo quando bem
// feito, e cada linha aqui já tem dois alvos de toque de 44px que funcionam de
// primeira.
function renderDashboardCustomizer() {
  const layout = normalizeDashboardLayout(state.data.dashboardLayout);
  const focus = normalizeDashboardFocus(state.data.dashboardFocus);
  const isCurrentMonth = state.monthOffset === 0;
  const counts = dashboardLayoutCounts(layout, { isCurrentMonth, data: state.data });

  return `<div class="card card--elevated dash-config">
    <div class="settings-row-header modal-header">
      <div>
        <p class="card-title" data-ui-css="margin:0">Personalizar o Início</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">${counts.visible} de ${counts.total} cartões visíveis. A ordem aqui é a ordem da tela.</p>
      </div>
      <button class="icon-btn" data-action="dash-customize-close" aria-label="Concluir personalização">${svgIcon("check", 17)}</button>
    </div>

    <fieldset class="dash-focus">
      <legend>Prioridade do Início</legend>
      <p class="field-hint">Muda a ordem sugerida. Cartões ocultos e fixados continuam como você escolheu.</p>
      <div class="dash-focus__options">
        ${DASHBOARD_FOCUS_OPTIONS.map((option) => `<button type="button" class="dash-focus__option ${focus === option.id ? "active" : ""}" data-action="dash-focus" data-value="${option.id}" aria-pressed="${focus === option.id ? "true" : "false"}">
          <span aria-hidden="true">${svgIcon(option.icon, 17)}</span>
          <span>${escapeHtml(option.label)}</span>
        </button>`).join("")}
      </div>
    </fieldset>

    <div class="dash-config-list">
      ${layout.order.map((id, i) => {
        const card = dashboardCardById(id);
        if (!card) return "";
        const hidden = layout.hidden.indexOf(id) !== -1;
        const relevant = isDashboardCardRelevant(state.data, id);
        const pinned = layout.pinned.indexOf(id) !== -1;
        const dormant = card.monthly && !isCurrentMonth;
        const visible = !hidden && !dormant && (relevant || pinned);
        return `<div class="dash-config-row ${visible ? "" : "dash-config-row--off"}">
          <div class="dash-config-row__moves">
            <button class="icon-btn" data-action="dash-card-move" data-id="${id}" data-value="up" ${i === 0 ? "disabled" : ""} aria-label="Subir ${escapeHtml(card.label)}">${svgIcon("chevronUp", 15)}</button>
            <button class="icon-btn" data-action="dash-card-move" data-id="${id}" data-value="down" ${i === layout.order.length - 1 ? "disabled" : ""} aria-label="Descer ${escapeHtml(card.label)}">${svgIcon("chevronDown", 15)}</button>
          </div>
          <div class="dash-config-row__text">
            <p class="dash-config-row__label">${escapeHtml(card.label)}${card.locked ? `<span class="dash-config-tag">fixo</span>` : ""}${!relevant && !card.locked ? `<span class="dash-config-tag">sem dados</span>` : ""}${pinned ? `<span class="dash-config-tag">mostrado por você</span>` : ""}${dormant ? `<span class="dash-config-tag">só no mês atual</span>` : ""}</p>
            <p class="dash-config-row__hint">${escapeHtml(card.hint)}</p>
          </div>
          ${card.locked
            ? `<span class="dash-config-row__lock" aria-hidden="true">${svgIcon("shieldCheck", 16)}</span>`
            : `<button class="switch ${visible ? "active" : ""}" data-action="dash-card-toggle" data-id="${id}" data-value="${visible ? "hide" : "show"}" role="switch" aria-checked="${visible ? "true" : "false"}" aria-label="${visible ? "Ocultar" : "Mostrar"} ${escapeHtml(card.label)}"><span class="switch__knob"></span></button>`}
        </div>`;
      }).join("")}
    </div>

    <div class="settings-actions" data-ui-css="margin-top:12px">
      <button class="btn btn--ghost btn--sm" data-action="dash-layout-reset">${svgIcon("refresh", 15)} Restaurar padrão</button>
      <button class="btn btn--primary btn--sm" data-action="dash-customize-close">${svgIcon("check", 15)} Concluir</button>
    </div>
  </div>`;
}

// ---- Cabeçalho: saudação dependente da hora + nome + navegação de meses ----
function renderDashboardHeader(m) {
  const g = m.greeting;
  const hello = `${g.text}${m.firstName ? `, ${escapeHtml(m.firstName)}` : ""}`;
  const title = m.isCurrentMonth
    ? "Seu resumo financeiro"
    : `Resumo de ${MONTH_NAMES[m.refDate.getMonth()]}`;
  return `<div class="screen-header">
    <div class="dash-greeting">
      <p class="dash-greeting__hello">${svgIcon(g.icon, 15, "dash-greeting__icon")}<span>${hello}</span></p>
      <h1 class="page-title">${title}</h1>
    </div>
    <div class="header-actions">
      <button class="icon-btn ${state.dashboardEditing ? "icon-btn--active" : ""}" data-action="dash-customize-toggle" aria-pressed="${state.dashboardEditing ? "true" : "false"}" aria-label="Personalizar os cartões do Início">${svgIcon("layout", 18)}</button>
      ${renderNotificationBell()}
      <div class="month-switcher">
        <button class="icon-btn" data-action="month-prev" aria-label="Mês anterior">${svgIcon("chevronLeft", 18)}</button>
        <span class="month-label">${MONTH_ABBR[m.refDate.getMonth()]} ${m.refDate.getFullYear()}</span>
        <button class="icon-btn" data-action="month-next" aria-label="Próximo mês" ${state.monthOffset >= 0 ? "disabled" : ""}>${svgIcon("chevronRight", 18)}</button>
      </div>
    </div>
  </div>`;
}

// [M8] Sino com contador. O badge mostra o NÃO LIDO, não o total: um número que
// nunca zera deixa de ser informação e vira decoração.
function renderNotificationBell() {
  const c = notificationCountsNow();
  const label = c.unread > 0
    ? `Notificações. ${c.unread} não ${c.unread === 1 ? "lida" : "lidas"}`
    : "Notificações";
  return `<button class="notif-bell ${c.urgent > 0 ? "notif-bell--urgent" : ""}" data-action="nav" data-tab="notifications" aria-label="${label}">
    ${svgIcon("bell", 19)}
    ${c.unread > 0 ? `<span class="notif-bell__badge">${c.unread > 9 ? "9+" : c.unread}</span>` : ""}
  </button>`;
}

// ---- Painel principal: saldo, entradas, gastos e economia do mês ----
function renderHeroCard(m) {
  const saved = m.month.savings;
  const savedTone = saved >= 0 ? "hero-chip--save" : "hero-chip--warn";
  const accounts = accountsSummary(state.data, todayIso());

  // OS TRÊS CHIPS PRECISAM FECHAR A CONTA ENTRE SI.
  //
  // Antes, "Receitas do mês" vinha de `effectiveIncome` (renda DECLARADA, que
  // projeta o mês inteiro) enquanto "Economia do mês" vinha de `savings`
  // (renda REALIZADA menos gastos). Lado a lado, no mesmo cartão, davam
  // R$ 5.420 − R$ 214,90 = −R$ 214,90, e quem fizesse a conta de cabeça
  // concluía, com razão, que o aplicativo estava errado.
  //
  // Agora os três saem da MESMA base, a realizada: receitas lançadas menos
  // despesas lançadas é exatamente a economia exibida. A renda declarada não
  // some da tela; vira a linha de aviso abaixo, que é o lugar honesto dela
  // enquanto o dinheiro não entrou de verdade.
  const rendaLancada = m.month.incomeRealized;
  const rendaPrevista = m.month.renda.planned;
  const rendaAReceber = m.month.partial ? subMoney(rendaPrevista, rendaLancada) : 0;
  return `<div class="card card--hero span-3">
    <div class="hero-glow"></div>
    <div class="hero-label-row"><p class="hero-label">${accounts.hasAccounts ? "Saldo em contas" : "Saldo calculado pelo histórico"}</p>${renderCalculationButton("accounts-balance")}</div>
    <p class="hero-value">${fmtBRL(accounts.cash)}</p>
    ${accounts.hasAccounts && accounts.cardDue > 0 ? `<p class="hero-reserved">${svgIcon("creditCard",14)} Após faturas abertas: <b>${fmtBRL(accounts.availableAfterCards)}</b></p>` : ""}
    ${m.worth.goals > 0 || m.worth.invested > 0
      ? `<p class="hero-reserved">${svgIcon("piggy", 14)} ${fmtBRL(addMoney(m.worth.goals, m.worth.invested))} em metas e investimentos (patrimônio, à parte deste saldo)</p>`
      : ""}
    ${rendaAReceber > 0
      ? `<p class="hero-reserved">${svgIcon("calendar", 14)} ${fmtBRL(rendaAReceber)} de renda declarada ainda não lançada neste mês</p>`
      : ""}
    ${/* O NÚMERO PRECISA CONFESSAR O QUE NÃO CONTA.
          Lançamento anterior à abertura da conta fica fora do saldo de
          propósito: o saldo inicial já embute o que veio antes dele. Só que ele
          continua entrando em "Despesas do mês", logo acima, e o painel passava
          a se contradizer em silêncio: a despesa aparecia e o saldo não se
          mexia. Dizer aqui, ao lado do número, é o que transforma isso de
          suspeita de erro em informação. */
      accounts.preOpening && accounts.preOpening.count
      ? `<p class="hero-reserved">${svgIcon("info", 14)} ${plural(accounts.preOpening.count, "lançamento anterior", "lançamentos anteriores")} à abertura das contas ${accounts.preOpening.count === 1 ? "está" : "estão"} fora deste saldo (${fmtBRL(accounts.preOpening.amount)})</p>`
      : ""}
    <div class="hero-chips">
      <div class="hero-chip hero-chip--in">${svgIcon("arrowUpRight", 17)}<div><span class="hero-chip__label">Receitas do mês</span><span class="hero-chip__value">${fmtBRL(rendaLancada)}</span></div></div>
      <div class="hero-chip hero-chip--out">${svgIcon("arrowDownRight", 17)}<div><span class="hero-chip__label">Despesas do mês</span><span class="hero-chip__value">${fmtBRL(m.month.expense)}</span></div></div>
      <div class="hero-chip ${savedTone}">${svgIcon(saved >= 0 ? "piggy" : "alertTriangle", 17)}<div><span class="hero-chip__label">Economia do mês</span><span class="hero-chip__value">${fmtBRL(saved)}</span></div></div>
    </div>
    <div class="hero-actions">
      <button class="hero-action hero-action--primary" data-action="nav" data-tab="add">${svgIcon("plus", 17)}Adicionar movimentação</button>
      ${dashboardHeroSecondaryActions().map((a) => `<button class="hero-action" data-action="nav" data-tab="${a.tab}">${svgIcon(a.icon, 15)}${a.label}</button>`).join("")}
    </div>
  </div>`;
}

function dashboardHeroSecondaryActions() {
  const d = state.data || {};
  const txCount = Array.isArray(d.transactions) ? d.transactions.length : 0;
  const hasAccounts = Array.isArray(d.accounts) && d.accounts.length > 0;
  const hasDebt = Array.isArray(d.assets) && d.assets.some((a) => a && (a.kind === "liability" || a.class === "divida"));
  const actions = [];

  if (hasDebt) actions.push({ tab: "debts", icon: "alertTriangle", label: "Planejar dívidas" });
  if (txCount === 0) actions.push({ tab: "import", icon: "upload", label: "Importar extrato" });
  else actions.push({ tab: "simulate", icon: "sparkles", label: "Simular gasto" });
  if (!hasAccounts) actions.push({ tab: "accounts", icon: "wallet", label: "Cadastrar conta" });
  else if (txCount === 0) actions.push({ tab: "accounts", icon: "wallet", label: "Ver contas" });

  return actions.slice(0, 2);
}

function renderScoreCard(m) {
  const s = m.score;
  if (!s) return "";
  if (s.insufficient) {
    return `<div class="card card--score span-1">
      <p class="card-title">Score financeiro</p>
      ${renderEmptyState("target", "Ainda não dá para calcular.", "Cadastre sua renda e alguns lançamentos para receber sua nota.")}
      <button class="btn btn--secondary btn--block btn--sm" data-action="nav" data-tab="settings">Informar minha renda</button>
      <button class="btn btn--ghost btn--block btn--sm" data-action="nav" data-tab="health">Ver saúde financeira</button>
    </div>`;
  }
  const expanded = state.scoreExpanded;
  const toneColor = { positive: "var(--positive)", warn: "var(--goal)", danger: "var(--negative)", neutral: "var(--ink-soft)" };
  return `<div class="card card--score span-1">
    <div class="score-head">
      ${renderScoreGauge(s.score, s.level.color)}
      <div class="score-head__text">
        <p class="card-title" data-ui-css="margin:0">Score financeiro</p>
        <p class="score-level" data-ui-css="color:${s.level.color}">${s.level.label}</p>
        <p class="score-note">${escapeHtml(s.level.note)}</p>
      </div>
    </div>

    <div class="score-reasons">
      ${s.reasons.slice(0, expanded ? s.reasons.length : 3).map((r) => `<div class="score-reason">
        <span class="score-reason__mark" data-ui-css="color:${toneColor[r.tone]}">${svgIcon(r.tone === "positive" ? "checkCircle" : "alertTriangle", 14)}</span>
        <span class="score-reason__text">${escapeHtml(r.text)}</span>
      </div>`).join("")}
    </div>

    ${expanded ? `<div class="score-pillars">
      ${s.pillars.map((p) => {
        const pct = p.applicable ? Math.round(p.ratio * 100) : 0;
        const color = !p.applicable ? "var(--ink-faint)" : (p.ratio >= 0.7 ? "var(--positive)" : p.ratio >= 0.4 ? "var(--goal)" : "var(--negative)");
        return `<div class="score-pillar">
          <div class="score-pillar__head">
            <span class="score-pillar__label">${svgIcon(p.icon, 13)} ${escapeHtml(p.label)}</span>
            <span class="score-pillar__points" data-ui-css="color:${color}">${p.applicable ? `${fmtNum(p.points)}/${p.weight}` : "sem dados"}</span>
          </div>
          <div class="progress progress--sm" data-ui-css="margin:0"><div class="progress__fill" data-ui-css="width:${pct}%; background:${color}"></div></div>
          ${p.advice ? `<p class="score-pillar__advice">${escapeHtml(p.advice)}</p>` : ""}
        </div>`;
      }).join("")}
      <p class="footnote">Pilares sem dados suficientes ficam fora da média; a nota nunca é penalizada por informação que você ainda não cadastrou.</p>
    </div>` : ""}

    <button class="btn btn--secondary btn--block btn--sm" data-action="nav" data-tab="health" data-ui-css="margin-top:14px">${svgIcon("shieldCheck", 15)} Ver saúde financeira</button>

    <button class="score-toggle" data-action="toggle-score-detail">
      <span>${expanded ? "Ocultar detalhes" : "Ver como é calculado"}</span>${svgIcon(expanded ? "chevronUp" : "chevronDown", 15)}
    </button>
  </div>`;
}

// ---- Patrimônio: total, composição e evolução ----
function renderNetWorthCard(m) {
  const w = m.worth;
  const series = netWorthSeries(state.data, 6);
  const first = series[0].value;
  const last = series[series.length - 1].value;
  const delta = subMoney(last, first);
  const deltaPct = first !== 0 ? (delta / Math.abs(first)) * 100 : null;
  const up = delta >= 0;
  const trendColor = up ? "var(--positive)" : "var(--negative)";

  const parts = [
    { label: "Em conta", value: Math.max(0, w.cash), color: "var(--brand)" },
    { label: "Investimentos", value: w.invested, color: "var(--goal)" },
    { label: "Em metas", value: w.goals, color: "var(--positive)" },
  ];
  const sum = parts.reduce((acc, p) => acc + p.value, 0);

  return `<div class="card card--networth span-2">
    <div class="networth-head">
      <div>
        <p class="card-title" data-ui-css="margin:0">Patrimônio</p>
        <p class="networth-value">${fmtBRL(w.total)}</p>
      </div>
      ${series.length > 1 ? `<span class="status-badge" data-ui-css="background:color-mix(in srgb, ${trendColor} 13%, transparent); color:${trendColor}">
        ${svgIcon(up ? "arrowUpRight" : "arrowDownRight", 12)} ${deltaPct == null ? fmtBRLShort(delta) : `${up ? "+" : ""}${deltaPct.toFixed(1)}%`}
      </span>` : ""}
    </div>

    ${renderSparkline(series, up ? "var(--brand)" : "var(--negative)")}
    <div class="networth-axis">${series.map((p) => `<span>${p.label}</span>`).join("")}</div>

    ${sum > 0 ? `<div class="segment-bar" data-ui-css="margin-top:14px">
      ${parts.filter((p) => p.value > 0).map((p) => `<div data-ui-css="flex:${p.value};background:${p.color}"></div>`).join("")}
    </div>` : ""}
    <div class="networth-legend">
      ${parts.map((p) => `<div class="networth-legend__item">
        <span class="cat-dot" data-ui-css="background:${p.color}"></span>
        <span class="networth-legend__label">${p.label}</span>
        <b>${fmtBRL(p.value)}</b>
      </div>`).join("")}
    </div>
    ${w.cash < 0 ? `<p class="footnote" data-ui-css="color:var(--negative)">Seu saldo em conta está negativo em ${fmtBRL(Math.abs(w.cash))}.</p>` : ""}
    <div class="networth-actions">
      ${renderCalculationButton("net-worth")}
      <button class="btn btn--secondary btn--sm" data-action="nav" data-tab="wealth">${svgIcon("layout", 15)} Patrimônio</button>
      <button class="btn btn--secondary btn--sm" data-action="nav" data-tab="invest">${svgIcon("trendUp", 15)} Carteira</button>
    </div>
  </div>`;
}

// ---- Reserva de emergência ----
function renderReserveCard(m) {
  const r = m.reserve;
  const meta = {
    ok:      { color: "var(--positive)", label: "Reserva completa" },
    partial: { color: "var(--goal)",     label: "Em construção" },
    low:     { color: "var(--negative)", label: "Reserva baixa" },
    empty:   { color: "var(--ink-faint)", label: "Sem reserva" },
  }[r.status];

  return `<div class="card card--reserve span-1">
    <div class="mini-card__head">
      <span class="icon-bubble icon-bubble--sm" data-ui-css="background:color-mix(in srgb, ${meta.color} 14%, transparent); color:${meta.color}">${svgIcon("shieldCheck", 16)}</span>
      <div>
        <p class="card-title" data-ui-css="margin:0">Reserva de emergência</p>
        <p class="mini-card__sub" data-ui-css="color:${meta.color}">${meta.label}</p>
      </div>
    </div>
    <p class="mini-card__value">${fmtBRL(r.current)}</p>
    <div class="progress progress--sm"><div class="progress__fill" data-ui-css="width:${clamp(r.pct, 0, 100)}%; background:${meta.color}"></div></div>
    <p class="mini-card__note">
      ${r.monthlyNeed > 0
        ? `Cobre <b>${r.monthsCovered.toFixed(1)}</b> de ${r.targetMonths} meses de despesa (${fmtBRL(r.monthlyNeed)}/mês).`
        : "Registre alguns gastos para calcular quantos meses sua reserva cobre."}
    </p>
    ${!r.configured
      ? `<button class="btn btn--secondary btn--block btn--sm" data-action="nav" data-tab="goals">Criar meta de reserva</button>`
      : `<p class="footnote" data-ui-css="margin-top:8px">Alvo: ${fmtBRL(r.target)}</p>`}
  </div>`;
}

// ---- Meta financeira em destaque ----
function renderFeaturedGoalCard(m) {
  const f = m.goal;
  if (!f) {
    return `<div class="card card--goal-featured span-1">
      <p class="card-title">Meta financeira</p>
      ${renderEmptyState("target", "Nenhuma meta ativa.", "Defina um objetivo para dar destino ao que você economiza.")}
      <button class="btn btn--goal btn--block btn--sm" data-action="nav" data-tab="goals">Criar minha primeira meta</button>
    </div>`;
  }
  const g = f.goal;
  const color = f.done ? "var(--positive)" : "var(--goal)";
  return `<div class="card card--goal-featured span-1">
    <div class="mini-card__head">
      ${renderGoalRing(f.pct, color, g.icon, 44)}
      <div>
        <p class="card-title" data-ui-css="margin:0">${escapeHtml(g.name)}</p>
        <p class="mini-card__sub" data-ui-css="color:${color}">${f.done ? `${svgIcon("checkCircle", 13)} Meta concluída` : `${f.pct.toFixed(0)}% concluída`}</p>
      </div>
    </div>
    <p class="mini-card__value">${fmtBRL(g.current)} <span class="mini-card__value-of">de ${fmtBRL(g.target)}</span></p>
    <div class="progress progress--sm"><div class="progress__fill" data-ui-css="width:${clamp(f.pct, 0, 100)}%; background:${color}"></div></div>
    <p class="mini-card__note">
      ${f.done ? "Você chegou lá. Que tal definir o próximo objetivo?"
        : f.daysLeft != null && f.daysLeft > 0
          ? `Faltam <b>${fmtBRL(f.remaining)}</b> e ${f.daysLeft} dias${f.monthlyNeeded ? `; cerca de ${fmtBRL(f.monthlyNeeded)}/mês.` : "."}`
          : f.daysLeft != null
            ? `Prazo vencido com <b>${fmtBRL(f.remaining)}</b> restantes.`
            : `Faltam <b>${fmtBRL(f.remaining)}</b> para concluir.`}
    </p>
    <button class="btn btn--goal-soft btn--block btn--sm" data-action="nav" data-tab="goals">Ver metas</button>
  </div>`;
}

// ---- Próximas contas (30 dias) ----
function renderUpcomingBillsCard(m) {
  const b = m.bills;
  if (b.items.length === 0) {
    return `<div class="card card--upcoming span-1">
      <p class="card-title">Próximas contas</p>
      ${renderEmptyState("bell", "Nada previsto para os próximos 30 dias.", "Parcelas e gastos fixos aparecem aqui automaticamente.")}
      <button class="btn btn--ghost btn--block btn--sm" data-action="nav" data-tab="calendar">${svgIcon("calendar", 14)} Ver no calendário</button>
    </div>`;
  }
  const KIND_LABEL = { late: "Atrasada", recurring: "Prevista", scheduled: "Agendada" };
  const KIND_COLOR = { late: "var(--negative)", recurring: "var(--goal)", scheduled: "var(--ink-faint)" };
  return `<div class="card card--upcoming span-1">
    <div class="mini-card__head">
      <div>
        <p class="card-title" data-ui-css="margin:0">Próximas contas</p>
        <p class="mini-card__sub">${b.items.length} nos próximos 30 dias</p>
      </div>
      <span class="leak-total">${fmtBRL(b.total)}</span>
    </div>
    <div class="bill-list">
      ${b.items.slice(0, 5).map((it) => `<div class="bill-row">
        <span class="icon-bubble icon-bubble--sm" data-ui-css="background:color-mix(in srgb, ${it.color} 14%, transparent); color:${it.color}">${svgIcon(it.icon, 14)}</span>
        <div class="bill-row__info">
          <p class="bill-row__label">${escapeHtml(it.label)}${it.installment ? ` <span class="bill-row__inst">${it.installment}</span>` : ""}</p>
          <p class="bill-row__meta" data-ui-css="color:${KIND_COLOR[it.kind]}">${KIND_LABEL[it.kind]} · ${fmtDateShort(it.date)}${it.kind !== "late" && it.daysLeft >= 0 ? ` · em ${it.daysLeft}d` : ""}</p>
        </div>
        <span class="bill-row__amount">${fmtBRL(it.amount)}</span>
      </div>`).join("")}
    </div>
    ${b.lateCount > 0 ? `<button class="btn btn--secondary btn--block btn--sm" data-action="carry-post-all">Lançar gastos fixos pendentes</button>` : ""}
    <button class="btn btn--ghost btn--block btn--sm" data-action="nav" data-tab="calendar">${svgIcon("calendar", 14)} Ver no calendário</button>
  </div>`;
}

// ---- Resumo inteligente do mês ----
function renderSmartSummaryCard(m) {
  const items = m.summary;
  if (!items || items.length === 0) return "";
  const tone = { positive: "var(--positive)", warn: "var(--goal)", danger: "var(--negative)", neutral: "var(--brand)" };
  return `<div class="card card--summary span-3">
    <div class="leak-header">
      ${svgIcon("sparkles", 18, "leak-header__icon")}
      <div>
        <p class="card-title" data-ui-css="margin:0">Resumo inteligente do mês</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">Leitura automática dos seus números, calculada no seu aparelho</p>
      </div>
    </div>
    <div class="summary-grid">
      ${items.map((it) => `<div class="summary-item" data-ui-css="--tone:${tone[it.tone]}">
        <span class="summary-item__icon">${svgIcon(it.icon, 16)}</span>
        <p class="summary-item__text">${escapeHtml(it.text)}</p>
      </div>`).join("")}
    </div>
  </div>`;
}

function renderLeakCard(mKey) {
  const { leaks, totalLeak, count } = detectSilentLeaks(state.data, mKey);
  if (leaks.length === 0) return "";
  return `<div class="card card--leak span-3">
    <div class="leak-header">
      ${svgIcon("drop", 18, "leak-header__icon")}
      <div>
        <p class="card-title" data-ui-css="margin:0">Vazamentos silenciosos</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">Pequenos gastos que se somam sem você perceber</p>
      </div>
      <span class="leak-total">${fmtBRL(totalLeak)}</span>
    </div>
    <div class="leak-list">
      ${leaks.map((l) => `<div class="leak-row">
        <span class="cat-dot" data-ui-css="background:${l.color}"></span>
        <span class="leak-name">${escapeHtml(l.label)}</span>
        <span class="leak-count">${l.count}x</span>
        <span class="leak-value">${fmtBRL(l.total)}</span>
      </div>`).join("")}
    </div>
    <p class="footnote" data-ui-css="margin-top:10px">Já foram ${count} lançamentos pequenos (até ${fmtBRL(40)}) neste mês.</p>
  </div>`;
}

function renderCarryBanner(pending) {
  const names = pending.slice(0, 3).map((t) => escapeHtml(t.description || categoryById(state.data, t.categoryId).name)).join(", ");
  const extra = pending.length > 3 ? ` +${pending.length - 3}` : "";
  return `<div class="banner">
    ${svgIcon("info", 20, "banner__icon")}
    <div class="banner__text">
      <strong>Gastos fixos do mês passado</strong>
      <span>${names}${extra}; deseja lançar novamente esse mês?</span>
    </div>
    <div class="banner__actions">
      <button class="btn btn--ghost btn--sm" data-action="carry-dismiss">Agora não</button>
      <button class="btn btn--primary btn--sm" data-action="carry-post-all">Lançar todos</button>
    </div>
  </div>`;
}

// Teto de fatura do cartão (Feature 3): compara os gastos do mês pagos em
// "Crédito" com o limite desejado que o usuário definiu em Ajustes.
function renderCreditLimitCard(mKey) {
  const limit = state.data.creditCardLimit || 0;
  const spent = creditSpentInMonth(state.data, mKey);
  if (limit <= 0) {
    if (spent <= 0) return "";
    return `<div class="card card--dashed span-3 banner-inline">
      ${svgIcon("creditCard", 30, "banner-inline__icon")}
      <div class="banner-inline__text">
        <strong>Já gastou ${fmtBRL(spent)} no crédito este mês</strong>
        <span>Defina um teto de fatura em Ajustes para acompanhar o quanto ainda cabe.</span>
      </div>
      <button class="btn btn--primary btn--sm" data-action="nav" data-tab="settings">Definir</button>
    </div>`;
  }
  const ratio = safeRatio(spent, limit);
  const color = ratio < 0.8 ? "var(--positive)" : ratio <= 1 ? "var(--goal)" : "var(--negative)";
  const remaining = subMoney(limit, spent);
  return `<div class="card span-3">
    <div class="health-header">
      <p class="card-title">Fatura do cartão de crédito</p>
      <span class="status-badge" data-ui-css="background:color-mix(in srgb, ${color} 16%, transparent); color:${color}">${svgIcon("creditCard", 13)}${fmtBRL(spent)} de ${fmtBRL(limit)}</span>
    </div>
    <div class="progress"><div class="progress__fill" data-ui-css="width:${clamp(ratio * 100, 0, 100)}%; background:${color}"></div></div>
    <p class="health-note">${remaining >= 0
      ? `Ainda cabem <b data-ui-css="color:${color}">${fmtBRL(remaining)}</b> na fatura deste mês antes de estourar o teto.`
      : `Você já passou <b data-ui-css="color:var(--negative)">${fmtBRL(Math.abs(remaining))}</b> do teto definido para a fatura.`}</p>
  </div>`;
}

function renderBudgetHealth(refDate, isCurrentMonth, monthExpense, fixedSpent, variableSpent) {
  const mKey = keyOfDate(refDate);
  const income = effectiveIncome(state.data, mKey);
  const remaining = subMoney(income, monthExpense);

  // Este cartão é de PLANEJAMENTO: ele responde "do que você espera receber,
  // quanto ainda dá para gastar", e por isso usa a renda declarada mesmo antes
  // de ela cair na conta. O cartão do saldo, logo acima, responde outra coisa
  // ("o que de fato entrou menos o que saiu"). Os dois números são corretos e
  // diferentes: o defeito era chamar os dois de sobra sem dizer a base. Com a
  // renda ainda não lançada, os rótulos passam a dizer `prevista`.
  const baseRenda = incomeBasis(state.data, mKey);
  const rendaPrevista = baseRenda.partial && baseRenda.planned > baseRenda.realized;
  const rotuloRenda = rendaPrevista ? "Renda prevista" : "Renda";
  const rotuloSobra = rendaPrevista ? "Sobra prevista" : "Sobra";

  if (income <= 0) {
    return `<div class="card card--dashed span-3 banner-inline">
      ${svgIcon("shieldCheck", 34, "banner-inline__icon")}
      <div class="banner-inline__text">
        <strong>Veja se suas contas estão no azul</strong>
        <span>Defina sua renda mensal em Ajustes para eu calcular quanto você ainda pode gastar.</span>
      </div>
      <button class="btn btn--primary btn--sm" data-action="nav" data-tab="settings">Definir</button>
    </div>`;
  }

  let dayOfMonth = refDate.getDate(), dim = 30, daysLeft = 0, dailyBudget = 0, projected = monthExpense;
  if (isCurrentMonth) {
    const now = new Date();
    dayOfMonth = now.getDate();
    dim = daysInMonthOf(now.getFullYear(), now.getMonth());
    daysLeft = Math.max(1, dim - dayOfMonth + 1);
    dailyBudget = remaining > 0 ? divMoney(remaining, daysLeft) : 0;
    projected = dayOfMonth > 0 ? mulMoney(monthExpense, dim / dayOfMonth) : monthExpense;
  }
  const ratio = safeRatio(projected, income);
  let status;
  if (!isCurrentMonth) {
    status = remaining >= 0 ? { label: "Fechou no azul", color: COLOR_VARS.positive, icon: "checkCircle" } : { label: "Fechou no vermelho", color: COLOR_VARS.negative, icon: "alertTriangle" };
  } else if (ratio <= 0.9) {
    status = { label: "No controle", color: COLOR_VARS.positive, icon: "shieldCheck" };
  } else if (ratio <= 1.05) {
    status = { label: "Atenção ao ritmo", color: COLOR_VARS.goal, icon: "alertTriangle" };
  } else {
    status = { label: "Acima da renda", color: COLOR_VARS.negative, icon: "alertTriangle" };
  }

  const note = isCurrentMonth
    ? (remaining > 0
      ? `No ritmo atual, você fecha o mês em <b>${fmtBRL(projected)}</b> de gastos. Ainda pode gastar cerca de <b data-ui-css="color:${status.color}">${fmtBRL(dailyBudget)} por dia</b> nos próximos ${daysLeft} dias.`
      : `Você já ultrapassou sua renda em <b data-ui-css="color:var(--negative)">${fmtBRL(Math.abs(remaining))}</b> este mês. Vale segurar os gastos esporádicos até o próximo salário.`)
    : (remaining >= 0
      ? `Sobraram <b data-ui-css="color:var(--positive)">${fmtBRL(remaining)}</b> depois de todos os gastos do mês.`
      : `Os gastos superaram a renda em <b data-ui-css="color:var(--negative)">${fmtBRL(Math.abs(remaining))}</b> neste mês.`);

  return `<div class="card span-3">
    <div class="health-header">
      <p class="card-title">Saúde financeira do mês</p>
      <span class="status-badge" data-ui-css="background:color-mix(in srgb, ${status.color} 16%, transparent); color:${status.color}">${svgIcon(status.icon, 13)}${status.label}</span>
    </div>
    <div class="health-grid">
      <div class="health-stat"><span>${rotuloRenda}</span><b>${fmtBRL(income)}</b></div>
      <div class="health-stat"><span>Gastos fixos</span><b>${fmtBRL(fixedSpent)}</b></div>
      <div class="health-stat"><span>Esporádicos</span><b>${fmtBRL(variableSpent)}</b></div>
      <div class="health-stat"><span>${rotuloSobra}</span><b data-ui-css="color:${remaining >= 0 ? "var(--positive)" : "var(--negative)"}">${fmtBRL(remaining)}</b></div>
    </div>
    <div class="progress"><div class="progress__fill" data-ui-css="width:${clamp(safePct(monthExpense, income), 0, 100)}%; background:${status.color}"></div></div>
    <p class="health-note">${note}</p>
  </div>`;
}

// ==================================================================
// FEATURE 1. Regra x/x/x (Necessidades / Desejos / Futuro)
// Três barras de progresso que mostram, para o mês corrente, o quanto já
// foi gasto em cada grupo em relação ao percentual da renda combinado
// para aquele grupo (ex: 50% Necessidades, 30% Desejos, 20% Futuro).
// ==================================================================
function renderBudgetSplitCard(mKey) {
  const income = effectiveIncome(state.data, mKey);
  if (income <= 0) return "";
  const spend = monthGroupSpend(state.data, mKey);
  return `<div class="card span-3">
    <div class="health-header">
      <p class="card-title" data-ui-css="margin:0">Regra de orçamento (Necessidades / Desejos / Futuro)</p>
      <button class="icon-btn icon-btn--muted" data-action="nav" data-tab="settings" aria-label="Ajustar percentuais">${svgIcon("gear", 15)}</button>
    </div>
    <div class="split-bars">
      ${BUDGET_GROUPS.map((g) => {
        const pctAllowed = state.data.budgetSplit[g];
        const allocated = mulMoney(income, pctAllowed / 100);
        const spent = spend[g];
        const ratio = safeRatio(spent, allocated);
        const color = ratio < 0.85 ? "var(--positive)" : ratio <= 1 ? "var(--goal)" : "var(--negative)";
        return `<div class="split-bar-row">
          <div class="split-bar-row__head">
            <span class="split-bar-row__label">${svgIcon(GROUP_ICONS[g], 14)}${GROUP_LABELS[g]} <span class="split-bar-row__pct">${pctAllowed}%</span></span>
            <span class="split-bar-row__value" data-ui-css="color:${color}">${fmtBRL(spent)} <span class="cat-value-muted">/ ${fmtBRL(allocated)}</span></span>
          </div>
          <div class="progress"><div class="progress__fill" data-ui-css="width:${clamp(ratio * 100, 0, 100)}%; background:${color}"></div></div>
        </div>`;
      }).join("")}
    </div>
  </div>`;
}

// ==================================================================
// FEATURE 2. Assistente financeiro (motor de regras)
// ==================================================================
function renderAssistantCard(mKey) {
  const alerts = getAssistantAlerts(state.data, mKey);
  if (alerts.length === 0) return "";
  const severityColor = { danger: "var(--negative)", warn: "var(--goal)", info: "var(--brand)" };
  const severityBg = { danger: "var(--negative-soft)", warn: "var(--goal-soft)", info: "var(--brand-soft)" };
  return `<div class="card card--assistant span-3 span-mt">
    <div class="leak-header">
      ${svgIcon("sparkles", 18, "leak-header__icon")}
      <div>
        <p class="card-title" data-ui-css="margin:0">Assistente financeiro</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">Alertas automáticos com base no seu mês, calculados no seu aparelho</p>
      </div>
    </div>
    <div class="assistant-alert-list">
      ${alerts.map((a) => `<div class="assistant-alert" data-ui-css="background:${severityBg[a.severity]}">
        <span class="assistant-alert__icon" data-ui-css="color:${severityColor[a.severity]}">${svgIcon(a.icon, 17)}</span>
        <div class="assistant-alert__text">
          <strong>${escapeHtml(a.title)}</strong>
          <span>${escapeHtml(a.message)}</span>
        </div>
      </div>`).join("")}
    </div>
  </div>`;
}

function renderCategoryBreakdown(catRows, monthExpense) {
  if (catRows.length === 0) return renderEmptyState("pie", "Sem gastos registrados neste mês.");
  const segHtml = catRows.map((c) => `<div data-ui-css="flex:${Math.max(c.value, 0.01)};background:${c.color}"></div>`).join("");
  const rows = catRows.slice(0, 6).map((c) => {
    if (c.budget) {
      const ratio = safeRatio(c.value, c.budget);
      const color = ratio < 0.8 ? "var(--positive)" : ratio <= 1 ? "var(--goal)" : "var(--negative)";
      return `<div class="cat-row">
        <span class="cat-dot" data-ui-css="background:${c.color}"></span>
        <span class="cat-name">${escapeHtml(c.name)}</span>
        <span class="cat-value">${fmtBRL(c.value)} <span class="cat-value-muted">/ ${fmtBRL(c.budget)}</span></span>
      </div>
      <div class="progress progress--sm"><div class="progress__fill" data-ui-css="width:${clamp(ratio * 100, 0, 100)}%; background:${color}"></div></div>`;
    }
    const pct = safePct(c.value, monthExpense);
    return `<div class="cat-row">
      <span class="cat-dot" data-ui-css="background:${c.color}"></span>
      <span class="cat-name">${escapeHtml(c.name)}</span>
      <span class="cat-pct">${pct.toFixed(0)}%</span>
    </div>`;
  }).join("");
  return `<div class="segment-bar">${segHtml}</div><div class="cat-list">${rows}</div>`;
}

function renderCategoryBudgetsCard(mKey) {
  const status = computeBudgetStatus(state.data, mKey);
  if (status.items.length === 0) {
    // Sem nenhum teto definido: convite curto, só no mês corrente.
    if (mKey !== keyOfCurrentMonth()) return "";
    return `<div class="card card--dashed span-3 banner-inline">
      ${svgIcon("target", 30, "banner-inline__icon")}
      <div class="banner-inline__text">
        <strong>Defina um teto mensal por categoria</strong>
        <span>Você recebe um aviso ao chegar em 80% e outro ao estourar o limite.</span>
      </div>
      <button class="btn btn--primary btn--sm" data-action="nav" data-tab="settings">Definir</button>
    </div>`;
  }

  const shown = state.budgetsExpanded ? status.items : status.items.slice(0, 3);
  const totalPct = safePct(status.totals.spent, status.totals.budget);
  const headline = status.counts.over > 0
    ? { text: plural(status.counts.over, "orçamento estourado", "orçamentos estourados"), color: "var(--negative)" }
    : status.counts.warn > 0
      ? { text: `${status.counts.warn} perto do limite`, color: "var(--goal)" }
      : { text: "Tudo dentro do limite", color: "var(--positive)" };

  return `<div class="card span-3">
    <div class="health-header">
      <div class="budgets-head">
        <p class="card-title" data-ui-css="margin:0">Orçamentos por categoria</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">${fmtBRL(status.totals.spent)} de ${fmtBRL(status.totals.budget)} · ${Math.round(totalPct)}% do teto total</p>
      </div>
      <span class="status-badge" data-ui-css="background:color-mix(in srgb, ${headline.color} 16%, transparent); color:${headline.color}">
        ${svgIcon(status.counts.over > 0 ? "alertTriangle" : "shieldCheck", 13)}${headline.text}
      </span>
    </div>

    <div class="budget-list">
      ${shown.map((b) => renderBudgetRow(b, status.thresholds)).join("")}
    </div>

    ${status.items.length > 3 ? `<button class="btn btn--ghost btn--sm btn--block" data-ui-css="margin-top:8px" data-action="toggle-budgets">
      ${state.budgetsExpanded ? "Mostrar menos" : `Ver todos os ${status.items.length} orçamentos`}
      ${svgIcon(state.budgetsExpanded ? "chevronUp" : "chevronDown", 14)}
    </button>` : ""}
  </div>`;
}

function renderBudgetRow(b, thresholds) {
  const meta = b.levelMeta;
  const pctCapped = clamp(b.pct, 0, 100);
  // Marcador visual da faixa de atenção (80% por padrão) desenhado sobre a barra.
  const warnMark = clamp(thresholds.warn, 0, 100);
  return `<div class="budget-row budget-row--${b.level}">
    <div class="budget-row__head">
      <span class="icon-bubble icon-bubble--sm" data-ui-css="background:color-mix(in srgb, ${b.color} 14%, transparent); color:${b.color}">${svgIcon(b.icon, 14)}</span>
      <span class="budget-row__name">${escapeHtml(b.name)}${b.isParent ? `<span class="budget-row__hint"> · inclui ${plural(b.childCount, "subcategoria", "subcategorias")}</span>` : ""}</span>
      <span class="budget-row__value" data-ui-css="color:${meta.color}">${fmtBRL(b.spent)}<span class="cat-value-muted"> / ${fmtBRL(b.budget)}</span></span>
    </div>
    <div class="progress budget-progress">
      <div class="progress__fill" data-ui-css="width:${pctCapped}%; background:${meta.color}"></div>
      <span class="budget-progress__mark" data-ui-css="left:${warnMark}%" title="Alerta em ${thresholds.warn}%"></span>
    </div>
    <p class="budget-row__note">
      ${b.level === "over"
        ? `<b data-ui-css="color:var(--negative)">Estourou em ${fmtBRL(Math.abs(b.remaining))}</b> (${Math.round(b.pct)}% do teto).`
        : b.level === "warn"
          ? `<b data-ui-css="color:var(--goal)">${Math.round(b.pct)}% usado.</b> Restam ${fmtBRL(b.remaining)}${b.dailyAllowance != null ? `; cerca de ${fmtBRL(b.dailyAllowance)} por dia nos próximos ${b.daysLeft} dias` : ""}.`
          : b.willExceed
            ? `${Math.round(b.pct)}% usado. <b data-ui-css="color:var(--goal)">No ritmo atual você fecha em ${fmtBRL(b.projected)}</b> e estoura o teto.`
            : `${Math.round(b.pct)}% usado. Restam ${fmtBRL(b.remaining)}${b.dailyAllowance != null ? ` (${fmtBRL(b.dailyAllowance)}/dia)` : ""}.`}
    </p>
  </div>`;
}

// source: js/screens/accounts.js
// js/screens/accounts.js. Contas, cartões e conciliação.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

function renderAccountForm() {
  const f = state.accountsUi.accountForm;
  if (!f) return "";
  return `<div class="card account-editor" id="account-form" data-ui-css="scroll-margin-top:18px">
    <div class="screen-header"><div><p class="eyebrow">Conta</p><p class="card-title" data-ui-css="margin:3px 0 0">${f.id ? "Editar conta" : "Nova conta"}</p></div>
      <button class="icon-btn" data-action="account-cancel" aria-label="Fechar">${svgIcon("x", 16)}</button></div>
    <div class="field"><label class="field__label" for="account-name-input">Nome</label><input id="account-name-input" class="input" data-field="account-name" value="${escapeHtml(f.name)}" placeholder="Ex: Nubank" maxlength="60" /></div>
    <div class="field-row">
      <div class="field"><label class="field__label" for="account-type-select">Tipo</label><select id="account-type-select" class="input" data-action-select="account-type">${Object.entries(ACCOUNT_TYPE_LABELS).map(([id,label]) => `<option value="${id}" ${f.type === id ? "selected" : ""}>${label}</option>`).join("")}</select></div>
      <div class="field"><label class="field__label" for="account-date-input">Saldo válido desde</label><input id="account-date-input" type="date" class="input" data-field="account-opening-date" value="${f.openingDate}" /></div>
    </div>
    <div class="field"><label class="field__label" for="account-balance-input">Saldo nessa data</label><div class="income-input-row"><span class="income-currency">R$</span><input id="account-balance-input" class="input income-input" data-field="account-opening-balance" value="${escapeHtml(f.openingBalance)}" inputmode="decimal" placeholder="0,00" /></div><p class="field-hint">Movimentos anteriores a essa data não alteram esta conta.</p></div>
    <div class="modal-actions"><button class="btn btn--ghost" data-action="account-cancel">Cancelar</button><button class="btn btn--primary" data-action="account-save">Salvar conta</button></div>
  </div>`;
}

function renderCardForm() {
  const f = state.accountsUi.cardForm;
  if (!f) return "";
  const accounts = (state.data.accounts || []).filter((a) => !a.archived);
  return `<div class="card account-editor" id="card-form" data-ui-css="scroll-margin-top:18px">
    <div class="screen-header"><div><p class="eyebrow">Cartão</p><p class="card-title" data-ui-css="margin:3px 0 0">${f.id ? "Editar cartão" : "Novo cartão"}</p></div>
      <button class="icon-btn" data-action="card-cancel" aria-label="Fechar">${svgIcon("x", 16)}</button></div>
    <div class="field"><label class="field__label" for="card-name-input">Nome</label><input id="card-name-input" class="input" data-field="card-name" value="${escapeHtml(f.name)}" placeholder="Ex: Mastercard Nubank" maxlength="60" /></div>
    <div class="field"><label class="field__label" for="card-account-select">Conta usada para pagar</label><select id="card-account-select" class="input" data-action-select="card-account">${accounts.map((a) => `<option value="${a.id}" ${f.accountId === a.id ? "selected" : ""}>${escapeHtml(a.name)}</option>`).join("")}</select></div>
    <div class="field-row">
      <div class="field"><label class="field__label" for="card-limit-input">Limite</label><input id="card-limit-input" class="input" data-field="card-limit" value="${escapeHtml(f.limit)}" inputmode="decimal" placeholder="0,00" /></div>
      <div class="field"><label class="field__label" for="card-closing-input">Fecha dia</label><input id="card-closing-input" class="input" type="number" min="1" max="31" data-field="card-closing" value="${f.closingDay}" /></div>
      <div class="field"><label class="field__label" for="card-due-input">Vence dia</label><input id="card-due-input" class="input" type="number" min="1" max="31" data-field="card-due" value="${f.dueDay}" /></div>
    </div>
    <div class="modal-actions"><button class="btn btn--ghost" data-action="card-cancel">Cancelar</button><button class="btn btn--primary" data-action="card-save" ${accounts.length ? "" : "disabled"}>Salvar cartão</button></div>
  </div>`;
}

function renderTransferForm() {
  const f = state.accountsUi.transferForm;
  if (!f) return "";
  const accounts = (state.data.accounts || []).filter((a) => !a.archived);
  const options = (selected) => accounts.map((a) => `<option value="${a.id}" ${selected === a.id ? "selected" : ""}>${escapeHtml(a.name)}</option>`).join("");
  return `<div class="card account-editor" id="transfer-form" data-ui-css="scroll-margin-top:18px">
    <div class="screen-header"><p class="card-title" data-ui-css="margin:0">Transferir entre contas</p><button class="icon-btn" data-action="transfer-cancel" aria-label="Fechar">${svgIcon("x",16)}</button></div>
    <div class="field-row"><div class="field"><label class="field__label" for="transfer-from-select">Origem</label><select id="transfer-from-select" class="input" data-action-select="transfer-from">${options(f.fromAccountId)}</select></div><div class="field"><label class="field__label" for="transfer-to-select">Destino</label><select id="transfer-to-select" class="input" data-action-select="transfer-to">${options(f.toAccountId)}</select></div></div>
    <div class="field-row"><div class="field"><label class="field__label" for="transfer-amount-input">Valor</label><input id="transfer-amount-input" class="input" data-field="transfer-amount" value="${escapeHtml(f.amount)}" inputmode="decimal" placeholder="0,00" /></div><div class="field"><label class="field__label" for="transfer-date-input">Data</label><input id="transfer-date-input" type="date" class="input" data-field="transfer-date" value="${f.date}" /></div></div>
    <div class="field"><label class="field__label" for="transfer-desc-input">Descrição</label><input id="transfer-desc-input" class="input" data-field="transfer-description" value="${escapeHtml(f.description)}" placeholder="Transferência" /></div>
    <div class="modal-actions"><button class="btn btn--ghost" data-action="transfer-cancel">Cancelar</button><button class="btn btn--primary" data-action="transfer-save">Transferir</button></div>
  </div>`;
}

function renderAccountRow(a, sourceStats) {
  const reconciling = state.accountsUi.reconcileId === a.id;
  const stats = sourceStats || { movementCount:0, lastMovementAt:null, reconciledAt:a.reconciledAt, pendingCount:0, beforeOpeningCount:0 };
  // A CONTAGEM SOZINHA NÃO DECIDE NADA. "2 lançamentos ficaram de fora" não
  // diz se são R$ 5 ou R$ 1.180: quem lê não consegue julgar se o saldo está
  // certo. O valor vem do mesmo cálculo do saldo, ao contrário (ver
  // `accountPreOpeningEffect`), e é ele que permite reconhecer o próprio erro
  // de data de abertura em vez de desconfiar do aplicativo.
  const fora = a.preOpening || { count: stats.beforeOpeningCount || 0, amount: 0 };
  const foraDoSaldo = fora.count || 0;
  return `<div class="account-row ${a.archived ? "is-archived" : ""}">
    <span class="account-mark" data-ui-css="--account-color:${a.color}">${svgIcon(a.type === "dinheiro" ? "wallet" : "bank",18)}</span>
    <div class="account-row__info"><b>${escapeHtml(a.name)}</b><span>${ACCOUNT_TYPE_LABELS[a.type] || "Conta"}${a.archived ? ", arquivada" : ""}</span><small>${stats.movementCount} ${stats.movementCount === 1 ? "movimentação" : "movimentações"} · última ${stats.lastMovementAt ? formatMovementTimestamp(stats.lastMovementAt) : "não registrada"}</small><small>Conferida: ${stats.reconciledAt ? formatMovementTimestamp(stats.reconciledAt) : "nunca"}${stats.pendingCount ? ` · ${stats.pendingCount} ${stats.pendingCount === 1 ? "pendência" : "pendências"}` : ""}</small>${foraDoSaldo ? `<small class="account-row__note">${svgIcon("info",12)} ${foraDoSaldo} ${foraDoSaldo === 1 ? "lançamento é anterior" : "lançamentos são anteriores"} à abertura em ${fmtDateFull(a.openingDate)} e ${foraDoSaldo === 1 ? "não entra" : "não entram"} neste saldo${moneyToCents(fora.amount) ? ` (${fmtBRL(fora.amount)}). O saldo inicial informado já deveria contê-${foraDoSaldo === 1 ? "lo" : "los"}; se não contém, corrija a data de abertura ou o valor inicial` : ""}</small>` : ""}</div>
    <strong class="account-row__value">${fmtBRL(a.balance)}</strong>
    <div class="account-row__actions"><button class="icon-btn" data-action="account-reconcile-open" data-id="${a.id}" aria-label="Conciliar ${escapeHtml(a.name)}">${svgIcon("refresh",15)}</button><button class="icon-btn" data-action="account-edit" data-id="${a.id}" aria-label="Editar ${escapeHtml(a.name)}">${svgIcon("pencil",15)}</button><button class="icon-btn" data-action="account-archive" data-id="${a.id}" aria-label="${a.archived ? "Reativar" : "Arquivar"} ${escapeHtml(a.name)}">${svgIcon(a.archived ? "checkCircle" : "archive",15)}</button><button class="icon-btn icon-btn--danger" data-action="account-delete" data-id="${a.id}" aria-label="Excluir ${escapeHtml(a.name)}">${svgIcon("trash",15)}</button></div>
    ${reconciling ? `<div class="account-reconcile"><label class="field__label" for="reconcile-balance-input">Saldo visto no banco hoje</label><div class="account-reconcile__line"><input id="reconcile-balance-input" class="input" data-field="reconcile-value" value="${escapeHtml(state.accountsUi.reconcileValue)}" inputmode="decimal" placeholder="0,00" /><button class="btn btn--primary btn--sm" data-action="account-reconcile-save" data-id="${a.id}">Conciliar</button><button class="btn btn--ghost btn--sm" data-action="account-reconcile-cancel">Cancelar</button></div></div>` : ""}
  </div>`;
}

function renderCardRow(c, sourceStats) {
  const open = c.statements.filter((s) => s.outstanding > 0);
  const stats = sourceStats || { movementCount:0, lastMovementAt:null };
  return `<div class="card account-card-item ${c.archived ? "is-archived" : ""}">
    <div class="account-card-head"><span class="account-mark" data-ui-css="--account-color:${c.color}">${svgIcon("creditCard",18)}</span><div><p class="card-title" data-ui-css="margin:0">${escapeHtml(c.name)}</p><p class="card-subtitle" data-ui-css="margin:2px 0 0">Fecha dia ${c.closingDay} · vence dia ${c.dueDay}${c.archived ? ", arquivado" : ""}</p><p class="account-source-line">${stats.movementCount} ${stats.movementCount === 1 ? "compra registrada" : "compras registradas"} · última ${stats.lastMovementAt ? formatMovementTimestamp(stats.lastMovementAt) : "não registrada"}</p></div><div class="account-row__actions"><button class="icon-btn" data-action="card-edit" data-id="${c.id}" aria-label="Editar ${escapeHtml(c.name)}">${svgIcon("pencil",15)}</button><button class="icon-btn" data-action="card-archive" data-id="${c.id}" aria-label="${c.archived ? "Reativar" : "Arquivar"} ${escapeHtml(c.name)}">${svgIcon(c.archived ? "checkCircle" : "archive",15)}</button><button class="icon-btn icon-btn--danger" data-action="card-delete" data-id="${c.id}" aria-label="Excluir ${escapeHtml(c.name)}">${svgIcon("trash",15)}</button></div></div>
    <div class="account-stats"><div><span>Faturas até este mês</span><b>${fmtBRL(c.due)}</b></div><div><span>Parcelas futuras</span><b>${fmtBRL(c.future)}</b></div><div><span>Limite disponível</span><b>${fmtBRL(c.availableLimit)}</b></div></div>
    ${open.length ? `<div class="statement-list">${open.slice(0,6).map((s) => `<div class="statement-row"><span><b>${MONTH_ABBR[Number(s.key.slice(5,7))-1]} ${s.key.slice(0,4)}</b><small>Vence ${fmtDateShort(s.dueDate)} · ${s.count} ${s.count === 1 ? "compra" : "compras"}</small></span><strong>${fmtBRL(s.outstanding)}</strong>${s.key <= monthKeyOf(todayIso()) ? `<button class="btn btn--secondary btn--sm" data-action="card-pay-open" data-id="${c.id}" data-value="${s.key}">Pagar</button>` : ""}</div>`).join("")}</div>` : `<p class="field-hint">Nenhuma fatura em aberto.</p>`}
  </div>`;
}

function renderCardPaymentForm(summary) {
  const p = state.accountsUi.payment;
  if (!p) return "";
  const card = summary.cards.find((c) => c.id === p.creditCardId);
  const statement = card && card.statements.find((s) => s.key === p.statementKey);
  const accounts = summary.accounts.filter((a) => !a.archived);
  return `<div class="card account-editor"><div class="screen-header"><div><p class="eyebrow">Pagamento de fatura</p><p class="card-title" data-ui-css="margin:3px 0 0">${card ? escapeHtml(card.name) : "Cartão"} · ${p.statementKey}</p></div><button class="icon-btn" data-action="card-pay-cancel" aria-label="Fechar">${svgIcon("x",16)}</button></div>
    <div class="field"><label class="field__label" for="payment-account-select">Pagar com</label><select id="payment-account-select" class="input" data-action-select="payment-account">${accounts.map((a) => `<option value="${a.id}" ${p.accountId === a.id ? "selected" : ""}>${escapeHtml(a.name)} · ${fmtBRL(a.balance)}</option>`).join("")}</select></div>
    <div class="field-row"><div class="field"><label class="field__label" for="payment-amount-input">Valor</label><input id="payment-amount-input" class="input" data-field="payment-amount" value="${escapeHtml(p.amount)}" inputmode="decimal" /></div><div class="field"><label class="field__label" for="payment-date-input">Data</label><input id="payment-date-input" type="date" class="input" data-field="payment-date" value="${p.date}" /></div></div>
    <p class="field-hint">Em aberto nesta fatura: ${fmtBRL(statement ? statement.outstanding : 0)}. O pagamento reduz a conta, mas não cria uma segunda despesa.</p>
    <div class="modal-actions"><button class="btn btn--ghost" data-action="card-pay-cancel">Cancelar</button><button class="btn btn--primary" data-action="card-pay-save">Registrar pagamento</button></div></div>`;
}

function renderAccountsScreen() {
  const summary = accountsSummary(state.data, todayIso());
  const sources = buildDataSourcesModel(state.data);
  const activeAccounts = summary.accounts.filter((a) => !a.archived);
  return `<div class="screen">
    ${renderBackHeader("Contas e cartões")}
    <div class="segmented accounts-segmented" role="tablist" aria-label="Visão de contas"><button class="segmented__btn ${state.accountsUi.view === "accounts" ? "active" : ""}" data-action="accounts-view" data-value="accounts" role="tab" aria-selected="${state.accountsUi.view === "accounts"}">Contas e cartões</button><button class="segmented__btn ${state.accountsUi.view === "sources" ? "active" : ""}" data-action="accounts-view" data-value="sources" role="tab" aria-selected="${state.accountsUi.view === "sources"}">Fontes dos dados${sources.pendingCount ? ` <span class="badge">${sources.pendingCount}</span>` : ""}</button></div>
    ${state.accountsUi.view === "sources" ? renderDataSourcesCenter(sources) : renderAccountsAndCards(summary, sources, activeAccounts)}
  </div>`;
}

function renderAccountsAndCards(summary, sources, activeAccounts) {
  const accountStats = new Map(sources.accountStats.map((item) => [item.accountId, item]));
  const cardStats = new Map(sources.cardStats.map((item) => [item.cardId, item]));
  return `
    <div class="account-toolbar"><button class="btn btn--primary btn--sm" data-action="account-new">${svgIcon("plus",15)} Conta</button><button class="btn btn--secondary btn--sm" data-action="card-new" ${activeAccounts.length ? "" : "disabled"}>${svgIcon("creditCard",15)} Cartão</button><button class="btn btn--secondary btn--sm" data-action="transfer-new" ${activeAccounts.length > 1 ? "" : "disabled"}>${svgIcon("arrowRight",15)} Transferir</button></div>
    <div class="card card--hero account-hero"><div class="hero-label-row"><p class="hero-label">Saldo em contas</p>${renderCalculationButton("accounts-balance")}</div><p class="hero-value">${fmtBRL(summary.cash)}</p><div class="hero-chips"><div class="hero-chip"><div><span class="hero-chip__label">Faturas abertas</span><span class="hero-chip__value">${fmtBRL(summary.cardDue)}</span></div></div><div class="hero-chip ${summary.availableAfterCards >= 0 ? "hero-chip--save" : "hero-chip--warn"}"><div><span class="hero-chip__label">Após faturas</span><span class="hero-chip__value">${fmtBRL(summary.availableAfterCards)}</span></div></div><div class="hero-chip"><div><span class="hero-chip__label">Parcelas futuras</span><span class="hero-chip__value">${fmtBRL(summary.futureCard)}</span></div></div></div></div>
    ${renderAccountForm()}${renderCardForm()}${renderTransferForm()}${renderCardPaymentForm(summary)}
    <div class="grid-2 accounts-grid"><div class="card"><div class="screen-header"><p class="card-title" data-ui-css="margin:0">Contas</p><span class="badge">${summary.accounts.length}</span></div>${summary.accounts.length ? `<div class="account-list">${summary.accounts.map((account) => renderAccountRow(account, accountStats.get(account.id))).join("")}</div>` : renderEmptyState("wallet","Nenhuma conta cadastrada.","Cadastre uma conta e informe o saldo visto no banco para o aplicativo começar com uma base confiável.")}${summary.legacy !== 0 ? `<div class="legacy-balance">${svgIcon("alertTriangle",15)}<span><b>Histórico anterior: ${fmtBRL(summary.legacy)}</b><small>Lançamentos antigos sem conta continuam preservados e entram no total.</small></span></div>` : ""}</div>
      <div><p class="section-title">Cartões</p>${summary.cards.length ? summary.cards.map((card) => renderCardRow(card, cardStats.get(card.id))).join("") : `<div class="card">${renderEmptyState("creditCard","Nenhum cartão cadastrado.","Compras no crédito só deixam de reduzir o caixa quando estão ligadas a um cartão.")}</div>`}</div></div>`;
}

function renderDataSourcesCenter(model) {
  return `<div class="sources-center">
    <div class="card sources-status"><div class="sources-status__icon">${svgIcon("shieldCheck",20)}</div><div><p class="card-title">${escapeHtml(model.connection.label)}</p><p class="card-subtitle">${escapeHtml(model.connection.detail)}. Seus dados financeiros continuam neste navegador.</p></div><span class="status-badge">Sem conexão bancária</span></div>
    <div class="sources-summary"><div class="card"><span>Registros rastreados</span><b>${model.totalRecords}</b></div><div class="card"><span>Última atualização</span><b>${model.lastUpdatedAt ? formatMovementTimestamp(model.lastUpdatedAt) : "Sem registros"}</b></div><div class="card"><span>Pendências</span><b>${model.pendingCount}</b></div></div>
    ${model.withoutDestination ? `<div class="inline-alert inline-alert--warn">${svgIcon("alertTriangle",14)} ${model.withoutDestination} ${model.withoutDestination === 1 ? "lançamento ainda não está ligado" : "lançamentos ainda não estão ligados"} a uma conta ou cartão. Eles continuam preservados no saldo histórico.</div>` : ""}
    <div class="card"><div class="screen-header"><div><p class="card-title" data-ui-css="margin:0">Origens encontradas</p><p class="card-subtitle">Quantidade e atualização de cada canal</p></div><button class="btn btn--primary btn--sm" data-action="nav" data-tab="import">${svgIcon("upload",14)} Importar extrato</button></div>
      ${model.sources.length ? `<div class="source-list">${model.sources.map((source) => `<div class="source-row"><span class="icon-bubble icon-bubble--sm">${svgIcon(source.icon,15)}</span><div class="source-row__main"><b>${escapeHtml(source.label)}</b><span>${escapeHtml(source.detail)}</span>${source.reference ? `<small>Último arquivo: ${escapeHtml(source.reference)}</small>` : ""}</div><div class="source-row__status"><span class="status-badge">${escapeHtml(source.status)}</span><b>${source.count}</b><small>${source.lastUpdatedAt ? formatMovementTimestamp(source.lastUpdatedAt) : "Sem atualização"}</small></div></div>`).join("")}</div>` : renderEmptyState("file","Nenhuma fonte registrada.","Adicione uma movimentação ou importe um extrato para começar.")}
    </div>
    <div class="card sources-next"><div><p class="card-title">Como atualizar</p><p class="card-subtitle">Importe um novo OFX ou CSV e revise os itens sinalizados. O aplicativo não consulta seu banco em segundo plano.</p></div><div><button class="btn btn--secondary" data-action="nav" data-tab="import">Importar arquivo</button><button class="btn btn--ghost" data-action="nav" data-tab="analytics">Abrir caixa de revisão</button></div></div>
  </div>`;
}

// source: js/screens/debts.js
// js/screens/debts.js. Central de dívidas.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// CENTRAL DE DÍVIDAS
// ==================================================================
function renderDebtForm() {
  const f = state.debtsUi.form;
  if (!f) return "";
  return `<div class="card debt-editor span-3" id="debt-form" data-ui-css="scroll-margin-top:18px">
    <div class="screen-header"><div><p class="eyebrow">${f.id ? "Editar dívida" : "Nova dívida"}</p><p class="card-title" data-ui-css="margin:3px 0 0">Saldo e condições do contrato</p></div><button class="icon-btn" data-action="debt-form-cancel" aria-label="Fechar">${svgIcon("x",16)}</button></div>
    <div class="field-row"><div class="field"><label class="field__label" for="debt-name">Nome</label><input id="debt-name" class="input" data-field="debt-name" value="${escapeHtml(f.name)}" placeholder="Ex: Financiamento do carro" maxlength="60" /></div><div class="field"><label class="field__label" for="debt-value">Saldo devedor hoje</label><input id="debt-value" class="input" data-field="debt-value" value="${escapeHtml(f.value)}" inputmode="decimal" placeholder="0,00" /></div></div>
    <div class="field-row"><div class="field"><label class="field__label" for="debt-type">Tipo</label><select id="debt-type" class="input" data-action-select="debt-type">${Object.entries(DEBT_TYPE_LABELS).map(([id,label]) => `<option value="${id}" ${f.debtType === id ? "selected" : ""}>${label}</option>`).join("")}</select></div><div class="field"><label class="field__label" for="debt-creditor">Credor</label><input id="debt-creditor" class="input" data-field="debt-creditor" value="${escapeHtml(f.creditor)}" placeholder="Banco ou empresa" maxlength="80" /></div></div>
    <div class="field-row"><div class="field"><label class="field__label" for="debt-payment">Parcela mínima mensal</label><input id="debt-payment" class="input" data-field="debt-payment" value="${escapeHtml(f.monthlyPayment)}" inputmode="decimal" placeholder="0,00" /></div><div class="field"><label class="field__label" for="debt-next-due">Próximo vencimento</label><input id="debt-next-due" type="date" class="input" data-field="debt-next-due" value="${f.nextDueDate || ""}" /></div></div>
    <details class="debt-details" ${f.id ? "open" : ""}><summary>Detalhes para uma projeção mais precisa</summary>
      <div class="field-row"><div class="field"><label class="field__label" for="debt-cet">CET anual (%)</label><input id="debt-cet" class="input" data-field="debt-cet" value="${escapeHtml(f.cetAnnualPct)}" inputmode="decimal" placeholder="Ex: 28,5" /><p class="field-hint">Se informado, o CET tem preferência no cálculo.</p></div><div class="field"><label class="field__label" for="debt-rate">Taxa de juros (%)</label><div class="debt-rate-row"><input id="debt-rate" class="input" data-field="debt-rate" value="${escapeHtml(f.ratePct)}" inputmode="decimal" placeholder="Ex: 2,1" /><select class="input" data-action-select="debt-rate-period"><option value="unknown" ${f.ratePeriod === "unknown" ? "selected" : ""}>Período</option><option value="month" ${f.ratePeriod === "month" ? "selected" : ""}>ao mês</option><option value="year" ${f.ratePeriod === "year" ? "selected" : ""}>ao ano</option></select></div></div></div>
      <div class="field-row"><div class="field"><label class="field__label" for="debt-original">Valor contratado</label><input id="debt-original" class="input" data-field="debt-original" value="${escapeHtml(f.originalPrincipal)}" inputmode="decimal" placeholder="0,00" /></div><div class="field"><label class="field__label" for="debt-installments">Parcelas restantes</label><input id="debt-installments" class="input" data-field="debt-installments" value="${escapeHtml(f.remainingInstallments)}" inputmode="numeric" placeholder="Ex: 24" /></div></div>
      <div class="field-row"><div class="field"><label class="field__label" for="debt-system">Amortização</label><select id="debt-system" class="input" data-action-select="debt-system">${Object.entries(DEBT_AMORTIZATION_LABELS).map(([id,label]) => `<option value="${id}" ${f.amortizationSystem === id ? "selected" : ""}>${label}</option>`).join("")}</select></div><div class="field"><label class="field__label" for="debt-status">Situação</label><select id="debt-status" class="input" data-action-select="debt-status"><option value="active" ${f.debtStatus === "active" ? "selected" : ""}>Ativa</option><option value="negotiating" ${f.debtStatus === "negotiating" ? "selected" : ""}>Em negociação</option><option value="paid" ${f.debtStatus === "paid" ? "selected" : ""}>Quitada</option></select></div></div>
      <div class="field"><label class="field__label" for="debt-note">Observação</label><input id="debt-note" class="input" data-field="debt-note" value="${escapeHtml(f.note)}" maxlength="140" placeholder="Contrato, garantia ou contato" /></div>
    </details>
    <div class="form-actions"><button class="btn btn--ghost" data-action="debt-form-cancel">Cancelar</button><button class="btn btn--primary" data-action="debt-save">${f.id ? "Salvar alterações" : "Cadastrar dívida"}</button></div>
  </div>`;
}

function renderDebtPaymentForm(model) {
  const p = state.debtsUi.payment;
  if (!p) return "";
  const debt = model.debts.find((d) => d.id === p.debtId) || (state.data.assets || []).find((d) => d.id === p.debtId);
  const accounts = (state.data.accounts || []).filter((a) => !a.archived);
  return `<div class="card debt-editor span-3" id="debt-payment-form" data-ui-css="scroll-margin-top:18px">
    <div class="screen-header"><div><p class="eyebrow">Registrar pagamento</p><p class="card-title" data-ui-css="margin:3px 0 0">${debt ? escapeHtml(debt.name) : "Dívida"}</p></div><button class="icon-btn" data-action="debt-payment-cancel" aria-label="Fechar">${svgIcon("x",16)}</button></div>
    <div class="field-row"><div class="field"><label class="field__label" for="debt-pay-amount">Valor pago</label><input id="debt-pay-amount" class="input" data-field="debt-pay-amount" value="${escapeHtml(p.amount)}" inputmode="decimal" placeholder="0,00" /></div><div class="field"><label class="field__label" for="debt-pay-date">Data</label><input id="debt-pay-date" type="date" class="input" data-field="debt-pay-date" value="${p.date}" /></div></div>
    <div class="field-row"><div class="field"><label class="field__label" for="debt-pay-account">Conta de origem</label><select id="debt-pay-account" class="input" data-action-select="debt-pay-account"><option value="">Sem conta vinculada</option>${accounts.map((a) => `<option value="${a.id}" ${p.accountId === a.id ? "selected" : ""}>${escapeHtml(a.name)}</option>`).join("")}</select></div><div class="field"><label class="field__label" for="debt-pay-category">Categoria</label><select id="debt-pay-category" class="input" data-action-select="debt-pay-category">${topLevelCategories(state.data).map((c) => `<option value="${c.id}" ${p.categoryId === c.id ? "selected" : ""}>${escapeHtml(c.name)}</option>`).join("")}</select></div></div>
    <div class="field"><label class="field__label" for="debt-new-balance">Novo saldo visto no credor (opcional)</label><input id="debt-new-balance" class="input" data-field="debt-new-balance" value="${escapeHtml(p.newBalance)}" inputmode="decimal" placeholder="Não é calculado pelo valor pago" /><p class="field-hint">Juros, seguros e tarifas fazem o saldo cair de modo diferente do pagamento. Por isso ele só muda quando você informar o valor visto no credor.</p></div>
    <div class="form-actions"><button class="btn btn--ghost" data-action="debt-payment-cancel">Cancelar</button><button class="btn btn--primary" data-action="debt-payment-save">Registrar pagamento</button></div>
  </div>`;
}

function renderDebtProjection(model) {
  const s = model.simulation;
  const max = Math.max(model.totalBalance, 1);
  const points = s.timeline.filter((_, i) => i === 0 || i === s.timeline.length - 1 || i % Math.max(1, Math.ceil(s.timeline.length / 10)) === 0);
  const monthLabel = s.months == null ? "Sem prazo calculável" : `${s.months} ${s.months === 1 ? "mês" : "meses"}`;
  return `<div class="card span-2">
    <div class="settings-row-header"><div><p class="card-title" data-ui-css="margin:0">Plano de quitação</p><p class="card-subtitle">${model.plan.strategy === "avalanche" ? "Avalanche: maior custo primeiro" : "Bola de neve: menor saldo primeiro"}</p></div><div class="seg-control"><button class="seg-control__btn ${model.plan.strategy === "avalanche" ? "active" : ""}" data-action="debt-strategy" data-value="avalanche">Avalanche</button><button class="seg-control__btn ${model.plan.strategy === "snowball" ? "active" : ""}" data-action="debt-strategy" data-value="snowball">Bola de neve</button></div></div>
    <div class="debt-plan-summary"><div><span>Prazo estimado</span><b>${monthLabel}</b></div><div><span>Orçamento mensal</span><b>${fmtBRL(s.monthlyBudget)}</b></div><div><span>Juros projetados</span><b>${s.totalInterest == null ? "Incompleto" : fmtBRL(s.totalInterest)}</b></div></div>
    <div class="field"><label class="field__label" for="debt-extra">Valor extra por mês</label><div class="debt-extra-row"><input id="debt-extra" class="input" data-field="debt-extra" value="${escapeHtml(state.debtsUi.extraDraft == null ? moneyDraft(model.plan.extraMonthly) : state.debtsUi.extraDraft)}" inputmode="decimal" placeholder="0,00" /><button class="btn btn--secondary" data-action="debt-extra-save">Aplicar</button></div></div>
    ${points.length ? `<div class="debt-timeline" aria-label="Queda estimada do saldo">${points.map((p) => `<div class="debt-timeline__row"><span>Mês ${p.month}</span><div><i data-ui-css="width:${Math.max(1,p.balance/max*100)}%"></i></div><b>${fmtBRLShort(p.balance)}</b></div>`).join("")}</div>` : ""}
    <p class="footnote">Estimativa educativa. Taxas desconhecidas usam queda linear sem juros; o resultado não substitui o saldo ou a proposta oficial do credor.</p>
  </div>`;
}

function renderDebtList(model) {
  if (!model.debts.length) return `<div class="card span-3">${renderEmptyState("alertTriangle","Nenhuma dívida ativa cadastrada.","Cadastre nome e saldo devedor. Os detalhes do contrato podem ser preenchidos depois.")}<button class="btn btn--primary btn--block btn--sm" data-action="debt-new">Cadastrar primeira dívida</button></div>`;
  return `<div class="card span-3"><div class="settings-row-header"><div><p class="card-title" data-ui-css="margin:0">Ordem de pagamento</p><p class="card-subtitle">Todas recebem a parcela mínima; o valor livre vai para a primeira da lista.</p></div><span class="badge">${model.debts.length}</span></div><div class="debt-list">${model.ordered.map((d,index) => {
    const rate = debtMonthlyRateInfo(d);
    const due = nextDueDateForDebt(d);
    const expanded = state.debtsUi.expandedId === d.id;
    const paid = model.payments.filter((p) => p.debtId === d.id).sort((a,b) => b.date.localeCompare(a.date));
    return `<div class="debt-row ${expanded ? "is-open" : ""}"><button class="debt-row__main" data-action="debt-toggle" data-id="${d.id}" aria-expanded="${expanded}"><span class="debt-rank">${index + 1}</span><span class="debt-row__text"><b>${escapeHtml(d.name)}</b><small>${escapeHtml(d.creditor || DEBT_TYPE_LABELS[d.debtType] || "Dívida")} · ${rate.known ? `${rate.annualPct.toFixed(2)}% a.a. ${rate.source === "cet" ? "CET" : "efetivos"}` : "custo não informado"}</small></span><span class="debt-row__values"><b>${fmtBRL(d.value)}</b><small>${d.monthlyPayment > 0 ? `${fmtBRL(d.monthlyPayment)}/mês` : "sem parcela mínima"}</small></span>${svgIcon(expanded ? "chevronUp" : "chevronDown",15)}</button>
      ${expanded ? `<div class="debt-row__detail"><div class="debt-facts"><div><span>Próximo vencimento</span><b>${due ? fmtDateFull(due) : "Não informado"}</b></div><div><span>Saldo conferido</span><b>${d.balanceCheckedAt ? fmtDateFull(d.balanceCheckedAt) : "Nunca"}</b></div><div><span>Situação</span><b>${d.debtStatus === "negotiating" ? "Em negociação" : "Ativa"}</b></div></div>
        ${model.staleIds.includes(d.id) ? `<div class="inline-alert inline-alert--warn">Saldo sem conferência há mais de 60 dias. Atualize ao registrar o próximo pagamento.</div>` : ""}
        ${model.simulation.negativeAmortizationIds.includes(d.id) ? `<div class="inline-alert inline-alert--danger">A parcela pode ser menor ou igual aos juros do mês. O saldo pode não cair.</div>` : ""}
        ${paid.length ? `<div class="debt-payment-history"><p class="field__label">Pagamentos vinculados</p>${paid.slice(0,5).map((p) => `<div><span>${fmtDateShort(p.date)}</span><b>${fmtBRL(p.amount)}</b></div>`).join("")}</div>` : ""}
        <div class="form-actions"><button class="btn btn--primary btn--sm" data-action="debt-payment-open" data-id="${d.id}">${svgIcon("checkCircle",14)} Registrar pagamento</button><button class="btn btn--ghost btn--sm" data-action="debt-edit" data-id="${d.id}">${svgIcon("pencil",14)} Editar</button><button class="btn btn--ghost btn--sm" data-action="debt-delete" data-id="${d.id}">${svgIcon("trash",14)} Excluir</button></div>
      </div>` : ""}</div>`;
  }).join("")}</div></div>`;
}

function renderDebtsScreen() {
  const model = debtsModel();
  const s = model.simulation;
  const warningCount = s.unknownRateIds.length + s.missingPaymentIds.length + s.negativeAmortizationIds.length + model.staleIds.length;
  return `<div class="screen"><div class="screen-header"><div class="back-header"><button class="icon-btn" data-action="back" data-tab="dashboard" aria-label="Voltar">${svgIcon("chevronLeft",19)}</button><div><h1 class="page-title">Central de Dívidas</h1><p class="card-subtitle">Um plano baseado nos mesmos saldos do Patrimônio</p></div></div><button class="btn btn--primary btn--sm" data-action="debt-new">${svgIcon("plus",15)} Dívida</button></div>
    <div class="grid-dashboard"><div class="card card--hero span-3 debt-hero"><div class="hero-glow"></div><div class="hero-label-row"><p class="hero-label">Saldo devedor total</p>${renderCalculationButton("debts")}</div><p class="hero-value">${fmtBRL(model.totalBalance)}</p>${model.estimatedDebtFreeAt ? `<p class="hero-reserved">${svgIcon("calendar",14)} Quitação estimada em ${fmtDateFull(model.estimatedDebtFreeAt)}</p>` : ""}<div class="hero-chips"><div class="hero-chip"><div><span class="hero-chip__label">Parcelas mínimas</span><span class="hero-chip__value">${fmtBRL(model.monthlyPayment)}</span></div></div><div class="hero-chip"><div><span class="hero-chip__label">Comprometimento da renda</span><span class="hero-chip__value">${model.burdenPct == null ? "Sem renda" : `${model.burdenPct.toFixed(1)}%`}</span></div></div><div class="hero-chip ${warningCount ? "hero-chip--warn" : "hero-chip--save"}"><div><span class="hero-chip__label">Pontos a revisar</span><span class="hero-chip__value">${warningCount}</span></div></div></div></div>
      ${renderDebtForm()}${renderDebtPaymentForm(model)}
      ${model.debts.length ? renderDebtProjection(model) : ""}
      ${model.debts.length ? `<div class="card span-1"><p class="card-title">Comparação</p><div class="debt-compare"><div><span>Avalanche</span><b>${model.avalanche.months == null ? "Sem prazo" : `${model.avalanche.months} meses`}</b><small>Prioriza o maior custo</small></div><div><span>Bola de neve</span><b>${model.snowball.months == null ? "Sem prazo" : `${model.snowball.months} meses`}</b><small>Prioriza o menor saldo</small></div></div>${model.shortTermCards.due > 0 || model.shortTermCards.future > 0 ? `<div class="inline-alert">Cartões à parte: ${fmtBRL(model.shortTermCards.due)} em faturas abertas e ${fmtBRL(model.shortTermCards.future)} futuras. Só cadastre aqui se a fatura virou rotativo ou parcelamento.</div>` : ""}</div>` : ""}
      ${renderDebtList(model)}
    </div></div>`;
}

// source: js/screens/add.js
// js/screens/add.js. Lançamento de transação, avisos de orçamento e entrada em linguagem natural.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// NATUREZA DO LANÇAMENTO
// ==================================================================
// Só aparece quando NÃO é o caso trivial. Perguntar "isto é um gasto?" para
// cada compra de padaria seria atrito puro; o valor está em poder marcar o que
// o app erraria sozinho: um estorno, uma transferência entre contas próprias,
// os juros de uma dívida. Por isso o campo nasce recolhido, com a dedução já
// aplicada, e só se abre quando o usuário quer corrigir.
function renderNatureField(f, isIncome) {
  const atual = normalizeTransactionNature(f.nature, {
    type: isIncome ? "income" : "expense",
    goalId: f.goalId || null,
    debtId: f.debtId || null,
    categoryId: f.categoryId,
  });
  // "Transferência entre contas" não salva um lançamento: ela troca o editor
  // pelo fluxo de conversão, que precisa de um lançamento gravado para
  // substituir. Num cadastro novo a opção seria uma armadilha, e o caminho
  // certo continua sendo a transferência própria da tela de Contas.
  const opcoes = transactionNatureOptions(isIncome ? "income" : "expense")
    .filter((o) => o.id !== "transferencia" || !!state.editingTxId);
  const aberto = !!state.natureFieldOpen;
  const rotulo = TRANSACTION_NATURE_LABELS[atual] || "Gasto";

  if (!aberto) {
    return `
    <button type="button" class="switch-row" data-action="toggle-nature-field" aria-expanded="false">
      <span>Tipo de movimento: <b>${escapeHtml(rotulo)}</b></span>
      <span class="micro">alterar</span>
    </button>`;
  }

  return `
    <fieldset class="field">
      <legend class="field__label">Tipo de movimento</legend>
      <div class="payment-chips" role="radiogroup" aria-label="Tipo de movimento">
        ${opcoes.map((o) => `
          <button type="button" class="payment-chip ${o.id === atual ? "active" : ""}"
            role="radio" aria-checked="${o.id === atual ? "true" : "false"}"
            data-action="set-nature" data-value="${escapeHtml(o.id)}">${escapeHtml(o.label)}</button>`).join("")}
      </div>
      <p class="micro" data-ui-css="margin-top:8px">${escapeHtml(TRANSACTION_NATURE_HINTS[atual] || "")}</p>
    </fieldset>`;
}

// ==================================================================
// CONVERSÃO DE UM LANÇAMENTO EM TRANSFERÊNCIA ENTRE CONTAS PRÓPRIAS
// ==================================================================
// Uma transferência de verdade mexe em DUAS contas, e uma transação comum só
// conhece uma. Por isso escolher "Transferência entre contas" na edição não
// grava mais um lançamento de uma ponta só: troca o editor por este fluxo, que
// pede origem e destino e substitui as transações envolvidas por um
// `accountTransfer`, fora de gasto, renda e orçamento.
function transferConversionModel() {
  const f = state.form || {};
  const data = state.data || {};
  const accounts = (data.accounts || []).filter((a) => a && !a.archived);
  const transaction = (data.transactions || []).find((t) => t.id === state.editingTxId) || null;
  const amount = parseMoneyInput(f.amount);
  const known = (id) => accounts.some((a) => a.id === id);
  const fromAccountId = known(f.transferFromAccountId) ? f.transferFromAccountId : "";
  const toAccountId = known(f.transferToAccountId) ? f.transferToAccountId : "";
  const accountsOk = !!fromAccountId && !!toAccountId && fromAccountId !== toAccountId;
  const resolution = transaction && accountsOk
    ? resolveTransferConversionCounterpart(transaction, data.transactions, {
        fromAccountId, toAccountId,
        amount: Number.isFinite(amount) && amount > 0 ? amount : transaction.amount,
        date: f.date || transaction.date,
        description: f.description,
      })
    : { status: "none", matches: [], transaction: null };
  // "none" é a decisão explícita de converter só este lançamento; ela precisa
  // sobreviver a um novo desenho da tela, senão a sugestão automática voltaria
  // a prometer substituir dois.
  const counterpartId = f.transferCounterpartId === "none"
    ? "none"
    : (resolution.matches.some((item) => item.id === f.transferCounterpartId) ? f.transferCounterpartId : "");
  const counterpart = counterpartId && counterpartId !== "none"
    ? resolution.matches.find((item) => item.id === counterpartId)
    : (counterpartId === "none" ? null : resolution.transaction);
  const needsChoice = resolution.status === "ambiguous" && !counterpartId;
  return {
    accounts, transaction, fromAccountId, toAccountId, amount, accountsOk,
    resolution, counterpartId, counterpart, needsChoice,
    enoughAccounts: accounts.length > 1,
    ready: !!transaction && accountsOk && Number.isFinite(amount) && amount > 0 && !needsChoice,
  };
}

function transferAccountOptions(accounts, selectedId, excludeId) {
  return accounts.map((a) => `<option value="${a.id}" ${a.id === selectedId ? "selected" : ""} ${a.id === excludeId ? "disabled" : ""}>${escapeHtml(a.name)} · ${fmtBRL(accountBalance(state.data, a.id, todayIso()))}</option>`).join("");
}

function transferCounterpartLabel(tx) {
  return `${tx.type === "income" ? "entrada" : "saída"} de ${fmtBRL(tx.amount)} em ${fmtDateFull(tx.date)}${tx.description ? ` · ${tx.description}` : ""}`;
}

function renderTransferConversionScreen() {
  const f = state.form;
  const m = transferConversionModel();

  return `<div class="screen screen--narrow add-form">
    <div class="screen-header">
      <h1 class="page-title">Converter em transferência</h1>
      <button class="icon-btn icon-btn--muted" data-action="cancel-edit" aria-label="Fechar">${svgIcon("x", 18)}</button>
    </div>

    <div class="origin-chip">${svgIcon("info", 14)}<span>Uma transferência entre suas contas sai de uma e entra na outra. Ela não conta como gasto nem como renda.</span></div>

    <div class="amount-input-wrap">
      <p class="field__label center">Valor</p>
      <div class="amount-row">
        <span class="amount-currency" data-ui-css="color:var(--ink-soft)">R$</span>
        <input id="tx-amount-input" data-field="tx-amount" class="amount-field" data-ui-css="color:var(--ink)"
          value="${escapeHtml(f.amount)}" inputmode="decimal" placeholder="0,00" autocomplete="off" />
      </div>
    </div>

    <div class="field">
      <label class="field__label" for="tx-date-input">Data</label>
      <input id="tx-date-input" type="date" class="input" data-field="tx-date" value="${f.date}" />
    </div>

    ${m.enoughAccounts ? `
    <div class="field">
      <label class="field__label" for="tx-transfer-from-select">Conta de origem</label>
      <select id="tx-transfer-from-select" class="input" data-action-select="tx-transfer-from">
        <option value="">Escolha a conta que envia</option>
        ${transferAccountOptions(m.accounts, m.fromAccountId, m.toAccountId)}
      </select>
    </div>

    <div class="field">
      <label class="field__label" for="tx-transfer-to-select">Conta de destino</label>
      <select id="tx-transfer-to-select" class="input" data-action-select="tx-transfer-to">
        <option value="">Escolha a conta que recebe</option>
        ${transferAccountOptions(m.accounts, m.toAccountId, m.fromAccountId)}
      </select>
    </div>` : `<div class="origin-chip">${svgIcon("alertTriangle", 14)}<span>Uma transferência precisa de duas contas ativas. Cadastre a outra conta para converter este lançamento.</span><button class="btn btn--ghost btn--sm" data-action="nav" data-tab="accounts">Cadastrar</button></div>`}

    <div class="field">
      <label class="field__label" for="tx-desc-input">Descrição (opcional)</label>
      <input id="tx-desc-input" class="input" data-field="tx-description" value="${escapeHtml(f.description)}" placeholder="Ex: Pix para a reserva" autocomplete="off" />
    </div>

    ${renderTransferCounterpartBlock(m)}

    ${renderNatureField(f, f.type === "income")}

    ${state.editingTxId ? `<button class="btn btn--danger btn--block" data-action="delete-tx" data-id="${state.editingTxId}" data-ui-css="margin-top:14px">${svgIcon("trash", 16)} Excluir lançamento</button>` : ""}

    <div id="form-warnings-slot"></div>
    <p class="micro" id="tx-transfer-hint">${m.ready
      ? "As duas contas mudam de saldo; nenhum gasto e nenhuma renda são criados."
      : "Escolha o valor e duas contas ativas diferentes para converter."}</p>

    <div class="submit-bar">
      <button id="tx-submit-btn" class="btn btn--block btn--primary" data-action="submit-tx" aria-describedby="tx-transfer-hint">
        Converter em transferência
      </button>
    </div>
  </div>`;
}

// A promessa da tela e o que a gravação faz têm de ser a mesma coisa. Com uma
// única candidata dá para dizer qual lançamento some junto; com várias, o app
// não escolhe sozinho: ou a pessoa aponta a outra ponta, ou diz que só este
// lançamento vira transferência.
function renderTransferCounterpartBlock(m) {
  if (!m.accountsOk || !m.transaction) return "";
  if (m.resolution.status === "ambiguous") {
    return `<div class="field">
      <label class="field__label" for="tx-transfer-counterpart-select">Outra ponta desta transferência</label>
      <select id="tx-transfer-counterpart-select" class="input ${m.needsChoice ? "input--error" : ""}" data-action-select="tx-transfer-counterpart">
        <option value="">Escolha o lançamento correspondente</option>
        ${m.resolution.matches.map((tx) => `<option value="${tx.id}" ${tx.id === m.counterpartId ? "selected" : ""}>${escapeHtml(transferCounterpartLabel(tx))}</option>`).join("")}
        <option value="none" ${m.counterpartId === "none" ? "selected" : ""}>Converter somente este lançamento</option>
      </select>
      <p class="field-hint">${m.needsChoice
        ? `Existem ${m.resolution.matches.length} lançamentos que combinam com esta transferência. Escolha qual é a outra ponta antes de converter.`
        : (m.counterpartId === "none" ? "Só o lançamento em edição será substituído." : "O lançamento escolhido também será substituído pela transferência.")}</p>
    </div>`;
  }
  if (m.counterpart) {
    return `<div class="origin-chip">${svgIcon("info", 14)}<span>A ${escapeHtml(transferCounterpartLabel(m.counterpart))} também será substituída por esta transferência.</span></div>`;
  }
  return `<p class="field-hint">Só este lançamento será substituído. A outra conta recebe o efeito da transferência mesmo sem um lançamento correspondente.</p>`;
}

// ==================================================================
// ADD / EDIT TRANSACTION
// ==================================================================
function isTxFormValid() {
  const f = state.form;
  const amt = parseMoneyInput(f.amount);
  const hasAccounts = (state.data.accounts || []).some((a) => !a.archived);
  const hasCards = (state.data.creditCards || []).some((c) => !c.archived);
  const destinationOk = !hasAccounts || (f.type === "expense" && f.payment === "Crédito"
    ? (!hasCards || !!f.creditCardId)
    : !!f.accountId);
  return Number.isFinite(amt) && amt > 0 && (f.type === "income" || !!f.categoryId) && destinationOk;
}

function renderAddScreen() {
  const f = state.form;
  // A conversão tem outras regras, outros campos e outro botão. Tentar
  // acomodá-la dentro do editor comum devolveria uma tela com categoria,
  // parcelas e "Salvar alterações" para algo que não é gasto nem renda.
  if (state.editingTxId && f.nature === "transferencia") return renderTransferConversionScreen();
  const valid = isTxFormValid();
  const editing = !!state.editingTxId;
  const isIncome = f.type === "income";
  const amt = parseMoneyInput(f.amount);

  return `<div class="screen screen--narrow add-form ${isIncome ? "add-form--income" : "add-form--expense"}">
    <div class="screen-header">
      <h1 class="page-title">${editing ? "Editar lançamento" : (isIncome ? "Nova receita" : "Novo gasto")}</h1>
      <button class="icon-btn icon-btn--muted" data-action="cancel-edit" aria-label="Fechar">${svgIcon("x", 18)}</button>
    </div>

    ${f.origin ? `<div class="origin-chip">${svgIcon("scan", 14)}<span>${escapeHtml(f.origin)}; confira os dados antes de salvar</span></div>` : ""}

    <div class="add-form__badge">
      <span class="add-form__badge-icon">${svgIcon(isIncome ? "trendUp" : "arrowDownRight", 22)}</span>
    </div>

    <div class="segmented segmented--type">
      <button class="segmented__option ${f.type === "expense" ? "active" : ""}" data-action="set-type" data-value="expense">Gasto</button>
      <button class="segmented__option segmented__option--income ${isIncome ? "active" : ""}" data-action="set-type" data-value="income">Receita</button>
    </div>

    <div class="amount-input-wrap">
      <p class="field__label center">Valor</p>
      <div class="amount-row">
        <span class="amount-currency" data-ui-css="color:${isIncome ? "var(--positive)" : "var(--ink-soft)"}">R$</span>
        <input id="tx-amount-input" data-field="tx-amount" class="amount-field" data-ui-css="color:${isIncome ? "var(--positive)" : "var(--ink)"}"
          value="${escapeHtml(f.amount)}" inputmode="decimal" placeholder="0,00" autocomplete="off" />
      </div>
    </div>

    ${isIncome ? `
      <div class="field">
        <p class="field__label">Fonte da receita</p>
        <div class="payment-chips">
          ${INCOME_SOURCES.map((s) => `<button class="payment-chip payment-chip--income ${f.description === s ? "active" : ""}" data-action="select-income-source" data-value="${escapeHtml(s)}">${escapeHtml(s)}</button>`).join("")}
        </div>
      </div>
    ` : `
      <div class="field" id="tx-category-group" tabindex="-1">
        <div class="field__label-row">
          <p class="field__label">Categoria</p>
          <button class="field__link" data-action="nav" data-tab="categories">${svgIcon("layout", 13)} Organizar categorias</button>
        </div>
        <div class="chip-grid">
          ${topLevelCategories(state.data).map((c) => {
            const children = childCategories(state.data, c.id);
            const selectedChild = children.find((ch) => ch.id === f.categoryId);
            const isSelected = f.categoryId === c.id || !!selectedChild;
            const hasChildren = children.length > 0;
            // Com subcategoria escolhida o rótulo mostra o caminho inteiro, não só o
            // nome do filho. Trocar "Alimentação" por "Mercado" fazia a fila de chips
            // virar "Moradia, Mercado, Transporte": dois níveis da taxonomia lado a
            // lado, sem nada que diga qual é qual, e o pai escolhido sumia da tela.
            // categoryFullName é o mesmo formato já usado no seletor de regras e no
            // rascunho do lançamento. O ícone continua sendo o do filho, que é o que
            // confirma a escolha de dentro do seletor.
            return `
            <button class="chip ${isSelected ? "active" : ""}" data-ui-css="${isSelected ? `border-color:${c.color}; background:color-mix(in srgb, ${c.color} 10%, transparent)` : ""}" data-action="${hasChildren ? "open-category-picker" : "select-category"}" data-id="${c.id}">
              <span class="icon-bubble" data-ui-css="background:color-mix(in srgb, ${c.color} 14%, transparent); color:${c.color}">${svgIcon(selectedChild ? selectedChild.icon : c.icon, 17)}</span>
              <span class="chip__label">${escapeHtml(selectedChild ? categoryFullName(state.data, selectedChild.id) : c.name)}</span>
              ${hasChildren ? `<span class="chip__caret">${svgIcon("chevronDown", 11)}</span>` : ""}
            </button>`;
          }).join("")}
        </div>
      </div>
    `}

    <div class="field-row">
      <div class="field">
        <label class="field__label" for="tx-date-input">Data</label>
        <input id="tx-date-input" type="date" class="input" data-field="tx-date" value="${f.date}" />
      </div>
      ${!isIncome ? `
      <div class="field">
        <p class="field__label">Pagamento</p>
        <div class="payment-chips">
          ${PAYMENT_METHODS.map((p) => `<button class="payment-chip ${f.payment === p ? "active" : ""}" data-action="select-payment" data-value="${p}">${escapeHtml(p)}</button>`).join("")}
        </div>
      </div>` : `
      <div class="field">
        <label class="field__label" for="tx-payment-select">Recebido via</label>
        <div class="payment-chips">
          ${PAYMENT_METHODS.map((p) => `<button class="payment-chip payment-chip--income ${f.payment === p ? "active" : ""}" data-action="select-payment" data-value="${p}">${escapeHtml(p)}</button>`).join("")}
        </div>
      </div>`}
    </div>

    ${(() => {
      const accounts = (state.data.accounts || []).filter((a) => !a.archived);
      const cards = (state.data.creditCards || []).filter((c) => !c.archived);
      if (!accounts.length) return `<div class="origin-chip">${svgIcon("info",14)}<span>Cadastre uma conta para o saldo representar o banco de verdade. Este lançamento ficará no histórico anterior.</span><button class="btn btn--ghost btn--sm" data-action="nav" data-tab="accounts">Cadastrar</button></div>`;
      if (!isIncome && f.payment === "Crédito") return `<div class="field"><label class="field__label" for="tx-card-select">Cartão</label><select id="tx-card-select" class="input" data-action-select="tx-card"><option value="">Escolha o cartão</option>${cards.map((c) => `<option value="${c.id}" ${f.creditCardId === c.id ? "selected" : ""}>${escapeHtml(c.name)}</option>`).join("")}</select>${cards.length ? `<p class="field-hint">A compra entra na fatura e não reduz o saldo da conta agora.</p>` : `<p class="field-hint">Cadastre um cartão em Contas e cartões.</p>`}</div>`;
      return `<div class="field"><label class="field__label" for="tx-account-select">${isIncome ? "Conta que recebeu" : "Conta usada"}</label><select id="tx-account-select" class="input" data-action-select="tx-account"><option value="">Escolha a conta</option>${accounts.map((a) => `<option value="${a.id}" ${f.accountId === a.id ? "selected" : ""}>${escapeHtml(a.name)} · ${fmtBRL(accountBalance(state.data,a.id,todayIso()))}</option>`).join("")}</select></div>`;
    })()}

    ${!isIncome && f.payment === "Crédito" && !editing ? `
    <div class="field">
      <p class="field__label">Parcelas</p>
      <div class="installments-grid">
        ${Array.from({ length: 12 }, (_, i) => i + 1).map((n) => `
          <button type="button" class="installment-chip ${Number(f.installments) === n ? "active" : ""}" data-action="select-installments" data-value="${n}">${n}x</button>
        `).join("")}
      </div>
      <p class="field-hint installment-hint">${amt > 0
        ? (Number(f.installments) > 1
            ? `${Number(f.installments)}x de <strong>${fmtBRL(splitMoney(amt, Number(f.installments))[0])}</strong>; lançado em ${Number(f.installments)} meses a partir de ${fmtDateFull(f.date)} (soma exata de ${fmtBRL(amt)})`
            : `À vista. <strong>${fmtBRL(amt)}</strong> lançado em ${fmtDateFull(f.date)}`)
        : "Informe o valor para ver a simulação das parcelas"}</p>
    </div>` : ""}

    <div class="field">
      <label class="field__label" for="tx-desc-input">Descrição ${isIncome ? "" : "(opcional)"}</label>
      <input id="tx-desc-input" class="input" data-field="tx-description" value="${escapeHtml(f.description)}" placeholder="${isIncome ? "Ex: Salário de julho" : "Ex: Mercado do mês"}" autocomplete="off" />
    </div>

    ${!isIncome ? `
    <button class="switch-row ${f.recurring ? "active" : ""}" data-action="toggle-recurring">
      <span>Gasto fixo mensal (recorrente)</span>
      <span class="switch ${f.recurring ? "active" : ""}"><span class="switch__knob"></span></span>
    </button>` : ""}

    ${renderNatureField(f, isIncome)}

    ${editing ? `<button class="btn btn--danger btn--block" data-action="delete-tx" data-id="${state.editingTxId}" data-ui-css="margin-top:14px">${svgIcon("trash", 16)} Excluir lançamento</button>` : ""}

    <div id="form-warnings-slot">${renderFormWarnings()}</div>

    <div class="submit-bar">
      <button id="tx-submit-btn" class="btn btn--block ${isIncome ? "btn--positive" : "btn--primary"}" data-action="submit-tx">
        ${editing ? "Salvar alterações" : (isIncome ? "Salvar receita" : "Salvar gasto")}
      </button>
    </div>
  </div>`;
}

// ==================================================================
// TARGETED PATCH HELPERS (evita re-render total durante digitação)
// ==================================================================
// Bloco de avisos do formulário: junta o aviso da Regra x/x/x com os alertas de
// ORÇAMENTO POR CATEGORIA (Feature 3). Ambos são informativos; nunca bloqueiam
// o lançamento; a decisão é sempre do usuário.
function renderFormWarnings() {
  const f = state.form;
  if (f.type === "income" || state.editingTxId) return "";
  const amt = parseMoneyInput(f.amount);
  if (!(amt > 0)) return "";

  const budget = evaluateBudgetImpact(state.data, f.categoryId, amt, keyOfCurrentMonth());
  const split = computeSplitWarning(f.categoryId, amt);

  return renderBudgetImpactBlock(budget) + renderSplitWarningBlock(split);
}

// Mostra, ao vivo, para onde este gasto leva o teto da categoria escolhida.

function renderBudgetImpactBlock(impact) {
  if (!impact || !impact.affected || impact.affected.length === 0) return "";
  const th = impact.thresholds || { warn: 80, over: 100 };

  return impact.affected.map((e) => {
    const meta = e.levelMeta || {};
    const crossed = e.levelAfter !== e.levelBefore && e.levelAfter !== "ok";
    const tone = e.levelAfter === "over" ? "over" : e.levelAfter === "warn" ? "warn" : "ok";
    const pctShown = clamp(e.pctAfter, 0, 100);
    const pctBefore = clamp(e.pctBefore, 0, 100);
    return `<div class="budget-impact budget-impact--${tone}">
      <div class="budget-impact__head">
        <span class="budget-impact__icon" data-ui-css="color:${meta.color || "var(--ink-soft)"}">${svgIcon(e.levelAfter === "ok" ? "target" : "alertTriangle", 16)}</span>
        <div class="budget-impact__title">
          <strong>${escapeHtml(e.fullName)}${e.inherited ? " (categoria principal)" : ""}</strong>
          <span>${e.levelAfter === "over"
            ? `Estoura o teto de ${fmtBRL(e.budget)} em <b>${fmtBRL(e.over)}</b>.`
            : `Fica em <b>${Math.round(e.pctAfter)}%</b> do teto de ${fmtBRL(e.budget)}; restam ${fmtBRL(Math.max(0, e.remaining))}.`}</span>
        </div>
        ${crossed ? `<span class="budget-impact__flag" data-ui-css="background:${meta.soft}; color:${meta.color}">${e.levelAfter === "over" ? "Estoura agora" : `Passa de ${th.warn}%`}</span>` : ""}
      </div>
      <div class="progress progress--stacked">
        <div class="progress__fill progress__fill--ghost" data-ui-css="width:${pctBefore}%"></div>
        <div class="progress__fill" data-ui-css="width:${pctShown}%; background:${meta.color || "var(--brand)"}"></div>
      </div>
    </div>`;
  }).join("");
}

function renderSplitWarningBlock(splitWarning) {
  if (!splitWarning) return "";
  return `<div class="split-warning">
    ${svgIcon("alertTriangle", 17, "split-warning__icon")}
    <div class="split-warning__text">
      <strong>Essa compra passa do combinado para "${splitWarning.groupLabel}"</strong>
      <span>Com esse gasto, o grupo chega a ${fmtBRL(splitWarning.newSpent)} este mês. ${fmtBRL(splitWarning.over)} acima dos ${splitWarning.pct}% da renda (${fmtBRL(splitWarning.allocated)}) combinados. Você decide se quer seguir mesmo assim.</span>
    </div>
  </div>`;
}

// Recalcula os avisos não-obstrutivos sem re-renderizar a tela inteira (o campo
// de valor usa patch pontual para não perder o foco do teclado ao digitar).
function patchFormWarnings() {
  const slot = document.getElementById("form-warnings-slot");
  if (!slot) return;
  slot.innerHTML = renderFormWarnings();
}

function patchSubmitButton() {
  const btn = document.getElementById("tx-submit-btn");
  if (btn) btn.dataset.formReady = isTxFormValid() ? "true" : "false";
}

function patchTxHistory() {
  const el = document.getElementById("tx-history-section");
  if (el) el.innerHTML = renderTxHistorySection();
}

// ==================================================================
// FEATURE 4. LANÇAMENTO INTELIGENTE (linguagem natural)
// ==================================================================
// Fluxo: o usuário escreve → parser LOCAL (nlp.js) devolve rascunhos → a tela
// mostra o que entendeu em forma de "chips" editáveis → o usuário confirma.
// Nada é gravado sem confirmação, porque errar a categoria de um gasto é mais
// caro do que um toque a mais na tela.
function renderQuickEntryCard() {
  const n = state.nlp;
  const hasDrafts = n.drafts.length > 0;
  return `<div class="card card--quick-entry span-3 span-mt">
    <div class="leak-header">
      ${svgIcon("sparkles", 18, "leak-header__icon")}
      <div>
        <p class="card-title" data-ui-css="margin:0">Lançamento rápido</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">Escreva do seu jeito; eu transformo em lançamento</p>
      </div>
    </div>

    <div class="quick-entry-row">
      <input id="nlp-input" class="input quick-entry-input" data-field="nlp-text"
        value="${escapeHtml(n.text)}" placeholder="Ex: gastei 30 no ifood"
        autocomplete="off" enterkeyhint="done" />
      <button id="nlp-parse-btn" class="btn btn--primary quick-entry-btn" data-action="nlp-parse" ${n.text.trim() && !n.loading ? "" : "disabled"}>
        ${n.loading ? `<span class="spinner spinner--light"></span>` : svgIcon("arrowUpRight", 16)}
        <span class="quick-entry-btn__label">Entender</span>
      </button>
    </div>

    ${!hasDrafts && !n.error ? `<div class="quick-entry-examples">
      ${NLP_EXAMPLES.slice(0, 3).map((ex) => `<button class="quick-entry-example" data-action="nlp-example" data-value="${escapeHtml(ex)}">${escapeHtml(ex)}</button>`).join("")}
    </div>` : ""}

    ${n.error ? `<div class="inline-error">
      ${svgIcon("alertTriangle", 16)}
      <div><p class="inline-error__title">${escapeHtml(n.error)}</p></div>
      <button class="icon-btn icon-btn--muted" data-action="nlp-clear" aria-label="Limpar lançamento rápido">${svgIcon("x", 14)}</button>
    </div>` : ""}

    ${hasDrafts ? renderNaturalDrafts(n.drafts) : ""}
  </div>`;
}

function renderNaturalDrafts(drafts) {
  const valid = drafts.filter((d) => d.amount > 0);
  const lowConfidence = drafts.some((d) => d.confidence < 0.6);
  return `<div class="nlp-drafts">
    ${drafts.map((d, i) => renderNaturalDraft(d, i)).join("")}

    ${lowConfidence ? `<button class="nlp-refine" data-action="nlp-ai-refine">
      ${svgIcon("sparkles", 13)} Não ficou certo? Pedir ajuda da IA para entender melhor
    </button>` : ""}

    <div class="nlp-actions">
      <button class="btn btn--ghost btn--sm" data-action="nlp-clear">Cancelar</button>
      <button class="btn btn--primary btn--sm" data-action="nlp-confirm" ${valid.length ? "" : "disabled"}>
        ${svgIcon("check", 15)} Lançar ${valid.length > 1 ? `${valid.length} itens` : ""}
      </button>
    </div>
  </div>`;
}

function renderNaturalDraft(d, index) {
  const cat = categoryById(state.data, d.categoryId);
  const isIncome = d.type === "income";
  const needsCategory = !isIncome && d.categorySource === "padrao";
  const confidenceLabel = d.confidence >= 0.8 ? "alta" : d.confidence >= 0.55 ? "média" : "baixa";
  const impact = !isIncome && d.amount > 0
    ? evaluateBudgetImpact(state.data, d.categoryId, d.amount, monthKeyOf(d.date))
    : null;
  const crossing = impact && impact.crossings.length ? impact.crossings[0] : null;

  return `<div class="nlp-draft ${d.amount > 0 ? "" : "nlp-draft--invalid"}">
    <div class="nlp-draft__head">
      <span class="icon-bubble ${isIncome ? "icon-bubble--income" : ""}" ${isIncome ? "" : `style="background:color-mix(in srgb, ${cat.color} 14%, transparent); color:${cat.color}"`}>
        ${svgIcon(isIncome ? "trendUp" : cat.icon, 17)}
      </span>
      <div class="nlp-draft__info">
        <p class="nlp-draft__title">${escapeHtml(d.description || (isIncome ? "Receita" : cat.name))}</p>
        <p class="nlp-draft__meta">${isIncome ? "Receita" : escapeHtml(categoryFullName(state.data, d.categoryId))} · ${fmtDateShort(d.date)} · ${escapeHtml(d.payment)}${d.installments > 1 ? ` · ${d.installments}x` : ""}${d.recurring ? " · fixo" : ""}</p>
      </div>
      <p class="nlp-draft__amount ${isIncome ? "tx-amount--income" : "tx-amount--expense"}">${d.amount > 0 ? `${isIncome ? "+" : "-"}${fmtBRL(d.amount)}` : "sem valor"}</p>
      <button class="icon-btn" data-action="nlp-remove-draft" data-id="${index}" aria-label="Remover">${svgIcon("x", 14)}</button>
    </div>

    <div class="nlp-draft__tags">
      <span class="nlp-tag nlp-tag--${confidenceLabel === "alta" ? "ok" : confidenceLabel === "média" ? "mid" : "low"}">confiança ${confidenceLabel}</span>
      ${d.categorySource === "historico" ? `<span class="nlp-tag">categoria do seu histórico</span>` : ""}
      ${d.categorySource === "verbo" || d.categorySource === "dicionario" ? `<span class="nlp-tag">categoria deduzida</span>` : ""}
      ${d.matched && d.matched.date ? `<span class="nlp-tag">data reconhecida</span>` : ""}
      ${d.amount <= 0 ? `<span class="nlp-tag nlp-tag--low">faltou o valor</span>` : ""}
      <button class="nlp-tag nlp-tag--action" data-action="nlp-edit-draft" data-id="${index}">${svgIcon("pencil", 11)} ajustar tudo</button>
    </div>

    ${needsCategory ? `<div class="nlp-draft__picker">
      <p class="field__label" data-ui-css="margin-bottom:6px">Não identifiquei a categoria; escolha uma:</p>
      <div class="nlp-cat-chips">
        ${topLevelCategories(state.data).slice(0, 8).map((c) => `<button class="cat-group-chip" data-action="nlp-set-category" data-index="${index}" data-id="${c.id}">
          <span data-ui-css="color:${c.color}">${svgIcon(c.icon, 12)}</span>${escapeHtml(c.name)}
        </button>`).join("")}
      </div>
    </div>` : ""}

    ${crossing ? `<p class="nlp-draft__budget" data-ui-css="color:${crossing.levelMeta.color}">
      ${svgIcon("alertTriangle", 12)} ${escapeHtml(budgetCrossingMessage(crossing, impact.thresholds))}
    </p>` : ""}
  </div>`;
}

// Patch pontual do botão (evita re-render que roubaria o foco do teclado).

function patchNlpButton() {
  const btn = document.getElementById("nlp-parse-btn");
  if (btn) btn.disabled = !state.nlp.text.trim() || state.nlp.loading;
}

function patchQrSaveButton() {
  const btn = document.querySelector('[data-action="qr-save"]');
  if (btn && state.qr.draft) btn.disabled = !(parseMoneyInput(state.qr.draft.amount) > 0);
}

function runNaturalEntryParse() {
  const text = state.nlp.text.trim();
  if (!text) return;
  const drafts = parseNaturalEntries(text, state.data);
  if (drafts.length === 0 || drafts.every((d) => !d.amount)) {
    state.nlp.drafts = drafts;
    state.nlp.error = drafts.length === 0
      ? "Não consegui entender essa frase. Tente algo como “gastei 30 no ifood”."
      : "Entendi o gasto, mas não achei o valor. Inclua o número (ex: “ifood 30”).";
    render();
    return;
  }
  state.nlp.drafts = drafts;
  state.nlp.error = null;
  render();
}

// Segunda opinião opcional da IA; só a frase e os NOMES das categorias saem do
// aparelho (ver netlify/functions/analyze.js, modo "lancamento").
function refineNaturalEntryWithAi() {
  const text = state.nlp.text.trim();
  if (!text) return;
  if (normalizePrivacy(state.data.privacy).aiSharing === "blocked") {
    notify("Envios para IA estão bloqueados em Privacidade", "warn");
    return;
  }
  requestConfirmation({
    title: "Enviar a frase para análise?",
    message: "A frase digitada e os nomes das suas categorias serão enviados para um serviço externo de IA. Nenhum histórico financeiro será enviado.",
    confirmLabel: "Analisar frase",
    icon: "sparkles",
    onConfirm: async () => {
      state.nlp.loading = true;
      state.nlp.error = null;
      render();
      try {
        const remote = await requestNaturalEntryParse(text, state.data.categories);
        const merged = {
          ...(state.nlp.drafts[0] || {}),
          original: text,
          type: remote.tipo === "income" ? "income" : "expense",
          amount: roundMoney(remote.valor),
          categoryId: remote.categoriaId || "outros",
          date: remote.data || todayIso(),
          payment: remote.pagamento || "Outro",
          description: remote.descricao || "",
          recurring: !!remote.recorrente,
          installments: clamp(Number(remote.parcelas) || 1, 1, 48),
          confidence: Number(remote.confianca) || 0.7,
          categorySource: "ia",
          missing: [],
          matched: { date: true, payment: true, installments: (Number(remote.parcelas) || 1) > 1, recurring: !!remote.recorrente },
        };
        state.nlp.drafts = [merged];
        state.nlp.loading = false;
        render();
        notify("Interpretação refinada pela IA");
      } catch (err) {
        if (typeof reportSafeError === "function") reportSafeError("ai", err, "ai_request");
        state.nlp.loading = false;
        state.nlp.error = (err && err.message) || "Não foi possível usar a IA agora.";
        render();
      }
    },
  });
}

function applyNaturalDraftToForm(draft) {
  state.form = {
    type: draft.type,
    amount: draft.amount > 0 ? draft.amount.toFixed(2).replace(".", ",") : "",
    categoryId: draft.type === "expense" ? draft.categoryId : null,
    date: draft.date,
    payment: draft.payment,
    description: draft.description || "",
    recurring: !!draft.recurring,
    installments: String(draft.installments || 1),
    source: "nlp",
    origin: "Escrito em linguagem natural",
    accountId: defaultCashAccountId() || "",
    creditCardId: (((state.data.creditCards || []).find((c) => !c.archived)) || {}).id || "",
  };
  state.editingTxId = null;
}

function commitNaturalDrafts() {
  const drafts = state.nlp.drafts.filter((d) => d.amount > 0);
  if (drafts.length === 0) return;

  // Avalia o impacto nos tetos ANTES de gravar (mesma razão do formulário comum).

  const impacts = drafts
    .filter((d) => d.type === "expense")
    .map((d) => evaluateBudgetImpact(state.data, d.categoryId, d.amount, monthKeyOf(d.date)));

  const firstCard = ((state.data.creditCards || []).find((c) => !c.archived) || {}).id || null;
  const newTxs = drafts.flatMap((d) => transactionsFromNaturalEntry(d)).map((t) => ({
    ...t,
    accountId: t.payment === "Crédito" ? null : defaultCashAccountId(),
    creditCardId: t.payment === "Crédito" ? firstCard : null,
  }));
  setData((d) => ({ ...d, transactions: [...d.transactions, ...newTxs] }));
  state.nlp = { text: "", drafts: [], error: null, loading: false, touched: false };
  notify(newTxs.length === 1 ? "Lançamento salvo" : `${newTxs.length} lançamentos salvos`);
  impacts.forEach((imp) => announceBudgetCrossings(imp));
}

// source: js/screens/analytics.js
// js/screens/analytics.js. Análises: extrato, projeções e o cartão de análise por IA.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// ANALYTICS
// ==================================================================
function movementFiltersSnapshot() {
  return {
    ...state.movementFilters,
    period: state.analyticsPeriod,
    start: state.analyticsCustomStart,
    end: state.analyticsCustomEnd,
    search: state.analyticsSearch,
  };
}

function renderMovementSummary(model) {
  return `<div class="movement-summary" aria-label="Resumo do resultado">
    <div class="movement-summary__item"><span>Entradas</span><b class="tx-amount--income">${fmtBRL(model.income)}</b></div>
    <div class="movement-summary__item"><span>Saídas</span><b class="tx-amount--expense">${fmtBRL(model.expense)}</b></div>
    <div class="movement-summary__item"><span>Saldo</span><b>${fmtBRL(model.balance)}</b></div>
    <div class="movement-summary__item"><span>Movimentos</span><b>${model.count}</b></div>
  </div>`;
}

function renderMovementFilters() {
  const f = state.movementFilters;
  const sourceOptions = [
    ["", "Todas as origens"], ["manual", "Manual"], ["import-ofx", "Extrato OFX"],
    ["import-csv", "Extrato CSV"], ["import-pdf", "PDF bancário"], ["nlp", "Lançamento inteligente"], ["qrcode-pix", "QR Pix"],
    ["qrcode-nfce", "QR nota fiscal"], ["transfer", "Transferência"], ["card-payment", "Pagamento de fatura"],
  ];
  return `<div class="movement-filters ${state.movementFiltersOpen ? "movement-filters--open" : ""}">
    <div class="search-row movement-search">
      <span class="search-icon">${svgIcon("search", 16)}</span>
      <input id="analytics-search" class="input input--search" data-field="search" value="${escapeHtml(state.analyticsSearch)}" placeholder="Buscar" aria-label="Buscar por descrição, valor, conta ou origem" title="Buscar por descrição, valor, conta ou origem" autocomplete="off" />
      ${state.analyticsSearch ? `<button class="icon-btn" data-action="movement-search-clear" aria-label="Limpar busca">${svgIcon("x", 16)}</button>` : ""}
    </div>
    <button class="btn btn--secondary movement-filter-toggle" data-action="movement-filters-toggle" aria-expanded="${state.movementFiltersOpen}">${svgIcon("filter", 16)} Filtros</button>
    <button class="btn btn--secondary movement-filter-toggle" data-action="export-statement-pdf" title="Baixar o extrato do período em PDF">${svgIcon("download", 16)} PDF</button>
    <div class="movement-filters__advanced">
      <div class="field"><label class="field__label" for="movement-type">Tipo</label><select id="movement-type" class="input" data-action-select="movement-type">
        ${[["all", "Todos"], ["income", "Entradas"], ["expense", "Saídas"], ["transfer", "Transferências"], ["card-payment", "Pagamentos de fatura"]].map(([id, label]) => `<option value="${id}" ${f.type === id ? "selected" : ""}>${label}</option>`).join("")}
      </select></div>
      <div class="field"><label class="field__label" for="movement-category">Categoria</label><select id="movement-category" class="input" data-action-select="movement-category">
        <option value="">Todas as categorias</option>${state.data.categories.map((c) => `<option value="${c.id}" ${f.categoryId === c.id ? "selected" : ""}>${escapeHtml(c.name)}</option>`).join("")}
      </select></div>
      <div class="field"><label class="field__label" for="movement-account">Conta ou cartão</label><select id="movement-account" class="input" data-action-select="movement-account">
        <option value="">Todas as contas e cartões</option>
        ${(state.data.accounts || []).map((a) => `<option value="${a.id}" ${f.accountId === a.id ? "selected" : ""}>${escapeHtml(a.name)}</option>`).join("")}
        ${(state.data.creditCards || []).map((c) => `<option value="${c.id}" ${f.accountId === c.id ? "selected" : ""}>${escapeHtml(c.name)}</option>`).join("")}
      </select></div>
      <div class="field"><label class="field__label" for="movement-source">Origem</label><select id="movement-source" class="input" data-action-select="movement-source">
        ${sourceOptions.map(([id, label]) => `<option value="${id}" ${f.source === id ? "selected" : ""}>${label}</option>`).join("")}
      </select></div>
      <button class="btn btn--ghost" data-action="movement-filters-clear">Limpar filtros</button>
    </div>
  </div>`;
}

function renderMovementEntry(entry) {
  const source = movementSourceMeta(entry.source, entry.origin);
  const selected = state.movementSelectedIds.includes(entry.id);
  const amountClass = entry.type === "income" ? "tx-amount--income" : entry.type === "expense" ? "tx-amount--expense" : "";
  const sign = entry.type === "income" ? "+" : entry.type === "expense" ? "-" : "";
  const icon = entry.type === "income" ? "trendUp" : entry.type === "expense" ? (entry.transaction ? categoryById(state.data, entry.categoryId).icon : "arrowRight") : entry.kind === "transfer" ? "arrowRight" : "creditCard";
  return `<div class="movement-row ${selected ? "movement-row--selected" : ""}">
    ${entry.kind === "transaction" ? `<label class="movement-check" aria-label="Selecionar ${escapeHtml(entry.description)}"><input type="checkbox" data-action-select="movement-select" data-id="${entry.id}" ${selected ? "checked" : ""} /></label>` : `<span class="movement-check movement-check--empty" aria-hidden="true"></span>`}
    <span class="icon-bubble">${svgIcon(icon, 18)}</span>
    <button class="movement-row__main" data-action="${entry.kind === "transaction" ? "edit-tx" : "movement-detail"}" data-id="${entry.id}">
      <span class="tx-title">${escapeHtml(entry.description)}</span>
      <span class="tx-meta">${escapeHtml(entry.categoryName)}${entry.accountName ? `, ${escapeHtml(entry.accountName)}` : ""}${entry.cardName ? `, ${escapeHtml(entry.cardName)}` : ""}</span>
      <span class="movement-origin">${svgIcon(source.icon, 12)} ${escapeHtml(source.label)}</span>
    </button>
    <span class="tx-amount ${amountClass}">${sign}${fmtBRL(entry.amount)}</span>
    <button class="icon-btn" data-action="movement-detail" data-id="${entry.id}" aria-label="Ver origem e histórico">${svgIcon("info", 16)}</button>
  </div>`;
}

function renderMovementList(model) {
  if (!model.entries.length) return renderEmptyState("search", state.data.transactions.length ? "Nenhum movimento encontrado" : "Nenhuma movimentação cadastrada", state.data.transactions.length ? "Revise a busca ou limpe os filtros." : "Os lançamentos aparecerão aqui depois de serem adicionados.");
  const shownIds = new Set(model.entries.slice(0, state.analyticsLimit).map((entry) => entry.id));
  const groups = model.groups.map((group) => ({ ...group, entries: group.entries.filter((entry) => shownIds.has(entry.id)) })).filter((group) => group.entries.length);
  return `<div class="movement-groups">${groups.map((group) => `<section class="movement-day"><h2>${fmtDateFull(group.date)}</h2>${group.entries.map(renderMovementEntry).join("")}</section>`).join("")}</div>
    ${model.entries.length > shownIds.size ? `<button class="btn btn--secondary btn--block" data-action="load-more">Carregar mais (${model.entries.length - shownIds.size} restantes)</button>` : ""}`;
}

function renderMovementBulkBar() {
  const count = state.movementSelectedIds.length;
  if (!count) return "";
  return `<div class="movement-bulk" role="region" aria-label="Ações em lote">
    <b>${count} selecionado${count === 1 ? "" : "s"}</b>
    <label class="sr-only" for="movement-bulk-category">Nova categoria</label>
    <select id="movement-bulk-category" class="input" data-action-select="movement-bulk-category"><option value="">Escolher categoria</option>${state.data.categories.map((c) => `<option value="${c.id}" ${state.movementBulkCategoryId === c.id ? "selected" : ""}>${escapeHtml(c.name)}</option>`).join("")}</select>
    <button class="btn btn--secondary" data-action="movement-bulk-apply" ${state.movementBulkCategoryId ? "" : "disabled"}>Aplicar categoria</button>
    <button class="btn btn--danger" data-action="movement-bulk-delete">${svgIcon("trash", 15)} Excluir</button>
    <button class="icon-btn" data-action="movement-selection-clear" aria-label="Limpar seleção">${svgIcon("x", 16)}</button>
  </div>`;
}

function renderReviewIssue(issue) {
  const tx = issue.txId ? state.data.transactions.find((item) => item.id === issue.txId) : null;
  const icon = { category: "tag", duplicate: "file", transfer: "arrowRight", "card-payment": "creditCard", "invoice-income": "creditCard", account: "bank" }[issue.type] || "alertTriangle";
  let action = "";
  if (issue.type === "category" && tx) action = `<select class="input review-category" data-action-select="review-category" data-id="${tx.id}" data-key="${issue.key}"><option value="">Escolher categoria</option>${state.data.categories.filter((c) => c.id !== "outros").map((c) => `<option value="${c.id}">${escapeHtml(c.name)}</option>`).join("")}</select>`;
  if (issue.type === "duplicate") action = `<button class="btn btn--secondary" data-action="review-delete-duplicate" data-id="${issue.txId}" data-key="${issue.key}">Revisar e excluir cópia</button>`;
  if (issue.type === "transfer") action = `<button class="btn btn--secondary" data-action="review-convert-transfer" data-id="${issue.txId}" data-key="${issue.key}">Converter em transferência</button>`;
  if (issue.type === "card-payment") action = `<button class="btn btn--secondary" data-action="review-card-payment-open" data-id="${issue.txId}" data-key="${issue.key}">Converter em pagamento</button>`;
  if (issue.type === "invoice-income") action = `<button class="btn btn--secondary" data-action="review-delete-invoice-income" data-id="${issue.txId}" data-key="${issue.key}">Excluir a receita</button>`;
  if (issue.type === "account") action = `<button class="btn btn--secondary" data-action="review-reconcile-account" data-id="${issue.accountId}">Conferir saldo</button>`;
  return `<article class="review-issue">
    <span class="review-issue__icon">${svgIcon(icon, 18)}</span>
    <div class="review-issue__copy"><b>${escapeHtml(issue.title)}</b><span>${escapeHtml(issue.detail)}</span><small>${fmtDateShort(issue.date)}, ${fmtBRL(issue.amount)}</small></div>
    <div class="review-issue__actions">${action}${issue.txId ? `<button class="btn btn--ghost" data-action="review-ignore" data-id="${issue.txId}" data-key="${issue.key}">Marcar como revisado</button>` : ""}</div>
  </article>`;
}

function renderMovementReview(review) {
  return `<section class="card movement-review ${state.movementReviewOpen ? "movement-review--open" : ""}">
    <button class="movement-review__header" data-action="movement-review-toggle" aria-expanded="${state.movementReviewOpen}">
      <span class="review-count">${review.issues.length}</span><span><b>Caixa de revisão</b><small>${review.issues.length ? "Sugestões que precisam da sua decisão" : "Nenhuma pendência encontrada"}</small></span>${svgIcon(state.movementReviewOpen ? "chevronUp" : "chevronDown", 18)}
    </button>
    ${state.movementReviewOpen ? `<div class="movement-review__body">${review.issues.length ? review.issues.map(renderReviewIssue).join("") : renderEmptyState("checkCircle", "Tudo revisado", "Novas sugestões aparecerão aqui quando necessário.")}</div>` : ""}
  </section>`;
}

function renderMovementsCenter() {
  const model = buildMovementCenterModel(state.data, movementFiltersSnapshot());
  const review = buildTransactionReviewModel(state.data);
  return `<div class="screen">
    <div class="page-heading"><div><h1 class="page-title">Movimentações</h1><p class="page-subtitle">Consulte, corrija e confira a origem dos seus dados.</p></div><button class="btn btn--primary" data-action="nav" data-tab="add">${svgIcon("plus", 16)} Adicionar</button></div>
    <div class="segmented movement-view-tabs"><button class="segmented__option active" data-action="analytics-view" data-value="movements">Movimentações</button><button class="segmented__option" data-action="analytics-view" data-value="reports">Relatórios</button></div>
    ${renderMovementReview(review)}
    <div class="card span-mt">${renderMovementFilters()}
      <div class="segmented movement-periods"><button class="segmented__option ${state.analyticsPeriod === "semana" ? "active" : ""}" data-action="set-period" data-value="semana">Semana</button><button class="segmented__option ${state.analyticsPeriod === "mes" ? "active" : ""}" data-action="set-period" data-value="mes">Mês</button><button class="segmented__option ${state.analyticsPeriod === "ano" ? "active" : ""}" data-action="set-period" data-value="ano">Ano</button><button class="segmented__option ${state.analyticsPeriod === "all" ? "active" : ""}" data-action="set-period" data-value="all">Tudo</button><button class="segmented__option ${state.analyticsPeriod === "custom" ? "active" : ""}" data-action="set-period" data-value="custom">Período</button></div>
      ${state.analyticsPeriod === "custom" ? `<div class="field-row movement-dates"><div class="field"><label class="field__label" for="an-start">De</label><input id="an-start" type="date" class="input" data-field="period-custom-start" value="${state.analyticsCustomStart}" /></div><div class="field"><label class="field__label" for="an-end">Até</label><input id="an-end" type="date" class="input" data-field="period-custom-end" value="${state.analyticsCustomEnd}" /></div></div>` : ""}
      ${renderMovementSummary(model)}${renderMovementBulkBar()}<div id="tx-history-section">${renderMovementList(model)}</div>
    </div>
  </div>`;
}

function renderAnalyticsScreen() {
  return state.analyticsView === "reports" ? renderAnalyticsReportsScreen() : renderMovementsCenter();
}

function filteredTransactionsForPeriod() {
  const now = new Date();
  return state.data.transactions.filter((t) => {
    const d = new Date(t.date + "T00:00:00");
    if (state.analyticsPeriod === "semana") { const diff = (now - d) / 86400000; return diff >= 0 && diff <= 7; }
    if (state.analyticsPeriod === "mes") return monthKeyOf(t.date) === keyOfDate(now);
    if (state.analyticsPeriod === "ano") return t.date.slice(0, 4) === String(now.getFullYear());
    if (state.analyticsPeriod === "custom") return t.date >= state.analyticsCustomStart && t.date <= state.analyticsCustomEnd;
    return true;
  });
}

function historyFiltered() {
  const searchLower = state.analyticsSearch.trim().toLowerCase();
  return [...state.data.transactions]
    .filter((t) => !searchLower || (t.description || "").toLowerCase().includes(searchLower) || categoryById(state.data, t.categoryId).name.toLowerCase().includes(searchLower))
    .sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : (a.createdAt < b.createdAt ? 1 : -1)));
}

function renderTxHistorySection() {
  const historyAll = historyFiltered();
  const historyShown = historyAll.slice(0, state.analyticsLimit);
  if (historyShown.length === 0) return renderEmptyState("search", "Nenhum resultado encontrado.");
  return `
    <div class="tx-list" data-ui-css="margin-top:8px">${historyShown.map((t) => renderTxRow(t)).join("")}</div>
    ${historyAll.length > historyShown.length ? `<button class="btn btn--secondary btn--block" data-ui-css="margin-top:12px" data-action="load-more">Carregar mais (${historyAll.length - historyShown.length} restantes)</button>` : ""}
  `;
}

function renderAnalyticsReportsScreen() {
  const filtered = filteredTransactionsForPeriod();
  const expenses = filtered.filter((t) => t.type === "expense");
  const total = sumMoney(expenses, (t) => t.amount);
  const byCategory = {};
  expenses.forEach((t) => { byCategory[t.categoryId] = (byCategory[t.categoryId] || 0) + moneyToCents(t.amount); });
  const catRows = Object.entries(byCategory)
    .map(([id, cents]) => { const c = categoryById(state.data, id); return { id, value: moneyFromCents(cents), name: c.name, color: c.color }; })
    .sort((a, b) => b.value - a.value);

  const now = new Date();
  const thisKey = keyOfDate(now);
  const lastKey = keyOfDate(addMonths(now, -1));
  const thisMonthTotal = realizedMonthTotals(state.data, thisKey).expense;
  const lastMonthTotal = realizedMonthTotals(state.data, lastKey).expense;
  const delta = lastMonthTotal > 0 ? safePct(subMoney(thisMonthTotal, lastMonthTotal), lastMonthTotal) : (thisMonthTotal > 0 ? 100 : 0);
  const riskAlert = creditRiskAlert(state.data, thisKey);

  return `<div class="screen">
    <div class="page-heading"><div><h1 class="page-title">Relatórios</h1><p class="page-subtitle">Gráficos, projeções e análises dos seus dados.</p></div></div>
    <div class="segmented movement-view-tabs"><button class="segmented__option" data-action="analytics-view" data-value="movements">Movimentações</button><button class="segmented__option active" data-action="analytics-view" data-value="reports">Relatórios</button></div>

    ${riskAlert.trigger ? `
    <div class="card card--leak span-mt" data-ui-css="border-color:var(--negative)">
      <div class="leak-header">
        ${svgIcon("alertTriangle", 18, "leak-header__icon")}
        <div>
          <p class="card-title" data-ui-css="margin:0">Atenção: Você está financiando grande parte dos seus gastos diários no crédito. Cuidado com o acúmulo de faturas.</p>
          <p class="card-subtitle" data-ui-css="margin:2px 0 0">${(riskAlert.pct * 100).toFixed(0)}% dos seus gastos do dia a dia este mês (${fmtBRL(riskAlert.creditTotal)} de ${fmtBRL(riskAlert.variableTotal)}) foram no Crédito.</p>
        </div>
      </div>
    </div>` : ""}

    <div class="segmented">
      <button class="segmented__option ${state.analyticsPeriod === "semana" ? "active" : ""}" data-action="set-period" data-value="semana">Semana</button>
      <button class="segmented__option ${state.analyticsPeriod === "mes" ? "active" : ""}" data-action="set-period" data-value="mes">Mês</button>
      <button class="segmented__option ${state.analyticsPeriod === "ano" ? "active" : ""}" data-action="set-period" data-value="ano">Ano</button>
      <button class="segmented__option ${state.analyticsPeriod === "all" ? "active" : ""}" data-action="set-period" data-value="all">Tudo</button>
      <button class="segmented__option ${state.analyticsPeriod === "custom" ? "active" : ""}" data-action="set-period" data-value="custom">Período</button>
    </div>

    ${state.analyticsPeriod === "custom" ? `
      <div class="field-row" data-ui-css="margin-top:12px">
        <div class="field"><label class="field__label" for="an-start">De</label><input id="an-start" type="date" class="input" data-field="period-custom-start" value="${state.analyticsCustomStart}" /></div>
        <div class="field"><label class="field__label" for="an-end">Até</label><input id="an-end" type="date" class="input" data-field="period-custom-end" value="${state.analyticsCustomEnd}" /></div>
      </div>` : ""}

    <div class="grid-2 span-mt">
      <div class="card">
        <p class="card-title">Gastos por categoria</p>
        ${catRows.length === 0 ? renderEmptyState("pie", "Sem dados no período selecionado.") : `
          <div class="donut-wrap">${renderDonut(catRows)}</div>
          <div class="cat-list" data-ui-css="margin-top:8px">
            ${catRows.map((c) => {
              const pct = safePct(c.value, total);
              return `<div class="cat-row">
                <span class="cat-dot" data-ui-css="background:${c.color}"></span>
                <span class="cat-name">${escapeHtml(c.name)}</span>
                <span class="cat-value">${fmtBRL(c.value)} <span class="cat-value-muted">· ${pct.toFixed(0)}%</span></span>
              </div>
              <div class="progress progress--sm"><div class="progress__fill" data-ui-css="width:${pct}%; background:${c.color}"></div></div>`;
            }).join("")}
          </div>`}
      </div>

      <div class="card">
        <p class="card-title">Este mês vs. mês anterior</p>
        <div class="compare-row">
          <div><span class="compare-label">${MONTH_NAMES[addMonths(now, -1).getMonth()]}</span><b>${fmtBRL(lastMonthTotal)}</b></div>
          <div><span class="compare-label">${MONTH_NAMES[now.getMonth()]}</span><b>${fmtBRL(thisMonthTotal)}</b></div>
          <span class="status-badge" data-ui-css="background:${delta > 0 ? "color-mix(in srgb, var(--negative) 14%, transparent)" : "color-mix(in srgb, var(--positive) 14%, transparent)"}; color:${delta > 0 ? "var(--negative)" : "var(--positive)"}">
            ${svgIcon(delta > 0 ? "arrowUpRight" : "arrowDownRight", 13)}${Math.abs(delta).toFixed(0)}%
          </span>
        </div>
        <p class="card-title" data-ui-css="margin-top:18px">Últimos 6 meses</p>
        ${renderTrendChart(last6MonthsSummary(state.data))}
        <div class="trend-legend"><span><i data-ui-css="background:var(--brand)"></i>Entradas</span><span><i data-ui-css="background:var(--negative)"></i>Gastos</span></div>
      </div>
    </div>

    ${renderProjectionCard()}

    ${renderInstallmentProjectionCard()}

    <div class="card span-mt card--wrapped-cta">
      <div class="leak-header">
        ${svgIcon("sparkles", 18, "leak-header__icon")}
        <div><p class="card-title" data-ui-css="margin:0">Resumo do mês em imagem</p><p class="card-subtitle" data-ui-css="margin:2px 0 0">Gere um cartão estilo "wrapped" para salvar ou compartilhar</p></div>
      </div>
      <button class="btn btn--secondary btn--block" data-ui-css="margin-top:10px" data-action="open-wrapped">${svgIcon("camera", 16)} Gerar resumo visual</button>
    </div>

    ${renderAiCard()}

    <div class="card span-mt">
      <p class="card-title">Histórico completo</p>
      <div class="search-row">
        <span class="search-icon">${svgIcon("search", 16)}</span>
        <input id="analytics-search" class="input input--search" data-field="search" value="${escapeHtml(state.analyticsSearch)}" placeholder="Buscar por descrição ou categoria" autocomplete="off" />
      </div>
      <div id="tx-history-section">${renderTxHistorySection()}</div>
    </div>
  </div>`;
}

// Soma todos os lançamentos futuros já engatilhados por parcelamentos no crédito,
// agrupados por mês, para o usuário enxergar o tamanho das próximas faturas.
function creditInstallmentProjection(data) {
  const today = todayIso();
  const future = data.transactions.filter((t) => t.installmentGroupId && t.type === "expense" && t.date > today);
  const byMonth = {};
  future.forEach((t) => { byMonth[monthKeyOf(t.date)] = (byMonth[monthKeyOf(t.date)] || 0) + moneyToCents(t.amount); });
  const months = Object.keys(byMonth).sort().map((key) => {
    const [y, m] = key.split("-").map(Number);
    return { key, label: `${MONTH_ABBR[m - 1]}/${String(y).slice(2)}`, value: moneyFromCents(byMonth[key]) };
  });
  const total = sumMoney(months, (m) => m.value);
  return { total, months };
}

function renderInstallmentProjectionCard() {
  const p = creditInstallmentProjection(state.data);
  return `<div class="card span-mt">
    <p class="card-title">Projeção de faturas</p>
    <p class="card-subtitle">Parcelas do crédito já lançadas para os próximos meses</p>
    ${p.months.length === 0 ? renderEmptyState("creditCard", "Nenhuma parcela futura em aberto no momento.") : `
      <div class="cat-list" data-ui-css="margin-top:8px">
        ${p.months.map((m) => {
          const pct = safePct(m.value, p.total);
          return `<div class="cat-row">
            <span class="cat-dot" data-ui-css="background:var(--goal)"></span>
            <span class="cat-name">${m.label}</span>
            <span class="cat-value">${fmtBRL(m.value)}</span>
          </div>
          <div class="progress progress--sm"><div class="progress__fill" data-ui-css="width:${pct}%; background:var(--goal)"></div></div>`;
        }).join("")}
      </div>
      <p class="health-note">Total comprometido em faturas futuras: <b>${fmtBRL(p.total)}</b>.</p>
    `}
  </div>`;
}

function renderProjectionCard() {
  const p = projectCashFlow(state.data);
  const w = 600, h = 160, pad = 8;
  const maxVal = Math.max(1, p.income, ...p.actualSeries.map((pt) => pt.value), ...p.projectedSeries.map((pt) => pt.value));
  const xScale = (day) => pad + (p.dim > 1 ? (day - 1) / (p.dim - 1) : 0) * (w - 2 * pad);
  const yScale = (val) => h - pad - (val / maxVal) * (h - 2 * pad);
  const pathOf = (series) => series.map((pt, i) => `${i === 0 ? "M" : "L"} ${xScale(pt.day).toFixed(1)} ${yScale(pt.value).toFixed(1)}`).join(" ");
  const incomeY = yScale(p.income).toFixed(1);
  const hasData = p.actualSeries.length > 1;

  return `<div class="card span-mt">
    <p class="card-title">Projeção de fluxo de caixa</p>
    <p class="card-subtitle">Regressão linear com base no ritmo de gastos ${p.dayOfMonth === 1 ? "do último dia" : `dos últimos ${p.dayOfMonth} dias`}</p>
    ${hasData ? `
    <svg viewBox="0 0 ${w} ${h}" class="projection-chart" preserveAspectRatio="none">
      ${p.income > 0 ? `<line x1="0" y1="${incomeY}" x2="${w}" y2="${incomeY}" stroke="var(--border)" stroke-width="2" stroke-dasharray="5 5"/>` : ""}
      <path d="${pathOf(p.actualSeries)}" fill="none" stroke="var(--brand)" stroke-width="3"/>
      <path d="${pathOf(p.projectedSeries)}" fill="none" stroke="var(--goal)" stroke-width="3" stroke-dasharray="6 5"/>
    </svg>
    <div class="trend-legend">
      <span><i data-ui-css="background:var(--brand)"></i>Realizado</span>
      <span><i data-ui-css="background:var(--goal)"></i>Projeção</span>
      ${p.income > 0 ? `<span><i data-ui-css="background:var(--border)"></i>Renda</span>` : ""}
    </div>
    <p class="health-note">No ritmo atual, a projeção é fechar o mês com <b>${fmtBRL(p.projectedTotal)}</b> em gastos${p.income > 0 ? (p.projectedRemaining >= 0 ? `, sobrando <b data-ui-css="color:var(--positive)">${fmtBRL(p.projectedRemaining)}</b>` : `, ultrapassando a renda em <b data-ui-css="color:var(--negative)">${fmtBRL(Math.abs(p.projectedRemaining))}</b>`) : "."}.</p>
    ` : renderEmptyState("pie", "Lance alguns gastos neste mês para gerar a projeção.")}
  </div>`;
}

function renderAiCard() {
  const ai = state.aiInsight;
  return `<div class="card card--ai span-mt">
    <div class="ai-card__header">
      ${svgIcon("sparkles", 19)}
      <div><p class="card-title" data-ui-css="margin:0">Insights com IA</p><p class="ai-subtitle">Peça uma análise personalizada dos seus gastos deste mês</p></div>
    </div>
    ${ai.loading ? `<div class="ai-loading"><span class="spinner"></span> Analisando seus gastos…</div>` : ""}
    ${ai.error ? `<p class="ai-error">${svgIcon("alertTriangle", 14)} ${escapeHtml(ai.error)}</p>` : ""}
    ${ai.analise ? renderAiStructured(ai.analise) : (ai.text ? `<div class="ai-text">${formatAiText(ai.text)}</div>` : "")}
    ${!ai.loading && !ai.analise ? `<p class="ai-privacy">${svgIcon("shieldCheck", 12)} Você vê o pacote inteiro antes de enviar, e pode tirar partes dele.</p>` : ""}
    ${!ai.loading ? `<button class="btn btn--secondary btn--block" data-ui-css="margin-top:10px" data-action="request-ai-insight">${ai.text ? "Analisar novamente" : "Analisar meus gastos"}</button>` : ""}
  </div>`;
}

// Renderiza a análise estruturada devolvida pela função Netlify:
// diagnóstico + score, fluxo de caixa, riscos e recomendações.
const AI_FLOW_LABEL = { positivo: "Fluxo positivo", equilibrado: "Fluxo equilibrado", negativo: "Fluxo negativo" };

const AI_FLOW_COLOR = { positivo: "var(--positive)", equilibrado: "var(--goal)", negativo: "var(--negative)" };

const AI_RISK_COLOR = { alto: "var(--negative)", medio: "var(--goal)", baixo: "var(--positive)" };

const AI_RISK_LABEL = { alto: "Risco alto", medio: "Atenção", baixo: "Risco baixo" };

function renderAiStructured(a) {
  const flow = (a.fluxoCaixa && a.fluxoCaixa.situacao) || "equilibrado";
  const scoreColor = a.score >= 70 ? "var(--positive)" : a.score >= 40 ? "var(--goal)" : "var(--negative)";
  return `<div class="ai-analysis">
    <div class="ai-analysis__head">
      <div class="ai-score" data-ui-css="color:${scoreColor}">
        <b>${a.score}</b><span>/100</span>
      </div>
      <p class="ai-analysis__diagnosis">${escapeHtml(a.diagnostico)}</p>
    </div>

    <div class="ai-block">
      <p class="ai-block__title" data-ui-css="color:${AI_FLOW_COLOR[flow]}">${svgIcon("trendUp", 14)} ${AI_FLOW_LABEL[flow]}${a.fluxoCaixa && a.fluxoCaixa.sobraEstimada ? ` · sobra estimada ${fmtBRL(a.fluxoCaixa.sobraEstimada)}` : ""}</p>
      ${a.fluxoCaixa && a.fluxoCaixa.comentario ? `<p class="ai-block__text">${escapeHtml(a.fluxoCaixa.comentario)}</p>` : ""}
    </div>

    ${a.riscos && a.riscos.length ? `<div class="ai-block">
      <p class="ai-block__title">${svgIcon("alertTriangle", 14)} Riscos identificados</p>
      ${a.riscos.map((r) => `<div class="ai-item">
        <span class="ai-item__tag" data-ui-css="color:${AI_RISK_COLOR[r.nivel] || "var(--goal)"}; border-color:${AI_RISK_COLOR[r.nivel] || "var(--goal)"}">${AI_RISK_LABEL[r.nivel] || "Atenção"}</span>
        <div><p class="ai-item__title">${escapeHtml(r.titulo)}</p><p class="ai-block__text">${escapeHtml(r.descricao)}</p></div>
      </div>`).join("")}
    </div>` : ""}

    ${a.recomendacoes && a.recomendacoes.length ? `<div class="ai-block">
      <p class="ai-block__title">${svgIcon("checkCircle", 14)} O que fazer agora</p>
      ${a.recomendacoes.map((r) => `<div class="ai-item">
        <span class="ai-item__bullet"></span>
        <div><p class="ai-item__title">${escapeHtml(r.acao)}</p>${r.impacto ? `<p class="ai-block__text">${escapeHtml(r.impacto)}</p>` : ""}</div>
      </div>`).join("")}
    </div>` : ""}

    ${a.metasComentario ? `<div class="ai-block">
      <p class="ai-block__title">${svgIcon("target", 14)} Suas metas</p>
      <p class="ai-block__text">${escapeHtml(a.metasComentario)}</p>
    </div>` : ""}

    <p class="ai-privacy">${svgIcon("shieldCheck", 12)} Só valores e nomes de categoria foram enviados. Descrições, datas e lançamentos individuais ficaram no seu aparelho.</p>
  </div>`;
}

function formatAiText(text) {
  const lines = text.split(/\n+/).filter(Boolean);
  return lines.map((l) => `<p>${escapeHtml(l.replace(/^[-•]\s*/, ""))}</p>`).join("");
}

// source: js/screens/goals.js
// js/screens/goals.js. Metas financeiras. Motor em goals.js.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// GOALS
// ==================================================================
const GOAL_ICON_OPTIONS = ["piggy", "target", "plane"];

function renderGoalsScreen() {
  const model = goalsModel();
  const gf = state.goalForm;
  const editing = !!state.editingGoalId;

  return `<div class="screen">
    <div class="screen-header">
      <h1 class="page-title">Metas financeiras</h1>
      ${gf.show ? "" : `<button class="btn btn--goal btn--sm" data-action="toggle-goal-form">${svgIcon("plus", 15)} Nova meta</button>`}
    </div>

    <div class="grid-dashboard">
      ${model.goals.length > 0 ? renderGoalsHero(model) : ""}
      ${gf.show ? renderGoalForm(gf, editing) : ""}
      ${model.goals.length > 0 ? renderGoalsPlanCard(model) : ""}
      ${model.advice.length > 0 ? renderGoalsAdviceCard(model) : ""}

      ${model.goals.length === 0 && !gf.show ? `<div class="card span-3">
        ${renderEmptyState("target", "Você ainda não criou metas.", "Escolha um objetivo abaixo ou toque em \u201cNova meta\u201d; o app passa a projetar quando você chega lá.")}
        <div class="goal-templates">
          ${GOAL_TEMPLATES.map((t) => `<button class="goal-template" data-action="goal-template" data-value="${t.id}">
            <span class="icon-bubble icon-bubble--sm" data-ui-css="background:color-mix(in srgb, var(--goal) 14%, transparent); color:var(--goal)">${svgIcon(t.icon, 15)}</span>
            <span class="goal-template__text"><b>${escapeHtml(t.name)}</b><span>${escapeHtml(t.hint)}</span></span>
          </button>`).join("")}
        </div>
      </div>` : ""}

      ${model.goals.map((m) => renderGoalCard(m)).join("")}
    </div>
  </div>`;
}

// ---- Painel do topo: total guardado, progresso e o que entrou neste mês ----
function renderGoalsHero(model) {
  const t = model.totals;
  return `<div class="card card--hero span-3">
    <div class="hero-glow"></div>
    <div class="hero-label-row"><p class="hero-label">Total guardado em metas</p>${renderCalculationButton("goals")}</div>
    <p class="hero-value">${fmtBRL(t.saved)}</p>
    <p class="hero-reserved">${t.pct.toFixed(0)}% de ${fmtBRL(t.target)} · faltam ${fmtBRL(t.remaining)}</p>

    <div class="wealth-bar" role="img" aria-label="Progresso combinado das metas">
      <div class="wealth-bar__seg" data-ui-css="flex:${Math.max(t.pct, 1)}; background:var(--goal)"></div>
      <div class="wealth-bar__seg" data-ui-css="flex:${Math.max(100 - t.pct, 1)}; background:rgba(255,255,255,0.16)"></div>
    </div>

    <div class="hero-chips">
      <div class="hero-chip">${svgIcon("piggy", 17)}<div><span class="hero-chip__label">Aportado neste mês</span><span class="hero-chip__value">${fmtBRL(t.contributedThisMonth)}</span></div></div>
      <div class="hero-chip">${svgIcon("target", 17)}<div><span class="hero-chip__label">Metas ativas</span><span class="hero-chip__value">${model.counts.total - model.counts.done}</span></div></div>
      ${model.counts.done > 0 ? `<div class="hero-chip">${svgIcon("checkCircle", 17)}<div><span class="hero-chip__label">Concluídas</span><span class="hero-chip__value">${model.counts.done}</span></div></div>` : ""}
    </div>
  </div>`;
}

// ---- Viabilidade do plano: o compromisso cabe na sobra real? ----
function renderGoalsPlanCard(model) {
  const p = model.plan;
  if (p.commitment <= 0 && p.capacity <= 0) return "";
  const tone = p.feasible === false ? "var(--negative)" : (p.feasible === true ? "var(--positive)" : "var(--ink-faint)");
  const ratio = p.capacity > 0 ? clamp(safePct(p.commitment, p.capacity), 0, 100) : 0;

  return `<div class="card span-3" data-ui-css="--tone:${tone}">
    <div class="mini-card__head">
      <div>
        <p class="card-title" data-ui-css="margin:0">Seu plano cabe no orçamento?</p>
        <p class="mini-card__sub">${p.capacityBasis === "historico"
          ? (p.capacityMonths === 1
            ? "Sobra média do último mês com movimento"
            : `Sobra média dos últimos ${p.capacityMonths} meses com movimento`)
          : p.capacityBasis === "renda" ? "Estimativa de 20% da renda informada (ainda sem histórico)" : "Sem histórico para estimar a sobra"}</p>
      </div>
      <span class="plan-verdict" data-ui-css="color:${tone}">${p.feasible === false ? "Aperta" : p.feasible === true ? "Cabe" : "Sem base"}</span>
    </div>

    <div class="plan-meter"><div class="plan-meter__fill" data-ui-css="width:${ratio}%; background:${tone}"></div></div>

    <div class="plan-grid">
      <div class="plan-cell"><span>Compromisso mensal</span><b>${fmtBRL(p.commitment)}</b></div>
      <div class="plan-cell"><span>Sobra média</span><b>${fmtBRL(p.capacity)}</b></div>
      <div class="plan-cell"><span>Ritmo real somado</span><b>${fmtBRL(p.paceTotal)}</b></div>
    </div>

    <p class="field-hint">${p.feasible === false
      ? `Faltam ${fmtBRL(p.gap)} por mês. Compare reduzir o valor, ampliar o prazo ou aumentar o aporte sem comprometer o orçamento.`
      : p.plannedTotal > 0
        ? "Compromisso = soma dos aportes mensais que você definiu. Sem aporte definido, entra o valor necessário para bater o prazo."
        : "Nenhuma meta tem aporte mensal definido ainda. Defina um para o app acompanhar o ritmo em vez de só o total."}</p>
  </div>`;
}

function renderGoalsAdviceCard(model) {
  const tone = { positive: "var(--positive)", warn: "var(--goal)", danger: "var(--negative)", neutral: "var(--brand)" };
  return `<div class="card card--summary span-3">
    <div class="leak-header">
      ${svgIcon("sparkles", 18, "leak-header__icon")}
      <div>
        <p class="card-title" data-ui-css="margin:0">O que fazer agora</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">Ordenado por urgência, calculado no seu aparelho</p>
      </div>
    </div>
    <div class="summary-grid">
      ${model.advice.map((a) => `<div class="summary-item" data-ui-css="--tone:${tone[a.tone]}">
        <span class="summary-item__icon">${svgIcon(a.icon, 16)}</span>
        <p class="summary-item__text">${escapeHtml(a.text)}</p>
      </div>`).join("")}
    </div>
  </div>`;
}

// ---- Formulário (mesmo componente para criar e editar) ----
function renderGoalForm(gf, editing) {
  return `<div class="card card--elevated span-3">
    <p class="card-title">${editing ? "Editar meta" : "Nova meta"}</p>

    ${!editing ? `<div class="field"><p class="field__label">Começar de um modelo</p>
      <div class="class-picker">
        ${GOAL_TEMPLATES.map((t) => `<button class="class-chip" data-ui-css="--tone:var(--goal)" data-action="goal-template" data-value="${t.id}">
          ${svgIcon(t.icon, 15)}<span>${escapeHtml(t.name)}</span>
        </button>`).join("")}
      </div>
    </div>` : ""}

    <div class="field"><label class="field__label" for="goal-name-input">Nome da meta</label>
      <input id="goal-name-input" class="input" data-field="goal-name" value="${escapeHtml(gf.name)}" placeholder="Ex: Reserva de emergência" autocomplete="off" /></div>

    <div class="field-row">
      <div class="field"><label class="field__label" for="goal-target-input">Valor alvo</label>
        <input id="goal-target-input" class="input" data-field="goal-target" value="${escapeHtml(gf.target)}" inputmode="decimal" placeholder="0,00" /></div>
      <div class="field"><label class="field__label" for="goal-saved-input">${editing ? "Valor já guardado" : "Valor inicial"}</label>
        <input id="goal-saved-input" class="input" data-field="goal-saved-upfront" value="${escapeHtml(gf.savedUpfront)}" inputmode="decimal" placeholder="0,00" ${editing ? "disabled" : ""} /></div>
    </div>

    <div class="field-row">
      <div class="field"><label class="field__label" for="goal-deadline-input">Prazo (opcional)</label>
        <input id="goal-deadline-input" type="date" class="input" data-field="goal-deadline" value="${gf.deadline}" /></div>
      <div class="field"><label class="field__label" for="goal-plan-input">Aporte mensal planejado</label>
        <input id="goal-plan-input" class="input" data-field="goal-monthly-plan" value="${escapeHtml(gf.monthlyPlan)}" inputmode="decimal" placeholder="0,00" /></div>
    </div>

    <p class="field-hint">${editing
      ? "O valor guardado só muda por aporte ou resgate; assim o histórico de lançamentos nunca discorda do saldo da meta."
      : "Se informar um valor inicial, você escolherá se ele sai do saldo agora ou se já estava guardado antes."}</p>
    <p class="field-hint">O aporte planejado é o seu compromisso. O app compara ele com o que você realmente guardou e com o que o prazo exige.</p>

    <div class="field"><p class="field__label">Ícone</p>
      <div class="icon-picker">${GOAL_ICON_OPTIONS.map((k) => `<button class="icon-picker__btn ${gf.icon === k ? "active" : ""}" data-action="set-goal-icon" data-value="${k}" aria-label="Escolher ícone ${k}" aria-pressed="${gf.icon === k ? "true" : "false"}">${svgIcon(k, 19)}</button>`).join("")}</div>
    </div>

    <div class="form-actions">
      <button class="btn btn--ghost" data-action="cancel-goal-form">Cancelar</button>
      <button class="btn btn--goal" data-action="submit-goal">${editing ? "Salvar alterações" : "Criar meta"}</button>
    </div>
  </div>`;
}

// Sugere quanto aportar por mês para bater a meta até o prazo, com base no
// valor que ainda falta e nos meses restantes até o deadline.
function goalMonthlySuggestion(g) {
  if (!g.deadline || !(g.target > 0)) return null;
  const remaining = subMoney(g.target, g.current);
  if (remaining <= 0) return null;
  const daysLeft = daysBetweenIso(todayIso(), g.deadline);
  if (daysLeft <= 0) return null;
  const monthsLeft = Math.max(1, Math.ceil(daysLeft / 30.44));
  return divMoney(remaining, monthsLeft);
}

function renderGoalCard(m) {
  const g = m.goal;
  const expanded = state.expandedGoalId === g.id;
  const mode = state.goalActionMode;
  const tone = { positive: "var(--positive)", warn: "var(--goal)", danger: "var(--negative)", neutral: "var(--brand)" }[m.tone];
  const ringColor = m.done ? "var(--positive)" : "var(--goal)";

  return `<div class="card goal-card card--elevated span-1" data-ui-css="--tone:${tone}">
    <div class="goal-header">
      ${renderGoalRing(m.pct, ringColor, g.icon, 62)}
      <div class="goal-header__text">
        <p class="goal-name">${escapeHtml(g.name)}</p>
        <p class="goal-progress-inline"><b>${fmtBRL(m.saved)}</b> de ${fmtBRL(m.target)}</p>
        <span class="goal-status" data-ui-css="color:${tone}">${svgIcon(m.statusIcon, 12)} ${m.statusLabel}</span>
      </div>
      <div class="goal-header__actions">
        <button class="icon-btn" data-action="edit-goal" data-id="${g.id}" aria-label="Editar meta">${svgIcon("pencil", 15)}</button>
        <button class="icon-btn" data-action="delete-goal" data-id="${g.id}" aria-label="Excluir meta">${svgIcon("trash", 15)}</button>
      </div>
    </div>

    <div class="progress progress--sm" data-ui-css="margin:12px 0 4px"><div class="progress__fill" data-ui-css="width:${clamp(m.pct, 0, 100)}%; background:${ringColor}"></div></div>
    <p class="goal-remaining">${m.done ? `${svgIcon("checkCircle", 14)} Meta concluída` : `Faltam <b>${fmtBRL(m.remaining)}</b>`}${m.daysLeft != null ? ` · ${m.daysLeft >= 0 ? `${m.daysLeft} dias restantes` : "prazo encerrado"}` : ""}</p>

    ${!m.done ? `<div class="goal-numbers">
      <div class="goal-number">
        <span class="goal-number__label">Necessário</span>
        <b>${m.requiredMonthly != null ? `${fmtBRL(m.requiredMonthly)}` : "Sem dados"}</b>
        <span class="goal-number__hint">${m.requiredMonthly != null ? "para bater o prazo" : "sem prazo definido"}</span>
      </div>
      <div class="goal-number">
        <span class="goal-number__label">Planejado</span>
        <b>${m.plannedMonthly > 0 ? fmtBRL(m.plannedMonthly) : "Não definido"}</b>
        <span class="goal-number__hint">${m.plannedMonthly > 0 ? "definido por você" : "toque no lápis para definir"}</span>
      </div>
      <div class="goal-number">
        <span class="goal-number__label">Ritmo real</span>
        <b data-ui-css="color:${m.paceActive ? tone : "var(--ink-faint)"}">${m.paceActive ? fmtBRL(m.paceMonthly) : "Sem histórico"}</b>
        <span class="goal-number__hint">${m.paceActive ? `média de ${m.paceWindow} ${m.paceWindow === 1 ? "mês" : "meses"}` : "nenhum aporte ainda"}</span>
      </div>
    </div>` : ""}

    ${!m.done && m.etaIso ? `<p class="goal-eta ${m.etaLate ? "is-late" : ""}">
      ${svgIcon("clock", 13)}<span>No ritmo ${m.projectionSource === "real" ? "atual" : "planejado"}, conclusão em <b>${fmtDateFull(m.etaIso)}</b>${m.etaMonths ? ` (${m.etaMonths} ${m.etaMonths === 1 ? "mês" : "meses"})` : ""}${m.etaLate ? "; depois do prazo." : "."}</span>
    </p>` : ""}
    ${!m.done && !m.etaIso ? `<p class="goal-eta">${svgIcon("info", 13)}<span>Sem aportes nem plano definido, não dá para estimar a conclusão.</span></p>` : ""}
    ${!m.done && m.gap > 0 ? `<p class="goal-eta is-late">${svgIcon("alertTriangle", 13)}<span>Faltam <b>${fmtBRL(m.gap)}</b> por mês para o prazo fechar.</span></p>` : ""}

    ${m.series.some((s) => s.contributed !== 0) ? `<div class="goal-spark">
      ${renderSparkline(m.series.map((s) => ({ value: s.balance })), ringColor, 300, 46)}
      <div class="chart-axis">${m.series.map((s) => `<span>${s.label}</span>`).join("")}</div>
    </div>` : ""}

    ${expanded ? `
      <div class="goal-contribute-row">
        <input id="goal-contribution-input" class="input" data-field="contribution-amount" value="${escapeHtml(state.goalContribution)}" inputmode="decimal" placeholder="Valor" autocomplete="off" />
        <button class="btn btn--goal" data-action="submit-goal-action" data-id="${g.id}">${mode === "resgatar" ? "Resgatar" : "Aportar"}</button>
        <button class="icon-btn" data-action="collapse-goal" aria-label="Fechar aporte ou resgate">${svgIcon("x", 15)}</button>
      </div>
      <p class="field-hint">${mode === "resgatar"
        ? (goalExistingBalance(g) > 0
          ? "O valor que já existia é liberado primeiro, sem alterar o saldo. Depois, a parte aportada volta como receita."
          : "O valor sai da meta e entra como receita no saldo livre deste mês.")
        : "O valor entra na meta e sai do seu saldo livre deste mês."}</p>
    ` : `<div class="goal-action-row">
        <button class="btn btn--goal-soft" data-action="expand-goal" data-value="aportar" data-id="${g.id}">${svgIcon("plus", 14)} Aportar${m.plannedMonthly > 0 && m.contributedThisMonth <= 0 ? ` ${fmtBRL(m.plannedMonthly)}` : ""}</button>
        <button class="btn btn--ghost" data-action="expand-goal" data-value="resgatar" data-id="${g.id}" ${m.saved <= 0 ? "disabled" : ""}>${svgIcon("arrowDownRight", 14)} Resgatar</button>
      </div>`}
  </div>`;
}

// source: js/screens/calendar.js
// js/screens/calendar.js. Calendário do mês e previsão financeira. Modelos em calendar.js e forecast.js.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// CALENDÁRIO FINANCEIRO E PREVISÃO (Módulo 4)
// ------------------------------------------------------------------
// Como nas telas anteriores, nenhum cálculo mora aqui: `calendar.js`
// entrega a grade pronta e `forecast.js` entrega o saldo dia a dia.
// Este bloco só decide layout e cor.
// ==================================================================

const CAL_KIND = {
  done:        { label: "Lançado",   color: "var(--ink-faint)" },
  goal:        { label: "Meta",      color: "var(--goal)" },
  installment: { label: "Parcela",   color: "var(--brand)" },
  scheduled:   { label: "Agendado",  color: "var(--brand)" },
  recurring:   { label: "Previsto",  color: "var(--goal)" },
  income:      { label: "Renda",     color: "var(--positive)" },
  liability:   { label: "Dívida",    color: "var(--negative)" },
  late:        { label: "Atrasado",  color: "var(--negative)" },
  "goal-deadline": { label: "Prazo", color: "var(--goal)" },
};

function renderCalendarScreen() {
  const ref = addMonths(new Date(), state.calendar.monthOffset);
  const cal = buildCalendarMonth(state.data, keyOfDate(ref));
  const forecast = forecastModel();
  const selected = state.calendar.selectedDay;

  return `<div class="screen">
    <div class="screen-header">
      <div class="back-header">
        <button class="icon-btn" data-action="back" data-tab="dashboard" aria-label="Voltar">${svgIcon("chevronLeft", 19)}</button>
        <h1 class="page-title">Calendário</h1>
      </div>
      <div class="month-nav">
        <button class="icon-btn" data-action="cal-prev" aria-label="Mês anterior">${svgIcon("chevronLeft", 17)}</button>
        <span class="month-nav__label">${MONTH_ABBR[cal.month]} ${cal.year}</span>
        <button class="icon-btn" data-action="cal-next" aria-label="Próximo mês">${svgIcon("chevronRight", 17)}</button>
      </div>
    </div>

    <div class="grid-dashboard">
      ${renderCalendarSummary(cal)}
      ${renderCalendarGrid(cal)}
      ${selected ? renderCalendarDayPanel(cal, selected) : ""}
      ${renderForecastCard(forecast, true)}
      ${renderAnnualPlanCard()}
      <p class="footnote span-3">Dias com barra cheia já foram lançados; barra vazada é previsão. Nada aqui vira lançamento sozinho; o calendário só antecipa o que já está nos seus dados.</p>
    </div>
  </div>`;
}

// ---- Cabeçalho do mês: realizado x previsto, lado a lado e nunca somados ----
function renderCalendarSummary(cal) {
  const t = cal.totals;
  const netTone = t.net >= 0 ? "var(--positive)" : "var(--negative)";
  return `<div class="card card--hero span-3">
    <div class="hero-glow"></div>
    <p class="hero-label">Resultado previsto de ${MONTH_NAMES[cal.month]}</p>
    <p class="hero-value">${t.net >= 0 ? "" : "−"}${fmtBRL(Math.abs(t.net))}</p>
    <p class="hero-reserved">${t.count} ${t.count === 1 ? "evento no mês" : "eventos no mês"}${t.lateCount > 0 ? ` · ${t.lateCount} em atraso` : ""}</p>

    <div class="hero-chips">
      <div class="hero-chip">${svgIcon("arrowUpRight", 17)}<div>
        <span class="hero-chip__label">Entradas</span>
        <span class="hero-chip__value">${fmtBRL(t.income)}</span>
      </div></div>
      <div class="hero-chip">${svgIcon("arrowDownRight", 17)}<div>
        <span class="hero-chip__label">Saídas</span>
        <span class="hero-chip__value">${fmtBRL(t.expense)}</span>
      </div></div>
      <div class="hero-chip">${svgIcon("clock", 17)}<div>
        <span class="hero-chip__label">Ainda por vir</span>
        <span class="hero-chip__value">${fmtBRL(t.plannedExpense)}</span>
      </div></div>
    </div>

    <div class="cal-split">
      <div class="cal-split__row">
        <span class="cal-split__dot cal-split__dot--done"></span>
        <span>Já lançado</span>
        <b>${fmtBRL(t.realizedExpense)}</b>
      </div>
      <div class="cal-split__row">
        <span class="cal-split__dot cal-split__dot--planned"></span>
        <span>Previsto até o fim do mês</span>
        <b>${fmtBRL(t.plannedExpense)}</b>
      </div>
    </div>
    ${t.lateCount > 0 ? `<p class="cal-late-note" data-ui-css="color:${netTone}">${svgIcon("alertTriangle", 13)} ${fmtBRL(t.lateTotal)} em gastos fixos venceram e ainda não foram lançados.</p>` : ""}
  </div>`;
}

// ---- Grade do mês ----
function renderCalendarGrid(cal) {
  const maxC = cal.weeks.reduce((mx, week) => week.reduce((m, d) => Math.max(m, moneyToCents(d.expense)), mx), 0);
  const selected = state.calendar.selectedDay;

  return `<div class="card span-3">
    <p class="card-title">${escapeHtml(cal.label)}</p>
    <div class="cal-grid" role="grid" aria-label="Calendário de ${escapeHtml(cal.label)}">
      ${cal.weekdays.map((w) => `<span class="cal-weekday">${w}</span>`).join("")}
      ${cal.weeks.map((week) => week.map((d) => {
        if (!d.inMonth) return `<span class="cal-day cal-day--out" aria-hidden="true">${d.day}</span>`;
        const ratio = maxC > 0 ? moneyToCents(d.expense) / maxC : 0;
        const classes = [
          "cal-day",
          d.isToday ? "is-today" : "",
          selected === d.iso ? "is-selected" : "",
          d.hasLate ? "is-late" : "",
          d.count > 0 ? "has-events" : "",
        ].filter(Boolean).join(" ");
        return `<button class="${classes}" data-action="cal-day" data-value="${d.iso}"
          aria-label="${d.day}. ${d.count} ${d.count === 1 ? "evento" : "eventos"}">
          <span class="cal-day__num">${d.day}</span>
          ${d.income > 0 ? `<span class="cal-day__in"></span>` : ""}
          ${d.expense > 0 ? `<span class="cal-day__bar ${d.hasPlanned ? "is-planned" : ""}" data-ui-css="height:${clamp(18 + ratio * 60, 18, 78)}%"></span>` : ""}
        </button>`;
      }).join("")).join("")}
    </div>
    <div class="cal-legend">
      <span><i class="cal-legend__swatch cal-legend__swatch--done"></i>Lançado</span>
      <span><i class="cal-legend__swatch cal-legend__swatch--planned"></i>Previsto</span>
      <span><i class="cal-legend__swatch cal-legend__swatch--in"></i>Entrada</span>
      <span><i class="cal-legend__swatch cal-legend__swatch--late"></i>Atraso</span>
    </div>
    ${cal.heaviest.length > 0 ? `<div class="cal-heavy">
      <p class="card-subtitle" data-ui-css="margin:0 0 8px">Dias mais pesados do mês</p>
      ${cal.heaviest.map((h) => `<button class="cal-heavy__row" data-action="cal-day" data-value="${h.iso}">
        <span class="cal-heavy__date">${fmtDateShort(h.iso)}</span>
        <span class="cal-heavy__count">${h.count} ${h.count === 1 ? "evento" : "eventos"}</span>
        <b>${fmtBRL(h.expense)}</b>
      </button>`).join("")}
    </div>` : ""}
  </div>`;
}

// ---- Painel do dia selecionado ----
function renderCalendarDayPanel(cal, iso) {
  const row = cal.dayOf(iso);
  const events = row ? row.events : [];
  const income = sumMoney(events.filter((e) => e.type === "income"), (e) => e.amount);
  const expense = sumMoney(events.filter((e) => e.type === "expense"), (e) => e.amount);

  return `<div class="card card--elevated span-3">
    <div class="mini-card__head">
      <div>
        <p class="card-title" data-ui-css="margin:0">${fmtDateFull(iso)}</p>
        <p class="mini-card__sub">${events.length === 0 ? "Nenhum evento neste dia" : `${events.length} ${events.length === 1 ? "evento" : "eventos"}`}</p>
      </div>
      <button class="icon-btn icon-btn--muted" data-action="cal-close-day" aria-label="Fechar detalhes do dia">${svgIcon("x", 16)}</button>
    </div>

    ${events.length === 0
      ? renderEmptyState("calendar", "Dia livre.", "Nenhuma conta, parcela ou recebimento previsto para esta data.")
      : `<div class="bill-list">
        ${events.map((e) => {
          const kind = CAL_KIND[e.kind] || CAL_KIND.scheduled;
          const sign = e.type === "income" ? "+" : (e.type === "marker" ? "" : "−");
          const amountColor = e.type === "income" ? "var(--positive)" : (e.type === "marker" ? "var(--ink-faint)" : "var(--ink)");
          return `<div class="bill-row ${e.done ? "" : "bill-row--planned"}">
            <span class="icon-bubble icon-bubble--sm" data-ui-css="background:color-mix(in srgb, ${e.color} 14%, transparent); color:${e.color}">${svgIcon(e.icon, 14)}</span>
            <div class="bill-row__info">
              <p class="bill-row__label">${escapeHtml(e.label)}${e.installment ? ` <span class="bill-row__inst">${e.installment}</span>` : ""}</p>
              <p class="bill-row__meta" data-ui-css="color:${kind.color}">${kind.label}${e.certain ? "" : " · estimativa"} · ${escapeHtml(e.categoryName)}</p>
            </div>
            ${e.type === "marker"
              ? `<span class="bill-row__amount" data-ui-css="color:${amountColor}">${e.meta && e.meta.remaining > 0 ? `faltam ${fmtBRL(e.meta.remaining)}` : "no prazo"}</span>`
              : `<span class="bill-row__amount" data-ui-css="color:${amountColor}">${sign}${fmtBRL(e.amount)}</span>`}
          </div>`;
        }).join("")}
      </div>
      <div class="cal-day-total">
        <span>Saldo do dia</span>
        <b data-ui-css="color:${subMoney(income, expense) >= 0 ? "var(--positive)" : "var(--negative)"}">${subMoney(income, expense) >= 0 ? "+" : "−"}${fmtBRL(Math.abs(subMoney(income, expense)))}</b>
      </div>`}
  </div>`;
}

// ---- Previsão financeira ----
// `full = true` mostra gráfico, premissas e alerta de saldo negativo (tela do
// calendário). `full = false` é a versão compacta do Dashboard.
function renderForecastCard(forecast, full) {
  const f = forecast || forecastModel();
  const active = f.horizons.find((h) => h.id === state.forecastHorizon) || f.horizons[1];
  const tone = { positive: "var(--positive)", warn: "var(--goal)", danger: "var(--negative)" }[active.tone];

  const chips = `<div class="horizon-chips">
      ${f.horizons.map((h) => `<button class="horizon-chip ${h.id === active.id ? "active" : ""}" data-action="set-forecast-horizon" data-value="${h.id}">${h.label}</button>`).join("")}
    </div>`;
  const alert = f.negativeDayIso
    ? `<p class="forecast-alert">${svgIcon("alertTriangle", 14)}<span>No ritmo atual seu saldo fica negativo em <b>${fmtDateFull(f.negativeDayIso)}</b>. O menor ponto é ${fmtBRL(f.lowest.value)} em ${fmtDateShort(f.lowest.iso)}.</span></p>`
    : "";

  // Versão compacta do Dashboard: faixa horizontal de largura inteira, para não
  // abrir buraco na grade de três colunas.
  if (!full) {
    return `<div class="card card--forecast span-3">
      <div class="forecast-strip">
        <div class="forecast-strip__main">
          <p class="card-title" data-ui-css="margin:0">Previsão de saldo</p>${renderCalculationButton("forecast")}
          <p class="forecast-value" data-ui-css="color:${tone}">${fmtBRL(active.projected)}</p>
          <p class="forecast-note">em ${active.label} · hoje você tem ${fmtBRL(f.balance)} (${active.delta >= 0 ? "+" : "−"}${fmtBRL(Math.abs(active.delta))})</p>
        </div>
        <div class="forecast-strip__side">
          ${chips}
          <div class="forecast-strip__stats">
            <span>${svgIcon("arrowUpRight", 13)} ${fmtBRL(active.income)}</span>
            <span>${svgIcon("arrowDownRight", 13)} ${fmtBRL(active.expense)}</span>
          </div>
          <button class="btn btn--secondary btn--sm" data-action="nav" data-tab="calendar">${svgIcon("calendar", 14)} Calendário</button>
        </div>
      </div>
      ${alert}
    </div>`;
  }

  return `<div class="card span-3 card--forecast">
    <div class="mini-card__head">
      <div>
        <p class="card-title" data-ui-css="margin:0">Previsão de saldo</p>
        <p class="mini-card__sub">Hoje: ${fmtBRL(f.balance)}</p>
      </div>
      ${renderCalculationButton("forecast")}
    </div>

    ${chips}

    <p class="forecast-value" data-ui-css="color:${tone}">${fmtBRL(active.projected)}</p>
    <p class="forecast-note">
      ${active.delta >= 0 ? "+" : "−"}${fmtBRL(Math.abs(active.delta))} em ${active.label} ·
      entradas ${fmtBRL(active.income)} · saídas ${fmtBRL(active.expense)}
    </p>

    ${renderForecastChart(f, active)}
    ${alert}

    <div class="forecast-assumptions">
      <p class="card-subtitle" data-ui-css="margin:0 0 8px">De onde vêm estes números</p>
      <ul class="forecast-list">${f.assumptions.map((a) => `<li>${escapeHtml(a)}</li>`).join("")}</ul>
      <p class="field-hint">Quanto mais longe o horizonte, maior a margem de erro: 7 e 30 dias saem quase todos de dados reais; 12 meses depende de médias.</p>
    </div>
  </div>`;
}

function renderForecastChart(f, horizon) {
  const w = 640, h = 170, padTop = 12, padBottom = 22;
  const slice = f.days.slice(0, horizon.days);
  const series = [{ iso: f.today, balance: f.balance }].concat(slice);
  const points = resampleSeries(series, 90);
  const values = points.map((p) => p.balance);
  if (values.length < 2) return "";

  const min = Math.min(...values, 0);
  const max = Math.max(...values, 1);
  const span = max - min || 1;
  const plotH = h - padTop - padBottom;
  const x = (i) => (i / (points.length - 1)) * w;
  const y = (v) => padTop + plotH - ((v - min) / span) * plotH;
  const pts = points.map((p, i) => `${x(i).toFixed(1)},${y(p.balance).toFixed(1)}`);
  const color = values[values.length - 1] >= 0 ? "var(--brand)" : "var(--negative)";
  const gid = `fc-grad-${Math.random().toString(36).slice(2, 8)}`;
  const zeroY = min < 0 ? y(0) : null;

  return `<div class="forecast-chart-wrap">
    <svg class="wealth-chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Projeção de saldo para ${horizon.label}">
      <defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${color}" stop-opacity="0.26"/>
        <stop offset="100%" stop-color="${color}" stop-opacity="0"/>
      </linearGradient></defs>
      ${zeroY != null ? `<line x1="0" y1="${zeroY.toFixed(1)}" x2="${w}" y2="${zeroY.toFixed(1)}" stroke="var(--negative)" stroke-width="1" stroke-dasharray="4 4"/>` : ""}
      <polygon points="0,${padTop + plotH} ${pts.join(" ")} ${w},${padTop + plotH}" fill="url(#${gid})"/>
      <polyline points="${pts.join(" ")}" fill="none" stroke="${color}" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke"/>
      <circle cx="${x(points.length - 1).toFixed(1)}" cy="${y(values[values.length - 1]).toFixed(1)}" r="4" fill="var(--card)" stroke="${color}" stroke-width="2.4" vector-effect="non-scaling-stroke"/>
    </svg>
    <div class="chart-axis">
      <span>${fmtDateShort(f.today)}</span>
      <span>${fmtDateShort(horizon.endIso)}</span>
    </div>
  </div>`;
}

// ---- Planejamento anual ----
function renderAnnualPlanCard() {
  const plan = buildAnnualPlan(state.data);
  const open = state.calendar.annualOpen;
  const list = open ? plan.items : plan.upcoming.slice(0, 4);

  return `<div class="card span-3">
    <div class="mini-card__head">
      <div>
        <p class="card-title" data-ui-css="margin:0">Planejamento anual de ${plan.year}</p>
        <p class="mini-card__sub">Datas que chegam todo ano e mesmo assim pegam de surpresa</p>
      </div>
      <button class="btn btn--ghost btn--sm" data-action="toggle-annual">${open ? "Ver só o que vem" : "Ver o ano todo"}</button>
    </div>

    ${plan.knownTotal > 0 ? `<div class="annual-summary">
      <div><span class="annual-summary__label">Estimado pelo seu histórico</span><b>${fmtBRL(plan.knownTotal)}</b></div>
      <div><span class="annual-summary__label">Guardando por mês</span><b>${fmtBRL(plan.monthlyReserve)}</b></div>
    </div>` : ""}

    <div class="annual-list">
      ${list.map((i) => `<div class="annual-row ${i.passed ? "is-past" : ""} ${i.isCurrent ? "is-current" : ""}">
        <span class="annual-row__month">${i.monthAbbr}</span>
        <span class="icon-bubble icon-bubble--sm" data-ui-css="background:color-mix(in srgb, ${i.isIncome ? "var(--positive)" : "var(--goal)"} 14%, transparent); color:${i.isIncome ? "var(--positive)" : "var(--goal)"}">${svgIcon(i.icon, 14)}</span>
        <div class="annual-row__info">
          <p class="annual-row__name">${escapeHtml(i.name)}</p>
          <p class="annual-row__note">${escapeHtml(i.note)}</p>
        </div>
        <span class="annual-row__value">${i.estimated
          ? `${i.isIncome ? "+" : ""}${fmtBRL(i.estimated)}<span class="annual-row__from">em ${i.estimatedFrom}</span>`
          : `<span class="annual-row__from">sem histórico</span>`}</span>
      </div>`).join("")}
    </div>
    <p class="field-hint">O valor vem do que você lançou em anos anteriores no mesmo mês; nada é estimado por média de mercado.</p>
  </div>`;
}

// source: js/screens/health.js
// js/screens/health.js. Saúde financeira. O diagnóstico vem de health.js.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// SAÚDE FINANCEIRA (Módulo 2)
// ------------------------------------------------------------------
// Tela dedicada de diagnóstico. Todo o raciocínio financeiro mora em
// health.js; aqui só existe transformação de modelo em HTML. O Score
// não é recalculado nem duplicado: o modelo devolve o mesmo objeto
// produzido por score.js e a tela reaproveita `renderScoreGauge`.
// ==================================================================
function renderHealthScreen() {
  const model = healthModel(keyOfCurrentMonth());
  const h = model.headline;
  const toneColor = { positive: "var(--positive)", warn: "var(--goal)", danger: "var(--negative)", neutral: "var(--ink-soft)" };

  return `<div class="screen">
    ${renderBackHeader("Saúde financeira")}
    <div class="grid-dashboard">
      ${renderHealthHero(model, h, toneColor)}
      ${model.indicators.map((i) => renderHealthIndicator(i)).join("")}
      ${renderHealthPlan(model)}
      <p class="footnote span-3">Os indicadores usam apenas os seus lançamentos, metas e renda cadastrada. Nada é enviado para fora do aparelho. As faixas são referências educativas, e indicadores sem base de cálculo ficam marcados como “sem dados”.</p>
    </div>
  </div>`;
}

// ---- Cabeçalho: diagnóstico em uma frase + nota geral + distribuição ----
function renderHealthHero(model, h, toneColor) {
  const s = model.score;
  const counts = model.counts;
  const chips = [
    { id: "otimo",   label: "ótimo",    color: "var(--positive)" },
    { id: "bom",     label: "saudável", color: "var(--brand)" },
    { id: "atencao", label: "atenção",  color: "var(--goal)" },
    { id: "critico", label: "crítico",  color: "var(--negative)" },
    { id: "sem",     label: "sem dados", color: "var(--ink-faint)" },
  ].filter((c) => counts[c.id] > 0);

  return `<div class="card card--health-hero span-3" data-ui-css="--tone:${toneColor[h.tone]}">
    <div class="health-calculation-link">${renderCalculationButton("health")}</div>
    <div class="health-hero__grid">
      ${s && !s.insufficient ? `<div class="health-hero__gauge">
        ${renderScoreGauge(s.score, s.level.color, 104)}
        <p class="health-hero__gauge-label" data-ui-css="color:${s.level.color}">${s.level.label}</p>
        <p class="health-hero__gauge-note">Score financeiro</p>
      </div>` : ""}
      <div class="health-hero__text">
        <p class="health-hero__eyebrow">${svgIcon(h.tone === "positive" ? "checkCircle" : h.tone === "neutral" ? "info" : "alertTriangle", 14)}<span>Diagnóstico de ${MONTH_NAMES[new Date().getMonth()].toLowerCase()}</span></p>
        <h2 class="health-hero__title">${escapeHtml(h.title)}</h2>
        <p class="health-hero__desc">${escapeHtml(h.text)}</p>
        ${chips.length > 0 ? `<div class="health-chips">
          ${chips.map((c) => `<span class="health-chip" data-ui-css="--tone:${c.color}"><b>${counts[c.id]}</b> ${c.label}</span>`).join("")}
        </div>` : ""}
      </div>
    </div>
  </div>`;
}

// ---- Cartão de um indicador ----
function renderHealthIndicator(i) {
  const open = state.healthDetailId === i.id;
  const color = i.status.color;
  const pct = Math.round(i.ratio * 100);

  return `<div class="card card--indicator span-1" data-ui-css="--tone:${color}">
    <div class="indicator__head">
      <span class="icon-bubble icon-bubble--sm" data-ui-css="background:color-mix(in srgb, ${color} 14%, transparent); color:${color}">${svgIcon(i.icon, 16)}</span>
      <div class="indicator__head-text">
        <p class="card-title" data-ui-css="margin:0">${escapeHtml(i.label)}</p>
        <p class="indicator__status" data-ui-css="color:${color}">${i.status.label}</p>
      </div>
    </div>

    ${i.applicable ? `
      <p class="indicator__value">${escapeHtml(i.display)}</p>
      <p class="indicator__caption">${escapeHtml(i.caption)}</p>
      <div class="indicator__meter" role="img" aria-label="${escapeHtml(i.label)}: ${pct} de 100">
        <div class="indicator__meter-fill" data-ui-css="width:${pct}%; background:${color}"></div>
        ${i.marks.map((m) => `<span class="indicator__mark" data-ui-css="left:${clamp(m.at * 100, 0, 100)}%" title="${escapeHtml(m.label)}"></span>`).join("")}
      </div>
    ` : `<p class="indicator__value indicator__value--empty">Sem dados</p>`}

    <p class="indicator__desc">${escapeHtml(i.description)}</p>

    ${i.recommendation ? `<div class="indicator__advice">
      ${svgIcon("sparkles", 14, "indicator__advice-icon")}
      <div>
        <p class="indicator__advice-text">${escapeHtml(i.recommendation)}</p>
        ${i.cta ? `<button class="btn btn--secondary btn--sm" data-action="nav" data-tab="${i.cta.tab}">${escapeHtml(i.cta.label)}</button>` : ""}
      </div>
    </div>` : ""}

    <button class="indicator__more" data-action="toggle-health-detail" data-id="${i.id}" aria-expanded="${open}">
      <span>${open ? "Ocultar" : "Como é calculado"}</span>${svgIcon(open ? "chevronUp" : "chevronDown", 14)}
    </button>
    ${open ? `<div class="indicator__method">
      <p>${escapeHtml(i.what)}</p>
      ${i.benchmark ? `<p class="indicator__benchmark">${escapeHtml(i.benchmark)}</p>` : ""}
    </div>` : ""}
  </div>`;
}

// ---- Plano de ação: fila priorizada, não uma lista de desejos ----
function renderHealthPlan(model) {
  const plan = model.actionPlan;
  if (plan.length === 0) {
    return `<div class="card span-3">
      <p class="card-title">Plano de ação</p>
      ${model.rated === 0
        ? renderEmptyState("target", "Sem diagnóstico ainda.", "Cadastre sua renda e alguns lançamentos para receber recomendações.")
        : renderEmptyState("checkCircle", "Nenhuma ação urgente.", "Todos os indicadores avaliados estão em nível saudável ou ótimo.")}
    </div>`;
  }
  return `<div class="card card--plan span-3">
    <p class="card-title">Plano de ação</p>
    <p class="health-sub">Na ordem em que faz sentido resolver: liquidez e dívida antes de reserva, reserva antes de investimento.</p>
    <ol class="plan-list">
      ${plan.map((p) => `<li class="plan-item" data-ui-css="--tone:${p.status.color}">
        <span class="plan-item__num">${p.order}</span>
        <div class="plan-item__body">
          <p class="plan-item__label">${svgIcon(p.icon, 13)}<span>${escapeHtml(p.label)}</span><span class="plan-item__tag">${p.status.label}</span></p>
          <p class="plan-item__text">${escapeHtml(p.text)}</p>
          ${p.cta ? `<button class="btn btn--secondary btn--sm" data-action="nav" data-tab="${p.cta.tab}">${escapeHtml(p.cta.label)}</button>` : ""}
        </div>
      </li>`).join("")}
    </ol>
  </div>`;
}

// source: js/screens/wealth.js
// js/screens/wealth.js. Patrimônio: bens, dívidas e evolução. Cálculo em wealth.js.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// PATRIMÔNIO (Módulo 3)
// ------------------------------------------------------------------
// Cadastro de bens e dívidas + evolução mensal + comparação anual.
// Todo o cálculo mora em wealth.js/metrics.js; aqui só há montagem de
// HTML e manipulação do formulário. O gráfico é SVG puro, sem lib.
// ==================================================================
function renderWealthScreen() {
  const model = wealthModel(state.wealth.months);
  const wf = state.wealth.form;

  return `<div class="screen">
    <div class="screen-header">
      <div class="back-header">
        <button class="icon-btn" data-action="back" data-tab="dashboard" aria-label="Voltar">${svgIcon("chevronLeft", 19)}</button>
        <h1 class="page-title">Patrimônio</h1>
      </div>
      <button class="btn btn--primary btn--sm" data-action="wealth-new">${svgIcon("plus", 15)} Cadastrar</button>
    </div>

    <div class="grid-dashboard">
      ${renderWealthHero(model)}
      ${wf ? renderWealthForm(wf) : ""}
      ${renderWealthChartCard(model)}
      ${renderWealthAnnualCard(model)}
      ${model.allocation.length > 0 ? renderWealthAllocationCard(model) : ""}
      ${renderWealthInsightsCard(model)}
      ${renderWealthGroups(model)}
      <p class="footnote span-3">O caixa vem dos seus lançamentos. Bens e dívidas cadastrados aqui completam o quadro; e cada item guarda o próprio histórico mensal, então a curva acima é reconstruída com o valor que cada bem tinha na época, não com o de hoje.</p>
    </div>
  </div>`;
}

// ---- Painel principal: patrimônio líquido e composição ----
function renderWealthHero(m) {
  const c = m.composition;
  const d = m.delta.year;
  const trendColor = d.up ? "var(--positive)" : "var(--negative)";

  return `<div class="card card--hero span-3">
    <div class="hero-glow"></div>
    <div class="hero-label-row"><p class="hero-label">Patrimônio líquido</p>${renderCalculationButton("net-worth")}</div>
    <p class="hero-value">${fmtBRL(m.worth.total)}</p>
    ${d.comparable ? `<p class="hero-reserved">${svgIcon(d.up ? "arrowUpRight" : "arrowDownRight", 14)} ${d.up ? "+" : "−"}${fmtBRL(Math.abs(d.value))} (${d.up ? "+" : "−"}${Math.abs(d.pct).toFixed(1)}%) em ${m.months} meses</p>` : ""}

    ${c.gross > 0 ? `<div class="wealth-bar">
      ${c.positive.map((b) => `<div class="wealth-bar__seg" data-ui-css="flex:${Math.max(b.value, 1)}; background:${b.color}" title="${escapeHtml(b.label)}"></div>`).join("")}
    </div>` : ""}

    <div class="hero-chips">
      <div class="hero-chip">${svgIcon("layout", 17)}<div><span class="hero-chip__label">Total em bens</span><span class="hero-chip__value">${fmtBRL(c.gross)}</span></div></div>
      <div class="hero-chip">${svgIcon("alertTriangle", 17)}<div><span class="hero-chip__label">Dívidas</span><span class="hero-chip__value">${fmtBRL(c.debts)}</span></div></div>
      ${m.monthlyPayment > 0 ? `<div class="hero-chip">${svgIcon("bell", 17)}<div><span class="hero-chip__label">Parcelas por mês</span><span class="hero-chip__value">${fmtBRL(m.monthlyPayment)}</span></div></div>` : ""}
    </div>
    ${c.debts > 0 ? `<button class="btn btn--secondary btn--sm" data-action="nav" data-tab="debts">Planejar quitação das dívidas</button>` : ""}

    <div class="wealth-legend">
      ${c.positive.map((b) => `<div class="wealth-legend__item">
        <span class="cat-dot" data-ui-css="background:${b.color}"></span>
        <div class="wealth-legend__text">
          <span class="wealth-legend__label">${escapeHtml(b.label)} · ${b.pct.toFixed(0)}%</span>
          <span class="wealth-legend__note">${escapeHtml(b.note)}</span>
        </div>
        <b>${fmtBRL(b.value)}</b>
      </div>`).join("")}
      ${c.negative.map((b) => `<div class="wealth-legend__item wealth-legend__item--neg">
        <span class="cat-dot" data-ui-css="background:${b.color}"></span>
        <div class="wealth-legend__text"><span class="wealth-legend__label">${escapeHtml(b.label)}</span></div>
        <b>−${fmtBRL(b.value)}</b>
      </div>`).join("")}
    </div>
  </div>`;
}

// ---- Formulário de cadastro/edição ----
function renderWealthForm(f) {
  const cls = assetClassOf(f.class);
  const editing = !!f.id;
  const isLiability = cls.kind === "liability";
  const isAccount = f.class === "conta" || f.class === "carteira";

  return `<div class="card card--elevated span-3" id="wealth-form" data-ui-css="scroll-margin-top:18px">
    <p class="card-title">${editing ? "Editar item" : "Cadastrar bem ou dívida"}</p>

    <div class="field"><p class="field__label">Tipo</p>
      <div class="class-picker">
        ${ASSET_CLASSES.map((c) => `<button class="class-chip ${f.class === c.id ? "active" : ""}" data-ui-css="--tone:${c.color}" data-action="wealth-set-class" data-value="${c.id}">
          ${svgIcon(c.icon, 15)}<span>${escapeHtml(c.label)}</span>
        </button>`).join("")}
      </div>
      <p class="field-hint">${escapeHtml(cls.hint)}</p>
    </div>

    <div class="field"><label class="field__label" for="wealth-name-input">Nome</label>
      <input id="wealth-name-input" class="input" data-field="wealth-name" value="${escapeHtml(f.name)}" placeholder="${escapeHtml(isLiability ? "Ex: Financiamento do carro" : "Ex: Apartamento")}" autocomplete="off" maxlength="60" /></div>

    <div class="field-row">
      <div class="field"><label class="field__label" for="wealth-value-input">${isLiability ? "Saldo devedor hoje" : "Valor atual"}</label>
        <input id="wealth-value-input" class="input" data-field="wealth-value" value="${escapeHtml(f.value)}" inputmode="decimal" placeholder="0,00" /></div>
      ${isLiability ? `<div class="field"><label class="field__label" for="wealth-payment-input">Parcela mensal</label>
        <input id="wealth-payment-input" class="input" data-field="wealth-payment" value="${escapeHtml(f.monthlyPayment)}" inputmode="decimal" placeholder="0,00" /></div>` : ""}
    </div>

    ${isLiability ? `<div class="field"><label class="field__label" for="wealth-dueday-input">Dia do vencimento (opcional)</label>
      <input id="wealth-dueday-input" class="input" data-field="wealth-dueday" value="${escapeHtml(f.dueDay)}" inputmode="numeric" placeholder="Ex: 10" maxlength="2" />
      <p class="field-hint">Informando o dia, a parcela aparece no Calendário e entra na previsão de saldo. Sem ele, nenhum dia é marcado; melhor não marcar do que marcar errado.</p></div>` : ""}

    <div class="field"><label class="field__label" for="wealth-note-input">Observação (opcional)</label>
      <input id="wealth-note-input" class="input" data-field="wealth-note" value="${escapeHtml(f.note)}" placeholder="Ex: Tesouro Selic 2029 na corretora" autocomplete="off" maxlength="140" /></div>

    ${isAccount ? `<button class="toggle-row" data-action="wealth-toggle-ledger">
      <span class="toggle-row__box ${f.inLedger ? "active" : ""}">${f.inLedger ? svgIcon("check", 13) : ""}</span>
      <span class="toggle-row__text">
        <b>O saldo desta conta já vem dos meus lançamentos</b>
        <span>Marque para o item aparecer na lista sem somar de novo no patrimônio; é o que evita contar o mesmo dinheiro duas vezes.</span>
      </span>
    </button>` : ""}

    ${isLiability ? `<p class="field-hint">A parcela mensal informada entra no indicador de Dívidas da tela Saúde Financeira.</p>` : ""}

    <div class="form-actions">
      <button class="btn btn--ghost" data-action="wealth-cancel">Cancelar</button>
      <button class="btn btn--primary" data-action="wealth-save">${editing ? "Salvar alterações" : "Cadastrar"}</button>
    </div>
  </div>`;
}

// ---- Gráfico de evolução (SVG puro, com eixo e ponto destacado) ----
function renderWealthChart(series, width, height) {
  const w = width || 640;
  const h = height || 170;
  const padTop = 12;
  const padBottom = 22;
  const values = series.map((p) => p.value);
  if (values.length < 2) return `<p class="footnote">Ainda não há meses suficientes para desenhar a evolução.</p>`;

  const min = Math.min(...values, 0);
  const max = Math.max(...values, 1);
  const span = max - min || 1;
  const plotH = h - padTop - padBottom;
  const x = (i) => (i / (series.length - 1)) * w;
  const y = (v) => padTop + plotH - ((v - min) / span) * plotH;

  const pts = series.map((p, i) => `${x(i).toFixed(1)},${y(p.value).toFixed(1)}`);
  const area = `0,${padTop + plotH} ${pts.join(" ")} ${w},${padTop + plotH}`;
  const up = values[values.length - 1] >= values[0];
  const color = up ? "var(--brand)" : "var(--negative)";
  const gid = `wealth-grad-${Math.random().toString(36).slice(2, 8)}`;
  const zeroY = min < 0 ? y(0) : null;
  const lastI = series.length - 1;

  return `<svg class="wealth-chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Evolução do patrimônio ${series.length === 1 ? "no último mês" : `nos últimos ${series.length} meses`}">
    <defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="${color}" stop-opacity="0.26"/>
      <stop offset="100%" stop-color="${color}" stop-opacity="0"/>
    </linearGradient></defs>
    ${zeroY != null ? `<line x1="0" y1="${zeroY.toFixed(1)}" x2="${w}" y2="${zeroY.toFixed(1)}" stroke="var(--border)" stroke-width="1" stroke-dasharray="4 4"/>` : ""}
    <polygon points="${area}" fill="url(#${gid})"/>
    <polyline points="${pts.join(" ")}" fill="none" stroke="${color}" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke"/>
    <circle cx="${x(lastI).toFixed(1)}" cy="${y(values[lastI]).toFixed(1)}" r="4" fill="var(--card)" stroke="${color}" stroke-width="2.4" vector-effect="non-scaling-stroke"/>
  </svg>`;
}

function renderWealthChartCard(m) {
  const opts = [6, 12, 24];
  const first = m.series[0];
  const last = m.series[m.series.length - 1];
  return `<div class="card span-3">
    <div class="wealth-chart__head">
      <div>
        <p class="card-title" data-ui-css="margin:0">Evolução mensal</p>
        <p class="health-sub">De ${escapeHtml(first.label)}/${String(first.year).slice(2)} até hoje.</p>
      </div>
      <div class="seg-control">
        ${opts.map((o) => `<button class="seg-control__btn ${m.months === o ? "active" : ""}" data-action="wealth-months" data-value="${o}">${o}m</button>`).join("")}
      </div>
    </div>
    ${renderWealthChart(m.series)}
    <div class="wealth-axis">${m.series.map((p, i) => `<span class="${p.isCurrent ? "is-current" : ""}">${i % Math.ceil(m.series.length / 6) === 0 || p.isCurrent ? escapeHtml(p.label) : ""}</span>`).join("")}</div>
    <div class="wealth-deltas">
      ${[["No mês", m.delta.month], ["6 meses", m.delta.sixMonths], [`${m.months} meses`, m.delta.year]].map(([label, d]) => `
        <div class="wealth-delta">
          <span class="wealth-delta__label">${escapeHtml(label)}</span>
          <b class="wealth-delta__value" data-ui-css="color:${d.comparable ? (d.up ? "var(--positive)" : "var(--negative)") : "var(--ink-faint)"}">
            ${d.comparable ? `${d.up ? "+" : "−"}${fmtBRLShort(Math.abs(d.value))}` : "Sem dados"}
          </b>
        </div>`).join("")}
    </div>
    <p class="footnote" data-ui-css="text-align:left">O último ponto é o patrimônio de hoje, não uma projeção de fim de mês; por isso ele bate exatamente com o número do topo. Início em ${fmtBRL(first.value)}, hoje ${fmtBRL(last.value)}.</p>
  </div>`;
}

// ---- Comparação anual ----
function renderWealthAnnualCard(m) {
  const a = m.annual;
  const years = a.years;
  const maxAbs = Math.max(...years.map((r) => Math.abs(r.value)), 1);

  return `<div class="card span-2">
    <p class="card-title">Comparação anual</p>
    <p class="health-sub">Fechamento de cada ano civil. O ano corrente é parcial, com o valor de hoje.</p>

    <div class="year-bars">
      ${years.map((r) => {
        const pct = clamp((Math.abs(r.value) / maxAbs) * 100, 2, 100);
        const neg = r.value < 0;
        return `<div class="year-bar ${r.isCurrent ? "is-current" : ""}">
          <span class="year-bar__label">${r.year}${r.isCurrent ? " · hoje" : ""}</span>
          <div class="year-bar__track"><div class="year-bar__fill" data-ui-css="width:${pct}%; background:${neg ? "var(--negative)" : (r.isCurrent ? "var(--brand)" : "color-mix(in srgb, var(--brand) 55%, transparent)")}"></div></div>
          <b class="year-bar__value">${fmtBRLShort(r.value)}</b>
        </div>`;
      }).join("")}
    </div>

    <div class="wealth-deltas" data-ui-css="margin-top:16px">
      <div class="wealth-delta">
        <span class="wealth-delta__label">No ano (desde 31/12)</span>
        <b class="wealth-delta__value" data-ui-css="color:${a.ytd.comparable ? (a.ytd.up ? "var(--positive)" : "var(--negative)") : "var(--ink-faint)"}">
          ${a.ytd.comparable ? `${a.ytd.up ? "+" : "−"}${fmtBRLShort(Math.abs(a.ytd.value))}` : "Sem dados"}
        </b>
      </div>
      <div class="wealth-delta">
        <span class="wealth-delta__label">Contra 12 meses atrás</span>
        <b class="wealth-delta__value" data-ui-css="color:${a.yoy.comparable ? (a.yoy.up ? "var(--positive)" : "var(--negative)") : "var(--ink-faint)"}">
          ${a.yoy.comparable ? `${a.yoy.up ? "+" : "−"}${Math.abs(a.yoy.pct).toFixed(1)}%` : "Sem dados"}
        </b>
      </div>
    </div>
  </div>`;
}

// ---- Distribuição por classe ----
function renderWealthAllocationCard(m) {
  return `<div class="card span-1">
    <p class="card-title">Distribuição dos bens</p>
    <div class="segment-bar" data-ui-css="margin:12px 0 14px">
      ${m.allocation.map((r) => `<div data-ui-css="flex:${Math.max(r.value, 1)}; background:${r.color}" title="${escapeHtml(r.label)}"></div>`).join("")}
    </div>
    <div class="alloc-list">
      ${m.allocation.map((r) => `<div class="alloc-row">
        <span class="cat-dot" data-ui-css="background:${r.color}"></span>
        <span class="alloc-row__label">${escapeHtml(r.label)}</span>
        <span class="alloc-row__pct">${r.pct.toFixed(0)}%</span>
        <b>${fmtBRLShort(r.value)}</b>
      </div>`).join("")}
    </div>
  </div>`;
}

function renderWealthInsightsCard(m) {
  if (m.insights.length === 0) return "";
  const toneColor = { positive: "var(--positive)", warn: "var(--goal)", danger: "var(--negative)", neutral: "var(--ink-soft)" };
  return `<div class="card span-3">
    <p class="card-title">Leitura do período</p>
    <div class="summary-grid" data-ui-css="margin-top:12px">
      ${m.insights.map((i) => `<div class="summary-item" data-ui-css="--tone:${toneColor[i.tone]}">
        <span class="summary-item__icon">${svgIcon(i.icon, 16)}</span>
        <p class="summary-item__text">${escapeHtml(i.text)}</p>
      </div>`).join("")}
    </div>
  </div>`;
}

// ---- Listas de bens e dívidas ----
function renderWealthGroups(m) {
  if (m.groups.length === 0) {
    return `<div class="card span-3">
      ${renderEmptyState("layout", "Nenhum bem ou dívida cadastrado.", "Cadastre suas contas, investimentos, veículos, imóveis e financiamentos para ver o patrimônio real; e não só o caixa dos lançamentos.")}
      <button class="btn btn--primary btn--block btn--sm" data-action="wealth-new">Cadastrar o primeiro item</button>
    </div>`;
  }
  return m.groups.map((g) => `<div class="card span-3" data-ui-css="--tone:${g.color}">
    <div class="wealth-group__head">
      <span class="icon-bubble icon-bubble--sm" data-ui-css="background:color-mix(in srgb, ${g.color} 14%, transparent); color:${g.color}">${svgIcon(g.icon, 16)}</span>
      <div class="wealth-group__title">
        <p class="card-title" data-ui-css="margin:0">${escapeHtml(g.label)}</p>
        <p class="mini-card__sub">${g.items.length} ${g.items.length === 1 ? "item" : "itens"}</p>
      </div>
      <b class="wealth-group__total" data-ui-css="color:${g.kind === "liability" ? "var(--negative)" : "var(--ink)"}">${g.kind === "liability" ? "−" : ""}${fmtBRL(g.total)}</b>
    </div>
    <div class="asset-list">
      ${g.items.map((a) => renderAssetRow(a, g)).join("")}
    </div>
  </div>`).join("");
}

function renderAssetRow(a, g) {
  const updating = state.wealth.updatingId === a.id;
  const ch = a.change;

  return `<div class="asset-row">
    <div class="asset-row__main">
      <div class="asset-row__info">
        <p class="asset-row__name">${escapeHtml(a.name)}${a.inLedger ? `<span class="asset-row__tag">já nos lançamentos</span>` : ""}</p>
        ${a.note ? `<p class="asset-row__note">${escapeHtml(a.note)}</p>` : ""}
        ${a.monthlyPayment > 0 ? `<p class="asset-row__note">${fmtBRL(a.monthlyPayment)} por mês</p>` : ""}
      </div>
      <div class="asset-row__values">
        <b class="asset-row__value ${a.inLedger ? "is-muted" : ""}">${fmtBRL(a.value)}</b>
        ${ch && Math.abs(ch.value) > 0 ? `<span class="asset-row__delta" data-ui-css="color:${ch.up ? "var(--positive)" : "var(--negative)"}">${ch.up ? "+" : "−"}${fmtBRLShort(Math.abs(ch.value))} no mês</span>` : ""}
      </div>
      <div class="asset-row__actions">
        <button class="icon-btn icon-btn--muted" data-action="wealth-update-open" data-id="${a.id}" aria-label="Atualizar valor de ${escapeHtml(a.name)}">${svgIcon("refresh", 15)}</button>
        <button class="icon-btn icon-btn--muted" data-action="wealth-edit" data-id="${a.id}" aria-label="Editar ${escapeHtml(a.name)}">${svgIcon("pencil", 15)}</button>
        <button class="icon-btn icon-btn--muted" data-action="wealth-delete" data-id="${a.id}" aria-label="Excluir ${escapeHtml(a.name)}">${svgIcon("trash", 15)}</button>
      </div>
    </div>

    ${updating ? `<div class="asset-row__update">
      <div class="field" data-ui-css="margin:0">
        <label class="field__label" for="wealth-update-input">Valor atual em ${escapeHtml(MONTH_NAMES[new Date().getMonth()])}</label>
        <input id="wealth-update-input" class="input" data-field="wealth-update" value="${escapeHtml(state.wealth.updateValue)}" inputmode="decimal" placeholder="0,00" />
      </div>
      <p class="field-hint">O valor anterior fica guardado no histórico; é ele que desenha a curva de evolução.</p>
      <div class="form-actions">
        <button class="btn btn--ghost btn--sm" data-action="wealth-update-cancel">Cancelar</button>
        <button class="btn btn--primary btn--sm" data-action="wealth-update-save" data-id="${a.id}">Atualizar</button>
      </div>
    </div>` : ""}

  </div>`;
}

function freshWealthForm(cls) {
  return { id: null, class: cls || "conta", name: "", value: "", monthlyPayment: "", dueDay: "", note: "", inLedger: false };
}

// source: js/screens/portfolio.js
// js/screens/portfolio.js. Carteira de investimentos. Cálculo em portfolio.js.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// MÓDULO 5. CENTRAL DE INVESTIMENTOS
// ------------------------------------------------------------------
// A carteira é a mesma coleção `assets` do Módulo 3 (classe "investimento").
// Esta tela não cria um cadastro paralelo: ela acrescenta o DETALHE que
// transforma "quanto eu tenho aplicado" em "quanto isso está rendendo".
// Todo cálculo mora em portfolio.js; aqui só há HTML.
// ==================================================================

function freshPortfolioForm(typeId) {
  return {
    id: null, invType: typeId || "tesouro-selic", name: "",
    value: "", invested: "", dividends: "", startedAt: todayIso(), note: "",
  };
}

function renderPortfolioScreen() {
  const m = portfolioModel(state.portfolio.months);
  const f = state.portfolio.form;

  return `<div class="screen">
    <div class="screen-header">
      <div>
        <p class="eyebrow">Central de investimentos</p>
        <h1 class="page-title">Minha carteira</h1>
      </div>
      <div class="header-actions">
        <button class="btn btn--ghost btn--sm" data-action="nav" data-tab="simulators">${svgIcon("sparkles", 15)} Simuladores</button>
        <button class="btn btn--primary btn--sm" data-action="pf-new">${svgIcon("plus", 15)} Aplicação</button>
      </div>
    </div>

    <div class="grid-dashboard">
      ${renderPortfolioHero(m)}
      ${f ? renderPortfolioForm(f) : ""}
      ${m.hasItems ? renderPortfolioChartCard(m) : ""}
      ${m.benchmark.comparable ? renderPortfolioBenchmarkCard(m) : ""}
      ${m.allocation.length > 0 ? renderPortfolioAllocationCard(m) : ""}
      ${m.insights.length > 0 ? renderPortfolioInsightsCard(m) : ""}
      ${renderPortfolioGroups(m)}
      <p class="footnote span-3">O valor de mercado de cada aplicação é o que entra no seu patrimônio. Os proventos recebidos entram apenas no cálculo de rentabilidade; o dinheiro deles, quando cai na conta, já é um lançamento de receita, e somá-lo aqui contaria duas vezes.</p>
    </div>
  </div>`;
}

// ---- Painel principal ----
function renderPortfolioHero(m) {
  const t = m.totals;
  const tone = t.up ? "var(--positive)" : "var(--negative)";
  return `<div class="card card--hero span-3">
    <div class="hero-glow"></div>
    <p class="hero-label">Total aplicado (valor de mercado)</p>
    <p class="hero-value">${fmtBRL(t.value)}</p>
    ${t.returnPct != null ? `<p class="hero-reserved">${svgIcon(t.up ? "arrowUpRight" : "arrowDownRight", 14)} ${t.up ? "+" : "−"}${fmtBRL(Math.abs(t.totalReturn))} (${t.up ? "+" : "−"}${fmtNum(Math.abs(t.returnPct))}%) sobre o que você aportou</p>` : ""}

    ${m.groups.length > 0 ? `<div class="wealth-bar" role="img" aria-label="Composição da carteira por classe">
      ${m.groups.map((g) => `<div class="wealth-bar__seg" data-ui-css="flex:${Math.max(g.value, 1)}; background:${g.color}" title="${escapeHtml(g.label)}"></div>`).join("")}
    </div>` : ""}

    <div class="hero-chips">
      <div class="hero-chip">${svgIcon("piggy", 17)}<div><span class="hero-chip__label">Total aportado</span><span class="hero-chip__value">${fmtBRL(t.invested)}</span></div></div>
      <div class="hero-chip">${svgIcon(t.up ? "trendUp" : "arrowDownRight", 17)}<div><span class="hero-chip__label">${t.up ? "Lucro" : "Prejuízo"}</span><span class="hero-chip__value" data-ui-css="color:${tone}">${fmtBRL(Math.abs(t.profit))}</span></div></div>
      ${t.dividends > 0 ? `<div class="hero-chip">${svgIcon("gift", 17)}<div><span class="hero-chip__label">Proventos</span><span class="hero-chip__value">${fmtBRL(t.dividends)}</span></div></div>` : ""}
      ${t.annualizedPct != null ? `<div class="hero-chip">${svgIcon("bolt", 17)}<div><span class="hero-chip__label">Rentabilidade a.a.</span><span class="hero-chip__value">${fmtNum(t.annualizedPct)}%</span></div></div>` : ""}
      ${t.realPct != null ? `<div class="hero-chip">${svgIcon("shieldCheck", 17)}<div><span class="hero-chip__label">Acima da inflação</span><span class="hero-chip__value">${fmtNum(t.realPct)}%</span></div></div>` : ""}
    </div>

    ${m.contributionThisMonth > 0 ? `<p class="hero-reserved" data-ui-css="margin-top:12px">${svgIcon("checkCircle", 14)} Você aportou ${fmtBRL(m.contributionThisMonth)} este mês</p>` : ""}
  </div>`;
}

// ---- Formulário de cadastro/edição ----
function renderPortfolioForm(f) {
  const type = investmentTypeOf(f.invType);
  const editing = !!f.id;

  return `<div class="card card--elevated span-3" id="portfolio-form" data-ui-css="scroll-margin-top:18px">
    <p class="card-title">${editing ? "Editar aplicação" : "Nova aplicação"}</p>

    <div class="field"><p class="field__label">Tipo de aplicação</p>
      <div class="class-picker">
        ${INVESTMENT_TYPES.map((t) => `<button class="class-chip ${f.invType === t.id ? "active" : ""}" data-ui-css="--tone:${t.color}" data-action="pf-set-type" data-value="${t.id}">
          <span>${escapeHtml(t.label)}</span>
        </button>`).join("")}
      </div>
      <p class="field-hint">${escapeHtml(type.hint)}</p>
    </div>

    <div class="field"><label class="field__label" for="pf-name-input">Nome</label>
      <input id="pf-name-input" class="input" data-field="pf-name" value="${escapeHtml(f.name)}" placeholder="Ex: CDB Banco X 110% CDI" autocomplete="off" maxlength="60" /></div>

    <div class="field-row">
      <div class="field"><label class="field__label" for="pf-value-input">Valor de mercado hoje</label>
        <input id="pf-value-input" class="input" data-field="pf-value" value="${escapeHtml(f.value)}" inputmode="decimal" placeholder="0,00" />
        <p class="field-hint">É este número que entra no seu patrimônio.</p></div>
      <div class="field"><label class="field__label" for="pf-invested-input">Total aportado (custo)</label>
        <input id="pf-invested-input" class="input" data-field="pf-invested" value="${escapeHtml(f.invested)}" inputmode="decimal" placeholder="0,00" />
        <p class="field-hint">Quanto saiu do seu bolso. Sem ele não há como calcular rentabilidade.</p></div>
    </div>

    <div class="field-row">
      <div class="field"><label class="field__label" for="pf-started-input">Aplicado desde</label>
        <input id="pf-started-input" class="input" type="date" data-field="pf-started" value="${escapeHtml(f.startedAt)}" /></div>
      <div class="field"><label class="field__label" for="pf-dividends-input">Proventos já recebidos</label>
        <input id="pf-dividends-input" class="input" data-field="pf-dividends" value="${escapeHtml(f.dividends)}" inputmode="decimal" placeholder="0,00" />
        <p class="field-hint">Dividendos, JCP e aluguéis de FII acumulados.</p></div>
    </div>

    <div class="field"><label class="field__label" for="pf-note-input">Observação (opcional)</label>
      <input id="pf-note-input" class="input" data-field="pf-note" value="${escapeHtml(f.note)}" placeholder="Ex: vence em 2029, corretora Y" autocomplete="off" maxlength="140" /></div>

    <div class="form-actions">
      <button class="btn btn--ghost" data-action="pf-cancel">Cancelar</button>
      <button class="btn btn--primary" data-action="pf-save">${editing ? "Salvar alterações" : "Cadastrar"}</button>
    </div>
  </div>`;
}

// ---- Evolução da carteira ----
function renderPortfolioChartCard(m) {
  const opts = [6, 12, 24];
  const d = m.delta;
  return `<div class="card span-2">
    <div class="wealth-chart__head">
      <div>
        <p class="card-title" data-ui-css="margin:0">Evolução da carteira</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">Reconstruída com o valor que cada aplicação tinha em cada mês.</p>
      </div>
      <div class="seg-control">
        ${opts.map((o) => `<button class="seg-control__btn ${m.months === o ? "active" : ""}" data-action="pf-months" data-value="${o}">${o}m</button>`).join("")}
      </div>
    </div>
    ${renderWealthChart(m.series, 640, 170)}
    <div class="wealth-axis">${m.series.map((p, i) => `<span class="${p.isCurrent ? "is-current" : ""}">${i % Math.ceil(m.series.length / 6) === 0 || p.isCurrent ? escapeHtml(p.label) : ""}</span>`).join("")}</div>
    ${d.comparable ? `<p class="health-note">${m.months === 1 ? "No último mês" : `Nos últimos ${m.months} meses`} a carteira ${d.up ? "cresceu" : "recuou"} <b data-ui-css="color:${d.up ? "var(--positive)" : "var(--negative)"}">${fmtBRL(Math.abs(d.value))}</b> (${d.up ? "+" : "−"}${fmtNum(Math.abs(d.pct))}%). O gráfico mistura aporte novo e rendimento; para separar os dois, veja a comparação com o CDI abaixo.</p>` : ""}
  </div>`;
}

// ---- Comparação com os índices ----
function renderPortfolioBenchmarkCard(m) {
  const b = m.benchmark;
  const rows = [
    { label: "Sua carteira", value: b.portfolioPct, color: "var(--brand)", strong: true },
    { label: "CDI", value: b.cdiPct, color: "var(--goal)" },
    { label: "Poupança", value: b.poupancaPct, color: "var(--ink-faint)" },
    { label: "Inflação (IPCA)", value: b.ipcaPct, color: "var(--negative)" },
  ];
  const max = Math.max(...rows.map((r) => Math.abs(r.value)), 0.01);

  return `<div class="card">
    <p class="card-title">Contra os índices</p>
    <p class="card-subtitle" data-ui-css="margin-top:0">Mesmo prazo médio da sua carteira: ${fmtNum(b.months)} meses.</p>
    <div class="bench-list">
      ${rows.map((r) => `<div class="bench-row ${r.strong ? "bench-row--strong" : ""}">
        <span class="bench-row__label">${escapeHtml(r.label)}</span>
        <div class="bench-row__track"><div class="bench-row__fill" data-ui-css="width:${Math.max(2, (Math.abs(r.value) / max) * 100).toFixed(1)}%; background:${r.color}"></div></div>
        <b class="bench-row__value" data-ui-css="color:${r.value < 0 ? "var(--negative)" : "var(--ink)"}">${fmtNum(r.value)}%</b>
      </div>`).join("")}
    </div>
    <p class="health-note">${b.beatsCdi
      ? `Sua carteira está <b data-ui-css="color:var(--positive)">${fmtNum(Math.abs(b.diffCdi))} pontos acima do CDI</b> no período.`
      : `Sua carteira está <b data-ui-css="color:var(--negative)">${fmtNum(Math.abs(b.diffCdi))} pontos abaixo do CDI</b> no período. Em renda variável isso é normal no curto prazo; se persistir por anos, o problema costuma ser taxa de administração.`}</p>
  </div>`;
}

// ---- Alocação por tipo ----
function renderPortfolioAllocationCard(m) {
  const segments = m.allocation.map((row) => ({ value: row.value, color: row.type.color }));
  return `<div class="card">
    <p class="card-title">Alocação</p>
    <div class="donut-wrap">${renderDonut(segments, 168, 20)}</div>
    <div class="pf-legend">
      ${m.allocation.map((row) => `<div class="pf-legend__item">
        <span class="cat-dot" data-ui-css="background:${row.type.color}"></span>
        <div class="pf-legend__text">
          <span class="pf-legend__label">${escapeHtml(row.type.label)} · ${row.pct.toFixed(0)}%</span>
          <span class="pf-legend__note">${row.count} ${row.count === 1 ? "aplicação" : "aplicações"}</span>
        </div>
        <b>${fmtBRL(row.value)}</b>
      </div>`).join("")}
    </div>
    <div class="pf-groups-summary">
      ${m.groups.map((g) => `<div class="pf-group-pill" data-ui-css="--tone:${g.color}">
        <span>${escapeHtml(g.label)}</span><b>${g.pct.toFixed(0)}%</b>
      </div>`).join("")}
    </div>
  </div>`;
}

// ---- Diagnóstico ----
function renderPortfolioInsightsCard(m) {
  const toneColor = { warn: "var(--negative)", ok: "var(--positive)", info: "var(--goal)" };
  return `<div class="card span-3">
    <p class="card-title">O que olhar na sua carteira</p>
    <div class="pf-insights">
      ${m.insights.map((i) => `<div class="pf-insight" data-ui-css="--tone:${toneColor[i.tone] || "var(--goal)"}">
        <span class="pf-insight__icon">${svgIcon(i.icon, 16)}</span>
        <div>
          <b>${escapeHtml(i.title)}</b>
          <span>${escapeHtml(i.text)}</span>
        </div>
      </div>`).join("")}
    </div>
  </div>`;
}

// ---- Listas por classe ----
function renderPortfolioGroups(m) {
  if (!m.hasItems) {
    return `<div class="card span-3">
      ${renderEmptyState("trendUp", "Nenhuma aplicação cadastrada ainda.", "Cadastre o que você já tem aplicado. Tesouro, CDB, ações, FIIs, cripto; para acompanhar rentabilidade, alocação e comparação com o CDI.")}
      <button class="btn btn--primary btn--block btn--sm" data-action="pf-new">Cadastrar a primeira aplicação</button>
    </div>`;
  }
  return m.groups.map((g) => `<div class="card span-3">
    <div class="wealth-group__head">
      <span class="icon-bubble" data-ui-css="background:color-mix(in srgb, ${g.color} 14%, transparent); color:${g.color}">${svgIcon("trendUp", 17)}</span>
      <div class="wealth-group__title">
        <b>${escapeHtml(g.label)}</b>
        <span>${g.count} ${g.count === 1 ? "aplicação" : "aplicações"} · ${g.pct.toFixed(0)}% da carteira</span>
      </div>
      <b class="wealth-group__total">${fmtBRL(g.value)}</b>
    </div>
    <div class="pf-list">
      ${g.items.map((it) => renderPortfolioRow(it)).join("")}
    </div>
  </div>`).join("");
}

function renderPortfolioRow(it) {
  const open = state.portfolio.expandedId === it.id;
  const updating = state.portfolio.updatingId === it.id;
  const dividing = state.portfolio.dividendId === it.id;
  const tone = it.up ? "var(--positive)" : "var(--negative)";

  return `<div class="pf-item ${open ? "is-open" : ""}">
    <button class="pf-item__head" data-action="pf-toggle" data-id="${it.id}" aria-expanded="${open ? "true" : "false"}">
      <span class="cat-dot" data-ui-css="background:${it.type.color}"></span>
      <span class="pf-item__name">
        <b>${escapeHtml(it.name)}</b>
        <span>${escapeHtml(it.type.label)} · ${it.share.toFixed(0)}% da carteira</span>
      </span>
      <span class="pf-item__figures">
        <b>${fmtBRL(it.value)}</b>
        ${it.returnPct != null ? `<span data-ui-css="color:${tone}">${it.up ? "+" : "−"}${fmtNum(Math.abs(it.returnPct))}%</span>` : `<span class="pf-item__nodata">sem custo</span>`}
      </span>
      ${svgIcon(open ? "chevronDown" : "chevronRight", 15, "pf-item__chevron")}
    </button>

    ${!open ? "" : `<div class="pf-item__body">
      <div class="health-grid">
        <div class="health-stat"><span>Total aportado</span><b>${it.hasCost ? fmtBRL(it.invested) : "Sem dados"}</b></div>
        <div class="health-stat"><span>${it.up ? "Lucro" : "Prejuízo"}</span><b data-ui-css="color:${tone}">${it.hasCost ? fmtBRL(Math.abs(it.profit)) : "Sem dados"}</b></div>
        <div class="health-stat"><span>Proventos</span><b>${fmtBRL(it.dividends)}</b></div>
        <div class="health-stat"><span>Rentabilidade a.a.</span><b>${it.annualizedPct != null ? `${fmtNum(it.annualizedPct)}%` : "Sem dados"}</b></div>
        <div class="health-stat"><span>Acima da inflação</span><b>${it.realPct != null ? `${fmtNum(it.realPct)}%` : "Sem dados"}</b></div>
        <div class="health-stat"><span>No mês</span><b data-ui-css="color:${it.monthDelta.comparable ? (it.monthDelta.pct >= 0 ? "var(--positive)" : "var(--negative)") : "var(--ink-faint)"}">${it.monthDelta.comparable ? `${it.monthDelta.pct >= 0 ? "+" : "−"}${fmtNum(Math.abs(it.monthDelta.pct))}%` : "Sem dados"}</b></div>
      </div>
      ${it.annualizedPct == null && it.hasCost ? `<p class="field-hint">Menos de 3 meses de aplicação: o app mostra o retorno acumulado (${fmtNum(it.returnPct)}%) e não anualiza; anualizar prazo curto produz número enganoso.</p>` : ""}
      ${it.note ? `<p class="field-hint">${escapeHtml(it.note)}</p>` : ""}

      <div class="pf-item__actions">
        <button class="btn btn--ghost btn--sm" data-action="pf-update-open" data-id="${it.id}">${svgIcon("refresh", 14)} Atualizar valor</button>
        <button class="btn btn--ghost btn--sm" data-action="pf-dividend-open" data-id="${it.id}">${svgIcon("gift", 14)} Provento</button>
        <button class="btn btn--ghost btn--sm" data-action="pf-edit" data-id="${it.id}">${svgIcon("pencil", 14)} Editar</button>
        <button class="btn btn--ghost btn--sm" data-action="pf-delete" data-id="${it.id}">${svgIcon("trash", 14)} Excluir</button>
      </div>

      ${updating ? `<div class="asset-row__update">
        <div class="field" data-ui-css="margin:0">
          <label class="field__label" for="pf-update-input">Valor de mercado em ${escapeHtml(MONTH_NAMES[new Date().getMonth()])}</label>
          <input id="pf-update-input" class="input" data-field="pf-update" value="${escapeHtml(state.portfolio.updateValue)}" inputmode="decimal" placeholder="0,00" />
        </div>
        <p class="field-hint">O valor anterior não é apagado: ele vira um ponto no histórico e é o que desenha a curva de evolução.</p>
        <div class="form-actions">
          <button class="btn btn--ghost btn--sm" data-action="pf-update-cancel">Cancelar</button>
          <button class="btn btn--primary btn--sm" data-action="pf-update-save" data-id="${it.id}">Atualizar</button>
        </div>
      </div>` : ""}

      ${dividing ? `<div class="asset-row__update">
        <div class="field" data-ui-css="margin:0">
          <label class="field__label" for="pf-dividend-input">Provento recebido agora</label>
          <input id="pf-dividend-input" class="input" data-field="pf-dividend" value="${escapeHtml(state.portfolio.dividendValue)}" inputmode="decimal" placeholder="0,00" />
        </div>
        <p class="field-hint">Soma ao total de proventos desta aplicação e entra na rentabilidade. Não altera o patrimônio; se o dinheiro caiu na sua conta, lance-o como receita normalmente.</p>
        <div class="form-actions">
          <button class="btn btn--ghost btn--sm" data-action="pf-dividend-cancel">Cancelar</button>
          <button class="btn btn--primary btn--sm" data-action="pf-dividend-save" data-id="${it.id}">Registrar</button>
        </div>
      </div>` : ""}

    </div>`}
  </div>`;
}

// source: js/screens/invest.js
// js/screens/invest.js. Máquina do tempo dos juros compostos e motor What-If.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// FEATURE 3. Máquina do tempo dos juros compostos ("Investimentos")
// ==================================================================
function renderInvestScreen() {
  return `<div class="screen">
    <div class="screen-header">
      <div>
        <p class="eyebrow">Máquina do tempo</p>
        <h1 class="page-title">Juros compostos</h1>
      </div>
    </div>

    <div class="grid-2">${renderCompoundSimCards()}</div>

    ${renderWhatIfCard()}
  </div>`;
}

// [M5] Os dois cartões da máquina do tempo foram extraídos para cá sem
// nenhuma alteração de conteúdo: agora servem tanto a esta tela quanto ao
// simulador de juros compostos da nova central de Simuladores. Uma marcação
// só, um comportamento só.
function renderCompoundSimCards() {
  const inv = state.invest;
  const inicial = Math.max(0, moneyOrZero(inv.inicial));
  const aporte = Math.max(0, moneyOrZero(inv.aporte));
  const anos = clamp(parseInt(inv.anos, 10) || 1, 1, 40);
  const taxa = clamp(moneyOrZero(inv.taxa), 0, 30);
  const ratePresets = investmentRatePresets(state.data);

  const sim = simulateCompoundInterest({ initial: inicial, monthlyContribution: aporte, years: anos, annualRatePct: taxa });
  return `      <div class="card">
        <p class="card-title">Sua simulação</p>
        <p class="card-subtitle" data-ui-css="margin-top:0">Arraste para ver como aportes recorrentes viram patrimônio ao longo do tempo. Nada aqui é lançado na sua conta; é só uma projeção.</p>

        <div class="invest-field">
          <div class="invest-field__head"><span>Valor inicial</span><b>${fmtBRL(inicial)}</b></div>
          <input id="invest-inicial-input" class="input" data-field="invest-inicial" inputmode="decimal" value="${escapeHtml(inv.inicial)}" placeholder="0,00" autocomplete="off" />
        </div>

        <div class="invest-field">
          <div class="invest-field__head"><span>Aporte mensal</span><b>${fmtBRL(aporte)}</b></div>
          <input type="number" inputmode="decimal" id="invest-aporte-range-input" class="input input--stepper" min="0" max="5000" step="25" data-field="invest-aporte-range" value="${clamp(aporte, 0, 5000)}" placeholder="0" />
        </div>

        <div class="invest-field">
          <div class="invest-field__head"><span>Prazo</span><b>${anos} ${anos === 1 ? "ano" : "anos"}</b></div>
          <input type="number" inputmode="numeric" id="invest-anos-range-input" class="input input--stepper" min="1" max="40" step="1" data-field="invest-anos-range" value="${anos}" placeholder="1" />
        </div>

        <div class="invest-field">
          <div class="invest-field__head"><span>Taxa de juros ao ano</span><b>${fmtNum(taxa)}%</b></div>
          <input type="number" inputmode="decimal" id="invest-taxa-range-input" class="input input--stepper" min="0" max="25" step="0.1" data-field="invest-taxa-range" value="${taxa}" placeholder="0" />
          <div class="invest-presets">
            ${ratePresets.map((p) => `<button class="payment-chip ${Math.abs(taxa - p.ratePct) < 0.05 ? "active" : ""}" data-action="set-invest-rate" data-value="${p.ratePct}">${p.label}</button>`).join("")}
          </div>
        </div>
      </div>

      <div class="card">
        <p class="card-title">Patrimônio projetado</p>
        <div class="invest-stats">
          <div class="invest-stat invest-stat--total">
            <span>Valor final em ${anos} ${anos === 1 ? "ano" : "anos"}</span>
            <b>${fmtBRL(sim.totalFinal)}</b>
          </div>
          <div class="invest-stat">
            <span>Total investido (aportes)</span>
            <b>${fmtBRL(sim.totalContributed)}</b>
          </div>
          <div class="invest-stat invest-stat--interest">
            <span>Ganho em juros</span>
            <b>${fmtBRL(sim.totalInterest)}</b>
          </div>
        </div>
        ${renderInvestChart(sim)}
        <div class="trend-legend">
          <span><i data-ui-css="background:var(--brand)"></i>Patrimônio total (com juros)</span>
          <span><i data-ui-css="background:var(--border)"></i>Só o que foi aportado</span>
        </div>
        <p class="health-note">Se você guardar <b>${fmtBRL(aporte)}</b> por mês${inicial > 0 ? `, começando já com <b>${fmtBRL(inicial)}</b>,` : ""} rendendo <b>${fmtNum(taxa)}% ao ano</b>, em <b>${anos} ${anos === 1 ? "ano" : "anos"}</b> você teria <b data-ui-css="color:var(--positive)">${fmtBRL(sim.totalFinal)}</b>; dos quais <b>${fmtBRL(sim.totalInterest)}</b> vieram só dos juros, sem sair do seu bolso.</p>
      </div>`;
}

// ==================================================================
// MOTOR WHAT-IF; comparar o cenário real com um cenário simulado
// ==================================================================
// Usa o saldo real (IndexedDB) e a sobra média dos últimos meses como ponto de
// partida, e desenha a projeção simulada em paralelo à projeção atual.
function renderWhatIfCard() {
  const wi = state.whatIf;
  const num = (v) => Math.max(0, moneyOrZero(v));

  const saldoHoje = realizedBalance(state.data);
  const sobraMensal = estimateAvgMonthlySaving(state.data);
  const anos = clamp(parseInt(wi.anos, 10) || 10, 1, 40);
  const taxa = clamp(num(wi.taxa), 0, 30);
  const isFin = wi.mode === "financiamento";
  const ratePresets = investmentRatePresets(state.data);

  const scenario = computeWhatIfScenario({
    startingBalance: saldoHoje,
    monthlySurplus: sobraMensal,
    annualRatePct: taxa,
    years: anos,
    mode: wi.mode,
    extraContribution: num(wi.aporteExtra),
    financing: {
      valorBem: num(wi.valorBem),
      entrada: num(wi.entrada),
      meses: clamp(parseInt(wi.meses, 10) || 12, 1, anos * 12),
      jurosAnualPct: clamp(num(wi.jurosFin), 0, 200),
    },
  });
  const s = scenario.summary;
  const positivo = s.diferenca >= 0;

  return `<div class="card span-mt">
    <div class="settings-row-header">
      <div>
        <p class="card-title" data-ui-css="margin:0">Motor What-If</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">Compare o seu cenário real com uma decisão que você está pensando em tomar</p>
      </div>
      <button class="icon-btn" data-action="toggle-whatif" aria-label="${wi.open ? "Recolher" : "Abrir"} comparação de cenários" aria-expanded="${wi.open ? "true" : "false"}">${svgIcon(wi.open ? "chevronDown" : "chevronRight", 16)}</button>
    </div>

    ${!wi.open ? "" : `
    <div class="whatif-base">
      <div><span>Saldo de hoje</span><b>${fmtBRL(saldoHoje)}</b></div>
      <div><span>Sobra média por mês</span><b>${fmtBRL(sobraMensal)}</b></div>
    </div>

    <div class="segmented" data-ui-css="margin-top:12px">
      <button class="segmented__option ${!isFin ? "active" : ""}" data-action="set-whatif-mode" data-value="aporte">Guardar mais por mês</button>
      <button class="segmented__option ${isFin ? "active" : ""}" data-action="set-whatif-mode" data-value="financiamento">Financiar uma compra</button>
    </div>

    <div class="grid-2" data-ui-css="margin-top:12px">
      <div>
        ${!isFin ? `
          <div class="invest-field">
            <div class="invest-field__head"><span>Aporte extra por mês</span><b>${fmtBRL(num(wi.aporteExtra))}</b></div>
            <input type="number" inputmode="decimal" id="whatif-aporte-input" class="input input--stepper" min="0" max="3000" step="25" data-field="whatif-aporte" value="${clamp(num(wi.aporteExtra), 0, 3000)}" placeholder="0" />
          </div>
        ` : `
          <div class="invest-field">
            <div class="invest-field__head"><span>Valor do bem</span><b>${fmtBRL(num(wi.valorBem))}</b></div>
            <input id="whatif-valorbem-input" class="input" data-field="whatif-valorbem" inputmode="decimal" value="${escapeHtml(wi.valorBem)}" placeholder="0,00" autocomplete="off" />
          </div>
          <div class="invest-field">
            <div class="invest-field__head"><span>Entrada</span><b>${fmtBRL(num(wi.entrada))}</b></div>
            <input id="whatif-entrada-input" class="input" data-field="whatif-entrada" inputmode="decimal" value="${escapeHtml(wi.entrada)}" placeholder="0,00" autocomplete="off" />
          </div>
          <div class="invest-field">
            <div class="invest-field__head"><span>Parcelas</span><b>${clamp(parseInt(wi.meses, 10) || 12, 1, anos * 12)}x</b></div>
            <input type="number" inputmode="numeric" id="whatif-meses-input" class="input input--stepper" min="1" max="${anos * 12}" step="1" data-field="whatif-meses" value="${clamp(parseInt(wi.meses, 10) || 12, 1, anos * 12)}" placeholder="12" />
          </div>
          <div class="invest-field">
            <div class="invest-field__head"><span>Juros do financiamento (ao ano)</span><b>${fmtNum(num(wi.jurosFin))}%</b></div>
            <input type="number" inputmode="decimal" id="whatif-jurosfin-input" class="input input--stepper" min="0" max="60" step="0.5" data-field="whatif-jurosfin" value="${clamp(num(wi.jurosFin), 0, 60)}" placeholder="0" />
          </div>
        `}
      </div>
      <div>
        <div class="invest-field">
          <div class="invest-field__head"><span>Horizonte da projeção</span><b>${anos} ${anos === 1 ? "ano" : "anos"}</b></div>
          <input type="number" inputmode="numeric" id="whatif-anos-input" class="input input--stepper" min="1" max="40" step="1" data-field="whatif-anos" value="${anos}" placeholder="1" />
        </div>
        <div class="invest-field">
          <div class="invest-field__head"><span>Rendimento do dinheiro guardado</span><b>${fmtNum(taxa)}% a.a.</b></div>
          <input type="number" inputmode="decimal" id="whatif-taxa-input" class="input input--stepper" min="0" max="25" step="0.1" data-field="whatif-taxa" value="${taxa}" placeholder="0" />
          <div class="invest-presets">
            ${ratePresets.map((p) => `<button class="payment-chip ${Math.abs(taxa - p.ratePct) < 0.05 ? "active" : ""}" data-action="set-whatif-rate" data-value="${p.ratePct}">${p.label}</button>`).join("")}
          </div>
        </div>
      </div>
    </div>

    ${renderWhatIfChart(scenario, { idSuffix: "Main" })}
    <div class="trend-legend">
      <span><i data-ui-css="background:var(--brand)"></i>Cenário atual</span>
      <span><i data-ui-css="background:var(--goal)"></i>Cenário simulado</span>
    </div>

    <div class="whatif-stats">
      <div class="invest-stat">
        <span>Em ${anos} ${anos === 1 ? "ano" : "anos"}, mantendo tudo como está</span>
        <b>${fmtBRL(s.finalBase)}</b>
      </div>
      <div class="invest-stat ${positivo ? "invest-stat--interest" : ""}">
        <span>No cenário simulado</span>
        <b data-ui-css="color:${positivo ? "var(--positive)" : "var(--negative)"}">${fmtBRL(s.finalSim)}</b>
      </div>
      <div class="invest-stat">
        <span>Diferença</span>
        <b data-ui-css="color:${positivo ? "var(--positive)" : "var(--negative)"}">${positivo ? "+" : "−"}${fmtBRL(Math.abs(s.diferenca))}</b>
      </div>
    </div>

    ${isFin ? `
      <p class="health-note">Financiando <b>${fmtBRL(s.valorBem)}</b> com <b>${fmtBRL(s.entrada)}</b> de entrada em <b>${s.nParcelas}x</b>, a parcela fica em <b>${fmtBRL(s.parcela)}</b>. Você pagaria <b>${fmtBRL(s.totalPago)}</b> no total. <b data-ui-css="color:var(--negative)">${fmtBRL(s.custoJuros)}</b> só de juros (${fmtNum(s.custoJurosPct)}% a mais que o valor à vista).${s.comprometimentoPct != null ? ` A parcela consome <b>${fmtNum(s.comprometimentoPct)}%</b> da sua sobra mensal.` : ""}</p>
      ${!s.viavel ? `<p class="ai-error">${svgIcon("alertTriangle", 14)} A parcela é maior que a sua sobra média mensal; nesse ritmo o saldo entra no vermelho durante o financiamento.</p>` : ""}
    ` : `
      <p class="health-note">Guardando <b>${fmtBRL(num(wi.aporteExtra))}</b> a mais por mês, você aportaria <b>${fmtBRL(s.totalAportado)}</b> do próprio bolso e terminaria com <b data-ui-css="color:var(--positive)">${fmtBRL(s.diferenca)}</b> a mais. <b>${fmtBRL(Math.max(0, s.jurosGerados))}</b> disso vêm só dos juros compostos.${s.comprometimentoPct != null ? ` Isso equivale a <b>${fmtNum(s.comprometimentoPct)}%</b> da sua sobra mensal atual.` : ""}</p>
      ${!s.viavel ? `<p class="ai-error">${svgIcon("alertTriangle", 14)} Esse aporte é maior que a sua sobra média mensal. Dá para começar menor e aumentar aos poucos.</p>` : ""}
    `}
    `}
  </div>`;
}

// Gráfico de área SVG: patrimônio total (com juros) vs. total aportado (sem juros),
// no mesmo estilo minimalista dos outros gráficos do app (sem bibliotecas externas).
function renderInvestChart(sim) {
  const points = downsampleSeries(sim.series, 60);
  const w = 600, h = 220, pad = 6;
  const maxVal = Math.max(1, sim.totalFinal);
  const lastMonth = sim.months;
  const xScale = (m) => pad + (lastMonth > 0 ? m / lastMonth : 0) * (w - 2 * pad);
  const yScale = (v) => h - pad - (v / maxVal) * (h - 2 * pad);

  const totalPath = points.map((p, i) => `${i === 0 ? "M" : "L"} ${xScale(p.month).toFixed(1)} ${yScale(p.total).toFixed(1)}`).join(" ");
  const contribPath = points.map((p, i) => `${i === 0 ? "M" : "L"} ${xScale(p.month).toFixed(1)} ${yScale(p.contributed).toFixed(1)}`).join(" ");
  const areaPath = `${totalPath} L ${xScale(lastMonth).toFixed(1)} ${h - pad} L ${xScale(0).toFixed(1)} ${h - pad} Z`;

  return `<svg viewBox="0 0 ${w} ${h}" class="invest-chart" preserveAspectRatio="none">
    <defs>
      <linearGradient id="investFill" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="var(--brand)" stop-opacity="0.35"/>
        <stop offset="100%" stop-color="var(--brand)" stop-opacity="0.02"/>
      </linearGradient>
    </defs>
    <path d="${areaPath}" fill="url(#investFill)" stroke="none"/>
    <path d="${contribPath}" fill="none" stroke="var(--border)" stroke-width="2.5" stroke-dasharray="5 5"/>
    <path d="${totalPath}" fill="none" stroke="var(--brand)" stroke-width="3"/>
  </svg>`;
}

