function simSpecOf(id) { return SIM_CATALOG.find((s) => s.id === id) || SIM_CATALOG[0]; }

// Valor de um campo: rascunho do usuário ou o padrão declarado.

function simFieldDefault(simId, field) {
  if (simId === "fgts" && field && field.key === "rendimento") {
    const rates = marketRatesOf(state.data);
    return String(Math.max(Number(rates.ipca) || 0, 3 + (Number(rates.tr) || 0))).replace(".", ",");
  }
  if (simId === "fgts" && field && field.key === "alternativa") {
    const rates = marketRatesOf(state.data);
    return String(Math.round((Number(rates.cdi) || 0) * 90) / 100).replace(".", ",");
  }
  return field ? field.def : "";
}

function simRaw(simId, key) {
  const stored = state.sim.values[`${simId}.${key}`];
  if (stored != null) return stored;
  const spec = simSpecOf(simId);
  const field = (spec.fields || []).find((f) => f.key === key);
  const option = (spec.options || []).find((o) => o.key === key);
  return field ? String(simFieldDefault(simId, field)) : (option ? String(option.def) : "");
}

function simMoney(simId, key) { return Math.max(0, moneyOrZero(simRaw(simId, key))); }

function simInt(simId, key, min, max) {
  const n = parseInt(String(simRaw(simId, key)).replace(/[^0-9]/g, ""), 10);
  return clamp(Number.isFinite(n) ? n : 0, min == null ? 0 : min, max == null ? 999999 : max);
}

function renderSimulatorsScreen() {
  const id = state.sim.id;
  const spec = simSpecOf(id);

  return `<div class="screen">
    <div class="screen-header">
      <div class="back-header">
        <button class="icon-btn" data-action="nav" data-tab="invest" aria-label="Voltar para investimentos">${svgIcon("chevronLeft", 19)}</button>
        <div>
          <p class="eyebrow">Central de investimentos</p>
          <h1 class="page-title">Simuladores</h1>
        </div>
      </div>
    </div>

    <div class="sim-picker">
      ${SIM_CATALOG.map((s) => `<button class="sim-chip ${s.id === id ? "active" : ""}" data-action="sim-select" data-value="${s.id}">
        ${svgIcon(s.icon, 15)}<span>${escapeHtml(s.label)}</span>
      </button>`).join("")}
    </div>

    <div class="sim-transparency"><p class="card-subtitle sim-subtitle">${escapeHtml(spec.subtitle)}</p>${renderCalculationButton("simulator")}</div>

    ${id === "juros" ? `<div class="grid-2">${renderCompoundSimCards()}</div>${renderWhatIfCard()}` : `
      <div class="grid-2">
        <div class="card">
          <p class="card-title">Premissas</p>
          ${(spec.options || []).map((o) => renderSimOption(id, o)).join("")}
          ${(spec.fields || []).map((f) => renderSimField(id, f)).join("")}
          ${renderSimRatesNote()}
        </div>
        ${renderSimResult(id)}
      </div>
    `}
    ${renderFinancialNotice(id)}
  </div>`;
}

function renderSimOption(simId, o) {
  const current = simRaw(simId, o.key);
  return `<div class="field">
    <p class="field__label">${escapeHtml(o.label)}</p>
    <div class="sim-options">
      ${o.choices.map((c) => `<button class="payment-chip ${current === c.value ? "active" : ""}" data-action="sim-set" data-id="${simId}.${o.key}" data-value="${c.value}">${escapeHtml(c.label)}</button>`).join("")}
    </div>
  </div>`;
}

function renderSimField(simId, f) {
  const inputId = `sim-${simId}-${f.key}-input`;
  return `<div class="field">
    <label class="field__label" for="${inputId}">${escapeHtml(f.label)}</label>
    <div class="sim-input">
      ${f.prefix ? `<span class="sim-input__affix">${escapeHtml(f.prefix)}</span>` : ""}
      <input id="${inputId}" class="input" data-field="sim-field" data-id="${simId}.${f.key}"
        value="${escapeHtml(simRaw(simId, f.key))}" inputmode="${f.type === "int" ? "numeric" : "decimal"}"
        placeholder="${escapeHtml(String(simFieldDefault(simId, f)))}" autocomplete="off" />
      ${f.suffix ? `<span class="sim-input__affix">${escapeHtml(f.suffix)}</span>` : ""}
    </div>
    ${f.hint ? `<p class="field-hint">${escapeHtml(f.hint)}</p>` : ""}
  </div>`;
}

// De onde vêm CDI, Selic e IPCA: premissas do usuário, com a data da revisão.
// Um simulador que esconde a premissa está vendendo o resultado.
function renderSimRatesNote() {
  const r = marketRatesOf(state.data);
  return `<div class="sim-rates">
    <span>${r.updatedAt ? "Premissas" : "Exemplos não revisados"}: CDI ${fmtNum(r.cdi)}% · Selic ${fmtNum(r.selic)}% · IPCA ${fmtNum(r.ipca)}% · Poupança ${fmtNum(r.poupanca)}%</span>
    <button class="link-btn" data-action="nav" data-tab="settings">${r.updatedAt ? `Revisadas em ${fmtDateFull(r.updatedAt)} · editar` : "Revisar antes de decidir"}</button>
  </div>`;
}

function simStat(label, value, opts) {
  const o = opts || {};
  return `<div class="invest-stat ${o.highlight ? "invest-stat--total" : ""} ${o.interest ? "invest-stat--interest" : ""}">
    <span>${escapeHtml(label)}</span>
    <b${o.color ? ` data-ui-css="color:${o.color}"` : ""}>${value}</b>
  </div>`;
}

function renderSimResult(id) {
  switch (id) {
    case "rendafixa": return renderSimFixedIncome();
    case "emprestimo": return renderSimLoan();
    case "financiamento": return renderSimFinancing();
    case "entrada-amortizacao": return renderSimDownPaymentComparison();
    case "cartao": return renderSimCard();
    case "consorcio": return renderSimConsortium();
    case "fgts": return renderSimFgts();
    case "aposentadoria": return renderSimRetirement();
    default: return "";
  }
}

/* ---------------------------------------------------------- renda fixa */
function renderSimFixedIncome() {
  const rates = marketRatesOf(state.data);
  const produto = simRaw("rendafixa", "produto");
  const map = {
    cdi: { indexer: "cdi", exempt: false },
    selic: { indexer: "selic", exempt: false },
    ipca: { indexer: "ipca", exempt: false },
    pre: { indexer: "pre", exempt: false },
    lci: { indexer: "cdi", exempt: true },
    poupanca: { indexer: "poupanca", exempt: true },
  };
  const cfg = map[produto] || map.cdi;
  const meses = simInt("rendafixa", "meses", 1, 600);

  const r = simFixedIncome({
    principal: simMoney("rendafixa", "principal"),
    monthlyContribution: simMoney("rendafixa", "aporte"),
    months: meses,
    indexer: cfg.indexer,
    ratePct: moneyOrZero(simRaw("rendafixa", "taxa")),
    feeAnnualPct: moneyOrZero(simRaw("rendafixa", "custodia")),
    taxExempt: cfg.exempt,
    rates,
  });

  // Referência de comparação: a mesma aplicação na poupança, no mesmo prazo.

  const poup = simFixedIncome({
    principal: simMoney("rendafixa", "principal"),
    monthlyContribution: simMoney("rendafixa", "aporte"),
    months: meses, indexer: "poupanca", taxExempt: true, rates,
  });
  const ganhoVsPoupanca = subMoney(r.netFinal, poup.netFinal);

  return `<div class="card">
    <p class="card-title">Resultado líquido</p>
    <div class="invest-stats">
      ${simStat("Você resgataria", fmtBRL(r.netFinal), { highlight: true })}
      ${simStat("Do próprio bolso (aportes)", fmtBRL(r.contributed))}
      ${simStat("Rendimento líquido", fmtBRL(r.netEarnings), { interest: true })}
    </div>

    <div class="sim-breakdown">
      <div class="sim-breakdown__row"><span>Valor bruto no vencimento</span><b>${fmtBRL(r.grossFinal)}</b></div>
      <div class="sim-breakdown__row"><span>Rendimento bruto</span><b>${fmtBRL(r.grossEarnings)}</b></div>
      <div class="sim-breakdown__row"><span>Imposto de renda</span><b data-ui-css="color:var(--negative)">${r.exempt ? "isento" : `− ${fmtBRL(r.tax)}`}</b></div>
      ${r.iof > 0 ? `<div class="sim-breakdown__row"><span>IOF (resgate antes de 30 dias)</span><b data-ui-css="color:var(--negative)">− ${fmtBRL(r.iof)}</b></div>` : ""}
      ${r.feeAnnual > 0 ? `<div class="sim-breakdown__row"><span>Taxa anual cobrada</span><b data-ui-css="color:var(--negative)">${fmtNum(r.feeAnnual)}% a.a.</b></div>` : ""}
      <div class="sim-breakdown__row"><span>Taxa bruta contratada</span><b>${fmtNum(r.grossAnnual)}% a.a.</b></div>
      <div class="sim-breakdown__row sim-breakdown__row--total"><span>Rentabilidade líquida</span><b>${r.netAnnualPct != null ? `${fmtNum(r.netAnnualPct)}% a.a.` : "Sem dados"}</b></div>
      <div class="sim-breakdown__row"><span>Acima da inflação (ganho real)</span><b data-ui-css="color:${r.losesToInflation ? "var(--negative)" : "var(--positive)"}">${r.realAnnualPct != null ? `${fmtNum(r.realAnnualPct)}% a.a.` : "Sem dados"}</b></div>
    </div>

    ${r.losesToInflation ? `<p class="ai-error">${svgIcon("alertTriangle", 14)} Nessa taxa o dinheiro rende menos que a inflação: você termina com mais reais e menos poder de compra.</p>` : ""}

    <p class="health-note">${r.exempt
      ? `Aplicação tratada como isenta de IR nesta estimativa. Uma taxa menor do CDI pode superar um produto tributado, dependendo do prazo e das demais condições.`
      : `O IR foi calculado <b>lote a lote</b>: cada aporte tem o próprio prazo e a própria alíquota. A alíquota efetiva da simulação ficou em <b>${fmtNum(r.effectiveAliquot)}%</b> sobre o rendimento.`}
    ${ganhoVsPoupanca > 0 ? ` Contra a poupança no mesmo prazo, a diferença é de <b data-ui-css="color:var(--positive)">${fmtBRL(ganhoVsPoupanca)}</b>.` : ""}</p>
  </div>`;
}

/* --------------------------------------------------------- empréstimo */
function renderSimLoan() {
  const mensal = moneyOrZero(simRaw("emprestimo", "juros"));
  const r = simLoan({
    principal: simMoney("emprestimo", "valor"),
    months: simInt("emprestimo", "parcelas", 1, 480),
    annualRatePct: monthlyToAnnual(mensal / 100),
    system: simRaw("emprestimo", "sistema"),
    monthlyFee: simMoney("emprestimo", "tarifa"),
    monthlyInsurance: simMoney("emprestimo", "seguro"),
    upfrontFee: simMoney("emprestimo", "iof"),
  });
  const sobra = estimateAvgMonthlySaving(state.data);
  const comprometimento = sobra > 0 ? safePct(r.firstPayment, sobra) : null;

  return `<div class="card">
    <p class="card-title">Custo do empréstimo</p>
    <div class="invest-stats">
      ${simStat(r.system === "sac" ? "Primeira parcela" : "Parcela mensal", fmtBRL(r.firstPayment), { highlight: true })}
      ${simStat("Total pago", fmtBRL(r.totalPaid))}
      ${simStat("Só de juros", fmtBRL(r.totalInterest), { color: "var(--negative)" })}
    </div>

    <div class="sim-breakdown">
      ${r.system === "sac" ? `<div class="sim-breakdown__row"><span>Última parcela</span><b>${fmtBRL(r.lastPayment)}</b></div>` : ""}
      <div class="sim-breakdown__row"><span>Taxa anunciada</span><b>${fmtNum(mensal)}% a.m. (${fmtNum(r.annualRatePct)}% a.a.)</b></div>
      <div class="sim-breakdown__row sim-breakdown__row--total"><span>Custo Efetivo Total (CET)</span><b>${r.cetAnnualPct != null ? `${fmtNum(r.cetMonthlyPct)}% a.m. · ${fmtNum(r.cetAnnualPct)}% a.a.` : "Sem dados"}</b></div>
      <div class="sim-breakdown__row"><span>Juros sobre o valor emprestado</span><b>${fmtNum(r.interestOverPrincipalPct)}%</b></div>
      ${r.totalExtras > 0 ? `<div class="sim-breakdown__row"><span>Tarifas e seguros no período</span><b data-ui-css="color:var(--negative)">${fmtBRL(r.totalExtras)}</b></div>` : ""}
    </div>

    ${r.cetAnnualPct != null && r.cetAnnualPct > r.annualRatePct + 0.5 ? `<p class="health-note">A taxa informada é <b>${fmtNum(r.annualRatePct)}% ao ano</b>, enquanto o fluxo digitado produz custo estimado de <b data-ui-css="color:var(--negative)">${fmtNum(r.cetAnnualPct)}% ao ano</b>. Compare com o CET oficial da proposta.</p>` : ""}
    ${comprometimento != null ? `<p class="health-note">A parcela consome <b>${fmtNum(comprometimento)}%</b> da sua sobra média mensal (${fmtBRL(sobra)}).${comprometimento > 100 ? " <b data-ui-css=\"color:var(--negative)\">Isso não cabe no seu orçamento atual.</b>" : ""}</p>` : ""}
  </div>`;
}

/* ------------------------------------------------------ financiamento */
function renderSimFinancing() {
  const bem = simMoney("financiamento", "bem");
  const r = simLoan({
    assetValue: bem,
    downPayment: simMoney("financiamento", "entrada"),
    months: simInt("financiamento", "parcelas", 1, 480),
    annualRatePct: moneyOrZero(simRaw("financiamento", "juros")),
    system: simRaw("financiamento", "sistema"),
    monthlyInsurance: simMoney("financiamento", "seguro"),
    monthlyFee: simMoney("financiamento", "tarifa"),
  });

  return `<div class="card">
    <p class="card-title">Custo do financiamento</p>
    <div class="invest-stats">
      ${simStat("Primeira parcela", fmtBRL(r.firstPayment), { highlight: true })}
      ${simStat("Última parcela", fmtBRL(r.lastPayment))}
      ${simStat("Custo total do bem", fmtBRL(r.totalCost), { color: "var(--negative)" })}
    </div>

    <div class="sim-breakdown">
      <div class="sim-breakdown__row"><span>Valor financiado</span><b>${fmtBRL(r.principal)}</b></div>
      <div class="sim-breakdown__row"><span>Juros pagos no total</span><b data-ui-css="color:var(--negative)">${fmtBRL(r.totalInterest)}</b></div>
      <div class="sim-breakdown__row"><span>Seguros e tarifas no total</span><b data-ui-css="color:var(--negative)">${fmtBRL(r.totalExtras)}</b></div>
      <div class="sim-breakdown__row sim-breakdown__row--total"><span>CET</span><b>${r.cetAnnualPct != null ? `${fmtNum(r.cetAnnualPct)}% a.a.` : "Sem dados"}</b></div>
      ${r.surchargePct != null ? `<div class="sim-breakdown__row"><span>Acima do preço à vista</span><b data-ui-css="color:var(--negative)">+${fmtNum(r.surchargePct)}%</b></div>` : ""}
    </div>

    <p class="health-note">Um bem de <b>${fmtBRL(bem)}</b> sai por <b>${fmtBRL(r.totalCost)}</b> ao fim do contrato${r.surchargePct != null ? `. <b data-ui-css="color:var(--negative)">${fmtNum(r.surchargePct)}% a mais</b>` : ""}. No sistema <b>${r.system === "sac" ? "SAC" : "Price"}</b>, ${r.system === "sac" ? "a parcela começa maior e cai todo mês, e o total de juros é menor" : "a parcela é fixa do começo ao fim, o que facilita o planejamento mas paga mais juros"}.</p>
    <p class="footnote">Se você usar 30% da renda bruta como limite pessoal de planejamento, uma primeira parcela de ${fmtBRL(r.firstPayment)} exigiria renda de ${fmtBRL(r.firstPayment / 0.3)}. A política de aprovação varia por instituição e contrato.</p>
  </div>`;
}

/* --------------------------------------------- entrada ou amortização futura */
function renderSimDownPaymentComparison() {
  const r = simDownPaymentVsPrepayment({
    assetValue: simMoney("entrada-amortizacao", "bem"),
    cashAvailable: simMoney("entrada-amortizacao", "dinheiro"),
    reserveToKeep: simMoney("entrada-amortizacao", "reserva"),
    months: simInt("entrada-amortizacao", "parcelas", 1, 480),
    prepaymentMonth: simInt("entrada-amortizacao", "mesamort", 1, 480),
    entryAnnualRatePct: moneyOrZero(simRaw("entrada-amortizacao", "taxaentrada")),
    fullAnnualRatePct: moneyOrZero(simRaw("entrada-amortizacao", "taxatotal")),
    investmentAnnualPct: moneyOrZero(simRaw("entrada-amortizacao", "rendimento")),
    system: simRaw("entrada-amortizacao", "sistema"),
    prepaymentMode: simRaw("entrada-amortizacao", "efeito"),
    monthlyInsurance: simMoney("entrada-amortizacao", "seguro"),
    monthlyFee: simMoney("entrada-amortizacao", "tarifa"),
  });

  if (!(r.assetValue > 0)) {
    return `<div class="card">${renderEmptyState("wallet", "Informe o valor do bem para comparar os dois caminhos.")}</div>`;
  }

  const entryWins = r.winner === "entry" || r.winner === "tie";
  const laterWins = r.winner === "later";
  const entryLoan = r.entry.loan;
  const entryOfferLoan = r.entry.offerLoan;
  const laterLoan = r.later.loan;
  const monthlySaving = estimateAvgMonthlySaving(state.data);
  const laterDoesNotFit = monthlySaving > 0 && moneyCompare(laterLoan.firstPayment, monthlySaving) > 0;
  const effectLabel = r.prepaymentMode === "term" ? "reduzir o prazo" : "reduzir as parcelas restantes";
  const verdict = r.noEntryAvailable
    ? "Não há dinheiro livre para comparar com uma entrada"
    : r.winner === "entry"
      ? `Menor custo estimado com ${fmtBRL(r.usableCash)} de entrada`
      : r.winner === "later"
        ? `Menor custo estimado amortizando no ${r.prepaymentMonth}º mês`
        : "Os dois caminhos empatam no dinheiro";
  const verdictDetail = r.noEntryAvailable
    ? `A reserva informada consome todo o dinheiro disponível. Reduza a reserva apenas se esse valor realmente puder ser usado.`
    : r.winner === "tie"
      ? `Como o custo estimado ficou igual, a entrada começa com menos dívida e depende de menos premissas futuras.`
      : `${entryWins ? "Dar entrada" : "Esperar para amortizar"} economiza ${fmtBRL(r.savings)} no custo total estimado.`;

  return `<div class="card">
    <p class="card-title">Entrada agora × amortização depois</p>

    <div class="invest-stats">
      ${simStat(verdict, fmtBRL(r.savings), { highlight: true })}
      ${simStat("Dinheiro usado na comparação", fmtBRL(r.usableCash))}
      ${simStat("Reserva preservada", fmtBRL(r.reserve))}
    </div>
    <p class="health-note">${verdictDetail}</p>

    <div class="sim-scenarios">
      <div class="sim-scenario ${entryWins && !r.noEntryAvailable ? "sim-scenario--best" : ""}">
        <div class="sim-scenario__head">
          <b>Dar entrada agora</b>
          ${entryWins && !r.noEntryAvailable ? `<span class="status-badge" data-ui-css="background:var(--positive-soft); color:var(--positive)">${r.winner === "tie" ? "mais simples" : "menor custo"}</span>` : ""}
        </div>
        <p class="sim-scenario__total">${fmtBRL(r.entry.economicCost)}</p>
        <span class="sim-scenario__detail">A proposta em ${r.months} meses começa em ${fmtBRL(entryOfferLoan.firstPayment)}. Para comparar com o mesmo esforço mensal da opção sem entrada, o cálculo mantém até ${fmtBRL(entryLoan.firstPayment)} e quita no ${entryLoan.payoffMonth}º mês.</span>
      </div>

      <div class="sim-scenario ${laterWins ? "sim-scenario--best" : ""}">
        <div class="sim-scenario__head">
          <b>Financiar tudo e amortizar</b>
          ${laterWins ? `<span class="status-badge" data-ui-css="background:var(--positive-soft); color:var(--positive)">menor custo</span>` : ""}
        </div>
        <p class="sim-scenario__total">${fmtBRL(r.later.economicCost)}</p>
        <span class="sim-scenario__detail">Custo econômico em valores de hoje. Financiamento de ${fmtBRL(laterLoan.principal)}, primeira parcela de ${fmtBRL(laterLoan.firstPayment)} e amortização de ${fmtBRL(laterLoan.prepaymentApplied)} no ${r.prepaymentMonth}º mês para ${effectLabel}. Quitação no ${laterLoan.payoffMonth}º mês.</span>
      </div>
    </div>

    <div class="sim-breakdown">
      <div class="sim-breakdown__row"><span>Dinheiro no mês da amortização</span><b>${fmtBRL(r.later.fundAtPrepayment)}</b></div>
      <div class="sim-breakdown__row"><span>Rendimento líquido acumulado</span><b data-ui-css="color:var(--positive)">+ ${fmtBRL(r.later.investmentGain)}</b></div>
      <div class="sim-breakdown__row"><span>Saldo antes da amortização</span><b>${fmtBRL(laterLoan.balanceBeforePrepayment)}</b></div>
      <div class="sim-breakdown__row"><span>Saldo depois da amortização</span><b>${fmtBRL(laterLoan.balanceAfterPrepayment)}</b></div>
      ${laterLoan.paymentAfterPrepayment > 0 ? `<div class="sim-breakdown__row"><span>Parcela depois da amortização</span><b>${fmtBRL(laterLoan.paymentAfterPrepayment)}</b></div>` : ""}
      <div class="sim-breakdown__row"><span>Desembolso nominal dando entrada e mantendo o esforço</span><b>${fmtBRL(addMoney(r.entry.downPayment, entryLoan.totalRegularPaid))}</b></div>
      <div class="sim-breakdown__row"><span>Total nominal recebido pelo banco na espera</span><b>${fmtBRL(laterLoan.totalToLender)}</b></div>
      <div class="sim-breakdown__row"><span>Juros dando entrada</span><b>${fmtBRL(entryLoan.totalInterest)}</b></div>
      <div class="sim-breakdown__row"><span>Juros amortizando depois</span><b>${fmtBRL(laterLoan.totalInterest)}</b></div>
      <div class="sim-breakdown__row"><span>Parcela inicial a mais sem entrada</span><b data-ui-css="color:${r.firstPaymentDifference > 0 ? "var(--negative)" : "var(--positive)"}">${r.firstPaymentDifference > 0 ? "+ " : ""}${fmtBRL(r.firstPaymentDifference)}</b></div>
      <div class="sim-breakdown__row sim-breakdown__row--total"><span>Rendimento líquido para esperar empatar</span><b>${r.breakEvenAnnualPct == null ? "Não alcançado" : `${fmtNum(r.breakEvenAnnualPct)}% a.a.`}</b></div>
    </div>

    ${r.breakEvenAnnualPct != null ? `<p class="health-note">Com estas duas propostas, esperar só ganha no custo se o dinheiro render pelo menos <b>${fmtNum(r.breakEvenAnnualPct)}% líquidos ao ano</b>. Você informou ${fmtNum(r.investmentAnnualPct)}%.</p>` : ""}
    ${r.reserveMissing ? `<p class="ai-error">${svgIcon("alertTriangle", 14)} A simulação usa todo o dinheiro disponível e deixa a reserva em zero. Uma opção matematicamente mais barata pode ser financeiramente ruim se qualquer imprevisto levar você a outra dívida.</p>` : ""}
    ${laterDoesNotFit ? `<p class="ai-error">${svgIcon("alertTriangle", 14)} A primeira parcela sem entrada, ${fmtBRL(laterLoan.firstPayment)}, supera sua sobra média mensal de ${fmtBRL(monthlySaving)}. Mesmo que o custo final pareça bom, esse fluxo não cabe no histórico atual.</p>` : ""}

    <p class="footnote">Use as taxas e os custos das duas propostas reais. Financiar 100% pode não ser aprovado ou ter uma taxa diferente. A amortização antecipada reduz juros futuros, mas o banco deve fornecer a planilha do contrato com o saldo e os descontos aplicados.</p>
  </div>`;
}

/* -------------------------------------------------------------- cartão */
function renderSimCard() {
  const r = simCreditCard({
    debt: simMoney("cartao", "divida"),
    monthlyRatePct: moneyOrZero(simRaw("cartao", "juros")),
    minPaymentPct: moneyOrZero(simRaw("cartao", "pagamento")),
    months: 24,
    installments: simInt("cartao", "parcelas", 1, 48),
    installmentRatePct: moneyOrZero(simRaw("cartao", "jurosparc")),
    alternativeAnnualPct: moneyOrZero(simRaw("cartao", "alternativa")),
  });

  return `<div class="card">
    <p class="card-title">As três saídas, lado a lado</p>
    <div class="sim-scenarios">
      ${r.ranking.map((opt, idx) => {
        const detail = opt.id === "rotativo"
          ? `Pagando ${fmtNum(moneyOrZero(simRaw("cartao", "pagamento")))}% da fatura por mês${r.rotativo.finalBalance > 0.01 ? `, ainda sobrariam ${fmtBRL(r.rotativo.finalBalance)} de dívida em 24 meses` : `, a dívida acabaria no ${r.rotativo.clearedAt}º mês`}.`
          : opt.id === "parcelamento"
            ? `${r.parcelamento.installments}x de ${fmtBRL(r.parcelamento.payment)} a ${fmtNum(r.parcelamento.monthlyRatePct)}% a.m.`
            : `${r.alternativa.installments}x de ${fmtBRL(r.alternativa.payment)} a ${fmtNum(r.alternativa.annualRatePct)}% a.a.`;
        return `<div class="sim-scenario ${idx === 0 ? "sim-scenario--best" : ""}">
          <div class="sim-scenario__head">
            <b>${escapeHtml(opt.label)}</b>
            ${idx === 0 ? `<span class="status-badge" data-ui-css="background:var(--positive-soft); color:var(--positive)">menor custo estimado</span>` : ""}
          </div>
          <p class="sim-scenario__total">${fmtBRL(opt.total)}</p>
          <span class="sim-scenario__detail">${detail}</span>
        </div>`;
      }).join("")}
    </div>

    <div class="sim-breakdown">
      <div class="sim-breakdown__row"><span>Juros do rotativo ao ano</span><b data-ui-css="color:var(--negative)">${fmtNum(r.annualEquivalentPct)}%</b></div>
      <div class="sim-breakdown__row"><span>Encargos acumulados no rotativo</span><b>${fmtBRL(r.rotativo.totalCharges)}</b></div>
      <div class="sim-breakdown__row sim-breakdown__row--total"><span>Economia trocando pela opção mais barata</span><b data-ui-css="color:var(--positive)">${fmtBRL(r.savingVsRotativo)}</b></div>
    </div>

    ${r.rotativo.cappedByLaw ? `<p class="health-note">Os encargos pararam de crescer porque a lei limita juros e encargos do rotativo a <b>100% do valor original da dívida</b>. Sem esse teto, a projeção seria ainda pior.</p>` : ""}
    <p class="health-note">${fmtNum(moneyOrZero(simRaw("cartao", "juros")))}% ao mês equivalem a <b data-ui-css="color:var(--negative)">${fmtNum(r.annualEquivalentPct)}% ao ano</b> nesta conversão composta. Compare o custo da dívida com alternativas reais antes de decidir.</p>
  </div>`;
}

/* ----------------------------------------------------------- consórcio */
function renderSimConsortium() {
  const credito = simMoney("consorcio", "credito");
  const prazo = simInt("consorcio", "prazo", 1, 240);
  const r = simConsortium({
    credit: credito, months: prazo,
    adminPct: moneyOrZero(simRaw("consorcio", "admin")),
    reserveFundPct: moneyOrZero(simRaw("consorcio", "reserva")),
    lancePct: moneyOrZero(simRaw("consorcio", "lance")),
    contemplationMonth: simInt("consorcio", "contemplacao", 1, prazo),
  });
  const fin = simLoan({
    principal: credito, months: prazo,
    annualRatePct: moneyOrZero(simRaw("consorcio", "jurosfin")),
    system: "price",
  });
  const consorcioMaisBarato = r.totalPaid < fin.totalPaid;

  return `<div class="card">
    <p class="card-title">Consórcio × financiamento</p>
    <div class="invest-stats">
      ${simStat("Parcela do consórcio", fmtBRL(r.payment), { highlight: true })}
      ${simStat("Total pago no consórcio", fmtBRL(r.totalPaid))}
      ${simStat("Custo acima da carta", fmtBRL(r.totalCost), { color: "var(--negative)" })}
    </div>

    <div class="sim-breakdown">
      <div class="sim-breakdown__row"><span>Custo total em % da carta</span><b>${fmtNum(r.costPct)}%</b></div>
      <div class="sim-breakdown__row"><span>Custo efetivo do consórcio</span><b>${r.effectiveAnnualPct != null ? `${fmtNum(r.effectiveAnnualPct)}% a.a.` : "Sem dados"}</b></div>
      ${r.lance > 0 ? `<div class="sim-breakdown__row"><span>Lance previsto</span><b>${fmtBRL(r.lance)}</b></div>` : ""}
      <div class="sim-breakdown__row sim-breakdown__row--total"><span>Financiamento equivalente (Price)</span><b>${fmtBRL(fin.totalPaid)} · ${fmtBRL(fin.payment)}/mês</b></div>
    </div>

    <p class="health-note">${consorcioMaisBarato
      ? `Em dinheiro, o consórcio sai <b data-ui-css="color:var(--positive)">${fmtBRL(subMoney(fin.totalPaid, r.totalPaid))}</b> mais barato que o financiamento. O preço disso é o tempo: sem lance, a carta só chega na contemplação; estimada aqui no <b>${r.contemplationMonth}º mês</b>. Consórcio é para quem pode esperar.`
      : `Neste cenário o financiamento sai <b>${fmtBRL(subMoney(r.totalPaid, fin.totalPaid))}</b> mais barato, e ainda entrega o bem hoje. A taxa de administração de ${fmtNum(moneyOrZero(simRaw("consorcio", "admin")))}% pesa mais do que parece porque incide sobre a carta inteira.`}</p>
    <p class="footnote">As parcelas do consórcio são reajustadas quando a carta é corrigida (INCC/IPCA), e o fundo de reserva pode ser devolvido no fim do grupo. Trate o número acima como ordem de grandeza, não como contrato.</p>
  </div>`;
}

/* ---------------------------------------------------------------- FGTS */
function renderSimFgts() {
  const rates = marketRatesOf(state.data);
  const r = simFgts({
    balance: simMoney("fgts", "saldo"),
    monthlySalary: simMoney("fgts", "salario"),
    years: simInt("fgts", "anos", 1, 40),
    fgtsAnnualPct: moneyOrZero(simRaw("fgts", "rendimento")),
    alternativeAnnualPct: moneyOrZero(simRaw("fgts", "alternativa")),
    rates,
  });

  return `<div class="card">
    <p class="card-title">Em ${r.years} ${r.years === 1 ? "ano" : "anos"}</p>
    <div class="sim-scenarios">
      <div class="sim-scenario ${!r.anniversaryWins ? "sim-scenario--best" : ""}">
        <div class="sim-scenario__head"><b>Deixar tudo no FGTS</b>${!r.anniversaryWins ? `<span class="status-badge" data-ui-css="background:var(--positive-soft); color:var(--positive)">maior valor estimado</span>` : ""}</div>
        <p class="sim-scenario__total">${fmtBRL(r.keep.final)}</p>
        <span class="sim-scenario__detail">Equivale a ${fmtBRL(r.keep.realFinal)} em poder de compra de hoje. Saque integral disponível em demissão sem justa causa.</span>
      </div>
      <div class="sim-scenario ${r.anniversaryWins ? "sim-scenario--best" : ""}">
        <div class="sim-scenario__head"><b>Saque-aniversário investido</b>${r.anniversaryWins ? `<span class="status-badge" data-ui-css="background:var(--positive-soft); color:var(--positive)">maior valor estimado</span>` : ""}</div>
        <p class="sim-scenario__total">${fmtBRL(r.anniversary.final)}</p>
        <span class="sim-scenario__detail">${fmtBRL(r.anniversary.fundLeft)} no fundo + ${fmtBRL(r.anniversary.invested)} investidos. Sacado no período: ${fmtBRL(r.anniversary.withdrawn)}.</span>
      </div>
    </div>

    <div class="sim-breakdown">
      <div class="sim-breakdown__row"><span>Depósito do empregador</span><b>${fmtBRL(r.deposit)}/mês (8% do salário)</b></div>
      <div class="sim-breakdown__row"><span>Rendimento do FGTS</span><b>${fmtNum(r.fgtsAnnualPct)}% a.a.</b></div>
      <div class="sim-breakdown__row sim-breakdown__row--total"><span>Diferença entre os dois caminhos</span><b data-ui-css="color:${r.anniversaryWins ? "var(--positive)" : "var(--negative)"}">${r.anniversaryWins ? "+" : "−"}${fmtBRL(Math.abs(r.difference))}</b></div>
    </div>

    ${r.floorApplied ? `<p class="inline-alert">${svgIcon("info", 14)} A estimativa digitada ficou abaixo do IPCA de ${fmtNum(r.inflationFloorAnnualPct)}%. O cálculo aplicou esse piso anual à remuneração do FGTS.</p>` : ""}

    <p class="health-note"><b>Liquidez na demissão:</b> no saque-aniversário, a demissão sem justa causa libera a multa rescisória quando devida, mas não o saldo integral. Os ${fmtBRL(r.lockedOnDismissal)} restantes continuam na conta e só podem ser movimentados nas hipóteses legais. O retorno ao saque-rescisão, quando permitido, produz efeito no primeiro dia do 25º mês após o pedido.</p>
  </div>`;
}

/* -------------------------------------------------------- aposentadoria */
function renderSimRetirement() {
  const rates = marketRatesOf(state.data);
  const idade = simInt("aposentadoria", "idade", 16, 90);
  const r = simRetirement({
    currentAge: idade,
    retireAge: simInt("aposentadoria", "idadeapos", idade + 1, 100),
    lifeExpectancy: simInt("aposentadoria", "expectativa", 60, 110),
    currentSaved: simMoney("aposentadoria", "guardado"),
    monthlyContribution: simMoney("aposentadoria", "aporte"),
    desiredIncome: simMoney("aposentadoria", "renda"),
    annualRatePct: moneyOrZero(simRaw("aposentadoria", "taxa")),
    rates,
  });

  return `<div class="card">
    <p class="card-title">Aos ${r.retireAge} anos</p>
    <div class="invest-stats">
      ${simStat("Patrimônio acumulado", fmtBRL(r.atRetirement), { highlight: true })}
      ${simStat("Renda mensal possível", fmtBRL(r.incomeDepleting), { interest: true })}
      ${simStat("Renda sem consumir o principal", fmtBRL(r.incomePerpetual))}
    </div>

    <div class="sim-breakdown">
      <div class="sim-breakdown__row"><span>Você teria aportado</span><b>${fmtBRL(r.contributed)}</b></div>
      <div class="sim-breakdown__row"><span>Juros no período</span><b data-ui-css="color:var(--positive)">${fmtBRL(r.interestEarned)}</b></div>
      <div class="sim-breakdown__row"><span>Rendimento real usado</span><b>${fmtNum(r.realAnnualPct)}% a.a. (nominal ${fmtNum(r.nominalAnnualPct)}% − inflação ${fmtNum(rates.ipca)}%)</b></div>
      ${r.desiredIncome > 0 ? `<div class="sim-breakdown__row"><span>Capital para a renda desejada</span><b>${fmtBRL(r.capitalDepleting)}</b></div>` : ""}
      ${r.desiredIncome > 0 ? `<div class="sim-breakdown__row sim-breakdown__row--total"><span>Aporte mensal necessário</span><b>${fmtBRL(r.requiredMonthly)}</b></div>` : ""}
    </div>

    ${r.realRateNegative ? `<p class="ai-error">${svgIcon("alertTriangle", 14)} Com rendimento abaixo da inflação, o patrimônio encolhe em poder de compra por mais que você aporte. Revise a taxa esperada ou o produto.</p>` : ""}

    ${r.desiredIncome > 0 ? (r.onTrack
      ? `<p class="health-note">${svgIcon("checkCircle", 14)} No ritmo atual você chega lá: a renda projetada de <b data-ui-css="color:var(--positive)">${fmtBRL(r.incomeDepleting)}</b> cobre os ${fmtBRL(r.desiredIncome)} que você quer, consumindo o patrimônio até os ${r.lifeExpectancy} anos. Se quiser deixar herança ou viver mais que o previsto, o número a mirar é <b>${fmtBRL(r.capitalPerpetual)}</b>, que sustenta a renda sem tocar no principal.</p>`
      : `<p class="health-note">Faltam <b data-ui-css="color:var(--negative)">${fmtBRL(r.gapIncome)}</b> por mês para a renda que você quer. Para fechar a conta, o aporte precisaria ser de <b>${fmtBRL(r.requiredMonthly)}</b>; hoje ele é de ${fmtBRL(r.monthlyContribution)}, uma diferença de <b>${fmtBRL(r.contributionGap)}</b> por mês. Adiar a parada em poucos anos também resolve, porque a diferença é composta.</p>`) : ""}

    <p class="footnote">Tudo em valores de hoje: a projeção desconta a inflação informada para facilitar a comparação do poder de compra ao longo do tempo.</p>
  </div>`;
}

// source: js/screens/simulate.js
// js/screens/simulate.js. Simulador de decisão pontual (impacto de uma compra no mês).
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// SIMULADOR "E SE...?"
// ==================================================================
function renderSimulateScreen() {
  const sim = state.simulate;
  const isFinance = sim.mode === "financiado";
  const amt = parseMoneyInput(sim.amount);
  const result = !isFinance && amt > 0 ? simulateExpenseImpact(state.data, amt, sim.goalId || null) : null;

  const fin = sim.finance;
  const financeReady = ["valorBem", "numParcelas", "valorParcela"].every((k) => moneyOrZero(fin[k]) > 0);
  const financeResult = isFinance && financeReady ? simulateFinancingImpact(state.data, {
    valorBem: moneyOrZero(fin.valorBem),
    entrada: moneyOrZero(fin.entrada),
    numParcelas: moneyOrZero(fin.numParcelas),
    valorParcela: moneyOrZero(fin.valorParcela),
  }, sim.goalId || null) : null;

  return `<div class="screen screen--narrow">
    ${renderBackHeader("Simular gasto")}
    <div class="segmented">
      <button class="segmented__option ${!isFinance ? "active" : ""}" data-action="set-sim-mode" data-value="vista">À Vista</button>
      <button class="segmented__option ${isFinance ? "active" : ""}" data-action="set-sim-mode" data-value="financiado">Financiado</button>
    </div>

    ${!isFinance ? `
    <div class="card" data-ui-css="margin-top:12px">
      <p class="card-subtitle" data-ui-css="margin-top:0">Veja o impacto de uma compra antes de fazer, sem lançar nada de verdade.</p>
      <div class="amount-input-wrap">
        <p class="field__label center">Quanto você pensa em gastar?</p>
        <div class="amount-row">
          <span class="amount-currency">R$</span>
          <input id="sim-amount-input" data-field="sim-amount" class="amount-field" value="${escapeHtml(sim.amount)}" inputmode="decimal" placeholder="0,00" autocomplete="off" />
        </div>
      </div>
      ${renderSimGoalSelect()}
    </div>
    ${result ? renderSimulateResult(result, amt) : ""}
    ` : `
    <div class="card" data-ui-css="margin-top:12px">
      <p class="card-subtitle" data-ui-css="margin-top:0">Compare o custo real de financiar contra o valor à vista do bem.</p>
      <div class="field-row">
        <div class="field"><label class="field__label" for="fin-bem-input">Valor do bem</label>
          <input id="fin-bem-input" class="input" data-field="sim-finance-valorbem" value="${escapeHtml(fin.valorBem)}" inputmode="decimal" placeholder="0,00" /></div>
        <div class="field"><label class="field__label" for="fin-entrada-input">Valor da entrada</label>
          <input id="fin-entrada-input" class="input" data-field="sim-finance-entrada" value="${escapeHtml(fin.entrada)}" inputmode="decimal" placeholder="0,00" /></div>
      </div>
      <div class="field-row">
        <div class="field"><label class="field__label" for="fin-parcelas-input">Número de parcelas</label>
          <input id="fin-parcelas-input" type="number" min="1" max="120" class="input" data-field="sim-finance-numparcelas" value="${escapeHtml(fin.numParcelas)}" placeholder="12" /></div>
        <div class="field"><label class="field__label" for="fin-valorparcela-input">Valor de cada parcela</label>
          <input id="fin-valorparcela-input" class="input" data-field="sim-finance-valorparcela" value="${escapeHtml(fin.valorParcela)}" inputmode="decimal" placeholder="0,00" /></div>
      </div>
      ${renderSimGoalSelect()}
    </div>
    ${financeResult ? renderFinanceResult(financeResult) : ""}
    `}
  </div>`;
}

function renderSimGoalSelect() {
  const sim = state.simulate;
  if (state.data.goals.length === 0) return "";
  return `<div class="field">
    <p class="field__label">Ver efeito em uma meta (opcional)</p>
    <select class="input" id="sim-goal-select" data-action-select="sim-goal">
      <option value="">Nenhuma meta específica</option>
      ${state.data.goals.map((g) => `<option value="${g.id}" ${sim.goalId === g.id ? "selected" : ""}>${escapeHtml(g.name)}</option>`).join("")}
    </select>
  </div>`;
}

function renderSimulateResult(r, amt) {
  const dropColor = r.willExceedIncome ? "var(--negative)" : (r.dailyDrop > r.dailyBefore * 0.3 ? "var(--goal)" : "var(--positive)");
  return `<div class="card card--elevated" data-ui-css="margin-top:14px">
    <p class="card-title">Se você gastar ${fmtBRL(amt)} agora</p>
    <div class="health-grid">
      <div class="health-stat"><span>Orçamento diário hoje</span><b>${fmtBRL(r.dailyBefore)}</b></div>
      <div class="health-stat"><span>Orçamento diário depois</span><b data-ui-css="color:${dropColor}">${fmtBRL(r.dailyAfter)}</b></div>
    </div>
    <p class="health-note">${r.willExceedIncome
      ? `Esse gasto <b data-ui-css="color:var(--negative)">ultrapassa sua renda</b> disponível este mês.`
      : `Seu limite diário para os próximos ${r.daysLeft} dias cai de <b>${fmtBRL(r.dailyBefore)}</b> para <b data-ui-css="color:${dropColor}">${fmtBRL(r.dailyAfter)}</b>.`}</p>
    ${r.goalDelay && r.goalDelay.stalls ? `<p class="health-note">Esse gasto consome praticamente toda a sua capacidade de poupança do mês; a meta <b>${escapeHtml(r.goalDelay.goalName)}</b> ficaria <b data-ui-css="color:var(--negative)">parada</b> enquanto isso.</p>`
      : r.goalDelay && r.goalDelay.extraDays != null ? `<p class="health-note">Isso pode atrasar sua meta <b>${escapeHtml(r.goalDelay.goalName)}</b> em aproximadamente <b data-ui-css="color:var(--goal)">${r.goalDelay.extraDays} dias</b>.</p>` : ""}
  </div>`;
}

function renderFinanceResult(r) {
  const dropColor = r.willExceedIncome ? "var(--negative)" : (r.dailyDrop > r.dailyBefore * 0.3 ? "var(--goal)" : "var(--positive)");
  const interestColor = r.interestCost > 0 ? "var(--negative)" : "var(--positive)";
  const commitColor = r.commitmentWarning ? "var(--negative)" : "var(--positive)";
  return `<div class="card card--elevated" data-ui-css="margin-top:14px">
    <p class="card-title">Custo real do financiamento</p>
    <div class="health-grid">
      <div class="health-stat"><span>Valor do bem</span><b>${fmtBRL(r.valorBem)}</b></div>
      <div class="health-stat"><span>Total pago ao final</span><b>${fmtBRL(r.totalPaid)}</b></div>
      <div class="health-stat"><span>Juros/taxas</span><b data-ui-css="color:${interestColor}">${r.interestCost >= 0 ? "+" : ""}${fmtBRL(r.interestCost)}${r.valorBem > 0 ? ` (${r.interestPct.toFixed(1)}%)` : ""}</b></div>
      <div class="health-stat"><span>${r.numParcelas}x de</span><b>${fmtBRL(r.valorParcela)}</b></div>
    </div>

    ${r.commitmentPct != null ? `
    <p class="card-title" data-ui-css="margin-top:16px">Comprometimento da renda</p>
    <div class="progress"><div class="progress__fill" data-ui-css="width:${clamp(r.commitmentPct, 0, 100)}%; background:${commitColor}"></div></div>
    <p class="health-note">A parcela consome <b data-ui-css="color:${commitColor}">${r.commitmentPct.toFixed(1)}%</b> da sua renda fixa cadastrada.
      ${r.commitmentWarning ? `<b data-ui-css="color:var(--negative)"> Isso passa da faixa de atenção de 20% usada nesta análise. Compare também com sua sobra real e outras parcelas.</b>` : ""}</p>
    ` : `<p class="health-note" data-ui-css="margin-top:16px">Defina sua renda mensal fixa em Ajustes para eu calcular quanto essa parcela compromete do seu orçamento.</p>`}

    <p class="card-title" data-ui-css="margin-top:16px">Impacto no saldo livre diário</p>
    <div class="health-grid">
      <div class="health-stat"><span>Orçamento diário hoje</span><b>${fmtBRL(r.dailyBefore)}</b></div>
      <div class="health-stat"><span>Com a parcela ativa</span><b data-ui-css="color:${dropColor}">${fmtBRL(r.dailyAfter)}</b></div>
    </div>
    <p class="health-note">${r.willExceedIncome
      ? `Com essa parcela, você <b data-ui-css="color:var(--negative)">ultrapassa sua renda</b> disponível nos meses em que ela estiver ativa.`
      : `Enquanto a parcela estiver ativa, seu orçamento diário cai de <b>${fmtBRL(r.dailyBefore)}</b> para <b data-ui-css="color:${dropColor}">${fmtBRL(r.dailyAfter)}</b>.`}</p>
    ${r.goalDelay && r.goalDelay.stalls ? `<p class="health-note">Essa parcela consome praticamente toda a sua capacidade de poupança do mês; a meta <b>${escapeHtml(r.goalDelay.goalName)}</b> ficaria <b data-ui-css="color:var(--negative)">parada</b> enquanto isso.</p>`
      : r.goalDelay && r.goalDelay.extraDays != null ? `<p class="health-note">Isso pode atrasar sua meta <b>${escapeHtml(r.goalDelay.goalName)}</b> em aproximadamente <b data-ui-css="color:var(--goal)">${r.goalDelay.extraDays} dias</b>.</p>` : ""}
  </div>`;
}

// source: js/screens/insights.js
// js/screens/insights.js. Conselheiro e padrões de gasto. Motores em advisor.js e analytics.js.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// [M7] CENTRAL INTELIGENTE; recomendações e insights avançados
// ------------------------------------------------------------------
// Três leituras da mesma base, separadas porque respondem perguntas
// diferentes: o que fazer (Recomendações), como você gasta (Padrões)
// e o que mudou (Comparar).
// ==================================================================
const ADV_TONE_COLOR = {
  danger: "var(--negative)",
  warn: "var(--goal)",
  info: "var(--brand)",
  positive: "var(--positive)",
};

const ADV_TONE_LABEL = { danger: "Urgente", warn: "Atenção", info: "Observação", positive: "Boa notícia" };

const INSIGHTS_VIEWS = [
  { id: "ia", label: "Recomendações" },
  { id: "padroes", label: "Padrões" },
  { id: "comparar", label: "Comparar" },
];

function renderInsightsScreen() {
  const mKey = insightsMonthKey();
  const an = analyticsModel(mKey);
  const adv = advisorModel(mKey);
  const view = state.insights.view;

  return `<div class="screen">
    <div class="screen-header">
      <div class="back-header">
        <button class="icon-btn" data-action="back" data-tab="dashboard" aria-label="Voltar">${svgIcon("chevronLeft", 19)}</button>
        <div>
          <p class="eyebrow">Central inteligente</p>
          <h1 class="page-title">${escapeHtml(an.monthLabel)}</h1>
        </div>
      </div>
      <div class="month-nav">
        <button class="icon-btn" data-action="ins-prev" aria-label="Mês anterior">${svgIcon("chevronLeft", 17)}</button>
        <button class="icon-btn" data-action="ins-next" aria-label="Próximo mês" ${state.insights.monthOffset >= 0 ? "disabled" : ""}>${svgIcon("chevronRight", 17)}</button>
      </div>
    </div>

    ${!an.hasData ? renderEmptyState("sparkles", "Sem lançamentos neste mês.", "As recomendações e comparações aparecem assim que houver movimento registrado.") : `
      ${renderAdvisorHeadline(adv)}

      <div class="segmented">
        ${INSIGHTS_VIEWS.map((v) => `<button class="segmented__option ${view === v.id ? "active" : ""}" data-action="ins-view" data-value="${v.id}">${v.label}</button>`).join("")}
      </div>

      ${view === "ia" ? renderInsightsAdvice(adv) : ""}
      ${view === "padroes" ? renderInsightsPatterns(an) : ""}
      ${view === "comparar" ? renderInsightsCompare(an) : ""}
      <p class="footnote">Leitura educativa baseada apenas nos dados cadastrados. Ela não conhece todo o seu contexto e não substitui orientação profissional individual.</p>
    `}
  </div>`;
}

function renderAdvisorHeadline(adv) {
  const h = adv.headline;
  const color = ADV_TONE_COLOR[h.tone];
  return `<div class="card adv-hero" data-ui-css="--tone:${color}">
    <span class="adv-hero__icon">${svgIcon(h.icon, 22)}</span>
    <div class="adv-hero__text">
      <p class="eyebrow" data-ui-css="color:${color}">${ADV_TONE_LABEL[h.tone]}</p>
      <p class="adv-hero__title">${escapeHtml(h.title)}</p>
      <p class="adv-hero__message">${escapeHtml(h.message)}</p>
    </div>
    ${adv.all.length > 1 ? `<div class="adv-hero__counts">
      ${["danger", "warn", "info", "positive"].filter((t) => adv.counts[t]).map((t) => `
        <span class="adv-count" data-ui-css="--tone:${ADV_TONE_COLOR[t]}">${adv.counts[t]} ${ADV_TONE_LABEL[t].toLowerCase()}</span>`).join("")}
    </div>` : ""}
  </div>`;
}

function renderInsightsAdvice(adv) {
  const rest = adv.cards.filter((c) => c.id !== adv.headline.id);
  return `
    ${adv.plan.total > 0 ? renderSavingPlanCard(adv.plan) : ""}
    ${rest.length === 0
      ? renderEmptyState("checkCircle", "Só a leitura acima por enquanto.", "Quanto mais meses registrados, mais comparações o app consegue fazer.")
      : `<div class="adv-list">${rest.map((c) => renderAdvisorItem(c)).join("")}</div>`}
    ${renderAiCard()}
  `;
}

function renderAdvisorItem(c) {
  const color = ADV_TONE_COLOR[c.tone];
  const open = state.insights.detailId === c.id;
  const hasDetail = Array.isArray(c.detail) && c.detail.length > 0;
  return `<div class="adv-item" data-ui-css="--tone:${color}">
    <span class="adv-item__icon">${svgIcon(c.icon, 17)}</span>
    <div class="adv-item__text">
      <p class="adv-item__title">${escapeHtml(c.title)}</p>
      <p class="adv-item__message">${escapeHtml(c.message)}</p>
      ${hasDetail && open ? `<div class="adv-item__detail">
        ${c.detail.map((d) => `<div class="adv-detail-row">
          <span class="cat-dot" data-ui-css="background:${d.color}"></span>
          <span>${escapeHtml(d.name)}</span>
          <b>${fmtBRL(d.excess)}</b>
        </div>`).join("")}
      </div>` : ""}
      <div class="adv-item__actions">
        ${hasDetail ? `<button class="btn btn--ghost btn--sm" data-action="ins-detail" data-id="${escapeHtml(c.id)}">${open ? "Ocultar detalhe" : "Ver detalhe"}</button>` : ""}
        ${c.action ? `<button class="btn btn--ghost btn--sm" data-action="nav" data-tab="${c.action.tab}">${escapeHtml(c.action.label)} ${svgIcon("chevronRight", 13)}</button>` : ""}
      </div>
    </div>
  </div>`;
}

function renderSavingPlanCard(plan) {
  return `<div class="card">
    <p class="card-title">Onde estão os ${fmtBRL(plan.total)}</p>
    <p class="card-subtitle">Comparação com a sua própria média ${plan.baselineMonths === 1 ? "do último mês" : `dos últimos ${plan.baselineMonths} meses`}; não com um padrão genérico. Categorias essenciais ficam fora da sugestão.</p>
    <div class="plan-list">
      ${plan.items.map((i) => `<div class="plan-row">
        <span class="icon-bubble" data-ui-css="width:28px;height:28px;background:color-mix(in srgb, ${i.color} 14%, transparent); color:${i.color}">${svgIcon(i.icon, 14)}</span>
        <div class="plan-row__text">
          <b>${escapeHtml(i.name)}</b>
          <span>${fmtBRL(i.current)} este mês · média de ${fmtBRL(i.baseline)}</span>
        </div>
        <span class="plan-row__value">${fmtBRL(i.excess)}</span>
      </div>`).join("")}
    </div>
  </div>`;
}

// ---- Padrões: quando e como o dinheiro sai ----
function renderInsightsPatterns(an) {
  const w = an.weekday;
  const avg = an.averages;
  const day = state.insights.heatDay
    ? an.heatmap.days.find((d) => d.iso === state.insights.heatDay)
    : null;

  return `
    <div class="card">
      <p class="card-title">Média diária e semanal</p>
      <div class="health-grid">
        <div class="health-stat"><span>Por dia</span><b>${fmtBRL(avg.daily)}</b></div>
        <div class="health-stat"><span>Por semana</span><b>${fmtBRL(avg.weekly)}</b></div>
        <div class="health-stat"><span>${avg.isCurrentMonth ? "Projeção do mês" : "Total do mês"}</span><b>${fmtBRL(avg.projected)}</b></div>
        <div class="health-stat"><span>Dias considerados</span><b>${avg.elapsedDays} de ${avg.totalDays}</b></div>
      </div>
      ${avg.isCurrentMonth ? `<p class="card-subtitle" data-ui-css="margin-top:10px">A média divide o gasto pelos dias já vividos do mês, não pelos ${avg.totalDays} dias completos; senão o mês pareceria barato justamente enquanto ainda dá para corrigir.</p>` : ""}
    </div>

    <div class="card">
      <p class="card-title">Mapa de calor do mês</p>
      <p class="card-subtitle">Cada quadrado é um dia; quanto mais escuro, mais saiu. Dias que ainda não chegaram ficam vazados.</p>
      ${renderHeatmap(an.heatmap, { action: "heat-day", selected: state.insights.heatDay })}
      ${day ? `<div class="heat-detail">
        <b>${fmtDateFull(day.iso)}</b>
        <span>${day.value > 0 ? `${fmtBRL(day.value)} em ${day.count} ${day.count === 1 ? "lançamento" : "lançamentos"}` : "Nenhum gasto neste dia"}</span>
        <button class="icon-btn icon-btn--muted" data-action="heat-clear" aria-label="Fechar">${svgIcon("x", 14)}</button>
      </div>` : ""}
      <div class="health-grid" data-ui-css="margin-top:12px">
        <div class="health-stat"><span>Dia mais caro</span><b>${an.heatmap.top.length ? `${fmtDateShort(an.heatmap.top[0].iso)} · ${fmtBRL(an.heatmap.top[0].value)}` : "Sem dados"}</b></div>
        <div class="health-stat"><span>Dias sem gasto</span><b>${an.heatmap.quietDays}</b></div>
      </div>
    </div>

    <div class="grid-2">
      <div class="card">
        <p class="card-title">Dia da semana</p>
        ${w.available ? `
          <p class="card-subtitle">Média por ocorrência do dia; um mês com cinco sábados não faz sábado parecer mais caro só por existir mais vezes.</p>
          ${renderBarList(w.rows.filter((r) => r.occurrences > 0).map((r) => ({
            label: r.label, value: r.average,
            color: r.weekend ? "var(--goal)" : "var(--brand)",
            highlight: w.heaviest && r.index === w.heaviest.index,
          })))}
          ${w.heaviest ? `<p class="card-subtitle" data-ui-css="margin-top:10px">Seu dia mais caro é <b>${escapeHtml(w.heaviest.label)}</b>, com média de ${fmtBRL(w.heaviest.average)}.${w.weekendExcessPct != null && w.weekendExcessPct > 0 ? ` O fim de semana custa ${w.weekendExcessPct.toFixed(0)}% mais que os dias úteis.` : ""}</p>` : ""}
        ` : renderEmptyState("calendar", "Ainda sem gastos registrados neste mês.")}
      </div>

      <div class="card">
        <p class="card-title">Horário</p>
        ${an.hours.available ? `
          <p class="card-subtitle">Hora em que o lançamento foi registrado, contando apenas os que você lançou no mesmo dia da compra (${an.hours.sample} de ${(an.extremes.count || 0)} lançamentos).</p>
          ${renderBarList(an.hours.periods.map((p) => ({
            label: p.label, value: p.total, hint: p.hint,
            highlight: an.hours.peakPeriod && p.id === an.hours.peakPeriod.id,
          })))}
          ${an.hours.peakPeriod ? `<p class="card-subtitle" data-ui-css="margin-top:10px">A maior parte sai à <b>${escapeHtml(an.hours.peakPeriod.label.toLowerCase())}</b>, com pico por volta das ${an.hours.peakHourLabel}.</p>` : ""}
        ` : `<p class="card-subtitle">Ainda não há registros suficientes lançados no mesmo dia da compra para uma leitura de horário confiável. O app prefere não desenhar um gráfico que não se sustenta.</p>`}
      </div>
    </div>

    <div class="grid-2">
      <div class="card">
        <p class="card-title">Extremos do mês</p>
        ${an.extremes.available ? `
          <div class="extreme-row">
            <span class="icon-bubble" data-ui-css="background:var(--negative-soft); color:var(--negative)">${svgIcon("arrowUpRight", 16)}</span>
            <div class="extreme-row__text"><b>${escapeHtml(an.extremes.biggest.description)}</b><span>${escapeHtml(an.extremes.biggest.categoryName)} · ${fmtDateShort(an.extremes.biggest.date)}</span></div>
            <span class="extreme-row__value">${fmtBRL(an.extremes.biggest.amount)}</span>
          </div>
          <div class="extreme-row">
            <span class="icon-bubble" data-ui-css="background:var(--positive-soft); color:var(--positive)">${svgIcon("arrowDownRight", 16)}</span>
            <div class="extreme-row__text"><b>${escapeHtml(an.extremes.smallest.description)}</b><span>${escapeHtml(an.extremes.smallest.categoryName)} · ${fmtDateShort(an.extremes.smallest.date)}</span></div>
            <span class="extreme-row__value">${fmtBRL(an.extremes.smallest.amount)}</span>
          </div>
          <div class="health-grid" data-ui-css="margin-top:12px">
            <div class="health-stat"><span>Ticket médio</span><b>${fmtBRL(an.extremes.ticket)}</b></div>
            <div class="health-stat"><span>Lançamentos</span><b>${an.extremes.count}</b></div>
          </div>
        ` : renderEmptyState("wallet", "Nenhum gasto neste mês.")}
      </div>

      <div class="card">
        <p class="card-title">Categoria dominante</p>
        ${an.dominant.available ? `
          <div class="dominant">
            <span class="icon-bubble icon-bubble--lg" data-ui-css="background:color-mix(in srgb, ${an.dominant.color} 14%, transparent); color:${an.dominant.color}">${svgIcon(an.dominant.icon, 22)}</span>
            <div>
              <p class="dominant__name">${escapeHtml(an.dominant.name)}</p>
              <p class="dominant__value">${fmtBRL(an.dominant.value)} · ${an.dominant.share.toFixed(0)}% do mês</p>
            </div>
          </div>
          <div class="progress" data-ui-css="margin-top:12px"><div class="progress__fill" data-ui-css="width:${an.dominant.share}%; background:${an.dominant.color}"></div></div>
          <p class="card-subtitle" data-ui-css="margin-top:10px">${an.dominant.concentrated
            ? "Uma categoria acima de 40% concentra o mês. Não é erro; moradia costuma passar disso, mas é onde qualquer corte tem efeito real."
            : "Seus gastos estão distribuídos: nenhuma categoria domina o mês."}</p>
        ` : renderEmptyState("pie", "Sem gastos para ranquear.")}
      </div>
    </div>
  `;
}

// ---- Comparar: o que mudou ----
function renderInsightsCompare(an) {
  const mom = an.mom;
  const yoy = an.yoy;
  const cats = an.categories;
  const deltaBadge = (d) => {
    if (!d.comparable) return `<span class="status-badge" data-ui-css="background:var(--paper-alt); color:var(--ink-soft)">sem base</span>`;
    const up = d.direction === "up";
    const color = up ? "var(--negative)" : "var(--positive)";
    return `<span class="status-badge" data-ui-css="background:color-mix(in srgb, ${color} 14%, transparent); color:${color}">${svgIcon(up ? "arrowUpRight" : "arrowDownRight", 12)}${Math.abs(d.pct || 0).toFixed(0)}%</span>`;
  };

  return `
    <div class="card">
      <p class="card-title">Contra o mês anterior</p>
      <p class="card-subtitle">${escapeHtml(mom.prevLabel)} ${svgIcon("arrowRight", 13)} ${escapeHtml(mom.label)}</p>
      ${!mom.hasPrevious ? renderEmptyState("calendar", "Não há lançamentos no mês anterior para comparar.") : `
      <div class="cmp-grid">
        <div class="cmp-cell">
          <span class="cmp-cell__label">Gastos</span>
          <b class="cmp-cell__value">${fmtBRL(mom.expense.current)}</b>
          <span class="cmp-cell__prev">era ${fmtBRL(mom.expense.previous)}</span>
          ${deltaBadge(mom.expense)}
        </div>
        <div class="cmp-cell">
          <span class="cmp-cell__label">Receitas</span>
          <b class="cmp-cell__value">${fmtBRL(mom.income.current)}</b>
          <span class="cmp-cell__prev">era ${fmtBRL(mom.income.previous)}</span>
          ${deltaBadge(mom.income)}
        </div>
        <div class="cmp-cell">
          <span class="cmp-cell__label">Sobra</span>
          <b class="cmp-cell__value">${fmtBRL(mom.saving.current)}</b>
          <span class="cmp-cell__prev">era ${fmtBRL(mom.saving.previous)}</span>
          ${deltaBadge(mom.saving)}
        </div>
      </div>`}
    </div>

    <div class="card">
      <p class="card-title">O que subiu e o que caiu</p>
      ${(cats.grew.length + cats.shrank.length) === 0
        ? renderEmptyState("pie", "Sem variação relevante entre os dois meses.")
        : `<p class="card-subtitle">Comparação por categoria principal; o gasto de uma subcategoria conta na categoria-mãe, a mesma herança dos orçamentos.</p>
           ${renderDivergingBars(cats.grew.concat(cats.shrank.slice().reverse()))}`}
    </div>

    <div class="card">
      <p class="card-title">Contra o ano passado</p>
      ${!yoy.available ? renderEmptyState("clock", "Ainda não há um ano de histórico.", "A comparação anual aparece quando existirem lançamentos do mesmo período do ano anterior.") : `
        <div class="cmp-grid">
          ${yoy.sameMonthAvailable ? `<div class="cmp-cell">
            <span class="cmp-cell__label">Mesmo mês</span>
            <b class="cmp-cell__value">${fmtBRL(yoy.sameMonth.current)}</b>
            <span class="cmp-cell__prev">${escapeHtml(yoy.sameMonthLabel)}: ${fmtBRL(yoy.sameMonth.previous)}</span>
            ${deltaBadge(yoy.sameMonth)}
          </div>` : ""}
          <div class="cmp-cell">
            <span class="cmp-cell__label">Gasto no ano</span>
            <b class="cmp-cell__value">${fmtBRL(yoy.ytdExpense.current)}</b>
            <span class="cmp-cell__prev">${yoy.lastYear}: ${fmtBRL(yoy.ytdExpense.previous)}</span>
            ${deltaBadge(yoy.ytdExpense)}
          </div>
          <div class="cmp-cell">
            <span class="cmp-cell__label">Receita no ano</span>
            <b class="cmp-cell__value">${fmtBRL(yoy.ytdIncome.current)}</b>
            <span class="cmp-cell__prev">${yoy.lastYear}: ${fmtBRL(yoy.ytdIncome.previous)}</span>
            ${deltaBadge(yoy.ytdIncome)}
          </div>
        </div>
        <p class="card-subtitle" data-ui-css="margin-top:10px">O acumulado compara janeiro até ${escapeHtml(an.monthLabel.split(" de ")[0].toLowerCase())} nos dois anos; nunca um ano inteiro contra um ano pela metade.</p>
      `}
    </div>

    <div class="card">
      <p class="card-title">Últimos 12 meses</p>
      ${renderTrendChart(an.series.filter((s) => !s.empty).length > 1 ? an.series : an.series.slice(-6))}
      <div class="trend-legend"><span><i data-ui-css="background:var(--brand)"></i>Entradas</span><span><i data-ui-css="background:var(--negative)"></i>Gastos</span></div>
    </div>
  `;
}

// Cartão do Dashboard; porta de entrada da central.

function renderAdvisorCard(mKey) {
  const adv = advisorModel(mKey);
  if (!adv.hasData) return "";
  const items = adv.cards.slice(0, 3);
  if (items.length === 0) return "";
  return `<div class="card span-2 card--advisor">
    <div class="leak-header">
      ${svgIcon("sparkles", 18, "leak-header__icon")}
      <div>
        <p class="card-title" data-ui-css="margin:0">Central inteligente</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">${adv.all.length} ${adv.all.length === 1 ? "leitura" : "leituras"} sobre o seu mês</p>
      </div>
    </div>
    <div class="adv-list adv-list--compact">
      ${items.map((c) => `<div class="adv-item adv-item--compact" data-ui-css="--tone:${ADV_TONE_COLOR[c.tone]}">
        <span class="adv-item__icon">${svgIcon(c.icon, 15)}</span>
        <div class="adv-item__text">
          <p class="adv-item__title">${escapeHtml(c.title)}</p>
          <p class="adv-item__message">${escapeHtml(c.message)}</p>
        </div>
      </div>`).join("")}
    </div>
    <button class="btn btn--secondary btn--block" data-ui-css="margin-top:10px" data-action="nav" data-tab="insights">Ver todas as recomendações</button>
  </div>`;
}

// ==================================================================
// Prévia do envio para a IA
// ------------------------------------------------------------------
// O cartão de IA prometia que "antes do envio você verá exatamente quais dados
// sairão do aparelho", e o que aparecia era um parágrafo descrevendo o pacote.
// Descrição não é o pacote: ela envelhece quando o formato muda e não mostra
// os NOMES que o usuário escolheu para categorias e metas, que são justamente
// a parte que pode revelar contexto pessoal.
//
// Esta tela usa `buildAiPayloadPreview`, a mesma função que monta o envio, e
// por isso não pode divergir dele.
// ==================================================================

// Quanto o pacote ocupa, em palavra de gente.
function aiPreviewSize(bytes) {
  return bytes >= 1024 ? `${(bytes / 1024).toFixed(1)} KB` : `${bytes} bytes`;
}

function renderAiPreviewFields(preview, hide) {
  const oculto = new Set(hide);
  return Object.entries(preview.ocultaveis).map(([id, label]) => {
    const incluido = !oculto.has(id);
    return `<label class="ai-preview__field">
      <input type="checkbox" data-action-select="ai-preview-field" data-value="${escapeHtml(id)}" ${incluido ? "checked" : ""} />
      <span>
        <b>${escapeHtml(label)}</b>
        <small>${incluido ? "Vai junto no envio" : (id === "categorias" ? "Sai como Categoria 1, Categoria 2..." : "Removido do pacote")}</small>
      </span>
    </label>`;
  }).join("");
}

function renderAiPreviewModal() {
  const mKey = state.aiPreview.monthKey;
  if (!mKey) return "";
  const hide = state.aiPreview.hide;
  let preview = null;
  try {
    preview = buildAiPayloadPreview(state.data, mKey, { hide });
  } catch (e) {
    return "";
  }
  // `_rendaLancada` é chave interna: `JSON.stringify` já a omite (o valor é
  // undefined), então mostrá-la na lista de campos anunciaria um envio que não
  // acontece.
  const campos = preview.campos.filter((nome) => nome.charAt(0) !== "_");
  return `<div class="modal-overlay" data-action="ai-preview-cancel">
    <div class="modal-sheet ai-preview" data-stop-close="1" role="dialog" aria-modal="true" aria-labelledby="ai-preview-title">
      <div class="modal-header">
        <span class="icon-bubble icon-bubble--lg">${svgIcon("sparkles", 20)}</span>
        <div>
          <p class="card-title" id="ai-preview-title" data-ui-css="margin:0">O que será enviado</p>
          <p class="card-subtitle" data-ui-css="margin:3px 0 0">${escapeHtml(anMonthLabel(mKey))}. Nada sai do aparelho até você tocar em enviar.</p>
        </div>
        <button class="icon-btn" data-action="ai-preview-cancel" aria-label="Fechar prévia do envio">${svgIcon("x", 16)}</button>
      </div>

      <div class="ai-preview__body">
        <p class="ai-preview__summary">${svgIcon("shieldCheck", 15)} <span>${escapeHtml(preview.resumo)}</span></p>

        <p class="field__label">O que você pode tirar antes de enviar</p>
        <div class="ai-preview__fields">${renderAiPreviewFields(preview, hide)}</div>

        <div class="ai-preview__meta">
          <span>${campos.length} ${campos.length === 1 ? "campo" : "campos"}</span>
          <span>${aiPreviewSize(preview.bytes)}</span>
        </div>

        <details class="ai-preview__json" ${state.aiPreview.showJson ? "open" : ""}>
          <summary data-action="ai-preview-toggle-json">Ver o pacote inteiro</summary>
          <pre><code>${escapeHtml(preview.json)}</code></pre>
        </details>
      </div>

      <div class="ai-preview__actions">
        <button type="button" class="btn btn--ghost" data-action="ai-preview-cancel">Cancelar</button>
        <button type="button" class="btn btn--primary" data-action="ai-preview-send">${svgIcon("sparkles", 15)} Enviar e analisar</button>
      </div>
    </div>
  </div>`;
}

// source: js/screens/subscriptions.js
// js/screens/subscriptions.js. Assinaturas e recorrências. Modelo em recurring.js.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// ASSINATURAS E RECORRÊNCIAS
// ==================================================================
// ==================================================================
// [M7] ASSINATURAS E RECORRÊNCIAS
// ------------------------------------------------------------------
// A tela é montada a partir de UM modelo (`buildRecurringModel`, em
// recurring.js). Nenhum cálculo mora aqui.
//
// A inversão de hierarquia é deliberada: o número grande é o CUSTO
// ANUAL, não a mensalidade. "R$ 55,90" não faz ninguém reavaliar um
// plano; "R$ 670,80 por ano" faz. A mensalidade continua visível,
// como referência; só deixou de ser a manchete.
// ==================================================================
const SUBS_VIEWS = [
  { id: "assinaturas", label: "Assinaturas" },
  { id: "variaveis", label: "Recorrentes" },
  { id: "ignoradas", label: "Sem acompanhar" },
];

function renderSubscriptionsScreen() {
  const mKey = keyOfCurrentMonth();
  const m = recurringModel(mKey);
  const view = state.subs.view;
  const list = view === "assinaturas" ? m.subscriptions : view === "variaveis" ? m.variable : m.ignored;

  return `<div class="screen screen--narrow">
    ${renderBackHeader("Assinaturas e recorrências")}

    ${renderSubsHero(m)}

    ${m.proposals.length > 0 ? renderRecurringProposals(m.proposals) : ""}

    ${m.increases.length > 0 ? `<div class="banner">
      ${svgIcon("alertTriangle", 20, "banner__icon")}
      <div class="banner__text">
        <strong>${m.increases.length === 1 ? "Um reajuste detectado" : `${m.increases.length} reajustes detectados`}</strong>
        <span>${m.increases.slice(0, 3).map((s) => `${escapeHtml(s.name)} (+${s.increasePct.toFixed(0)}%, ${fmtBRL(s.increaseAnnualImpact)}/ano)`).join(" · ")}</span>
      </div>
    </div>` : ""}

    <div class="segmented">
      ${SUBS_VIEWS.map((v) => {
        const count = v.id === "assinaturas" ? m.counts.subscriptions : v.id === "variaveis" ? m.counts.variable : m.counts.ignored;
        return `<button class="segmented__option ${view === v.id ? "active" : ""}" data-action="subs-view" data-value="${v.id}">${v.label}${count > 0 ? ` (${count})` : ""}</button>`;
      }).join("")}
    </div>

    ${list.length === 0
      ? renderEmptyState("refresh", subsEmptyTitle(view), subsEmptyHint(view))
      : `<div class="sub-list">${list.map((s) => renderSubItem(s, view === "ignoradas")).join("")}</div>`}

    ${view !== "ignoradas" && m.ended.length > 0 ? `<div class="card">
      <p class="card-title">Parou de cobrar</p>
      <p class="card-subtitle">Sem lançamento há mais tempo do que a própria cadência. Já saíram do total mensal; se voltarem a aparecer, retornam sozinhas.</p>
      <div class="leak-list">
        ${m.ended.map((s) => `<div class="leak-row">
          <span class="icon-bubble" data-ui-css="width:26px;height:26px;background:color-mix(in srgb, ${s.categoryColor} 14%, transparent); color:${s.categoryColor}">${svgIcon(s.categoryIcon, 13)}</span>
          <span class="leak-name">${escapeHtml(s.name)}</span>
          <span class="import-row__meta">último em ${fmtDateShort(s.lastDate)}</span>
          <span class="leak-value">${fmtBRL(s.lastAmount)}</span>
        </div>`).join("")}
      </div>
    </div>` : ""}

    <p class="footnote">Tudo é identificado a partir do histórico salvo neste navegador; nada é enviado para servidor algum. "Parar de acompanhar" tira o item das listas e dos totais, mas não apaga nenhum lançamento.</p>
  </div>`;
}

function subsEmptyTitle(view) {
  if (view === "ignoradas") return "Você não parou de acompanhar nada.";
  if (view === "variaveis") return "Nenhuma cobrança recorrente de valor variável.";
  return "Nenhuma assinatura identificada ainda.";
}

function subsEmptyHint(view) {
  if (view === "ignoradas") return "Itens que você mandar parar de acompanhar aparecem aqui e podem voltar a qualquer momento.";
  if (view === "variaveis") return "Contas de luz, água e mercado entram aqui quando repetem a cadência com valores diferentes.";
  return "Assim que o mesmo gasto aparecer duas vezes no mesmo intervalo, ele é reconhecido automaticamente.";
}

// Manchete: o ano inteiro. Ver a nota no topo do bloco.

function renderSubsHero(m) {
  return `<div class="card sub-hero">
    <div class="sub-hero__main">
      <p class="eyebrow">Assinaturas · custo de 12 meses</p>
      <p class="sub-hero__annual">${fmtBRL(m.annualTotal)}</p>
      <p class="sub-hero__monthly">${fmtBRL(m.monthlyTotal)} por mês em ${m.counts.subscriptions} ${m.counts.subscriptions === 1 ? "cobrança" : "cobranças"} de valor fixo</p>
    </div>
    <div class="health-grid">
      <div class="health-stat"><span>Recorrentes variáveis</span><b>${fmtBRL(m.variableMonthly)}</b></div>
      <div class="health-stat"><span>Comprometido por mês</span><b>${fmtBRL(m.committedMonthly)}</b></div>
      ${m.income > 0 ? `<div class="health-stat"><span>Da sua renda</span><b>${m.incomeShare.toFixed(0)}%</b></div>` : ""}
      <div class="health-stat"><span>Próximos 30 dias</span><b>${fmtBRL(m.upcomingTotal)}</b></div>
    </div>
    ${m.upcoming.length > 0 ? `<div class="sub-upcoming">
      ${m.upcoming.slice(0, 4).map((s) => `<span class="sub-chip" title="${escapeHtml(s.name)}">
        <i data-ui-css="background:${s.categoryColor}"></i><span class="sub-chip__txt">${fmtDateShort(s.nextDate)} · ${escapeHtml(s.name)} · ${fmtBRL(s.lastAmount)}</span>
      </span>`).join("")}
    </div>` : ""}
  </div>`;
}

// §9; a pergunta do briefing, feita só quando o app tem confiança de acertar.

function renderRecurringProposals(proposals) {
  return `<div class="card card--proposal">
    <div class="leak-header">
      ${svgIcon("refresh", 18, "leak-header__icon")}
      <div>
        <p class="card-title" data-ui-css="margin:0">Padrão detectado</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">Estes gastos se repetem sempre no mesmo intervalo, mas ainda não estão marcados como recorrentes. Marcar faz a previsão de saldo e o calendário já contarem com eles.</p>
      </div>
    </div>
    <div class="rec-proposals">
      ${proposals.map((p) => `<div class="rec-proposal">
        <span class="icon-bubble" data-ui-css="background:color-mix(in srgb, ${p.categoryColor} 14%, transparent); color:${p.categoryColor}">${svgIcon(p.categoryIcon, 16)}</span>
        <div class="rec-proposal__text">
          <b>${escapeHtml(p.pattern)} · ${escapeHtml(p.name)}</b>
          <span>${fmtBRL(p.amount)} · ${p.occurrences} cobranças · ${fmtBRL(p.annualCost)} por ano</span>
        </div>
        <div class="rec-proposal__actions">
          <button class="btn btn--secondary btn--sm" data-action="rec-dismiss" data-id="${escapeHtml(p.key)}">Agora não</button>
          <button class="btn btn--primary btn--sm" data-action="rec-confirm" data-id="${escapeHtml(p.key)}">Cadastrar</button>
        </div>
      </div>`).join("")}
    </div>
  </div>`;
}

function subStatusBadge(s) {
  if (s.status === "atrasada") {
    return `<span class="status-badge" data-ui-css="background:var(--goal-soft); color:var(--goal)">${svgIcon("clock", 11)} não veio ainda</span>`;
  }
  if (s.increasePct > 3) {
    return `<span class="status-badge" data-ui-css="background:var(--negative-soft); color:var(--negative)">${svgIcon("arrowUpRight", 11)} +${s.increasePct.toFixed(0)}%</span>`;
  }
  return "";
}

function renderSubItem(s, ignored) {
  const open = state.subs.expandedKey === s.key;
  return `<div class="sub-item ${open ? "is-open" : ""}">
    <button class="sub-item__head" data-action="sub-expand" data-id="${escapeHtml(s.key)}" aria-expanded="${open ? "true" : "false"}">
      <span class="icon-bubble" data-ui-css="background:color-mix(in srgb, ${s.categoryColor} 14%, transparent); color:${s.categoryColor}">${svgIcon(s.categoryIcon, 16)}</span>
      <span class="sub-item__id">
        <b>${escapeHtml(s.name)}</b>
        <span>${s.cadenceLabel}${s.cadenceId === "mensal" ? ` · todo dia ${s.dayOfMonth}` : ""} · ${escapeHtml(s.categoryName)}</span>
      </span>
      ${subStatusBadge(s)}
      <span class="sub-item__price">
        <b>${fmtBRL(s.annualCost)}</b>
        <span>por ano · ${fmtBRL(s.lastAmount)}/${s.cadenceId === "mensal" ? "mês" : s.cadenceLabel.toLowerCase()}</span>
      </span>
      ${svgIcon(open ? "chevronUp" : "chevronDown", 15, "sub-item__chevron")}
    </button>
    ${open ? `<div class="sub-item__body">
      <div class="health-grid">
        <div class="health-stat"><span>Próxima cobrança</span><b>${fmtDateFull(s.nextDate)}</b></div>
        <div class="health-stat"><span>Equivalente mensal</span><b>${fmtBRL(s.monthlyEquivalent)}</b></div>
        <div class="health-stat"><span>Cobranças registradas</span><b>${s.occurrences}</b></div>
        <div class="health-stat"><span>Acompanhando desde</span><b>${fmtDateShort(s.firstDate)}</b></div>
      </div>
      ${s.sinceFirstPct > 3 ? `<p class="sub-item__note">Desde a primeira cobrança o valor subiu ${s.sinceFirstPct.toFixed(0)}%; de ${fmtBRL(s.firstAmount)} para ${fmtBRL(s.lastAmount)}.</p>` : ""}
      ${s.kind === "recorrente" ? `<p class="sub-item__note">O valor varia entre as cobranças, então este é um gasto recorrente e não uma assinatura de preço fixo. O total usa a última cobrança como referência.</p>` : ""}
      <div class="sub-item__actions">
        ${ignored
          ? `<button class="btn btn--primary btn--sm" data-action="sub-track" data-id="${escapeHtml(s.key)}">Voltar a acompanhar</button>`
          : `${s.flaggedRecurring
              ? `<button class="btn btn--secondary btn--sm" data-action="sub-unflag" data-id="${escapeHtml(s.key)}">Desmarcar como recorrente</button>`
              : `<button class="btn btn--secondary btn--sm" data-action="rec-confirm" data-id="${escapeHtml(s.key)}">Marcar como recorrente</button>`}
             <button class="btn btn--ghost btn--sm" data-action="sub-ignore" data-id="${escapeHtml(s.key)}">Parar de acompanhar</button>`}
      </div>
    </div>` : ""}
  </div>`;
}

// Cartão do Dashboard; agora com o número que importa (o ano) e o alerta de
// reajuste, que antes só existia na tela cheia.
function renderSubscriptionsCard() {
  const m = recurringModel(keyOfCurrentMonth());
  if (m.counts.subscriptions === 0 && m.counts.variable === 0) return "";
  const top = m.subscriptions.concat(m.variable).slice(0, 3);
  return `<div class="card card--subs span-3" data-action="nav" data-tab="subscriptions" data-ui-css="cursor:pointer">
    <div class="leak-header">
      ${svgIcon("refresh", 18, "leak-header__icon")}
      <div>
        <p class="card-title" data-ui-css="margin:0">Assinaturas e recorrências</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">${m.counts.subscriptions + m.counts.variable} identificadas · ${fmtBRL(m.annualTotal)} por ano em assinaturas</p>
      </div>
      <span class="leak-total">${fmtBRL(m.committedMonthly)}/mês</span>
    </div>
    <div class="leak-list">
      ${top.map((s) => `<div class="leak-row">
        <span class="icon-bubble" data-ui-css="width:26px;height:26px;background:color-mix(in srgb, ${s.categoryColor} 14%, transparent); color:${s.categoryColor}">${svgIcon(s.categoryIcon, 13)}</span>
        <span class="leak-name">${escapeHtml(s.name)}</span>
        ${s.increasePct > 3 ? `<span class="status-badge" data-ui-css="background:var(--negative-soft); color:var(--negative)">${svgIcon("arrowUpRight", 11)} +${s.increasePct.toFixed(0)}%</span>` : ""}
        <span class="leak-value">${fmtBRL(s.lastAmount)}</span>
      </div>`).join("")}
    </div>
    ${m.proposals.length > 0 ? `<p class="card-subtitle" data-ui-css="margin:8px 0 0">${svgIcon("info", 13)} ${m.proposals.length} ${m.proposals.length === 1 ? "padrão aguarda" : "padrões aguardam"} confirmação de cadastro.</p>` : ""}
  </div>`;
}

// source: js/screens/notifications.js
// js/screens/notifications.js. Central de notificações. Modelo em services.js.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// [M8] CENTRAL DE NOTIFICAÇÕES
// ==================================================================
// A tela não decide nada: `NotificationService` monta o modelo (agrupado por
// período, com contagens e estado de leitura) e aqui só se desenha. A escrita
// volta pelas mesmas funções puras; a UI nunca mexe no array de avisos à mão.
const NOTIF_TONE_CLASS = { danger: "notif-item--danger", warn: "notif-item--warn", positive: "notif-item--positive", info: "" };

function renderNotificationsScreen() {
  const m = notificationsModel();
  const c = m.counts;

  return `<div class="screen screen--narrow">
    ${renderBackHeader("Notificações")}

    <div class="card card--hero">
      <div class="hero-glow"></div>
      <p class="hero-label">${c.unread > 0 ? `${c.unread} ${c.unread === 1 ? "aviso não lido" : "avisos não lidos"}` : "Tudo em dia"}</p>
      <p class="hero-value">${c.total}</p>
      <p class="hero-reserved">${svgIcon("bell", 14)} ${c.total === 1 ? "aviso no histórico" : "avisos no histórico"}${c.urgent > 0 ? ` · ${c.urgent} ${c.urgent === 1 ? "urgente" : "urgentes"}` : ""}</p>
      <div class="hero-tools">
        ${c.unread > 0 ? `<button class="hero-tool-btn" data-action="notif-read-all">${svgIcon("checkCircle", 15)}Marcar todas como lidas</button>` : ""}
        <button class="hero-tool-btn" data-action="notif-settings">${svgIcon("gear", 15)}Silenciar grupos</button>
        ${c.total > c.unread ? `<button class="hero-tool-btn" data-action="notif-clear">${svgIcon("trash", 15)}Limpar as lidas</button>` : ""}
      </div>
    </div>

    ${state.notif.settingsOpen ? renderNotifSettingsCard(m) : ""}

    <div class="segmented segmented--scroll">
      <button class="segmented__option ${state.notif.filter === "all" ? "active" : ""}" data-action="notif-filter" data-value="all">Todas${c.total > 0 ? ` (${c.total})` : ""}</button>
      <button class="segmented__option ${state.notif.filter === "unread" ? "active" : ""}" data-action="notif-filter" data-value="unread">Não lidas${c.unread > 0 ? ` (${c.unread})` : ""}</button>
      ${m.groups.filter((g) => g.count > 0).map((g) => `
        <button class="segmented__option ${state.notif.filter === g.id ? "active" : ""}" data-action="notif-filter" data-value="${g.id}">${escapeHtml(g.label)} (${g.count})</button>`).join("")}
    </div>

    ${m.buckets.length === 0
      ? renderEmptyState("bell", notifEmptyTitle(m), notifEmptyHint(m))
      : m.buckets.map((b) => `<div class="card">
          <p class="card-title">${b.label}</p>
          <div class="notif-list">${b.items.map(renderNotifItem).join("")}</div>
        </div>`).join("")}

    <p class="footnote">Os avisos são gerados no seu aparelho a partir do histórico já salvo; nenhum dado é enviado a servidor algum e nenhuma permissão de notificação do sistema é solicitada. Silenciar um grupo interrompe novos avisos daquele tipo, sem apagar nada do histórico.</p>
  </div>`;
}

function notifEmptyTitle(m) {
  if (!m.hasAny) return "Nenhum aviso ainda.";
  if (state.notif.filter === "unread") return "Você está em dia.";
  return "Nada neste filtro.";
}

function notifEmptyHint(m) {
  if (!m.hasAny) return "Contas a vencer, orçamento estourado, reajuste de assinatura, meta atrasada e saldo projetado negativo aparecem aqui assim que acontecerem.";
  if (state.notif.filter === "unread") return "Todos os avisos foram lidos. Os novos aparecem aqui automaticamente.";
  return "Troque o filtro para ver os outros avisos do histórico.";
}

function renderNotifItem(n) {
  return `<div class="notif-item ${NOTIF_TONE_CLASS[n.tone] || ""} ${n.readAt ? "is-read" : ""}">
    <span class="notif-item__icon">${svgIcon(n.icon, 16)}</span>
    <div class="notif-item__body">
      <p class="notif-item__title">${n.readAt ? "" : `<i class="notif-dot" aria-label="Não lida"></i>`}${escapeHtml(n.title)}</p>
      <p class="notif-item__msg">${escapeHtml(n.message)}</p>
      <p class="notif-item__meta">${escapeHtml(n.groupLabel)} · ${n.dateLabel}</p>
    </div>
    <div class="notif-item__actions">
      <button class="btn btn--secondary btn--sm" data-action="notif-open" data-id="${n.id}" data-tab="${n.tab}">Ver</button>
      ${n.readAt ? "" : `<button class="icon-btn icon-btn--muted" data-action="notif-read" data-id="${n.id}" aria-label="Marcar como lida">${svgIcon("check", 15)}</button>`}
      <button class="icon-btn icon-btn--muted" data-action="notif-remove" data-id="${n.id}" aria-label="Remover aviso">${svgIcon("x", 15)}</button>
    </div>
  </div>`;
}

function renderNotifSettingsCard(m) {
  return `<div class="card">
    <p class="card-title">O que pode me avisar</p>
    <p class="card-subtitle">Silenciar um grupo interrompe apenas a criação de novos avisos daquele tipo. Os lançamentos, os totais e as outras telas continuam exatamente iguais.</p>
    <div class="tool-links">
      ${m.groups.map((g) => `
        <button class="tool-link" data-action="notif-mute" data-id="${g.id}">
          ${svgIcon(g.icon, 17)}<span>${escapeHtml(g.label)}</span>
          <span class="switch ${g.muted ? "" : "active"}"><span class="switch__knob"></span></span>
        </button>`).join("")}
    </div>
  </div>`;
}

// source: js/screens/achievements.js
// js/screens/achievements.js. Gamificação: nível, XP e conquistas. A regra mora em achievements.js.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// [M6] GAMIFICAÇÃO; nível, XP e conquistas
// ------------------------------------------------------------------
// Toda a regra mora em `achievements.js`. Aqui só há HTML.
//
// A tela foi desenhada para responder, nesta ordem: "onde eu estou?" (nível),
// "o que eu já fiz?" (conquistas), "o que eu faço agora?" (próximas). A última
// pergunta é a que muda comportamento; por isso as trancadas COM progresso
// aparecem antes das já conquistadas dentro de cada grupo.
// ==================================================================

function achFormatValue(item, value) {
  if (item.unit === "money") return fmtBRLShort(value);
  if (item.unit === "pct") return `${fmtNum(Math.round(value))}%`;
  return fmtNum(Math.round(value * 10) / 10);
}

// Anel de nível: mesmo vocabulário visual do Score e das metas.
// `onDark` troca a paleta para o painel esmeralda; sobre fundo escuro a cor do
// nível (cinza no nível 1) some, então lá o arco usa o brilho da marca e o texto
// herda o branco do painel. Contraste não é detalhe estético.
function renderLevelRing(level, size, onDark) {
  const s = size || 92;
  const stroke = Math.round(s * 0.095);
  const r = s / 2 - stroke / 2 - 1;
  const c = 2 * Math.PI * r;
  const len = Math.max(0, clamp(level.progress, 0, 1) * c);
  const track = onDark ? "rgba(255,255,255,0.22)" : "var(--border)";
  const arc = onDark ? "var(--brand-glow)" : level.color;
  return `<svg class="level-ring" viewBox="0 0 ${s} ${s}" width="${s}" height="${s}" role="img" aria-label="Nível ${level.level}, ${escapeHtml(level.name)}, ${Math.round(level.progress * 100)}% para o próximo">
    <circle cx="${s / 2}" cy="${s / 2}" r="${r}" fill="none" stroke="${track}" stroke-width="${stroke}" />
    <circle cx="${s / 2}" cy="${s / 2}" r="${r}" fill="none" stroke="${arc}" stroke-width="${stroke}"
      stroke-linecap="round" stroke-dasharray="${len} ${c - len}"
      transform="rotate(-90 ${s / 2} ${s / 2})" class="level-ring__arc" />
    <text x="50%" y="47%" text-anchor="middle" class="level-ring__num" fill="currentColor">${level.level}</text>
    <text x="50%" y="66%" text-anchor="middle" class="level-ring__cap" fill="currentColor">NÍVEL</text>
  </svg>`;
}

function renderAchievementBadge(item, compact) {
  const tier = item.tierMeta;
  const color = item.done ? tier.color : "var(--ink-faint)";
  const pct = Math.round(item.progress * 100);
  const open = state.gamification.detailId === item.id;
  const remaining = Math.max(0, item.target - item.current);
  return `<button class="ach-badge ${item.done ? "ach-badge--done" : ""} ${compact ? "ach-badge--compact" : ""} ${open ? "ach-badge--open" : ""}"
      data-action="ach-detail" data-id="${item.id}" aria-expanded="${open}"
      aria-label="${escapeHtml(item.name)}. ${item.done ? "conquistada" : `${pct}% concluída`}">
    <span class="ach-badge__medal" data-ui-css="--ach-color:${color}">
      ${svgIcon(item.icon, compact ? 17 : 20)}
      ${item.done ? `<span class="ach-badge__check">${svgIcon("check", 10)}</span>` : ""}
    </span>
    <span class="ach-badge__body">
      <span class="ach-badge__name">${escapeHtml(item.name)}</span>
      <span class="ach-badge__meta">
        <span class="ach-tier" data-ui-css="color:${tier.color}">${tier.label}</span>
        <span class="ach-xp">+${item.xp} XP</span>
      </span>
      ${item.done
        ? `<span class="ach-badge__done">${svgIcon("checkCircle", 12)} ${item.unlockedAt ? `Conquistada em ${fmtDateFull(item.unlockedAt)}` : "Conquistada"}</span>`
        : `<span class="ach-progress"><span class="ach-progress__fill" data-ui-css="width:${pct}%;background:${tier.color}"></span></span>
           <span class="ach-badge__hint">${achFormatValue(item, item.current)} de ${achFormatValue(item, item.target)}${remaining > 0 ? ` · faltam ${achFormatValue(item, remaining)}` : ""}</span>`}
      ${open ? `<span class="ach-badge__desc">${escapeHtml(item.desc)}</span>` : ""}
    </span>
  </button>`;
}

// ---- Cartão do dashboard: nível, barra de XP e o que vem a seguir ----
function renderGamificationCard(m) {
  if (!(state.data.achievements && state.data.achievements.enabled)) return "";
  const lvl = m.level;
  const next = m.nextUp[0];
  return `<div class="card span-1 card--level">
    <div class="settings-row-header">
      <p class="card-title">Seu nível</p>
      <button class="link-btn" data-action="nav" data-tab="achievements">Ver conquistas ${svgIcon("chevronRight", 13)}</button>
    </div>
    <div class="level-head">
      ${renderLevelRing(lvl, 84)}
      <div class="level-head__text">
        <p class="level-name" data-ui-css="color:${lvl.color}">${escapeHtml(lvl.name)}</p>
        <p class="level-sub">${m.unlockedCount} de ${m.total} conquistas · ${fmtNum(m.xp)} XP</p>
        ${lvl.isMax
          ? `<p class="level-next">${svgIcon("star", 12)} Nível máximo alcançado.</p>`
          : `<p class="level-next">Faltam <b>${fmtNum(lvl.toNext)} XP</b> para <b>${escapeHtml(lvl.next.name)}</b></p>`}
      </div>
    </div>
    <div class="level-bar"><span class="level-bar__fill" data-ui-css="width:${Math.round(lvl.progress * 100)}%;background:${lvl.color}"></span></div>
    ${m.streak.saving >= 2
      ? `<p class="level-streak">${svgIcon("bolt", 13)} <b>${m.streak.saving} meses seguidos</b> economizando. Não quebre a sequência.</p>`
      : m.streak.active >= 2
        ? `<p class="level-streak">${svgIcon("refresh", 13)} <b>${m.streak.active} meses seguidos</b> registrando seus lançamentos.</p>`
        : ""}
    ${next ? `<div class="level-next-goal">
      <p class="level-next-goal__label">Próxima conquista</p>
      ${renderAchievementBadge(next, true)}
    </div>` : ""}
  </div>`;
}

// ---- Overlay de celebração ----
// Aparece UMA vez, no momento do desbloqueio, e não bloqueia nada: qualquer
// clique fecha. Comemoração que atrapalha vira interrupção.
function renderCelebrationOverlay() {
  if (!(state.data.achievements && state.data.achievements.enabled)) return "";
  const list = state.gamification.celebrating;
  if (!list || list.length === 0) return "";
  const first = list[0];
  return `<div class="celebrate-overlay" data-action="dismiss-celebration" role="dialog" aria-modal="true" aria-label="Nova conquista">
    <div class="celebrate-card" data-stop-close="1">
      <div class="celebrate-rays" aria-hidden="true"></div>
      <span class="celebrate-medal" data-ui-css="--ach-color:${first.tierMeta.color}">${svgIcon(first.icon, 34)}</span>
      <p class="celebrate-kicker">${list.length > 1 ? `${list.length} novas conquistas` : "Conquista desbloqueada"}</p>
      <p class="celebrate-title">${escapeHtml(first.name)}</p>
      <p class="celebrate-desc">${escapeHtml(first.desc)}</p>
      <p class="celebrate-xp">+${fmtNum(list.reduce((sum, i) => sum + i.xp, 0))} XP</p>
      ${list.length > 1 ? `<p class="celebrate-more">${list.slice(1).map((i) => escapeHtml(i.name)).join(" · ")}</p>` : ""}
      <div class="celebrate-actions">
        <button class="btn btn--primary btn--block" data-action="dismiss-celebration">Continuar</button>
        <button class="btn btn--block" data-action="celebration-see-all">Ver todas as conquistas</button>
      </div>
    </div>
  </div>`;
}

// ---- Tela completa ----
const ACH_FILTERS = [
  { id: "all", label: "Todas" },
  { id: "locked", label: "Em andamento" },
  { id: "unlocked", label: "Conquistadas" },
];

function renderAchievementsScreen() {
  if (!(state.data.achievements && state.data.achievements.enabled)) {
    return `<div class="screen screen--narrow">
      ${renderBackHeader("Conquistas")}
      <div class="card card--starter">
        <span class="starter-mark" aria-hidden="true">${svgIcon("star", 20)}</span>
        <div class="starter-copy">
          <p class="card-title">Conquistas estão desligadas</p>
          <p class="card-subtitle">Seu organizador funciona por completo sem níveis, XP ou celebrações. Ative apenas se esse tipo de acompanhamento ajudar você.</p>
        </div>
        <button class="btn btn--primary btn--block" data-action="toggle-gamification">Ativar conquistas</button>
      </div>
    </div>`;
  }
  const m = achievementsModel();
  const filter = state.gamification.filter;
  const groups = m.byGroup
    .map((g) => ({
      ...g,
      visible: g.items.filter((i) =>
        filter === "all" ? true : filter === "unlocked" ? i.done : filter === "locked" ? !i.done : g.id === filter),
    }))
    .filter((g) => g.visible.length > 0);

  return `<div class="screen">
    ${renderBackHeader("Conquistas")}
    <div class="grid-dashboard">
      ${renderAchievementsHero(m)}
      ${m.nextUp.length > 0 ? `<div class="card span-2">
        <p class="card-title">O que vem a seguir</p>
        <p class="card-subtitle">As três conquistas mais próximas de fechar.</p>
        <div class="ach-grid">${m.nextUp.map((i) => renderAchievementBadge(i)).join("")}</div>
      </div>` : ""}
      ${m.recent.length > 0 ? `<div class="card span-1">
        <p class="card-title">Conquistas recentes</p>
        <div class="ach-recent">
          ${m.recent.map((i) => `<div class="ach-recent__row">
            <span class="ach-recent__medal" data-ui-css="--ach-color:${i.tierMeta.color}">${svgIcon(i.icon, 15)}</span>
            <div class="ach-recent__text"><b>${escapeHtml(i.name)}</b><span>${fmtDateFull(i.unlockedAt)}</span></div>
            <span class="ach-xp">+${i.xp}</span>
          </div>`).join("")}
        </div>
      </div>` : ""}

      <div class="card span-3">
        <div class="settings-row-header">
          <p class="card-title">Todas as conquistas</p>
          <span class="card-subtitle" data-ui-css="margin:0">${m.unlockedCount}/${m.total}</span>
        </div>
        <div class="ach-filters" role="tablist" aria-label="Filtrar conquistas">
          ${ACH_FILTERS.map((f) => `<button class="ach-filter-chip ${filter === f.id ? "active" : ""}" role="tab" aria-selected="${filter === f.id}" data-action="ach-filter" data-value="${f.id}">${f.label}</button>`).join("")}
          ${m.byGroup.map((g) => `<button class="ach-filter-chip ${filter === g.id ? "active" : ""}" role="tab" aria-selected="${filter === g.id}" data-action="ach-filter" data-value="${g.id}">${svgIcon(g.icon, 12)}${g.label}</button>`).join("")}
        </div>
        ${groups.length === 0
          ? renderEmptyState("target", "Nada por aqui ainda.", "Troque o filtro para ver as outras conquistas.")
          : groups.map((g) => `
            <div class="ach-group">
              <div class="ach-group__head">
                <span class="ach-group__icon">${svgIcon(g.icon, 15)}</span>
                <div class="ach-group__text">
                  <b>${g.label}</b>
                  <span>${g.desc}</span>
                </div>
                <span class="ach-group__count">${g.unlocked}/${g.total}</span>
              </div>
              <div class="ach-grid">${g.visible.map((i) => renderAchievementBadge(i)).join("")}</div>
            </div>`).join("")}
      </div>
    </div>
  </div>`;
}

function renderAchievementsHero(m) {
  const lvl = m.level;
  const tierCounts = ["bronze", "prata", "ouro", "platina"].map((t) => ({
    ...ACH_TIERS[t],
    count: m.items.filter((i) => i.tier === t && i.done).length,
    total: m.items.filter((i) => i.tier === t).length,
  }));
  return `<div class="card card--hero span-3 level-hero">
    <div class="hero-glow"></div>
    <div class="level-hero__main">
      ${renderLevelRing(lvl, 104, true)}
      <div class="level-hero__text">
        <p class="hero-label">Nível ${lvl.level}</p>
        <p class="level-hero__name">${escapeHtml(lvl.name)}</p>
        <p class="level-hero__sub">${fmtNum(m.xp)} XP acumulados · ${m.unlockedCount} de ${m.total} conquistas (${m.completionPct}%)</p>
        <div class="level-bar level-bar--lg level-bar--on-dark"><span class="level-bar__fill" data-ui-css="width:${Math.round(lvl.progress * 100)}%"></span></div>
        <p class="level-hero__next">${lvl.isMax
          ? "Você chegou ao topo. Agora é manter."
          : `Faltam <b>${fmtNum(lvl.toNext)} XP</b> para <b>${escapeHtml(lvl.next.name)}</b>`}</p>
      </div>
    </div>
    <div class="level-hero__chips">
      ${tierCounts.map((t) => `<div class="level-tier-chip"><span class="level-tier-dot" data-ui-css="background:${t.color}"></span><b>${t.count}/${t.total}</b><span>${t.label}</span></div>`).join("")}
      <div class="level-tier-chip"><span class="level-tier-dot" data-ui-css="background:var(--brand)"></span><b>${m.streak.saving}</b><span>meses economizando</span></div>
      <div class="level-tier-chip"><span class="level-tier-dot" data-ui-css="background:var(--goal)"></span><b>${m.streak.active}</b><span>meses seguidos ativos</span></div>
    </div>
  </div>`;
}

// source: js/screens/import.js
// js/screens/import.js. Importação de extrato e fatura (OFX/CSV/PDF).
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// IMPORTADOR DE EXTRATOS E FATURAS (OFX/CSV/PDF)
// ==================================================================
function renderImportScreen() {
  const rows = state.importRows;
  return `<div class="screen screen--narrow">
    ${renderBackHeader("Importar extrato")}

    ${!rows ? `
      <div class="card">
        <p class="card-subtitle" data-ui-css="margin-top:0">Baixe o extrato ou a fatura no app do seu banco e solte aqui. Aceita OFX, CSV e PDF com texto selecionável. A leitura e a categorização acontecem no seu aparelho; nada é enviado para nenhum servidor.</p>
        ${state.importError ? `<div class="inline-error">
          ${svgIcon("alertTriangle", 16)}
          <div>
            <p class="inline-error__title">${escapeHtml(state.importError.title)}</p>
            ${state.importError.detail ? `<p class="inline-error__detail">${escapeHtml(state.importError.detail)}</p>` : ""}
          </div>
          <button class="icon-btn icon-btn--muted" data-action="dismiss-import-error" aria-label="Fechar erro de importação">${svgIcon("x", 14)}</button>
        </div>` : ""}
        ${state.importError && (state.importError.code === "PDF_PASSWORD_REQUIRED" || state.importError.code === "PDF_PASSWORD_INCORRECT") && state.importPendingFile ? `
        <div class="import-password">
          <div class="field">
            <label class="field__label" for="import-pdf-password">Senha do PDF</label>
            <input id="import-pdf-password" class="input" type="password" autocomplete="off" data-field="import-password" value="${escapeHtml(state.importPassword || "")}" />
          </div>
          <button class="btn btn--primary" data-action="import-password-retry">Abrir PDF</button>
        </div>` : ""}
        ${state.importLoading ? `<div class="ai-loading"><span class="spinner"></span> Lendo e categorizando o extrato…</div>` : `
        <label class="dropzone ${state.importDragOver ? "dropzone--over" : ""}" id="statement-dropzone" data-action="statement-dropzone-click">
          ${svgIcon("file", 30)}
          <span class="dropzone__title">Arraste o arquivo aqui</span>
          <span class="dropzone__subtitle">ou toque para escolher (.ofx, .csv, .pdf)</span>
        </label>`}
      </div>` : renderImportReview(rows)}
  </div>`;
}

function renderImportReviewRow(row, idx, context) {
  const transfer = row.importAs === "transfer";
  const otherAccounts = context.activeAccounts.filter((account) => account.id !== context.destinationId);
  const otherIsValid = otherAccounts.some((account) => account.id === row.otherAccountId);
  const transferError = transfer && !otherIsValid;
  const recordedTag = row.recordedTransferStatus === "unique"
    ? `<span class="import-role-tag">transferência já registrada</span>`
    : (row.recordedTransferStatus === "ambiguous" ? `<span class="import-dup-tag">transferência semelhante</span>` : "");
  const reason = row.recordedTransferStatus === "unique"
    ? "A outra conta já registrou esta transferência. Marque a linha apenas se for outro movimento."
    : (row.roleDetail || row.categoryReason || "");
  const typeLabel = transfer ? "Transferência" : (row.nature === "estorno" ? "Estorno" : (row.type === "income" ? "Receita" : "Gasto"));

  return `<div class="import-row ${!row.include ? "import-row--off" : ""} ${transfer ? "import-row--transfer" : ""}">
    <button class="checkbox ${row.include ? "checked" : ""}" data-action="import-toggle" data-id="${idx}" aria-label="${row.include ? "Não importar" : "Importar"} ${escapeHtml(row.description || "movimento")}">${row.include ? svgIcon("check", 13) : ""}</button>
    <div class="import-row__info">
      <p class="import-row__desc">${escapeHtml(row.description || (row.type === "income" ? "Receita" : "Gasto"))} ${row.duplicate ? `<span class="import-dup-tag">possível duplicata</span>` : ""}${row.roleLabel ? `<span class="import-role-tag">${escapeHtml(row.roleLabel)}</span>` : ""}${recordedTag}</p>
      <p class="import-row__meta">${fmtDateShort(row.date)} · ${typeLabel}${row.page ? ` · página ${row.page}` : ""}${reason ? ` · ${escapeHtml(reason)}` : ""}</p>
    </div>
    <span class="import-row__amount ${!transfer && row.type === "income" ? "tx-amount--income" : ""}">${row.type === "income" ? "+" : "-"}${fmtBRL(row.amount)}</span>
    <div class="import-row__controls">
      ${context.canTransfer ? `<select class="import-kind-select" data-action-select="import-record-type" data-id="${idx}" aria-label="Como registrar ${escapeHtml(row.description || "este movimento")}">
        <option value="transaction" ${transfer ? "" : "selected"}>${row.type === "income" ? "Entrada" : "Saída"}</option>
        <option value="transfer" ${transfer ? "selected" : ""}>Transferência entre minhas contas</option>
      </select>` : ""}
      ${transfer ? `<select class="import-transfer-select ${transferError ? "input--error" : ""}" data-action-select="import-transfer-account" data-id="${idx}" aria-label="Outra conta da transferência">
        <option value="">Escolha a outra conta</option>
        ${otherAccounts.map((account) => `<option value="${account.id}" ${account.id === row.otherAccountId ? "selected" : ""}>${escapeHtml(account.name)}</option>`).join("")}
      </select>` : (row.type === "expense" ? `<select class="import-cat-select" data-action-select="import-category" data-id="${idx}" aria-label="Categoria de ${escapeHtml(row.description || "gasto")}">
        ${state.data.categories.map((category) => `<option value="${category.id}" ${category.id === row.categoryId ? "selected" : ""}>${escapeHtml(category.name)}</option>`).join("")}
      </select>` : "")}
    </div>
    ${transferError ? `<p class="import-row__error">Escolha a outra conta para registrar a transferência.</p>` : ""}
  </div>`;
}

function renderImportReview(rows) {
  const included = rows.filter((row) => row.include);
  const includedTransfers = included.filter((row) => row.importAs === "transfer");
  const includedTransactions = included.filter((row) => row.importAs !== "transfer");
  const meta = rows.meta || {};
  const documentKind = state.importDocumentKind === "card" ? "card" : "account";
  const activeAccounts = (state.data.accounts || []).filter((account) => !account.archived);
  const destinations = documentKind === "card"
    ? (state.data.creditCards || []).filter((card) => !card.archived)
    : activeAccounts;
  const destinationId = destinations.some((item) => item.id === state.importDestinationId)
    ? state.importDestinationId
    : (destinations[0] ? destinations[0].id : "");
  const canTransfer = documentKind === "account" && activeAccounts.length > 1;

  // Transferência fica num terceiro balde. Misturá-la com saída ou entrada
  // faria a própria revisão prometer um gasto ou uma renda que não será criada.
  const totalEntradas = sumMoney(includedTransactions.filter((row) => row.type === "income"), (row) => row.amount);
  const totalSaidas = sumMoney(includedTransactions.filter((row) => row.type !== "income"), (row) => row.amount);
  const totalTransferencias = sumMoney(includedTransfers, (row) => row.amount);
  const partesTotal = [];
  if (totalEntradas > 0) partesTotal.push(`${fmtBRL(totalEntradas)} em entradas`);
  if (totalSaidas > 0) partesTotal.push(`${fmtBRL(totalSaidas)} em saídas`);
  if (totalTransferencias > 0) partesTotal.push(`${fmtBRL(totalTransferencias)} em transferências`);

  const contaDestino = documentKind === "account" ? accountById(state.data, destinationId) : null;
  const aberturaConta = contaDestino ? String(contaDestino.openingDate || "") : "";
  const anterioresAoSaldo = aberturaConta
    ? includedTransactions.filter((row) => String(row.date || "") < aberturaConta).length
    : 0;
  const transferenciasAntesDaAbertura = includedTransfers.filter((row) => {
    const other = accountById(state.data, row.otherAccountId);
    return (aberturaConta && String(row.date || "") < aberturaConta)
      || (other && other.openingDate && String(row.date || "") < other.openingDate);
  }).length;

  const papeis = meta.roles || {};
  const avisoPapeis = [];
  if (papeis["card-payment"]) {
    avisoPapeis.push(`${plural(papeis["card-payment"], "linha é o pagamento da própria fatura", "linhas são pagamentos da própria fatura")} e ${papeis["card-payment"] === 1 ? "veio desmarcada" : "vieram desmarcadas"}: esse dinheiro saiu da sua conta para quitar o mês passado, então lançá-lo como receita inflaria o que você recebeu`);
  }
  if (papeis.carryover) avisoPapeis.push(`${plural(papeis.carryover, "linha é o saldo da fatura anterior", "linhas são saldo da fatura anterior")}: aquele gasto já foi contado no mês em que aconteceu`);

  const documentLabel = documentKind === "card" ? "Fatura de cartão" : "Extrato bancário";
  const sourceParts = [meta.format ? meta.format.toUpperCase() : "ARQUIVO"];
  if (meta.bank) sourceParts.push(meta.bank);
  sourceParts.push(documentLabel);
  if (meta.pageCount) sourceParts.push(plural(meta.pageCount, "página", "páginas"));
  const invalidTransfer = includedTransfers.some((row) => !activeAccounts.some((account) => account.id === row.otherAccountId && account.id !== destinationId));
  const buttonParts = [];
  if (includedTransactions.length) buttonParts.push(plural(includedTransactions.length, "lançamento", "lançamentos"));
  if (includedTransfers.length) buttonParts.push(plural(includedTransfers.length, "transferência", "transferências"));

  return `<div class="card">
    <div class="settings-row-header">
      <p class="card-title">Revisar lançamentos (${rows.length})</p>
      <button class="icon-btn" data-action="import-cancel" aria-label="Cancelar importação">${svgIcon("x", 16)}</button>
    </div>
    <p class="card-subtitle">${sourceParts.map(escapeHtml).join(" · ")} · ${plural(included.length, "selecionado para importar", "selecionados para importar")}${partesTotal.length ? ` · ${partesTotal.join(" e ")}` : ""}. Duplicados e transferências já registradas vêm desmarcados${meta.skipped ? ` · ${plural(meta.skipped, "linha ignorada", "linhas ignoradas")}` : ""}.</p>
    <div class="import-destination-grid">
      <div class="field">
        <label class="field__label" for="import-document-kind">O que este arquivo contém</label>
        <select id="import-document-kind" class="input" data-action-select="import-document-kind">
          <option value="account" ${documentKind === "account" ? "selected" : ""}>Extrato bancário</option>
          <option value="card" ${documentKind === "card" ? "selected" : ""}>Fatura de cartão</option>
        </select>
      </div>
      <div class="field">
        <label class="field__label" for="import-destination">${documentKind === "card" ? "Cartão da fatura" : "Conta do extrato"}</label>
        <select id="import-destination" class="input" data-action-select="import-destination" ${destinations.length ? "" : "disabled"}>
          ${destinations.length
            ? destinations.map((item) => `<option value="${item.id}" ${item.id === destinationId ? "selected" : ""}>${escapeHtml(item.name)}</option>`).join("")
            : `<option value="">${documentKind === "card" ? "Nenhum cartão cadastrado" : "Nenhuma conta cadastrada"}</option>`}
        </select>
      </div>
    </div>
    ${!destinations.length ? `<div class="inline-error import-destination-error">${svgIcon("alertTriangle", 16)}<div><p class="inline-error__title">Cadastre ${documentKind === "card" ? "um cartão" : "uma conta"} antes de importar.</p><p class="inline-error__detail">O destino é obrigatório para manter saldos e faturas corretos.</p></div><button class="btn btn--secondary btn--sm" data-action="nav" data-tab="accounts">Cadastrar</button></div>` : ""}
    ${documentKind === "account" && activeAccounts.length === 1 ? `<div class="import-notice">${svgIcon("info", 16)}<div><b>Cadastre outra conta para identificar Pix entre suas contas.</b><span>Com duas contas ativas, cada linha pode ser registrada como transferência e movimentar os dois saldos.</span></div></div>` : ""}
    ${meta.confidence === "baixa" ? `<div class="import-notice">${svgIcon("alertTriangle", 16)}<div><b>Confira o tipo e os valores com atenção.</b><span>O banco ou o formato da tabela não foi reconhecido com segurança. Nada será gravado antes de você confirmar.</span></div></div>` : ""}
    ${avisoPapeis.length ? `<div class="import-notice">${svgIcon("creditCard", 16)}<div><b>Isto parece a fatura de um cartão.</b><span>${escapeHtml(avisoPapeis.join(". "))}. As compras continuam marcadas normalmente; se você quiser importar alguma dessas linhas mesmo assim, é só marcar a caixa.</span></div></div>` : ""}
    ${anterioresAoSaldo ? `<div class="import-notice">${svgIcon("info", 16)}<div><b>${anterioresAoSaldo} ${anterioresAoSaldo === 1 ? "lançamento é anterior" : "lançamentos são anteriores"} à abertura de ${escapeHtml(contaDestino.name)} em ${fmtDateFull(aberturaConta)}.</b><span>${anterioresAoSaldo === 1 ? "Ele entra" : "Eles entram"} nas despesas, categorias e gráficos, mas não ${anterioresAoSaldo === 1 ? "altera" : "alteram"} o saldo da conta: o saldo inicial que você informou já inclui esse período. Para que ${anterioresAoSaldo === 1 ? "ele conte" : "eles contem"} no saldo, edite a conta e recue a data de abertura.</span></div></div>` : ""}
    ${transferenciasAntesDaAbertura ? `<div class="import-notice">${svgIcon("info", 16)}<div><b>${transferenciasAntesDaAbertura === 1 ? "Uma transferência está" : `${transferenciasAntesDaAbertura} transferências estão`} fora do período acompanhado por uma das contas.</b><span>O saldo inicial dessa conta já inclui o movimento, então somente a ponta dentro do período será recalculada.</span></div></div>` : ""}
    <div class="import-list">
      ${rows.map((row, idx) => renderImportReviewRow(row, idx, { activeAccounts, destinationId, canTransfer })).join("")}
    </div>
    <button class="btn btn--primary btn--block" data-ui-css="margin-top:14px" data-action="import-confirm" ${included.length === 0 || !destinationId || invalidTransfer ? "disabled" : ""}>Importar ${buttonParts.join(" e ")}</button>
    <button class="btn btn--ghost btn--block btn--sm" data-ui-css="margin-top:8px" data-action="nav" data-tab="rules">${svgIcon("tag", 14)} Corrigindo a mesma categoria várias vezes? Crie uma regra</button>
  </div>`;
}

// source: js/screens/all.js
// js/screens/all.js. "Recursos": o índice do app.
// ------------------------------------------------------------------------------
// A lista de ferramentas morava dentro de um cartão de Ajustes, e isso tinha
// duas consequências: quem procurava a Central de Dívidas precisava adivinhar
// que ela estava em "Ajustes", e a tela de Ajustes ficou com quinze destinos
// espremidos entre campos de configuração.
//
// Aqui os mesmos destinos ganham tela própria, agrupada por intenção e com
// busca. A busca não é enfeite: com vinte e dois recursos, rolar procurando um
// nome é mais lento do que digitar três letras.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// `keywords` existe porque o usuário procura pelo problema, não pelo nome do
// recurso: quem digita "fatura" quer Contas e cartões, quem digita "juros" quer
// os simuladores. Sem isso a busca só encontraria o que a pessoa já sabia achar.
const ALL_SECTIONS = [
  {
    title: "Dia a dia",
    subtitle: "O que você abre com mais frequência.",
    items: [
      { tab: "add", icon: "plus", label: "Novo lançamento", desc: "Registrar um gasto ou uma receita.", keywords: "adicionar gasto receita despesa lancar" },
      { tab: "import", icon: "upload", label: "Importar extrato", desc: "Ler um arquivo OFX ou CSV do seu banco.", keywords: "ofx csv extrato banco importar arquivo" },
      { action: "open-qr", icon: "scan", label: "Ler QR Code", desc: "Pix ou nota fiscal, direto pela câmera.", keywords: "qr pix nota fiscal camera codigo" },
      { tab: "calendar", icon: "calendar", label: "Calendário e previsão", desc: "O que vence, quando, e para onde o saldo caminha.", keywords: "calendario previsao vencimento agenda planejamento anual" },
      { tab: "subscriptions", icon: "refresh", label: "Assinaturas e recorrências", desc: "Cobranças que se repetem todo mês.", keywords: "assinatura recorrente mensalidade streaming" },
      { tab: "notifications", icon: "bell", label: "Central de notificações", desc: "Histórico de avisos do app.", keywords: "avisos alertas notificacao sino" },
    ],
  },
  {
    title: "Contas e dívidas",
    subtitle: "Onde o dinheiro está e o que ele deve.",
    items: [
      { tab: "accounts", icon: "wallet", label: "Contas, cartões e faturas", desc: "Saldos, limites, transferências e conciliação.", keywords: "conta cartao fatura banco saldo transferencia conciliacao limite" },
      { tab: "debts", icon: "alertTriangle", label: "Central de dívidas", desc: "Plano de quitação por bola de neve ou avalanche.", keywords: "divida emprestimo financiamento quitar bola de neve avalanche juros" },
      { tab: "wealth", icon: "layout", label: "Patrimônio", desc: "Bens, dívidas e a evolução do seu líquido.", keywords: "patrimonio bens ativos passivos liquido imovel carro" },
    ],
  },
  {
    title: "Planejar e simular",
    subtitle: "Decidir antes de gastar.",
    items: [
      { tab: "goals", icon: "target", label: "Metas", desc: "Objetivos, aportes e prazo.", keywords: "meta objetivo reserva emergencia guardar sonho" },
      { tab: "invest", icon: "trendUp", label: "Carteira de investimentos", desc: "Aplicações, rentabilidade e proventos.", keywords: "investir carteira acoes cdb tesouro rendimento dividendo" },
      { tab: "simulators", icon: "bolt", label: "Simuladores", desc: "Renda fixa, financiamento, cartão, FGTS e mais.", keywords: "simulador juros financiamento fgts parcelamento cdb selic" },
      { tab: "simulate", icon: "sparkles", label: "Simulador “E se…?”", desc: "O impacto de um gasto antes de fazê-lo.", keywords: "e se simular gasto impacto comparar cenario" },
    ],
  },
  {
    title: "Entender os números",
    subtitle: "O que os lançamentos estão dizendo.",
    items: [
      { tab: "analytics", icon: "pie", label: "Análises e histórico", desc: "Períodos, categorias e busca no histórico.", keywords: "analise historico grafico relatorio periodo buscar filtro" },
      { tab: "insights", icon: "sparkles", label: "Central inteligente", desc: "Recomendações, padrões e comparação entre meses.", keywords: "insight recomendacao ia padrao comparar inteligente" },
      { tab: "health", icon: "shieldCheck", label: "Saúde financeira", desc: "Diagnóstico completo com os indicadores explicados.", keywords: "saude diagnostico score indicador nota" },
      { tab: "achievements", icon: "star", label: "Conquistas e nível", desc: "As medalhas que o seu histórico já desbloqueou.", keywords: "conquista medalha nivel gamificacao progresso" },
    ],
  },
  {
    title: "Ajustar o app",
    subtitle: "Como ele calcula e como ele se comporta.",
    items: [
      { tab: "account", icon: "shieldCheck", label: "Conta e acesso", desc: "Cadastro, recuperação de senha e dispositivos conectados.", keywords: "conta login senha recuperar acesso dispositivo sessao" },
      { tab: "categories", icon: "layout", label: "Categorias e tetos", desc: "Hierarquia, grupos da Regra x/x/x e limites por categoria.", keywords: "categoria subcategoria teto limite orcamento grupo necessidade desejo futuro organizar" },
      { tab: "rules", icon: "tag", label: "Regras de categorização", desc: "Ensine o app a classificar sozinho o que vem do banco.", keywords: "regra categorizar importar automatico palavra chave" },
      { tab: "settings", icon: "gear", label: "Ajustes", desc: "Perfil, renda, reserva, alertas, tema e backup.", keywords: "ajustes configuracao perfil renda backup tema reserva alerta premissa" },
      { tab: "privacy", icon: "shieldCheck", label: "Privacidade, termos e fontes", desc: "Controle de dados, IA, exclusão e diagnóstico local.", keywords: "privacidade lgpd termos dados excluir apagar ia diagnostico fontes" },
    ],
  },
];

function allScreenMatches(item, query) {
  if (!query) return true;
  const haystack = normalizeText(`${item.label} ${item.desc} ${item.keywords || ""}`);
  // Todos os termos precisam casar. Buscar "conta cartao" deve estreitar o
  // resultado, não ampliá-lo; o contrário transformaria a busca em ruído.
  return normalizeText(query).split(" ").filter(Boolean).every((term) => haystack.indexOf(term) !== -1);
}

function renderAllScreen() {
  const query = state.allSearch || "";
  const sections = ALL_SECTIONS
    .map((sec) => ({ ...sec, items: sec.items.filter((it) => allScreenMatches(it, query)) }))
    .filter((sec) => sec.items.length > 0);
  const total = sections.reduce((n, sec) => n + sec.items.length, 0);

  return `<div class="screen screen--narrow">
    <div class="screen-header">
      <div class="back-header">
        <button class="icon-btn" data-action="back" data-tab="dashboard" aria-label="Voltar">${svgIcon("chevronLeft", 19)}</button>
        <h1 class="page-title">Recursos</h1>
      </div>
    </div>

    <div class="card">
      <div class="all-search">
        ${svgIcon("search", 17, "all-search__icon")}
        <input id="all-search-input" class="input" data-field="all-search" value="${escapeHtml(query)}"
          placeholder="Buscar recurso (ex: fatura, juros, meta)" autocomplete="off" />
        ${query ? `<button class="icon-btn icon-btn--muted" data-action="all-search-clear" aria-label="Limpar busca">${svgIcon("x", 15)}</button>` : ""}
      </div>
      ${query ? `<p class="field-hint" data-ui-css="margin-top:8px">${plural(total, "resultado", "resultados")} para “${escapeHtml(query)}”.</p>` : ""}
    </div>

    ${total === 0 ? `<div class="card">
      ${renderEmptyState("search", "Nada encontrado.", "Tente uma palavra mais curta, como “cartão”, “meta” ou “juros”.")}
    </div>` : sections.map((sec) => `<div class="card">
      <p class="card-title">${escapeHtml(sec.title)}</p>
      <p class="card-subtitle" data-ui-css="margin-top:0">${escapeHtml(sec.subtitle)}</p>
      <div class="tool-links">
        ${sec.items.map((it) => `<button class="tool-link tool-link--rich" ${it.tab ? `data-action="nav" data-tab="${it.tab}"` : `data-action="${it.action}"`}>
          <span class="tool-link__icon">${svgIcon(it.icon, 17)}</span>
          <span class="tool-link__text">
            <span class="tool-link__label">${escapeHtml(it.label)}</span>
            <span class="tool-link__desc">${escapeHtml(it.desc)}</span>
          </span>
          ${svgIcon("chevronRight", 15, "tool-link__chevron")}
        </button>`).join("")}
      </div>
    </div>`).join("")}

    <p class="footnote">Recursos marcados como IA precisam de conexão e enviam somente os dados descritos antes da confirmação. Todo o resto funciona sem internet.</p>
  </div>`;
}

// source: js/screens/rules.js
// js/screens/rules.js. Regras de categorização: as do usuário e as de fábrica.
// ------------------------------------------------------------------------------
// O motor está em `js/rules.js` e não sabe que esta tela existe. Aqui só há HTML.
//
// A ordem dos cartões segue o caminho de quem chega com um problema concreto
// ("o app insiste em jogar meu posto de gasolina em Outros"): primeiro o
// laboratório onde ele cola a descrição e vê o que acontece, depois as regras
// dele, depois o botão que conserta o histórico, e só no fim as regras de
// fábrica; que a maioria nunca vai precisar abrir.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

function rulesCategoryOptions(selectedId) {
  return topLevelCategories(state.data).map((c) => {
    const subs = childCategories(state.data, c.id);
    const own = `<option value="${c.id}" ${selectedId === c.id ? "selected" : ""}>${escapeHtml(c.name)}</option>`;
    const kids = subs.map((sub) => `<option value="${sub.id}" ${selectedId === sub.id ? "selected" : ""}>${escapeHtml(c.name)} › ${escapeHtml(sub.name)}</option>`).join("");
    return own + kids;
  }).join("");
}

function renderRulesScreen() {
  const cfg = normalizeCategoryRules(state.data.categoryRules);
  return `<div class="screen screen--narrow">
    ${renderBackHeader("Regras de categorização")}

    <div class="card">
      <p class="card-subtitle" data-ui-css="margin-top:0">Quando um lançamento chega de um extrato, de um QR Code ou do campo de texto livre, o app tenta adivinhar a categoria pela descrição. Aqui você ensina o que ele ainda não sabe. Tudo é calculado no seu aparelho.</p>
      <p class="field-hint">Em caso de empate, vence a regra de maior peso; entre pesos iguais, a sua regra ganha da regra de fábrica.</p>
    </div>

    ${renderRuleTesterCard()}
    ${renderCustomRulesCard(cfg)}
    ${renderRuleApplyCard()}
    ${renderBuiltinRulesCard(cfg)}
  </div>`;
}

// ---- Laboratório: cole uma descrição, veja quem ganha ----
// Existe porque regra de texto é a classe de configuração em que o usuário mais
// erra em silêncio: ele escreve "posto ipiranga", o extrato diz "POSTO IPIRANGA
// LTDA 04", e sem um lugar para testar ele só descobre no mês seguinte.
function renderRuleTesterCard() {
  const text = state.rules.testText || "";
  const compiled = compileCategoryRules(state.data);
  const best = text ? matchCategoryRules(compiled, normalizeText(text)) : null;
  const hits = text ? compiled.filter((r) => { try { return r.re.test(normalizeText(text)); } catch (e) { return false; } }) : [];
  const cat = best ? categoryById(state.data, best.categoryId) : null;

  return `<div class="card">
    <p class="card-title">Testar uma descrição</p>
    <p class="card-subtitle" data-ui-css="margin-top:0">Cole aqui um texto igual ao que aparece no seu extrato.</p>
    <input id="rule-test-input" class="input" data-field="rule-test" value="${escapeHtml(text)}"
      placeholder="Ex: PAG*PostoIpiranga 04" autocomplete="off" />

    ${!text ? "" : best ? `<div class="rule-test-result">
      <span class="icon-bubble icon-bubble--sm" data-ui-css="background:color-mix(in srgb, ${cat.color} 14%, transparent); color:${cat.color}">${svgIcon(cat.icon, 15)}</span>
      <div class="rule-test-result__text">
        <p class="rule-test-result__cat">${escapeHtml(cat.name)}</p>
        <p class="rule-test-result__rule">por ${best.source === "custom" ? "sua regra" : "regra de fábrica"} “${escapeHtml(best.label)}” · peso ${best.weight}</p>
      </div>
    </div>
    ${hits.length > 1 ? `<p class="field-hint">${hits.length} regras casaram com esse texto. As demais perderam no peso: ${hits.filter((r) => r !== best).map((r) => escapeHtml(r.label)).slice(0, 3).join(", ")}.</p>` : ""}` : `<div class="rule-test-result rule-test-result--miss">
      ${svgIcon("info", 16)}
      <div class="rule-test-result__text">
        <p class="rule-test-result__cat">Nenhuma regra casou</p>
        <p class="rule-test-result__rule">Esse lançamento cairia em “Outros”. Crie uma regra abaixo.</p>
      </div>
    </div>`}
  </div>`;
}

// ---- Regras do usuário ----
function renderCustomRulesCard(cfg) {
  const form = state.rules.form;
  return `<div class="card">
    <div class="settings-row-header">
      <div>
        <p class="card-title" data-ui-css="margin:0">Suas regras</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">${cfg.custom.length === 0 ? "Nenhuma regra criada ainda." : `${plural(cfg.custom.length, "regra", "regras")} · ${cfg.custom.filter((r) => r.enabled).length} ${pluralWord(cfg.custom.filter((r) => r.enabled).length, "ativa", "ativas")}`}</p>
      </div>
      ${form ? "" : `<button class="btn btn--primary btn--sm" data-action="rule-new">${svgIcon("plus", 15)} Nova</button>`}
    </div>

    ${form ? renderRuleForm(form) : ""}

    ${cfg.custom.length === 0 && !form
      ? renderEmptyState("tag", "Sem regras suas.", "Crie uma para que o app pare de errar na mesma descrição todo mês.")
      : `<div class="rule-list">${cfg.custom.map((r) => renderRuleRow(r)).join("")}</div>`}
  </div>`;
}

function renderRuleRow(r) {
  const cat = categoryById(state.data, r.categoryId);
  const type = RULE_MATCH_TYPES.find((m) => m.id === r.matchType) || RULE_MATCH_TYPES[0];
  const compiled = compileRulePattern(r.pattern, r.matchType);

  return `<div class="rule-row ${r.enabled ? "" : "rule-row--off"}">
    <span class="icon-bubble icon-bubble--sm" data-ui-css="background:color-mix(in srgb, ${cat.color} 14%, transparent); color:${cat.color}">${svgIcon(cat.icon, 15)}</span>
    <div class="rule-row__text">
      <p class="rule-row__pattern">${escapeHtml(r.pattern)}</p>
      <p class="rule-row__meta">${escapeHtml(type.label)} · ${escapeHtml(cat.name)} · peso ${r.weight}</p>
      ${compiled.ok ? "" : `<p class="rule-row__error">${svgIcon("alertTriangle", 12)} ${escapeHtml(compiled.error)}; a regra está sendo ignorada.</p>`}
    </div>
    <button class="switch ${r.enabled ? "active" : ""}" data-action="rule-toggle" data-id="${r.id}" role="switch" aria-checked="${r.enabled ? "true" : "false"}" aria-label="${r.enabled ? "Desativar" : "Ativar"} regra"><span class="switch__knob"></span></button>
    <button class="icon-btn" data-action="rule-edit" data-id="${r.id}" aria-label="Editar regra">${svgIcon("pencil", 14)}</button>
    <button class="icon-btn" data-action="rule-delete" data-id="${r.id}" aria-label="Excluir regra">${svgIcon("trash", 14)}</button>
  </div>`;
}

function renderRuleForm(form) {
  const compiled = compileRulePattern(form.pattern, form.matchType);
  const typeMeta = RULE_MATCH_TYPES.find((m) => m.id === form.matchType) || RULE_MATCH_TYPES[0];
  const canSave = compiled.ok && !!form.categoryId;

  return `<div class="rule-form">
    <div class="field">
      <label class="field__label" for="rule-pattern-input">Texto que a regra procura</label>
      <input id="rule-pattern-input" class="input" data-field="rule-pattern" value="${escapeHtml(form.pattern)}"
        placeholder="Ex: ipiranga" autocomplete="off" maxlength="120" />
      ${form.pattern && !compiled.ok ? `<p class="rule-row__error">${svgIcon("alertTriangle", 12)} ${escapeHtml(compiled.error)}</p>` : `<p class="field-hint">Acentos e maiúsculas não importam.</p>`}
    </div>

    <div class="field">
      <label class="field__label" for="rule-type-select">Como comparar</label>
      <select class="input" id="rule-type-select" data-action-select="rule-type">
        ${RULE_MATCH_TYPES.map((m) => `<option value="${m.id}" ${form.matchType === m.id ? "selected" : ""}>${escapeHtml(m.label)}</option>`).join("")}
      </select>
      <p class="field-hint">${escapeHtml(typeMeta.hint)}</p>
    </div>

    <div class="field">
      <label class="field__label" for="rule-category-select">Categoria de destino</label>
      <select class="input" id="rule-category-select" data-action-select="rule-category">
        <option value="">Escolha uma categoria</option>
        ${rulesCategoryOptions(form.categoryId)}
      </select>
    </div>

    <div class="field">
      <label class="field__label" for="rule-weight-input">Peso (${RULE_WEIGHT_MIN} a ${RULE_WEIGHT_MAX})</label>
      <input id="rule-weight-input" class="input input--budget" type="number" min="${RULE_WEIGHT_MIN}" max="${RULE_WEIGHT_MAX}" step="1"
        data-field="rule-weight" value="${escapeHtml(String(form.weight))}" inputmode="numeric" />
      <p class="field-hint">Só importa quando duas regras casam com a mesma descrição. O padrão (${RULE_WEIGHT_DEFAULT}) já ganha de todas as de fábrica.</p>
    </div>

    <div class="settings-actions">
      <button class="btn btn--ghost btn--sm" data-action="rule-cancel">Cancelar</button>
      <button class="btn btn--primary btn--sm" data-action="rule-save" ${canSave ? "" : "disabled"}>${svgIcon("check", 15)} ${form.id ? "Salvar regra" : "Criar regra"}</button>
    </div>
  </div>`;
}

// ---- Aplicar ao que já está gravado ----
// Só mexe em despesas que estão em "Outros". Recategorizar o histórico inteiro
// apagaria correções feitas à mão; e a pessoa que corrigiu à mão é exatamente
// a que mais confia no app.
function renderRuleApplyCard() {
  const preview = state.rules.applyPreview;
  return `<div class="card">
    <p class="card-title">Aplicar aos lançamentos antigos</p>
    <p class="card-subtitle" data-ui-css="margin-top:0">Passa as regras atuais pelas despesas que estão em “Outros”. Nada que você já categorizou à mão é tocado.</p>

    ${preview ? (preview.count === 0
      ? `<div class="inline-note">${svgIcon("checkCircle", 16)}<span>Nenhum lançamento em “Outros” casou com as regras atuais.</span></div>`
      : `<div class="inline-note">${svgIcon("info", 16)}<span><b>${preview.count}</b> ${pluralWord(preview.count, "lançamento mudaria", "lançamentos mudariam")} de categoria.</span></div>
         <div class="rule-preview-list">
           ${preview.changes.slice(0, 8).map((c) => `<div class="rule-preview-row">
             <span class="rule-preview-row__desc">${escapeHtml(c.description || "(sem descrição)")}</span>
             <span class="rule-preview-row__to">${svgIcon("arrowRight", 13)} ${escapeHtml(categoryById(state.data, c.to).name)}</span>
           </div>`).join("")}
           ${preview.count > 8 ? `<p class="footnote" data-ui-css="text-align:left">e mais ${preview.count - 8}.</p>` : ""}
         </div>`) : ""}

    <div class="settings-actions" data-ui-css="margin-top:12px">
      ${preview
        ? `<button class="btn btn--ghost btn--sm" data-action="rule-apply-cancel">Cancelar</button>
           ${preview.count > 0 ? `<button class="btn btn--primary btn--sm" data-action="rule-apply-confirm">${svgIcon("check", 15)} Recategorizar ${preview.count}</button>` : ""}`
        : `<button class="btn btn--secondary btn--sm" data-action="rule-apply-preview">${svgIcon("refresh", 15)} Ver o que mudaria</button>`}
    </div>
  </div>`;
}

// ---- Regras de fábrica ----
// Não são editáveis, e isso é deliberado: elas evoluem com o app, e uma cópia
// congelada no aparelho de cada usuário deixaria de receber correções. O que o
// usuário controla é se cada uma vale e para onde ela aponta.
function renderBuiltinRulesCard(cfg) {
  const open = state.rules.showBuiltins;
  const changed = Object.keys(cfg.builtin).length;

  return `<div class="card">
    <div class="settings-row-header">
      <div>
        <p class="card-title" data-ui-css="margin:0">Regras de fábrica</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">${BUILTIN_CATEGORY_RULES.length} dicionários prontos${changed > 0 ? ` · ${plural(changed, "alterado", "alterados")} por você` : ""}</p>
      </div>
      <button class="btn btn--ghost btn--sm" data-action="rules-toggle-builtins">
        ${open ? "Ocultar" : "Ver todas"} ${svgIcon(open ? "chevronUp" : "chevronDown", 14)}
      </button>
    </div>

    ${!open ? "" : `<div class="rule-list">
      ${BUILTIN_CATEGORY_RULES.map((rule) => {
        const o = cfg.builtin[rule.id] || {};
        const enabled = o.enabled !== false;
        const targetId = o.categoryId || rule.categoryId;
        const cat = categoryById(state.data, targetId);
        return `<div class="rule-row rule-row--builtin ${enabled ? "" : "rule-row--off"}">
          <span class="icon-bubble icon-bubble--sm" data-ui-css="background:color-mix(in srgb, ${cat.color} 14%, transparent); color:${cat.color}">${svgIcon(cat.icon, 15)}</span>
          <div class="rule-row__text">
            <p class="rule-row__pattern">${escapeHtml(rule.label)}</p>
            <p class="rule-row__meta">${escapeHtml(rule.sample)}</p>
          </div>
          <button class="switch ${enabled ? "active" : ""}" data-action="rule-builtin-toggle" data-id="${rule.id}" role="switch" aria-checked="${enabled ? "true" : "false"}" aria-label="${enabled ? "Desativar" : "Ativar"} ${escapeHtml(rule.label)}"><span class="switch__knob"></span></button>
          <select class="input rule-row__select" data-action-select="rule-builtin-category" data-id="${rule.id}" ${enabled ? "" : "disabled"}>
            ${rulesCategoryOptions(targetId)}
          </select>
        </div>`;
      }).join("")}
      ${changed > 0 ? `<button class="btn btn--ghost btn--sm btn--block" data-action="rules-builtin-reset" data-ui-css="margin-top:8px">${svgIcon("refresh", 15)} Restaurar ${plural(changed, "regra de fábrica alterada", "regras de fábrica alteradas")}</button>` : ""}
    </div>`}
  </div>`;
}

// source: js/screens/categories.js
// js/screens/categories.js. Central de categorias: estrutura, grupos e tetos.
// ------------------------------------------------------------------------------
// Categoria era um cartão espremido no fim de Ajustes: uma linha por categoria
// (ícone, nome, teto, dois botõezinhos e três chips de grupo) e, no rodapé, um
// formulário de criação com um <select> de "categoria pai". O resultado era
// previsível:
//
//   1. Criar subcategoria exigia entender o <select> ANTES de digitar o nome;
//      quem não mexia nele criava tudo solto na raiz.
//   2. Não havia como mudar o pai depois. Categoria criada no lugar errado
//      ficava errada para sempre, ou era apagada levando o histórico junto.
//   3. Os chips de grupo (Necessidade/Desejo/Futuro) repetiam em TODAS as
//      linhas e, ainda assim, não havia visão de conjunto: responder "o que eu
//      classifiquei como Desejo?" exigia varrer a lista inteira com o olho.
//
// Aqui os mesmos dados ganham três lentes; Estrutura (a hierarquia), Grupos (a
// Regra x/x/x) e Tetos (os limites do mês); mais um editor em folha que cria E
// edita, inclusive movendo uma categoria de pai.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

const CATEGORY_VIEWS = [
  { id: "tree", label: "Estrutura", icon: "layout" },
  { id: "groups", label: "Grupos", icon: "pie" },
  { id: "budgets", label: "Tetos", icon: "target" },
];

// Paleta do editor. As oito primeiras são as do app (usadas também pelos
// gráficos); as seis seguintes existem só para dar variedade a quem cria muitas
// categorias e não quer duas do mesmo tom lado a lado.
const CATEGORY_COLOR_CHOICES = PALETTE.concat(["#1F8A5F", "#2E6F7E", "#7A4E8C", "#A33B4C", "#6B7A2E", "#8C5A2B"]);

function freshCategoryEditor(patch) {
  return Object.assign({
    id: null,
    name: "",
    parentId: "",
    group: "necessidade",
    icon: "tag",
    color: PALETTE[0],
    budget: "",
    confirmDelete: false,
  }, patch || {});
}

// ------------------------------------------------------------------------------
// Modelo da tela. Puro: lê `state.data` e devolve o que as três lentes precisam,
// já com gasto do mês, teto e nível de alerta resolvidos por categoria.
// ------------------------------------------------------------------------------
function categoryStatOf(data, cat, monthKey, thresholds) {
  const spent = spentForCategory(data, cat.id, monthKey);
  const budget = typeof cat.budget === "number" && cat.budget > 0 ? cat.budget : null;
  const pct = budget ? safePct(spent, budget) : 0;
  const level = budget ? budgetLevelOf(pct, thresholds) : null;
  return {
    id: cat.id,
    name: cat.name,
    color: cat.color,
    icon: cat.icon,
    parentId: cat.parentId || null,
    group: categoryGroup(data, cat.id),
    spent, budget, pct, level,
    levelMeta: level ? BUDGET_LEVEL_META[level] : null,
  };
}

function categoriesModel() {
  const data = state.data;
  const monthKey = keyOfCurrentMonth();
  const thresholds = budgetThresholds(data, monthKey);
  const query = normalizeText(state.categoriesUi.search || "");
  const hits = (name) => !query || normalizeText(name).indexOf(query) !== -1;

  const nodes = topLevelCategories(data).map((parent) => {
    const stat = categoryStatOf(data, parent, monthKey, thresholds);
    const children = childCategories(data, parent.id).map((child) => categoryStatOf(data, child, monthKey, thresholds));
    const parentHit = hits(parent.name);
    const visibleChildren = children.filter((child) => parentHit || hits(child.name));
    // O gasto do pai já inclui o das filhas (é assim que o teto funciona); aqui
    // separamos o que foi lançado DIRETO nele, que é o número que explica uma
    // categoria-mãe com subcategorias.
    const childrenSpent = children.reduce((sum, child) => addMoney(sum, child.spent), 0);
    return Object.assign({}, stat, {
      children,
      visibleChildren,
      ownSpent: Math.max(0, subMoney(stat.spent, childrenSpent)),
      visible: parentHit || visibleChildren.length > 0,
    });
  });

  const flat = [];
  nodes.forEach((node) => {
    flat.push(Object.assign({}, node, { depth: 0, path: node.name }));
    node.children.forEach((child) => flat.push(Object.assign({}, child, { depth: 1, path: `${node.name} › ${child.name}` })));
  });

  const groupSpend = monthGroupSpend(data, monthKey);
  const byGroup = {};
  BUDGET_GROUPS.forEach((group) => {
    byGroup[group] = flat.filter((item) => item.group === group).sort((a, b) => b.spent - a.spent);
  });

  return {
    monthKey, thresholds, query, nodes, flat, byGroup, groupSpend,
    totals: {
      parents: nodes.length,
      children: flat.length - nodes.length,
      total: flat.length,
      withBudget: flat.filter((item) => item.budget).length,
      over: flat.filter((item) => item.level === "over").length,
      spent: nodes.reduce((sum, node) => addMoney(sum, node.spent), 0),
    },
  };
}

// Um nó fica aberto por padrão. Durante uma busca todos abrem: esconder o
// resultado atrás de um chevron seria o oposto de procurar.
function isCategoryNodeOpen(model, id) {
  if (model.query) return true;
  return (state.categoriesUi.collapsed || []).indexOf(id) === -1;
}

function categoryGroupTag(group) {
  return `<span class="cat-tag cat-tag--${group}">${svgIcon(GROUP_ICONS[group], 11)}${GROUP_LABELS[group]}</span>`;
}

function categoryBubbleCss(color, strength) {
  return `background:color-mix(in srgb, ${color} ${strength || 14}%, transparent); color:${color}`;
}

// ------------------------------------------------------------------------------
// Tela
// ------------------------------------------------------------------------------
function renderCategoriesScreen() {
  const ui = state.categoriesUi;
  const model = categoriesModel();
  const view = CATEGORY_VIEWS.some((v) => v.id === ui.view) ? ui.view : "tree";

  return `<div class="screen screen--narrow cat-hub">
    ${renderBackHeader("Categorias")}

    ${renderCategoriesOverviewCard(model)}

    <div class="card cat-toolbar">
      <div class="cat-toolbar__top">
        <div class="cat-search">
          ${svgIcon("search", 16, "cat-search__icon")}
          <input id="cat-search-input" class="input input--search" data-field="cat-search" value="${escapeHtml(ui.search || "")}"
            placeholder="Buscar categoria ou subcategoria" autocomplete="off" />
          ${ui.search ? `<button class="icon-btn icon-btn--muted cat-search__clear" data-action="cat-search-clear" aria-label="Limpar busca">${svgIcon("x", 14)}</button>` : ""}
        </div>
        <button class="btn btn--primary cat-toolbar__new" data-action="cat-editor-open">${svgIcon("plus", 16)} Nova categoria</button>
      </div>
      <div class="segmented cat-toolbar__views" role="tablist" aria-label="Modo de visualização das categorias">
        ${CATEGORY_VIEWS.map((v) => `<button class="segmented__option ${view === v.id ? "active" : ""}" role="tab" aria-selected="${view === v.id ? "true" : "false"}" data-action="cat-view" data-value="${v.id}">${svgIcon(v.icon, 14)} ${v.label}</button>`).join("")}
      </div>
      <p class="field-hint">${escapeHtml(CATEGORY_VIEW_HINTS[view])}</p>
    </div>

    ${view === "tree" ? renderCategoryTreeView(model) : ""}
    ${view === "groups" ? renderCategoryGroupsView(model) : ""}
    ${view === "budgets" ? renderCategoryBudgetsView(model) : ""}

    <p class="footnote">O gasto de uma subcategoria conta para o teto da categoria principal. Excluir uma categoria não apaga lançamentos: eles são movidos para “Outros”.</p>
  </div>`;
}

const CATEGORY_VIEW_HINTS = {
  tree: "Toque em qualquer categoria para editar nome, ícone, cor, grupo, teto ou mudar de categoria principal.",
  groups: "É esta divisão que alimenta a Regra x/x/x do Início. Toque numa categoria para trocá-la de grupo.",
  budgets: "Digite o limite do mês e saia do campo; o valor salva sozinho. Campo vazio significa sem limite.",
};

function renderCategoriesOverviewCard(model) {
  const totals = model.totals;
  const monthName = MONTH_NAMES[new Date().getMonth()].toLowerCase();
  const segments = BUDGET_GROUPS.map((group) => ({
    group,
    value: model.groupSpend[group],
    pct: totals.spent > 0 ? safePct(model.groupSpend[group], totals.spent) : 0,
  }));

  return `<div class="card cat-overview">
    <p class="card-title" data-ui-css="margin-bottom:4px">Como seus gastos estão organizados</p>
    <p class="card-subtitle">${plural(totals.parents, "categoria principal", "categorias principais")} e ${plural(totals.children, "subcategoria", "subcategorias")}, com ${fmtBRL(totals.spent)} classificados em ${escapeHtml(monthName)}.</p>

    ${totals.spent > 0 ? `<div class="segment-bar cat-overview__bar" role="img" aria-label="Divisão dos gastos do mês entre necessidades, desejos e futuro">
      ${segments.filter((s) => s.pct > 0).map((s) => `<span class="cat-overview__seg cat-overview__seg--${s.group}" data-ui-css="width:${s.pct}%"></span>`).join("")}
    </div>
    <div class="cat-overview__legend">
      ${segments.map((s) => `<span class="cat-overview__legend-item">
        <i class="cat-overview__dot cat-overview__dot--${s.group}" aria-hidden="true"></i>
        <b>${GROUP_LABELS[s.group]}</b>
        <small>${fmtBRL(s.value)} · ${Math.round(s.pct)}%</small>
      </span>`).join("")}
    </div>` : `<p class="field-hint">Nenhum gasto lançado neste mês ainda. A divisão por grupo aparece assim que o primeiro entrar.</p>`}

    <div class="cat-overview__stats">
      <div><span>Com teto definido</span><b>${totals.withBudget} de ${totals.total}</b></div>
      <div><span>Estouradas no mês</span><b class="${totals.over > 0 ? "is-over" : ""}">${totals.over}</b></div>
      <div><span>Grupos em uso</span><b>${BUDGET_GROUPS.filter((g) => model.byGroup[g].length > 0).length} de 3</b></div>
    </div>
  </div>`;
}

// ---------------------------------------------------------------- Lente 1: estrutura
function renderCategoryTreeView(model) {
  const nodes = model.nodes.filter((node) => node.visible);
  if (nodes.length === 0) {
    return `<div class="card">${renderEmptyState("search", "Nenhuma categoria com esse nome.", "Tente um termo mais curto ou crie uma categoria nova.")}</div>`;
  }
  return `<div class="card cat-tree">
    ${nodes.map((node) => renderCategoryNode(model, node)).join("")}
  </div>`;
}

function renderCategoryNode(model, node) {
  const open = isCategoryNodeOpen(model, node.id);
  const hasChildren = node.children.length > 0;
  const children = model.query ? node.visibleChildren : node.children;

  return `<div class="cat-node ${open ? "is-open" : ""}">
    <div class="cat-node__head">
      <button class="cat-node__main" data-action="cat-editor-open" data-id="${node.id}" aria-label="Editar categoria ${escapeHtml(node.name)}">
        <span class="icon-bubble" data-ui-css="${categoryBubbleCss(node.color)}">${svgIcon(node.icon, 18)}</span>
        <span class="cat-node__text">
          <span class="cat-node__name">${escapeHtml(node.name)}</span>
          <span class="cat-node__meta">
            ${categoryGroupTag(node.group)}
            ${hasChildren ? `<span class="cat-node__count">${node.children.length} subcategoria${node.children.length > 1 ? "s" : ""}</span>` : ""}
          </span>
        </span>
        <span class="cat-node__values">
          <b>${fmtBRL(node.spent)}</b>
          <small>${node.budget ? `de ${fmtBRL(node.budget)}` : "sem teto"}</small>
        </span>
      </button>
      ${hasChildren
        ? `<button class="cat-node__toggle" data-action="cat-toggle" data-id="${node.id}" aria-expanded="${open ? "true" : "false"}" aria-label="${open ? "Recolher" : "Expandir"} as subcategorias de ${escapeHtml(node.name)}">${svgIcon("chevronDown", 16)}</button>`
        : `<button class="cat-node__toggle cat-node__toggle--add" data-action="cat-editor-open" data-parent="${node.id}" aria-label="Criar subcategoria em ${escapeHtml(node.name)}">${svgIcon("plus", 16)}</button>`}
    </div>

    ${renderCategoryBudgetBar(node)}

    ${open && hasChildren ? `<div class="cat-node__children">
      ${children.map((child) => renderCategoryChildRow(child)).join("")}
      <button class="cat-node__add" data-action="cat-editor-open" data-parent="${node.id}">
        ${svgIcon("plus", 14)} Nova subcategoria em ${escapeHtml(node.name)}
      </button>
    </div>` : ""}
  </div>`;
}

function renderCategoryChildRow(child) {
  return `<button class="cat-child" data-action="cat-editor-open" data-id="${child.id}" aria-label="Editar subcategoria ${escapeHtml(child.name)}">
    <span class="cat-child__rail" aria-hidden="true"></span>
    <span class="icon-bubble icon-bubble--sm" data-ui-css="${categoryBubbleCss(child.color)}">${svgIcon(child.icon, 15)}</span>
    <span class="cat-child__text">
      <span class="cat-child__name">${escapeHtml(child.name)}</span>
      <span class="cat-child__meta">${categoryGroupTag(child.group)}${child.budget ? `<span class="cat-child__budget">teto ${fmtBRL(child.budget)}</span>` : ""}</span>
    </span>
    <span class="cat-child__value ${child.level === "over" ? "is-over" : ""}">${fmtBRL(child.spent)}</span>
  </button>`;
}

function renderCategoryBudgetBar(item) {
  if (!item.budget) return "";
  const meta = item.levelMeta || BUDGET_LEVEL_META.ok;
  return `<div class="cat-bar">
    <div class="progress progress--sm" data-ui-css="margin:0">
      <div class="progress__fill" data-ui-css="width:${clamp(item.pct, 0, 100)}%; background:${meta.color}"></div>
    </div>
    <span class="cat-bar__text" data-ui-css="color:${meta.color}">${Math.round(item.pct)}%</span>
  </div>`;
}

// ---------------------------------------------------------------- Lente 2: grupos
function renderCategoryGroupsView(model) {
  const income = effectiveIncome(state.data, model.monthKey);
  return BUDGET_GROUPS.map((group) => {
    const items = model.byGroup[group].filter((item) => !model.query || normalizeText(item.path).indexOf(model.query) !== -1);
    const spent = model.groupSpend[group];
    const allocated = income > 0 ? groupAllocated(state.data, model.monthKey, group) : 0;
    const pct = allocated > 0 ? safePct(spent, allocated) : 0;
    const over = allocated > 0 && spent > allocated;

    return `<div class="card cat-group-card cat-group-card--${group}">
      <div class="cat-group-card__head">
        <span class="icon-bubble cat-group-card__icon cat-group-card__icon--${group}">${svgIcon(GROUP_ICONS[group], 18)}</span>
        <div class="cat-group-card__text">
          <p class="card-title" data-ui-css="margin:0">${GROUP_LABELS[group]}</p>
          <p class="card-subtitle" data-ui-css="margin:3px 0 0">${plural(items.length, "categoria", "categorias")} · ${fmtBRL(spent)} neste mês</p>
        </div>
        ${allocated > 0 ? `<span class="cat-group-card__pct ${over ? "is-over" : ""}">${Math.round(pct)}%</span>` : ""}
      </div>

      ${allocated > 0 ? `<div class="progress progress--sm" data-ui-css="margin:12px 0 6px">
          <div class="progress__fill" data-ui-css="width:${clamp(pct, 0, 100)}%; background:${over ? "var(--negative)" : "var(--brand)"}"></div>
        </div>
        <p class="field-hint" data-ui-css="margin-top:0">A Regra x/x/x reserva ${fmtBRL(allocated)} por mês (${state.data.budgetSplit[group]}% da renda) para este grupo.</p>`
        : `<p class="field-hint">Informe sua renda em Ajustes para ver quanto a Regra x/x/x reserva para este grupo.</p>`}

      ${items.length > 0 ? `<div class="cat-group-list">
        ${items.map((item) => `<button class="cat-group-row" data-action="cat-editor-open" data-id="${item.id}" aria-label="Editar ${escapeHtml(item.path)}">
          <span class="icon-bubble icon-bubble--sm" data-ui-css="${categoryBubbleCss(item.color)}">${svgIcon(item.icon, 15)}</span>
          <span class="cat-group-row__text">
            <span class="cat-group-row__name">${escapeHtml(item.name)}</span>
            ${item.depth === 1 ? `<span class="cat-group-row__path">${escapeHtml(item.path)}</span>` : ""}
          </span>
          <span class="cat-group-row__value">${fmtBRL(item.spent)}</span>
          ${svgIcon("chevronRight", 14, "cat-group-row__chevron")}
        </button>`).join("")}
      </div>` : `<p class="field-hint" data-ui-css="margin-top:12px">Nenhuma categoria neste grupo${model.query ? " com esse nome" : ""}.</p>`}
    </div>`;
  }).join("");
}

// ---------------------------------------------------------------- Lente 3: tetos
function renderCategoryBudgetsView(model) {
  const items = model.flat.filter((item) => !model.query || normalizeText(item.path).indexOf(model.query) !== -1);
  if (items.length === 0) {
    return `<div class="card">${renderEmptyState("search", "Nenhuma categoria com esse nome.", "Limpe a busca para ver a lista completa.")}</div>`;
  }
  return `${renderBudgetSeedBanner(model)}<div class="card">
    <p class="card-title">Tetos deste mês</p>
    <p class="card-subtitle">Um teto é um limite seu, não um bloqueio: o app avisa quando você se aproxima e quando passa.</p>
    <div class="cat-budget-list">
      ${items.map((item) => renderCategoryBudgetRow(model, item)).join("")}
    </div>
  </div>`;
}

// POR QUE A SEMEADURA TAMBÉM PRECISA MORAR AQUI.
//
// A conclusão do assistente inicial semeia tetos a partir da regra x/x/x, mas
// isso só alcança quem passar por ele daqui para frente. Quem pulou o assistente
// e quem já usava o app antes desta versão continuaria sem teto nenhum, sem
// nunca saber que a regra escolhida sabe calcular um.
//
// O botão fica na lente de tetos porque é para cá que vem quem quer definir um.
// O banner some sozinho quando não há o que sugerir: sem renda declarada, ou com
// todas as categorias principais já com teto próprio.
function renderBudgetSeedBanner(model) {
  // Durante uma busca o usuário está atrás de uma linha específica; um convite
  // sobre as outras nove seria ruído em cima do que ele pediu para ver.
  if (model.query) return "";
  const seeds = seedBudgetsFromSplit(state.data, effectiveIncome(state.data, model.monthKey), state.data.budgetSplit);
  if (seeds.items.length === 0) return "";
  const s = state.data.budgetSplit;
  const total = sumMoney(seeds.items, (item) => item.budget);
  return `<div class="card card--dashed banner-inline">
    ${svgIcon("target", 30, "banner-inline__icon")}
    <div class="banner-inline__text">
      <strong>${seeds.items.length === 1
        ? "1 categoria principal ainda está sem teto"
        : `${seeds.items.length} categorias principais ainda estão sem teto`}</strong>
      <span>A regra ${s.necessidade}/${s.desejo}/${s.futuro} tem ${fmtBRL(total)} para distribuir, a partir da sua renda. Cada linha continua editável depois.</span>
    </div>
    <button class="btn btn--primary btn--sm" data-action="seed-budgets-from-split">Sugerir tetos</button>
  </div>`;
}

function renderCategoryBudgetRow(model, item) {
  const draft = Object.prototype.hasOwnProperty.call(state.categoryBudgetDrafts, item.id)
    ? state.categoryBudgetDrafts[item.id]
    : (item.budget ? item.budget.toFixed(2).replace(".", ",") : "");
  const suggestion = item.budget ? null : suggestBudgetFor(state.data, item.id);
  const meta = item.levelMeta;

  return `<div class="cat-budget-row ${item.depth === 1 ? "cat-budget-row--child" : ""}">
    <div class="cat-budget-row__main">
      <span class="icon-bubble icon-bubble--sm" data-ui-css="${categoryBubbleCss(item.color)}">${svgIcon(item.icon, 15)}</span>
      <div class="cat-budget-row__text">
        <span class="cat-budget-row__name">${escapeHtml(item.name)}</span>
        <span class="cat-budget-row__meta">${item.depth === 1 ? escapeHtml(item.path) : GROUP_LABELS[item.group]} · ${fmtBRL(item.spent)} gastos</span>
      </div>
      <div class="cat-budget-row__input">
        <span>R$</span>
        <input id="cat-budget-input-${item.id}" class="input input--budget" data-field="category-budget" data-id="${item.id}"
          value="${escapeHtml(draft)}" inputmode="decimal" placeholder="sem limite" aria-label="Teto mensal de ${escapeHtml(item.name)}" />
      </div>
    </div>
    ${item.budget ? `<div class="cat-bar">
      <div class="progress progress--sm" data-ui-css="margin:0">
        <div class="progress__fill" data-ui-css="width:${clamp(item.pct, 0, 100)}%; background:${meta.color}"></div>
      </div>
      <span class="cat-bar__text" data-ui-css="color:${meta.color}">${fmtBRL(item.spent)} de ${fmtBRL(item.budget)} · ${Math.round(item.pct)}%</span>
    </div>` : (suggestion ? `<button class="cat-budget-suggest" data-action="apply-budget-suggestion" data-id="${item.id}" data-value="${suggestion}">
      ${svgIcon("sparkles", 12)} Sugerir ${fmtBRL(suggestion)} (média dos últimos meses)
    </button>` : "")}
  </div>`;
}

// ------------------------------------------------------------------------------
// Editor em folha. O mesmo componente cria e edita; é ele que torna possível
// mover uma categoria de pai sem perder o histórico.
// ------------------------------------------------------------------------------
function renderCategoryEditorModal() {
  const draft = state.categoriesUi.editor;
  if (!draft) return "";
  const editing = !!draft.id;
  const existing = editing ? categoryById(state.data, draft.id) : null;
  // Uma categoria com filhas não pode virar filha de outra: o modelo tem um
  // nível só, e aninhar mais esconderia gastos de todos os tetos.
  const childCount = editing ? childCategories(state.data, draft.id).length : 0;
  const canBeChild = childCount === 0;
  const parents = topLevelCategories(state.data).filter((c) => c.id !== draft.id);
  const previewName = draft.name.trim() || (editing ? existing.name : "Nova categoria");
  const parentName = draft.parentId ? categoryById(state.data, draft.parentId).name : "";
  const suggestion = editing && !draft.budget.trim() ? suggestBudgetFor(state.data, draft.id) : null;

  return `<div class="modal-overlay" data-action="cat-editor-close">
    <div class="modal-sheet cat-editor" data-stop-close="1" role="dialog" aria-modal="true" aria-labelledby="cat-editor-title">
      <div class="modal-header">
        <span class="icon-bubble icon-bubble--lg" data-ui-css="${categoryBubbleCss(draft.color, 16)}">${svgIcon(draft.icon, 21)}</span>
        <div>
          <p class="card-title" id="cat-editor-title" data-ui-css="margin:0">${escapeHtml(previewName)}</p>
          <p class="card-subtitle" data-ui-css="margin:3px 0 0">${parentName ? `Subcategoria de ${escapeHtml(parentName)}` : "Categoria principal"} · ${GROUP_LABELS[draft.group]}</p>
        </div>
        <button class="icon-btn" data-action="cat-editor-close" aria-label="Fechar editor de categoria">${svgIcon("x", 16)}</button>
      </div>

      <div class="field">
        <label class="field__label" for="cat-editor-name">Nome</label>
        <input id="cat-editor-name" class="input" data-field="cat-editor-name" value="${escapeHtml(draft.name)}"
          placeholder="Ex: Mercado, Farmácia, Academia" autocomplete="off" maxlength="60" />
      </div>

      <div class="field cat-editor__field">
        <p class="field__label">Onde ela fica</p>
        <div class="cat-parent-picker">
          <button class="cat-parent-option ${!draft.parentId ? "active" : ""}" data-action="cat-editor-set-parent" data-value="">
            ${svgIcon("layout", 15)} Categoria principal
          </button>
          ${canBeChild ? parents.map((parent) => `<button class="cat-parent-option ${draft.parentId === parent.id ? "active" : ""}" data-action="cat-editor-set-parent" data-value="${parent.id}">
            <span class="cat-parent-option__dot" data-ui-css="background:${parent.color}"></span>${escapeHtml(parent.name)}
          </button>`).join("") : ""}
        </div>
        <p class="field-hint">${canBeChild
          ? "Subcategorias somam no teto da principal e continuam aparecendo separadas nas análises."
          : `Esta categoria tem ${plural(childCount, "subcategoria", "subcategorias")}, então ela mesma precisa continuar sendo principal.`}</p>
      </div>

      <div class="field cat-editor__field">
        <p class="field__label">Grupo da Regra x/x/x</p>
        <div class="cat-group-choice">
          ${BUDGET_GROUPS.map((group) => `<button class="cat-group-choice__option ${draft.group === group ? "active" : ""}" data-action="cat-editor-set-group" data-value="${group}" aria-pressed="${draft.group === group ? "true" : "false"}">
            ${svgIcon(GROUP_ICONS[group], 15)}
            <span>${GROUP_LABELS[group]}</span>
          </button>`).join("")}
        </div>
        <p class="field-hint">${escapeHtml(CATEGORY_GROUP_HINTS[draft.group])}</p>
      </div>

      <div class="field cat-editor__field">
        <p class="field__label">Ícone</p>
        <div class="cat-icon-grid">
          ${CATEGORY_ICON_CHOICES.map((icon) => `<button class="cat-icon-option ${draft.icon === icon ? "active" : ""}" data-action="cat-editor-set-icon" data-value="${icon}" aria-label="Usar o ícone ${icon}" aria-pressed="${draft.icon === icon ? "true" : "false"}">${svgIcon(icon, 17)}</button>`).join("")}
        </div>
      </div>

      <div class="field cat-editor__field">
        <p class="field__label">Cor</p>
        <div class="cat-color-row">
          ${CATEGORY_COLOR_CHOICES.map((color) => `<button class="cat-color-option ${draft.color === color ? "active" : ""}" data-ui-css="background:${color}" data-action="cat-editor-set-color" data-value="${color}" aria-label="Usar a cor ${color}" aria-pressed="${draft.color === color ? "true" : "false"}"></button>`).join("")}
        </div>
      </div>

      <div class="field cat-editor__field">
        <label class="field__label" for="cat-editor-budget">Teto mensal (opcional)</label>
        <div class="cat-editor__money">
          <span>R$</span>
          <input id="cat-editor-budget" class="input" data-field="cat-editor-budget" value="${escapeHtml(draft.budget)}"
            inputmode="decimal" placeholder="sem limite" autocomplete="off" />
        </div>
        ${suggestion ? `<button class="cat-budget-suggest" data-action="cat-editor-suggest" data-value="${suggestion}">
          ${svgIcon("sparkles", 12)} Usar ${fmtBRL(suggestion)} (média dos últimos meses)
        </button>` : `<p class="field-hint">Deixe em branco para acompanhar o gasto sem limite definido.</p>`}
      </div>

      ${draft.confirmDelete ? `<div class="cat-editor__danger">
        <p class="cat-editor__danger-title">${svgIcon("alertTriangle", 15)} Excluir “${escapeHtml(existing ? existing.name : previewName)}”?</p>
        <p class="cat-editor__danger-text">${childCount > 0 ? `${plural(childCount, "subcategoria também será excluída", "subcategorias também serão excluídas")}. ` : ""}Os lançamentos não são apagados: eles passam para “Outros”.</p>
        <div class="cat-editor__danger-actions">
          <button class="btn btn--ghost btn--sm" data-action="cat-editor-delete-cancel">Manter categoria</button>
          <button class="btn btn--danger btn--sm" data-action="cat-editor-delete-confirm">${svgIcon("trash", 14)} Excluir mesmo assim</button>
        </div>
      </div>` : ""}

      <div class="cat-editor__actions">
        ${editing && !draft.confirmDelete ? `<button class="btn btn--ghost btn--sm cat-editor__delete" data-action="cat-editor-delete">${svgIcon("trash", 14)} Excluir</button>` : ""}
        <button class="btn btn--secondary" data-action="cat-editor-close">Cancelar</button>
        <button class="btn btn--primary" data-action="cat-editor-save">${svgIcon("check", 15)} ${editing ? "Salvar alterações" : "Criar categoria"}</button>
      </div>
    </div>
  </div>`;
}

const CATEGORY_GROUP_HINTS = {
  necessidade: "Necessidades: o que você pagaria mesmo num mês apertado (moradia, mercado, remédio).",
  desejo: "Desejos: o que melhora a vida mas pode esperar (lazer, delivery, assinatura).",
  futuro: "Futuro: o que sai hoje e volta depois (aporte, reserva, amortização de dívida).",
};

// source: js/screens/settings.js
// js/screens/settings.js. Ajustes: perfil, regra de orçamento, categorias, tetos e backup.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

// ==================================================================
// Feature 1; edição dos percentuais da Regra x/x/x (Necessidades/Desejos/Futuro) em Ajustes.
function renderBudgetSplitSettingsCard() {
  const bs = state.data.budgetSplit;
  const sum = BUDGET_GROUPS.reduce((s, g) => {
    const draft = state.splitDrafts[g];
    const v = draft !== undefined ? (parseInt(draft, 10) || 0) : bs[g];
    return s + v;
  }, 0);
  return `<div class="card">
    <p class="card-title">Regra de orçamento (x/x/x)</p>
    <p class="card-subtitle" data-ui-css="margin-top:0">Defina quanto da sua renda deve ir para cada grupo. Isso alimenta as barras e os alertas automáticos do Dashboard.</p>
    <div class="split-settings-grid">
      ${BUDGET_GROUPS.map((g) => {
        const draft = state.splitDrafts[g];
        const val = draft !== undefined ? draft : String(bs[g]);
        return `<div class="split-settings-field">
          <label class="field__label" for="split-${g}-input">${svgIcon(GROUP_ICONS[g], 13)} ${GROUP_LABELS[g]}</label>
          <div class="income-input-row">
            <input id="split-${g}-input" class="input input--budget" data-field="split-${g}" value="${escapeHtml(val)}" inputmode="numeric" />
            <span class="income-currency">%</span>
          </div>
        </div>`;
      }).join("")}
    </div>
    <p class="footnote" data-ui-css="margin-top:10px; text-align:left">${sum === 100 ? `Soma: ${sum}%; perfeito.` : `Soma atual: ${sum}%. O ideal é somar 100%, mas o app funciona com qualquer combinação.`}</p>
  </div>`;
}

// Configuração da reserva de emergência: qual meta representa a reserva e
// quantos meses de despesa ela deve cobrir. Alimenta o Dashboard e o Score.
function renderEmergencySettingsCard() {
  const goals = state.data.goals || [];
  const r = emergencyFund(state.data);
  return `<div class="card">
    <p class="card-title">Reserva de Emergência</p>
    <p class="card-subtitle">Escolha qual meta representa sua reserva e por quantos meses ela precisa cobrir suas despesas.</p>
    ${goals.length === 0
      ? `<p class="field-hint">Você ainda não tem metas. Crie uma meta chamada “Reserva de emergência” na aba Metas e ela aparecerá aqui.</p>`
      : `<div class="field">
          <label class="field__label" for="emergency-goal-select">Meta usada como reserva</label>
          <select class="input" id="emergency-goal-select" data-action-select="emergency-goal">
            <option value="">Detectar automaticamente pelo nome</option>
            ${goals.map((g) => `<option value="${g.id}" ${state.data.emergencyGoalId === g.id ? "selected" : ""}>${escapeHtml(g.name)}</option>`).join("")}
          </select>
        </div>`}
    <div class="field" data-ui-css="margin-top:12px">
      <label class="field__label" for="emergency-months-input">Meses de despesa que a reserva deve cobrir</label>
      <input id="emergency-months-input" class="input" data-field="emergency-months" type="number" min="1" max="24" step="1" value="${Number(state.data.emergencyMonths) || 6}" />
    </div>
    <p class="field-hint">Hoje sua despesa média é de ${fmtBRL(r.monthlyNeed)}/mês; o alvo sugerido é ${fmtBRL(mulMoney(r.monthlyNeed, r.targetMonths))}.</p>
  </div>`;
}

// [M5] Premissas de mercado usadas por todos os simuladores.
// O app é offline: não existe cotação em tempo real, e fingir que existe seria
// pior do que não ter. Aqui o usuário revisa os números e o app carimba a data
//; todo simulador mostra de onde veio a taxa que usou.
function renderMarketRatesCard() {
  const r = marketRatesOf(state.data);
  const draft = (key) => (state.ratesDraft[key] != null ? state.ratesDraft[key] : String(r[key]).replace(".", ","));
  const rows = [
    { key: "selic", label: "Selic", hint: "Taxa básica de juros ao ano." },
    { key: "cdi", label: "CDI", hint: "Referência da renda fixa. Costuma ficar levemente abaixo da Selic." },
    { key: "ipca", label: "IPCA", hint: "Inflação anual esperada. É o que separa ganho nominal de ganho real." },
    { key: "tr", label: "TR", hint: "Entra na poupança e no rendimento do FGTS." },
  ];

  return `<div class="card">
    <div class="settings-row-header">
      <div>
        <p class="card-title" data-ui-css="margin:0">Premissas de mercado</p>
        <p class="card-subtitle" data-ui-css="margin:2px 0 0">Valores editáveis usados pelos simuladores e pela comparação da carteira.</p>
      </div>
      <button class="btn btn--ghost btn--sm" data-action="rates-reset">Restaurar</button>
    </div>
    <div class="rates-grid">
      ${rows.map((row) => `<div class="field" data-ui-css="margin:0">
        <label class="field__label" for="rate-${row.key}-input">${escapeHtml(row.label)}</label>
        <div class="sim-input">
          <input id="rate-${row.key}-input" class="input" data-field="market-rate" data-id="${row.key}"
            value="${escapeHtml(draft(row.key))}" inputmode="decimal" autocomplete="off" />
          <span class="sim-input__affix">% a.a.</span>
        </div>
        <p class="field-hint">${escapeHtml(row.hint)}</p>
      </div>`).join("")}
    </div>
    <div class="rates-derived">
      <span>Poupança (derivada da Selic pela regra oficial)</span>
      <b>${fmtNum(r.poupanca)}% a.a.</b>
    </div>
    <p class="card-subtitle" data-ui-css="margin-top:8px">${r.updatedAt
      ? `Revisadas por você em ${fmtDateFull(r.updatedAt)}.`
      : "Exemplos iniciais, não cotações atuais. Revise os quatro valores antes de usar uma simulação para decidir."}</p>
    <div class="source-links" aria-label="Fontes oficiais das premissas">
      <a href="https://www.bcb.gov.br/controleinflacao/taxaselic" target="_blank" rel="noopener noreferrer">Selic e CDI no Banco Central</a>
      <a href="https://www.ibge.gov.br/explica/inflacao.php" target="_blank" rel="noopener noreferrer">IPCA no IBGE</a>
    </div>
  </div>`;
}

// ==================================================================
// AJUSTES EM TÓPICOS
// ==================================================================
// A tela tinha onze cartões abertos ao mesmo tempo, e achar "alertas de
// orçamento" no meio disso exigia rolar passando por categorias, backup e
// premissas de mercado. Agora cada assunto é um tópico fechado, e só um fica
// aberto por vez.
//
// A linha fechada NÃO é só um título: ela mostra o valor atual do ajuste
// (a regra em vigor, quantas categorias têm teto, quando foi o último backup).
// Sem isso o usuário teria de abrir cada tópico só para lembrar como está, e a
// tela ficaria mais lenta de ler do que a lista antiga.
//
// O estado do acordeão mora em `state.settingsSection` porque `render()`
// reconstrói o DOM inteiro; um `<details>` nativo perderia o aberto/fechado a
// cada tecla digitada em qualquer campo da tela.

function renderProfileSettingsCard() {
  const nameVal = state.userNameInput !== null ? state.userNameInput : (state.data.userName || "");
  return `<div class="card">
    <p class="card-title">Seu Perfil</p>
    <div class="field">
      <label class="field__label" for="user-name-input">Como devo te chamar?</label>
      <input id="user-name-input" class="input" data-field="user-name" value="${escapeHtml(String(nameVal))}" placeholder="Seu nome" autocomplete="off" maxlength="40" />
    </div>
    <p class="card-subtitle" data-ui-css="margin-top:8px">Usado apenas na saudação do início. Fica salvo só neste aparelho.</p>
    <button class="btn btn--secondary btn--block btn--sm" data-action="onb-restart" data-ui-css="margin-top:12px">
      ${svgIcon("refresh", 15)} Refazer a configuração inicial
    </button>
    <p class="card-subtitle" data-ui-css="margin-top:8px">Revisa nome, renda, conta principal e regra de orçamento nos mesmos 4 passos do primeiro uso. Nada é apagado.</p>
  </div>`;
}

function renderIncomeSettingsCard() {
  const incomeVal = state.incomeInput !== null ? state.incomeInput : (state.data.monthlyIncome ? state.data.monthlyIncome.toFixed(2).replace(".", ",") : "");
  return `<div class="card">
    <p class="card-title">Renda mensal fixa</p>
    <div class="income-input-row">
      <span class="income-currency">R$</span>
      <input id="income-input" class="input income-input" data-field="income" value="${escapeHtml(String(incomeVal))}" inputmode="decimal" placeholder="0,00" autocomplete="off" />
    </div>
    <p class="card-subtitle" data-ui-css="margin-top:8px">Usada para calcular sua saúde financeira mensal. Salva automaticamente ao sair do campo.</p>
  </div>`;
}

function renderCreditLimitSettingsCard() {
  const creditLimitVal = state.creditLimitInput !== null ? state.creditLimitInput : (state.data.creditCardLimit ? state.data.creditCardLimit.toFixed(2).replace(".", ",") : "");
  return `<div class="card">
    <p class="card-title">Limite desejado para a fatura do cartão</p>
    <div class="income-input-row">
      <span class="income-currency">R$</span>
      <input id="credit-limit-input" class="input income-input" data-field="credit-limit" value="${escapeHtml(String(creditLimitVal))}" inputmode="decimal" placeholder="0,00" autocomplete="off" />
    </div>
    <p class="card-subtitle" data-ui-css="margin-top:8px">Um teto próprio (não o limite do banco) pra acompanhar no Dashboard o quanto já comprometeu no crédito este mês.</p>
  </div>`;
}

function renderAppearanceSettingsCard() {
  const escuro = state.data.theme === "dark";
  const conquistas = !!(state.data.achievements && state.data.achievements.enabled);
  return `<div class="card">
    <button class="theme-toggle" data-action="toggle-theme" role="switch" aria-checked="${escuro ? "true" : "false"}">
      ${svgIcon(escuro ? "moon" : "sun", 17)}
      <span>Modo ${escuro ? "escuro" : "claro"}</span>
      <span class="switch ${escuro ? "active" : ""}" aria-hidden="true"><span class="switch__knob"></span></span>
    </button>
    <button class="theme-toggle" data-action="toggle-gamification" role="switch" aria-checked="${conquistas ? "true" : "false"}">
      ${svgIcon("star", 17)}
      <span><b>Conquistas e níveis</b><small>Opcional. Fica fora do Início até você ativar.</small></span>
      <span class="switch ${conquistas ? "active" : ""}" aria-hidden="true"><span class="switch__knob"></span></span>
    </button>
  </div>`;
}

// Cada tópico traz `resumo()`, que é lido com a seção FECHADA. Deve caber numa
// linha e responder "como está isso hoje" sem abrir nada.
const SETTINGS_SECTIONS = [
  {
    id: "perfil",
    icon: "briefcase",
    label: "Perfil e renda",
    resumo() {
      const nome = String(state.data.userName || "").trim();
      const renda = Number(state.data.monthlyIncome) || 0;
      return `${nome || "Sem nome"} · ${renda > 0 ? `${fmtBRLShort(renda)} por mês` : "renda não informada"}`;
    },
    render: () => `${renderProfileSettingsCard()}${renderIncomeSettingsCard()}`,
  },
  {
    id: "orcamento",
    icon: "pie",
    label: "Orçamento e alertas",
    resumo() {
      const bs = state.data.budgetSplit;
      const alerts = state.data.budgetAlerts || defaultBudgetAlerts();
      return `Regra ${bs.necessidade}/${bs.desejo}/${bs.futuro} · aviso em ${alerts.warn}%`;
    },
    render: () => `${renderBudgetSplitSettingsCard()}${renderBudgetSettingsCard()}${renderCreditLimitSettingsCard()}`,
  },
  // Categoria NÃO é um tópico daqui. Ela ganhou tela própria (`#/categorias`),
  // e o cartão de resumo abaixo dos tópicos é o caminho para ela: enfiar um
  // destino dentro de um acordeão seria pedir dois toques para chegar onde
  // antes bastava um.
  {
    id: "reserva",
    icon: "piggy",
    label: "Reserva de emergência",
    resumo() {
      const r = emergencyFund(state.data);
      const meses = `${r.targetMonths} ${r.targetMonths === 1 ? "mês" : "meses"}`;
      if (!r.configured && r.current === 0) return `Alvo de ${meses} · nenhuma meta escolhida`;
      // Percentual em vez dos dois valores: `fmtBRLShort` abrevia acima de dez
      // mil, e "R$ 5.200,00 de R$ 20 mil" na mesma linha lê mal.
      return `${meses} · ${Math.round(r.pct)}% do alvo de ${fmtBRLShort(r.target)}`;
    },
    render: renderEmergencySettingsCard,
  },
  {
    id: "mercado",
    icon: "trendUp",
    label: "Premissas de mercado",
    resumo() {
      const r = marketRatesOf(state.data);
      return `Selic ${fmtNum(r.selic)}% · ${r.updatedAt ? `revisadas em ${fmtDateFull(r.updatedAt)}` : "ainda não revisadas"}`;
    },
    render: renderMarketRatesCard,
  },
  {
    id: "aparencia",
    icon: "sun",
    label: "Aparência",
    resumo() {
      const escuro = state.data.theme === "dark";
      const conquistas = !!(state.data.achievements && state.data.achievements.enabled);
      return `Modo ${escuro ? "escuro" : "claro"} · conquistas ${conquistas ? "ligadas" : "desligadas"}`;
    },
    render: renderAppearanceSettingsCard,
  },
  {
    id: "dados",
    icon: "archive",
    label: "Backup e dados",
    resumo() {
      const last = state.data.lastBackupAt;
      return last ? `Último backup em ${fmtDateFull(last)}` : "Nenhum backup exportado ainda";
    },
    render: renderBackupCard,
  },
];

// A prévia de importação e o erro de backup aparecem depois de o usuário
// escolher um arquivo. Se o tópico estivesse fechado, o resultado da ação dele
// ficaria escondido; então esses dois estados forçam a abertura.
function settingsOpenSection() {
  if (state.backup.preview || state.backup.error) return "dados";
  return state.settingsSection;
}

function renderSettingsTopic(section, aberto) {
  const painelId = `settings-panel-${section.id}`;
  return `<section class="settings-topic${aberto ? " settings-topic--open" : ""}">
    <h2 class="settings-topic__heading">
      <button class="settings-topic__toggle" data-action="settings-section" data-value="${section.id}"
        aria-expanded="${aberto ? "true" : "false"}" aria-controls="${painelId}">
        <span class="settings-topic__icon">${svgIcon(section.icon, 18)}</span>
        <span class="settings-topic__text">
          <span class="settings-topic__label">${escapeHtml(section.label)}</span>
          <span class="settings-topic__summary">${escapeHtml(section.resumo())}</span>
        </span>
        ${svgIcon("chevronDown", 16, "settings-topic__chevron")}
      </button>
    </h2>
    ${aberto ? `<div class="settings-topic__panel" id="${painelId}">${section.render()}</div>` : ""}
  </section>`;
}

function renderSettingsScreen() {
  const aberto = settingsOpenSection();
  return `<div class="screen screen--narrow">
    <h1 class="page-title" data-ui-css="margin-bottom:16px">Ajustes</h1>

    <div class="settings-topics">
      ${SETTINGS_SECTIONS.map((section) => renderSettingsTopic(section, section.id === aberto)).join("")}
    </div>

    ${renderCategoriesSettingsCard()}

    <div class="card">
      <p class="card-title">Ir para outras telas</p>
      <p class="card-subtitle">Navegação, não configuração. Fica sempre visível.</p>
      <div class="tool-links">
        <button class="tool-link tool-link--rich" data-action="nav" data-tab="account">
          <span class="tool-link__icon">${svgIcon("shieldCheck", 17)}</span>
          <span class="tool-link__text"><span class="tool-link__label">Conta e acesso</span><span class="tool-link__desc">Entrar, sincronizar e revisar dispositivos conectados.</span></span>
          ${svgIcon("chevronRight", 15, "tool-link__chevron")}
        </button>
        <button class="tool-link tool-link--rich" data-action="nav" data-tab="all">
          <span class="tool-link__icon">${svgIcon("search", 17)}</span>
          <span class="tool-link__text">
            <span class="tool-link__label">Abrir “Recursos”</span>
            <span class="tool-link__desc">Contas, dívidas, metas, simuladores, importação, patrimônio e o resto.</span>
          </span>
          ${svgIcon("chevronRight", 15, "tool-link__chevron")}
        </button>
        <button class="tool-link tool-link--rich" data-action="nav" data-tab="rules">
          <span class="tool-link__icon">${svgIcon("tag", 17)}</span>
          <span class="tool-link__text">
            <span class="tool-link__label">Regras de categorização</span>
            <span class="tool-link__desc">Ensine o app a classificar sozinho o que vem do extrato.</span>
          </span>
          ${svgIcon("chevronRight", 15, "tool-link__chevron")}
        </button>
        <button class="tool-link tool-link--rich" data-action="nav" data-tab="privacy">
          <span class="tool-link__icon">${svgIcon("shieldCheck", 17)}</span>
          <span class="tool-link__text">
            <span class="tool-link__label">Privacidade, termos e fontes</span>
            <span class="tool-link__desc">Envios para IA, exportação, exclusão, limites financeiros e diagnóstico local.</span>
          </span>
          ${svgIcon("chevronRight", 15, "tool-link__chevron")}
        </button>
      </div>
    </div>

    <p class="footnote">Seus dados ficam salvos neste navegador/dispositivo (${escapeHtml(FinanceStore.adapterName())}). Use o backup em JSON para levá-los para outro aparelho.</p>
  </div>`;
}

// Ajustes não edita mais categoria; ele resume o estado atual e entrega a tela
// que edita. Manter as duas coisas era o que fazia esta tela crescer sem parar.
//
// O cartão é um botão inteiro, não um cartão com um link dentro. Ele não tem
// nada para configurar aqui: só anuncia um destino. Pedir um segundo toque num
// alvo pequeno depois de já ter lido o resumo era desenho de página de índice,
// não de app. A moldura e o medalhão são os mesmos do tópico logo acima, para
// que a coisa pertença à pilha em vez de flutuar solta no meio dela.
function renderCategoriesSettingsCard() {
  const cats = state.data.categories || [];
  const parents = topLevelCategories(state.data).length;
  const subs = Math.max(0, cats.length - parents);
  // Mesma leitura do cartão de alertas logo acima: uma varredura do mês, sobre
  // o índice já montado por `dataIndex`. Barata o bastante para uma tela de
  // configuração, e evita repetir aqui a regra de quem estourou.
  const status = computeBudgetStatus(state.data, keyOfCurrentMonth());
  const comTeto = status.counts.total;
  const estouradas = status.counts.over;
  const bs = state.data.budgetSplit;

  const stat = (label, valor, alerta) => `<span class="settings-destination__stat${alerta ? " settings-destination__stat--alert" : ""}">
        <span class="settings-destination__stat-label">${label}</span>
        <b class="settings-destination__stat-value">${valor}</b>
      </span>`;

  // O rodapé responde "e daí?": a linha muda conforme o estado, porque
  // "0 estouradas" quer dizer coisas opostas com e sem teto definido.
  const rodape = estouradas > 0
    ? `${plural(estouradas, "categoria passou", "categorias passaram")} do teto neste mês.`
    : comTeto > 0
      ? "Nenhum teto estourado neste mês."
      : "Nenhum teto definido ainda; a central é onde se cria o primeiro.";

  return `<button class="settings-destination" data-action="nav" data-tab="categories">
    <span class="settings-destination__head">
      <span class="settings-destination__icon">${svgIcon("tag", 18)}</span>
      <span class="settings-destination__text">
        <span class="settings-destination__title">Categorias e Tetos</span>
        <span class="settings-destination__sub">Hierarquia, grupos da Regra ${bs.necessidade}/${bs.desejo}/${bs.futuro} e tetos numa tela só.</span>
      </span>
      ${svgIcon("chevronRight", 16, "settings-destination__chevron")}
    </span>
    <span class="settings-destination__stats">
      ${stat("Principais", parents, false)}
      ${stat("Subcategorias", subs, false)}
      ${stat("Com teto", `${comTeto}<small> de ${cats.length}</small>`, false)}
      ${stat("Estouradas", estouradas, estouradas > 0)}
    </span>
    <span class="settings-destination__foot">${rodape}</span>
  </button>`;
}

// Ajustes: faixas de alerta + visão geral do mês.

function renderBudgetSettingsCard() {
  const status = computeBudgetStatus(state.data, keyOfCurrentMonth());
  const alerts = state.data.budgetAlerts || defaultBudgetAlerts();
  return `<div class="card">
    <p class="card-title">Alertas de orçamento</p>
    <p class="card-subtitle" data-ui-css="margin-top:0">Em que ponto do teto de cada categoria eu devo te avisar. O primeiro aviso é preventivo; o segundo marca o estouro.</p>
    <div class="split-settings-grid">
      <div class="split-settings-field">
        <label class="field__label" for="budget-warn-input">${svgIcon("alertTriangle", 13)} Atenção</label>
        <div class="income-input-row">
          <input id="budget-warn-input" type="number" min="1" max="200" class="input input--budget" data-field="budget-warn" value="${alerts.warn}" inputmode="numeric" />
          <span class="income-currency">%</span>
        </div>
      </div>
      <div class="split-settings-field">
        <label class="field__label" for="budget-over-input">${svgIcon("x", 13)} Estouro</label>
        <div class="income-input-row">
          <input id="budget-over-input" type="number" min="1" max="300" class="input input--budget" data-field="budget-over" value="${alerts.over}" inputmode="numeric" />
          <span class="income-currency">%</span>
        </div>
      </div>
    </div>
    ${status.items.length > 0 ? `<p class="footnote" data-ui-css="text-align:left; margin-top:10px">
      ${plural(status.counts.total, "Categoria com Teto", "Categorias com Teto")} · ${status.counts.warn} em atenção · ${status.counts.over} ${pluralWord(status.counts.over, "estourada", "estouradas")} neste mês.
    </p>` : `<p class="footnote" data-ui-css="text-align:left; margin-top:10px">Nenhum teto definido ainda; abra a central de categorias, logo abaixo, para criar o primeiro.</p>`}
  </div>`;
}

// ==================================================================
// FEATURE 2. BACKUP: cartão de Ajustes
// ==================================================================
function renderBackupCard() {
  const b = state.backup;
  const counts = {
    tx: state.data.transactions.length,
    cat: state.data.categories.length,
    goals: state.data.goals.length,
  };

  if (b.preview) return renderBackupPreview(b);

  return `<div class="card">
    <p class="card-title">Backup e restauração</p>
    <p class="card-subtitle">Seus dados vivem só neste aparelho. Exporte de tempos em tempos; é a única cópia que existe.</p>

    <div class="backup-summary">
      <div><span>Lançamentos</span><b>${counts.tx}</b></div>
      <div><span>Categorias</span><b>${counts.cat}</b></div>
      <div><span>Metas</span><b>${counts.goals}</b></div>
    </div>

    <p class="field__label" data-ui-css="margin-top:14px">Exportar</p>
    <div class="settings-actions">
      <button class="btn btn--primary btn--sm" data-action="export-json">${svgIcon("download", 15)} Backup completo (JSON)</button>
      <button class="btn btn--secondary btn--sm" data-action="export-csv">${svgIcon("download", 15)} Lançamentos (CSV)</button>
      <button class="btn btn--secondary btn--sm" data-action="export-statement-pdf">${svgIcon("download", 15)} Extrato (PDF)</button>
      <button class="btn btn--secondary btn--sm" data-action="export-budgets-csv">${svgIcon("download", 15)} Orçamentos (CSV)</button>
    </div>
    <p class="field-hint">O JSON guarda tudo (lançamentos, categorias, tetos, metas e ajustes) e é o que restaura o app por completo. O CSV serve para abrir no Excel ou no Google Sheets. O PDF é o extrato pronto para imprimir ou enviar, com o período e os filtros escolhidos em Movimentações (por padrão, o mês atual).</p>
    ${renderLastBackupLine()}

    <p class="field__label" data-ui-css="margin-top:14px">Importar</p>
    ${b.error ? `<div class="inline-error">
      ${svgIcon("alertTriangle", 16)}
      <div><p class="inline-error__title">${escapeHtml(b.error)}</p><p class="inline-error__detail">Seus dados atuais continuam intactos.</p></div>
      <button class="icon-btn icon-btn--muted" data-action="backup-cancel" aria-label="Fechar erro de backup">${svgIcon("x", 14)}</button>
    </div>` : ""}
    <div class="settings-actions">
      <button class="btn btn--secondary btn--sm" data-action="import-json-trigger" ${b.busy ? "disabled" : ""}>
        ${b.busy ? `<span class="spinner"></span>` : svgIcon("upload", 15)} Escolher arquivo de backup
      </button>
      ${b.undoAvailable ? `<button class="btn btn--ghost btn--sm" data-action="backup-undo">${svgIcon("refresh", 15)} Desfazer última restauração</button>` : ""}
    </div>
  </div>`;
}

function renderBackupPreview(b) {
  const p = b.preview;
  const current = state.data.transactions.length;
  const merge = b.mode === "merge";
  // Prévia do resultado da mesclagem; o usuário vê o número final ANTES de decidir.
  const mergedPreview = merge ? mergeBackupInto(state.data, p.data) : null;

  return `<div class="card card--elevated">
    <div class="settings-row-header modal-header">
      <p class="card-title" data-ui-css="margin:0">Confirmar importação</p>
      <button class="icon-btn" data-action="backup-cancel" aria-label="Cancelar importação do backup">${svgIcon("x", 16)}</button>
    </div>
    <p class="card-subtitle">${escapeHtml(p.filename)}${p.meta.exportedAt ? ` · exportado em ${fmtDateFull(p.meta.exportedAt.slice(0, 10))}` : ""}${p.meta.legacy ? " · formato antigo (será convertido)" : ""}</p>

    <div class="backup-summary">
      <div><span>No arquivo</span><b>${p.meta.counts.transactions}</b></div>
      <div><span>Neste aparelho</span><b>${current}</b></div>
      <div><span>Depois</span><b>${merge ? mergedPreview.data.transactions.length : p.meta.counts.transactions}</b></div>
    </div>

    <div class="segmented" data-ui-css="margin-top:14px">
      <button class="segmented__option ${merge ? "active" : ""}" data-action="backup-set-mode" data-value="merge">Mesclar</button>
      <button class="segmented__option ${!merge ? "active" : ""}" data-action="backup-set-mode" data-value="replace">Substituir</button>
    </div>

    <p class="field-hint" data-ui-css="margin-top:10px">${merge
      ? `Mantém tudo o que já existe aqui e acrescenta o que faltar. Lançamentos repetidos são detectados por conteúdo e ignorados. ${plural(mergedPreview.stats.added, "novo", "novos")}, ${mergedPreview.stats.skipped} já ${pluralWord(mergedPreview.stats.skipped, "existente", "existentes")}.`
      : `<b data-ui-css="color:var(--negative)">Apaga tudo o que está neste aparelho</b> e deixa apenas o conteúdo do arquivo. Use quando estiver migrando para um celular novo.`}</p>

    <div class="settings-actions" data-ui-css="margin-top:12px">
      <button class="btn btn--ghost btn--sm" data-action="backup-cancel">Cancelar</button>
      <button class="btn ${merge ? "btn--primary" : "btn--danger"} btn--sm" data-action="backup-confirm" ${b.busy ? "disabled" : ""}>
        ${b.busy ? `<span class="spinner"></span>` : svgIcon("check", 15)} ${merge ? "Mesclar agora" : "Substituir tudo"}
      </button>
    </div>
  </div>`;
}

// source: js/screens/privacy.js
// js/screens/privacy.js. Privacidade, termos, limites financeiros e diagnóstico.
"use strict";

// Um campo do controlador que ainda não foi definido é mostrado como pendência
// explícita, e não escondido. Esconder daria à política a aparência de pronta.
function renderLegalControllerField(label, value) {
  const pendente = String(value == null ? "" : value).trim() === "" || String(value) === LEGAL_PENDING;
  return `<div><dt>${escapeHtml(label)}</dt><dd class="${pendente ? "legal-pending" : ""}">${pendente ? "Ainda não definido" : escapeHtml(String(value))}</dd></div>`;
}

function renderLegalRetentionGroup(scope, title, note) {
  const itens = LEGAL_RETENTION.filter((item) => item.scope === scope);
  if (!itens.length) return "";
  return `<p class="legal-subhead">${escapeHtml(title)}</p>
    <p class="card-subtitle">${escapeHtml(note)}</p>
    <dl class="legal-list">${itens.map((item) => `<div><dt>${escapeHtml(item.label)}</dt><dd>${escapeHtml(item.term)}</dd></div>`).join("")}</dl>`;
}

function renderPrivacyScreen() {
  const privacy = normalizePrivacy(state.data.privacy || defaultPrivacy());
  const accepted = legalAccepted(privacy);
  const diagnostics = safeErrorSummary();
  const gaps = legalControllerGaps(LEGAL_CONTROLLER);
  const anteriores = privacy.acceptedVersions.filter((item) => item.version !== LEGAL_TEXT_VERSION);
  return `<div class="screen screen--narrow">
    ${renderBackHeader("Privacidade, termos e fontes")}

    <div class="card legal-status ${accepted ? "legal-status--ok" : "legal-status--pending"}">
      <div class="settings-row-header">
        <div><p class="card-title">Estado dos textos</p><p class="card-subtitle">Versão ${LEGAL_TEXT_VERSION}. Revisão em ${fmtDateFull(LEGAL_REVIEW_DATE)}.</p></div>
        <span class="status-badge">${accepted ? "Aceitos" : "Pendente"}</span>
      </div>
      <p class="card-subtitle">${accepted ? `Aceitos em ${fmtDateFull(String(privacy.acceptedAt).slice(0, 10))}.` : "Nenhum aceite foi presumido para dados que já existiam antes desta versão."}</p>
      ${anteriores.length ? `<p class="card-subtitle">Você já havia aceitado ${anteriores.map((item) => `a versão ${escapeHtml(item.version)} em ${fmtDateFull(String(item.at).slice(0, 10))}`).join("; ")}. O registro fica neste aparelho.</p>` : ""}
      ${accepted ? "" : `<button class="btn btn--primary btn--block" data-action="legal-accept">${svgIcon("checkCircle", 16)} Aceitar política e termos</button>`}
    </div>

    <div class="card">
      <p class="card-title">Quem responde por estes dados</p>
      <p class="card-subtitle">O controlador é quem decide como os dados são tratados e a quem você dirige qualquer pedido (LGPD, art. 5, VI).</p>
      <dl class="legal-list">
        ${renderLegalControllerField("Controlador", LEGAL_CONTROLLER.name)}
        ${renderLegalControllerField("CPF ou CNPJ", LEGAL_CONTROLLER.document)}
        ${renderLegalControllerField("Endereço", LEGAL_CONTROLLER.address)}
        ${renderLegalControllerField("Canal de atendimento", LEGAL_CONTROLLER.supportEmail)}
        ${renderLegalControllerField("Encarregado pelos dados", LEGAL_CONTROLLER.dpoName)}
        ${renderLegalControllerField("Contato do encarregado", LEGAL_CONTROLLER.dpoEmail)}
      </dl>
      <p class="card-subtitle">Prazo de resposta a pedidos do titular: ${LEGAL_CONTROLLER.responseDays} dias (art. 19, II).</p>
      ${gaps.length ? `<div class="financial-notice" role="note">${svgIcon("alertTriangle", 16)}<div><p><b>Identificação incompleta.</b> Falta definir: ${escapeHtml(gaps.join(", "))}. Enquanto isso, esta instalação é versão local em desenvolvimento e não deve ser oferecida ao público.</p><small>Nada aqui foi preenchido por suposição.</small></div></div>` : ""}
    </div>

    <div class="card">
      <p class="card-title">Onde seus dados ficam</p>
      <p class="card-subtitle">Sem conta, lançamentos, contas financeiras, cartões, metas, dívidas, categorias e preferências ficam apenas no armazenamento deste navegador. Com conta ligada, esses mesmos registros passam a ser sincronizados com o servidor para aparecerem em outros aparelhos, junto com email, sessão e identificação dos aparelhos.</p>
      <div class="legal-facts">
        <p>${svgIcon("shieldCheck", 15)} O backup JSON é criado apenas quando você toca em exportar.</p>
        <p>${svgIcon("wifi", 15)} Precisam de rede: a sincronização com conta, a IA e a consulta opcional de nota fiscal ao portal da Sefaz.</p>
        <p>${svgIcon("file", 15)} A tipografia é servida pelo próprio app. Nenhuma fonte, métrica ou script de terceiro carrega junto com a página.</p>
        <p>${svgIcon("phone", 15)} Apagar a conta online (tela Conta e acesso) e apagar os dados deste aparelho são ações separadas. Uma não faz a outra.</p>
      </div>
      <p class="legal-subhead">Quem mais recebe dados</p>
      <dl class="legal-list">
        <div><dt>Hospedagem e banco de dados</dt><dd>Recebem o que você sincroniza quando há conta ligada. Sem conta, não recebem nada.</dd></div>
        <div><dt>Provedor de IA</dt><dd>Recebe o pacote mostrado na prévia, e só depois da sua confirmação. O app não guarda cópia do que foi enviado.</dd></div>
        <div><dt>Portal fiscal da Sefaz</dt><dd>Recebe a chave da nota apenas quando você usa a leitura de QR code.</dd></div>
      </dl>
      <div class="source-links"><a href="https://www.gov.br/anpd/pt-br/assuntos/titular-de-dados-1/direito-dos-titulares" target="_blank" rel="noopener noreferrer">Direitos do titular na ANPD</a><a href="https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm" target="_blank" rel="noopener noreferrer">Lei Geral de Proteção de Dados</a></div>
    </div>

    <div class="card">
      <p class="card-title">Por quanto tempo cada coisa fica</p>
      ${renderLegalRetentionGroup("local", "Neste aparelho", "Você controla diretamente e pode apagar a qualquer momento.")}
      ${renderLegalRetentionGroup("conta", "No servidor, apenas com conta ligada", "Sem conta criada, nada nesta lista existe.")}
    </div>

    <div class="card">
      <p class="card-title">Seus direitos</p>
      <p class="card-subtitle">A LGPD garante os direitos do art. 18, listados abaixo. Onde há botão no app, o botão é o caminho mais rápido; o pedido pelo canal de atendimento continua valendo e é respondido em ${LEGAL_CONTROLLER.responseDays} dias.</p>
      <dl class="legal-list">
        ${LEGAL_SUBJECT_RIGHTS.map((right) => `<div><dt>${escapeHtml(right.title)} <span class="legal-law">${escapeHtml(right.law)}</span></dt><dd>${escapeHtml(right.detail)}${right.selfService ? ` <span class="legal-self">Já disponível no app.</span>` : ""}</dd></div>`).join("")}
      </dl>
    </div>

    <div class="card">
      <p class="card-title">Se houver incidente de segurança</p>
      <p class="card-subtitle">Incidente com risco ou dano relevante a você deve ser comunicado a você e à ANPD em prazo razoável (art. 48). O aviso descreve os dados atingidos, o risco, as medidas tomadas e o que você pode fazer.</p>
      <dl class="legal-list">
        ${renderLegalControllerField("Canal para comunicar ou receber aviso de incidente", LEGAL_CONTROLLER.incidentEmail)}
      </dl>
      <p class="card-subtitle">Encontrou uma falha? Use o mesmo canal. Enquanto a conta não é usada, um incidente no servidor não alcança dados financeiros que nunca saíram do seu aparelho.</p>
      <div class="source-links"><a href="https://www.gov.br/anpd/pt-br/canais_atendimento/agente-de-tratamento/comunicado-de-incidente-de-seguranca-cis" target="_blank" rel="noopener noreferrer">Comunicação de incidente na ANPD</a></div>
    </div>

    <div class="card">
      <p class="card-title">Envio para IA</p>
      <p class="card-subtitle">O padrão é confirmar cada envio. A análise financeira envia totais mensais, nomes de categorias, nomes e valores de metas e regras de orçamento. O refinamento de lançamento envia a frase digitada e os nomes das categorias. Esses pacotes são agregados ou limitados, mas não são chamados de anônimos porque os nomes podem revelar contexto pessoal.</p>
      <button class="theme-toggle" data-action="privacy-ai-mode" data-value="ask" role="radio" aria-checked="${privacy.aiSharing !== "blocked" ? "true" : "false"}">
        ${svgIcon("shieldCheck", 17)}<span><b>Perguntar antes de enviar</b><small>Mostra o conteúdo e pede confirmação em cada uso.</small></span><span class="switch ${privacy.aiSharing !== "blocked" ? "active" : ""}"><span class="switch__knob"></span></span>
      </button>
      <button class="theme-toggle" data-action="privacy-ai-mode" data-value="blocked" role="radio" aria-checked="${privacy.aiSharing === "blocked" ? "true" : "false"}">
        ${svgIcon("x", 17)}<span><b>Bloquear envios para IA</b><small>Os recursos locais continuam funcionando.</small></span><span class="switch ${privacy.aiSharing === "blocked" ? "active" : ""}"><span class="switch__knob"></span></span>
      </button>
      ${privacy.aiSharing === "blocked" ? "" : `
      <p class="legal-subhead">O que sai por padrão</p>
      <p class="card-subtitle">Desmarque o que não deve acompanhar o envio. A prévia mostrada na hora do envio já vem com esta escolha, e pode ser mudada lá também.</p>
      <div class="ai-preview__fields">${Object.entries(AI_HIDEABLE_FIELDS).map(([id, label]) => {
        const incluido = privacy.aiHide.indexOf(id) === -1;
        return `<label class="ai-preview__field">
          <input type="checkbox" data-action-select="privacy-ai-field" data-value="${escapeHtml(id)}" ${incluido ? "checked" : ""} />
          <span><b>${escapeHtml(label)}</b><small>${incluido ? "Vai junto no envio" : (id === "categorias" ? "Sai como Categoria 1, Categoria 2..." : "Removido do pacote")}</small></span>
        </label>`;
      }).join("")}</div>`}
    </div>

    <div class="card">
      <p class="card-title">Seus controles</p>
      <div class="tool-links">
        <button class="tool-link tool-link--rich" data-action="export-json"><span class="tool-link__icon">${svgIcon("download", 17)}</span><span class="tool-link__text"><span class="tool-link__label">Exportar todos os dados</span><span class="tool-link__desc">Cria um backup JSON que você controla.</span></span>${svgIcon("chevronRight", 15, "tool-link__chevron")}</button>
        <button class="tool-link tool-link--rich" data-action="privacy-delete-all"><span class="tool-link__icon">${svgIcon("trash", 17)}</span><span class="tool-link__text"><span class="tool-link__label">Apagar todos os dados deste aparelho</span><span class="tool-link__desc">Remove dados financeiros, preferências, cópias locais de recuperação e diagnósticos.</span></span>${svgIcon("chevronRight", 15, "tool-link__chevron")}</button>
      </div>
    </div>

    <div class="card">
      <p class="card-title">Limites financeiros e jurídicos</p>
      <p class="card-subtitle">O aplicativo organiza informações e produz estimativas educativas. Ele não presta consultoria de valores mobiliários, não conhece seu perfil completo, não oferece crédito, não garante rentabilidade e não confirma direito ou valor de aposentadoria. Propostas, contratos, tributos, regras e taxas oficiais prevalecem sobre os cálculos.</p>
      <div class="source-links">
        <a href="https://www.bcb.gov.br/meubc/faqs/p/cuidados-na-hora-de-contratar-uma-operacao-de-credito" target="_blank" rel="noopener noreferrer">CET e crédito no Banco Central</a>
        <a href="https://www.gov.br/cvm/pt-br/assuntos/educacao/" target="_blank" rel="noopener noreferrer">Educação do investidor na CVM</a>
        <a href="https://www.gov.br/pt-br/servicos/simular-aposentadoria" target="_blank" rel="noopener noreferrer">Simulação oficial no Meu INSS</a>
      </div>
    </div>

    <div class="card">
      <div class="settings-row-header"><div><p class="card-title">Diagnóstico local</p><p class="card-subtitle">${plural(diagnostics.total, "ocorrência", "ocorrências")} nos últimos 30 dias. Limite de 50.</p></div><span class="status-badge">Não enviado</span></div>
      <p class="card-subtitle">O registro contém somente data, área, código controlado, versão, schema e estado de conexão. Mensagens, pilhas, valores, descrições, contas, categorias, metas, arquivos e identificadores não entram.</p>
      <div class="button-row">
        <button class="btn btn--secondary" data-action="diagnostics-export" ${diagnostics.total ? "" : "disabled"}>${svgIcon("download", 15)} Exportar resumo</button>
        <button class="btn btn--ghost" data-action="diagnostics-clear" ${diagnostics.total ? "" : "disabled"}>${svgIcon("trash", 15)} Apagar diagnóstico</button>
      </div>
    </div>

    <div class="card">
      <p class="card-title">Termos de uso</p>
      <div class="legal-copy">
        <p><b>1. O que este aplicativo é.</b> Uma ferramenta de organização financeira pessoal que registra o que você informa e calcula estimativas educativas a partir disso. Ele não é instituição financeira, corretora, consultoria de valores mobiliários, correspondente bancário nem órgão previdenciário.</p>
        <p><b>2. Quem pode usar.</b> Uso pessoal e não comercial, por pessoa capaz de contratar. O aplicativo não é destinado a menores de 18 anos e não coleta dados de crianças ou adolescentes de forma consciente.</p>
        <p><b>3. Sua responsabilidade.</b> Conferir os dados inseridos e as condições reais antes de contratar crédito, investir, resgatar recursos ou tomar decisão previdenciária. Números do app não substituem proposta, contrato, extrato oficial nem simulação do Meu INSS.</p>
        <p><b>4. Backups são seus.</b> O funcionamento local reduz o envio de dados, mas exige que você mantenha backups. Limpar o navegador, trocar de aparelho ou perder o aparelho pode apagar informações sem recuperação. Com conta ligada há cópia no servidor, e ela também depende de a conta continuar existindo.</p>
        <p><b>5. Disponibilidade.</b> Não há garantia de funcionamento ininterrupto, de preservação de dados no servidor nem de prazo de atendimento além do prazo legal de resposta ao titular. Recursos que dependem de rede podem ficar indisponíveis sem aviso.</p>
        <p><b>6. Limite de responsabilidade.</b> O aplicativo é fornecido no estado em que se encontra. Ele não responde por decisão financeira tomada com base nas estimativas, por perda de dados no seu aparelho nem por indisponibilidade de terceiros. Esta cláusula não afasta direitos do consumidor previstos em lei.</p>
        <p><b>7. Uso indevido.</b> É vedado tentar acessar conta alheia, contornar limites de uso, automatizar chamadas às funções do servidor ou usar o aplicativo para atividade ilícita. A conta usada dessa forma pode ser encerrada.</p>
        <p><b>8. Propriedade.</b> O código e o conteúdo do aplicativo pertencem ao seu titular. Os dados financeiros que você registra pertencem a você, e o app não os usa para publicidade, perfilamento comercial, venda a terceiros ou treinamento de modelo.</p>
        <p><b>9. Mudanças nos textos.</b> Alteração de conteúdo sobe a versão do texto e o aceite é pedido de novo. O aceite anterior permanece registrado neste aparelho. Continuar usando sem aceitar mantém o app funcionando localmente, com os envios opcionais desligados.</p>
        <p><b>10. Encerramento.</b> Você pode encerrar quando quiser apagando os dados deste aparelho e, se houver, a conta online. Nenhuma das duas ações exige pedido, aprovação ou espera.</p>
        <p><b>11. Lei e foro.</b> Aplica-se a lei brasileira. O foro é o do domicílio do consumidor, na forma do Código de Defesa do Consumidor.</p>
        <p><b>12. Estado desta instalação.</b> ${gaps.length ? "Enquanto a identificação do controlador e o canal de atendimento não forem definidos, esta instalação deve ser tratada como versão local em desenvolvimento e não deve ser oferecida ao público." : "Identificação do controlador e canal de atendimento definidos."}</p>
      </div>
    </div>
  </div>`;
}

// source: js/screens/account.js
"use strict";

function accountStatusCard() {
  if (state.account.loading) return `<div class="card account-status">${svgIcon("loader", 20)}<div><p class="card-title">Verificando sua conta</p><p class="card-subtitle">Seus dados locais continuam disponíveis.</p></div></div>`;
  if (state.account.configured === false) return `<div class="card account-status">${svgIcon("wifi", 20)}<div><p class="card-title">Modo local ativo</p><p class="card-subtitle">O serviço de contas ainda não foi configurado nesta publicação. O app continua funcionando neste aparelho, sem enviar seus dados.</p></div></div>`;
  return "";
}

function accountGuestForm() {
  const a = state.account;
  const register = a.mode === "register";
  const recover = a.mode === "recover";
  return `<div class="card account-auth-card">
    <p class="eyebrow">Conta opcional</p>
    <h2 class="card-title">${recover ? "Recuperar acesso" : register ? "Criar conta" : "Entrar"}</h2>
    <p class="card-subtitle">${recover ? "Enviaremos um link para o email informado." : "A conta prepara o acesso em outros dispositivos. O uso local continua disponível sem cadastro."}</p>
    <div class="field"><label class="field__label" for="account-email">Email</label><input id="account-email" class="input" type="email" data-field="auth-email" data-validate="email" maxlength="254" value="${escapeHtml(a.form.email)}" autocomplete="email" inputmode="email" /></div>
    ${recover ? "" : `<div class="field"><label class="field__label" for="account-password">Senha</label><input id="account-password" class="input" type="password" data-field="auth-password" minlength="10" maxlength="128" value="${escapeHtml(a.form.password)}" autocomplete="${register ? "new-password" : "current-password"}" /><p class="field-hint">Mínimo de 10 caracteres.</p></div>`}
    <button class="btn btn--primary btn--block" data-action="account-submit" data-value="${recover ? "recover" : (register ? "register" : "login")}" ${a.busy ? "disabled" : ""}>${a.busy ? svgIcon("loader", 16) : svgIcon(register ? "plus" : (recover ? "refresh" : "shieldCheck"), 16)} ${recover ? "Enviar link" : (register ? "Criar conta" : "Entrar")}</button>
    <div class="account-auth-links">
      ${recover ? `<button class="link-btn" data-action="account-mode" data-value="login">Voltar para entrar</button>` : `<button class="link-btn" data-action="account-mode" data-value="${register ? "login" : "register"}">${register ? "Já tenho uma conta" : "Criar uma conta"}</button><button class="link-btn" data-action="account-mode" data-value="recover">Esqueci minha senha</button>`}
    </div>
  </div>`;
}

// Cartão de confirmação pendente.
//
// Ele existe porque não havia saída para o email que não chega: a tela dizia
// "Confira seu email", o email não vinha, e não havia botão nenhum para pedir
// outro. Reenviar exigia cadastrar de novo, o que devolve a mesma resposta
// opaca do servidor e não dispara link nenhum para quem já tem conta.
function accountPendingCard() {
  const a = state.account;
  if (!a.pendingEmail || a.authenticated) return "";
  return `<div class="card account-sync account-pending">
    <div class="account-sync__head">
      <span class="account-sync__icon account-sync__icon--idle">${svgIcon("clock", 18)}</span>
      <div>
        <p class="card-title">Confirmação de email pendente</p>
        <p class="card-subtitle">O link de confirmação vai para ${escapeHtml(a.pendingEmail)}. Enquanto ele não for aberto, esta conta não entra e não sincroniza.</p>
        <p class="field-hint">O link vale 24 horas. Se ele não aparecer, procure na caixa de spam antes de pedir outro.</p>
      </div>
    </div>
    <button class="btn btn--secondary btn--sm" data-action="account-resend" ${a.busy ? "disabled" : ""}>${svgIcon("refresh", 15)} Reenviar confirmação</button>
  </div>`;
}

function accountDeviceDate(value) {
  const date = new Date(value || "");
  return Number.isNaN(date.getTime()) ? "data indisponível" : date.toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" });
}

const ACCOUNT_DEVICE_ICONS = {
  desktop: "monitor",
  phone: "phone",
  tablet: "tablet",
  unknown: "globe",
};

function accountDeviceType(device) {
  const informed = String((device && (device.type || device.deviceType)) || "").toLowerCase();
  if (ACCOUNT_DEVICE_ICONS[informed]) return informed;
  const label = String((device && device.label) || "").toLowerCase();
  if (/ipad|tablet/.test(label)) return "tablet";
  if (/iphone|android|celular|mobile/.test(label)) return "phone";
  if (/windows|macos|mac os|linux|chrome os|desktop|notebook/.test(label)) return "desktop";
  return "unknown";
}

function accountDeviceLastSeen(value, current) {
  if (current) return "Ativo agora";
  const date = new Date(value || "");
  if (Number.isNaN(date.getTime())) return "Último acesso indisponível";
  const now = new Date();
  const day = new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
  const todayDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const today = todayDate.getTime();
  const yesterdayDate = new Date(todayDate);
  yesterdayDate.setDate(yesterdayDate.getDate() - 1);
  const time = date.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });
  if (day === today) return `Hoje, ${time}`;
  if (day === yesterdayDate.getTime()) return `Ontem, ${time}`;
  return date.toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" });
}

function accountDevicesCard(account) {
  const devices = (Array.isArray(account.devices) ? account.devices : [])
    .filter((device) => !device.revokedAt)
    .sort((a, b) => Number(!!b.current) - Number(!!a.current) || new Date(b.lastSeenAt || 0) - new Date(a.lastSeenAt || 0));
  const activeCount = devices.length;
  const rows = devices.map((device) => {
    const type = accountDeviceType(device);
    const current = !!device.current;
    return `<div class="account-device account-device--${type}${current ? " account-device--current" : ""}">
      <span class="account-device__rail" aria-hidden="true"></span>
      <span class="account-device__icon">${svgIcon(ACCOUNT_DEVICE_ICONS[type], 20)}</span>
      <span class="account-device__body">
        <span class="account-device__identity"><strong>${escapeHtml(device.label || "Navegador não identificado")}</strong>${current ? `<span class="account-device__badge">Este aparelho</span>` : ""}</span>
        <small>${escapeHtml(accountDeviceLastSeen(device.lastSeenAt, current))}</small>
      </span>
      ${current ? "" : `<button class="btn btn--ghost btn--sm account-device__revoke" data-action="account-revoke" data-id="${escapeHtml(device.id)}" ${account.busy ? "disabled" : ""}>Revogar acesso</button>`}
    </div>`;
  }).join("");

  return `<section class="card account-access" aria-labelledby="account-access-title">
    <div class="account-access__header">
      <div class="account-access__heading">
        <p class="eyebrow">Segurança da conta</p>
        <h2 class="card-title" id="account-access-title">Dispositivos com acesso</h2>
        <p class="card-subtitle">Confira onde sua conta está aberta e encerre qualquer acesso que você não reconheça.</p>
      </div>
      <div class="account-access__tools">
        <span class="account-access__count">${escapeHtml(activeCount === 1 ? "1 ativo" : `${activeCount} ativos`)}</span>
        <button class="btn btn--secondary btn--sm account-access__refresh" data-action="account-refresh" ${account.busy ? "disabled" : ""}>${svgIcon("refresh", 15)} Atualizar</button>
      </div>
    </div>
    <div class="account-device-list">${rows || `<p class="account-access__empty">Nenhum dispositivo com acesso.</p>`}</div>
  </section>`;
}

// Estado da sincronização em linguagem de usuário. A regra de escrita aqui é
// não assustar: em toda situação de falha o aparelho continua com tudo, e a
// frase precisa dizer isso, senão a pessoa acha que perdeu o extrato.
const ACCOUNT_SYNC_VIEW = {
  syncing:  { icon: "loader",        title: "Sincronizando",            note: "Enviando e recebendo as alterações deste aparelho." },
  synced:   { icon: "checkCircle",   title: "Tudo sincronizado",        note: "" },
  offline:  { icon: "wifi",          title: "Sem conexão",              note: "As alterações ficam guardadas aqui e sobem assim que a rede voltar." },
  error:    { icon: "alertTriangle", title: "Sincronização com falha",  note: "Seus dados continuam completos neste aparelho." },
  idle:     { icon: "clock",         title: "Alterações pendentes",     note: "O envio acontece sozinho em alguns segundos." },
  disabled: { icon: "info",          title: "Sincronização indisponível", note: "Esta publicação não tem o serviço de sincronização configurado." },
};

function accountSyncCard() {
  if (typeof CloudSync === "undefined") return "";
  const sync = CloudSync.status();
  const phase = sync.phase === "idle" && !sync.pending ? "synced" : sync.phase;
  const view = ACCOUNT_SYNC_VIEW[phase] || ACCOUNT_SYNC_VIEW.idle;
  const quando = sync.lastSyncAt ? accountDeviceDate(sync.lastSyncAt) : null;
  const detalhe = sync.error || view.note;
  // A frase que tranquiliza NÃO pode ocupar o lugar da que explica. Quando o
  // servidor manda o motivo, os dois aparecem: o motivo em cima, a garantia de
  // que nada se perdeu embaixo. Antes, um excluía o outro, e no caso de falha o
  // motivo era exatamente o que sumia.
  const garantia = phase === "error" && sync.error ? view.note : "";
  // O caminho saudável é automático. A ação manual só aparece quando houve
  // uma falha e a pessoa precisa de uma saída imediata além da recuperação do
  // próprio motor.
  const podeTentar = phase === "error";
  // A CONFERÊNCIA COMPLETA É UMA SAÍDA, NÃO UMA ROTINA.
  //
  // O ciclo comum é incremental: o cursor diz até onde este aparelho já leu, e
  // o servidor nunca reenvia o que ficou atrás dele. Quando uma operação escapa
  // (marca recusada, gravação desfeita, aba fechada na hora errada), o aparelho
  // fica atrasado sem ter como perceber, e a conta aparece com saldos
  // diferentes em cada navegador. Este botão é o caminho de volta: relê a conta
  // inteira e reoferece a base inteira. Fica sempre à mão porque a pessoa que
  // precisa dele está justamente vendo uma tela que diz "Tudo sincronizado".
  const podeConferir = phase !== "disabled" && phase !== "syncing";
  return `<div class="card account-sync">
    <div class="account-sync__head">
      <span class="account-sync__icon account-sync__icon--${escapeHtml(phase)}">${svgIcon(view.icon, 18)}</span>
      <div>
        <p class="card-title">${escapeHtml(view.title)}</p>
        ${detalhe ? `<p class="card-subtitle">${escapeHtml(detalhe)}</p>` : ""}
        ${garantia ? `<p class="field-hint">${escapeHtml(garantia)}</p>` : ""}
        ${quando ? `<p class="field-hint">Última sincronização: ${escapeHtml(quando)}</p>` : ""}
        ${phase === "error" && sync.errorCode ? `<p class="field-hint">Código da falha: ${escapeHtml(sync.errorCode)}</p>` : ""}
      </div>
    </div>
    ${podeTentar ? `<button class="btn btn--secondary btn--sm" data-action="account-sync-now">${svgIcon("refresh", 15)} Tentar novamente</button>` : ""}
    ${podeConferir ? `<div class="account-sync__repair">
      <button class="btn btn--secondary btn--sm" data-action="account-reconcile">${svgIcon("refresh", 15)} Conferir a conta inteira</button>
      <p class="field-hint">Use se este aparelho mostrar números diferentes de outro na mesma conta. Ele relê tudo o que está na conta e reapresenta tudo o que está aqui. Nada é apagado dos dois lados: quando o mesmo registro existe nos dois, vence a versão mais recente.</p>
    </div>` : ""}
  </div>`;
}

// Cartão do vínculo entre os dados deste aparelho e a conta.
//
// Ele só mostra CONTAGENS e estado. Nunca a impressão do conteúdo, nunca o UUID
// da conta, nunca o id de um registro: quem está olhando a tela precisa decidir,
// não auditar. E a decisão nunca é gravada por abrir ou fechar o cartão.
function accountLinkParts(resumo) {
  if (!resumo) return "";
  const partes = [];
  if (resumo.transactions) partes.push(plural(resumo.transactions, "lançamento", "lançamentos"));
  if (resumo.accounts) partes.push(plural(resumo.accounts, "conta", "contas"));
  if (resumo.creditCards) partes.push(plural(resumo.creditCards, "cartão", "cartões"));
  if (resumo.accountTransfers) partes.push(plural(resumo.accountTransfers, "transferência", "transferências"));
  if (resumo.cardPayments) partes.push(plural(resumo.cardPayments, "pagamento", "pagamentos"));
  if (resumo.accountAdjustments) partes.push(plural(resumo.accountAdjustments, "conciliação", "conciliações"));
  if (resumo.goals) partes.push(plural(resumo.goals, "meta", "metas"));
  if (resumo.assets) partes.push(plural(resumo.assets, "item de patrimônio", "itens de patrimônio"));
  if (resumo.categories) partes.push(plural(resumo.categories, "categoria personalizada", "categorias personalizadas"));
  if (resumo.monthlyIncome) partes.push("a renda cadastrada");
  const restante = Number(resumo.settings) - (resumo.monthlyIncome ? 1 : 0);
  if (restante > 0) partes.push(plural(restante, "configuração financeira", "configurações financeiras"));
  if (!partes.length) return "";
  if (partes.length === 1) return partes[0];
  return `${partes.slice(0, -1).join(", ")} e ${partes[partes.length - 1]}`;
}

const ACCOUNT_LINK_VIEW = {
  checking: { icon: "loader", title: "Conferindo os dados deste aparelho" },
  linking: { icon: "loader", title: "Vinculando dados deste aparelho" },
  linked: { icon: "checkCircle", title: "Dados deste aparelho vinculados" },
  confirm: { icon: "upload", title: "Trazer os dados deste aparelho?" },
  waiting: { icon: "wifi", title: "Vínculo aguardando conexão" },
  pending: { icon: "alertTriangle", title: "Vínculo pendente" },
  dismissed: { icon: "info", title: "Dados deste aparelho separados da conta" },
};

function accountGuestLinkCard() {
  const link = state.account.guestLink || freshGuestLink();
  const view = ACCOUNT_LINK_VIEW[link.phase];
  // `idle` é ausência de trabalho: nenhum cartão, nenhuma pergunta.
  if (!view) return "";
  const conteudo = accountLinkParts(link.summary);
  const busy = !!link.busy || link.phase === "checking" || link.phase === "linking";

  let corpo = "";
  if (link.phase === "confirm") {
    corpo = `<p class="card-subtitle">Este navegador tem ${escapeHtml(conteudo || "dados salvos sem conta")} guardados fora da conta.${
      link.errorCode === "remote_changed"
        ? " A conta recebeu alterações de outro aparelho enquanto isto era preparado."
        : (String(link.remoteRevision || "0") === "0" ? "" : " A conta já tem conteúdo de outro aparelho.")
    }</p>
    <p class="field-hint">Juntar não substitui nem apaga nada: registros diferentes entram por união e, no mesmo registro, vence a versão mais recente. A cópia deste aparelho continua aqui de qualquer forma.</p>`;
  } else if (link.phase === "linked") {
    const stats = link.stats || null;
    corpo = `<p class="card-subtitle">O conteúdo deste aparelho já faz parte da conta e está no servidor.</p>${
      stats ? `<p class="field-hint">Incorporados: ${escapeHtml(plural(Number(stats.added) || 0, "lançamento", "lançamentos"))}, ${escapeHtml(plural(Number(stats.goals) || 0, "meta", "metas"))}, ${escapeHtml(plural(Number(stats.accounts) || 0, "conta", "contas"))}.</p>` : ""
    }`;
  } else if (link.phase === "dismissed") {
    corpo = `<p class="card-subtitle">Você escolheu manter ${escapeHtml(conteudo || "esses dados")} fora da conta. Nada foi apagado.</p>
      <p class="field-hint">Se mudar de ideia, o vínculo continua disponível aqui.</p>`;
  } else if (link.phase === "waiting") {
    corpo = `<p class="card-subtitle">${escapeHtml(link.error || "Sem conexão para conferir a conta.")}</p>
      <p class="field-hint">Nada é presumido sem saber o que a conta já tem. O vínculo termina quando a rede voltar.</p>`;
  } else if (link.phase === "pending") {
    corpo = `<p class="card-subtitle">${escapeHtml(link.error || "O vínculo não foi concluído.")}</p>
      <p class="field-hint">Seus dados continuam completos nos dois lados. A sincronização não aparece como concluída enquanto isto não terminar.</p>
      ${link.errorCode ? `<p class="field-hint">Código da falha: ${escapeHtml(link.errorCode)}</p>` : ""}`;
  } else {
    corpo = `<p class="card-subtitle">Conferindo o que existe aqui e o que a conta já tem, antes de qualquer envio.</p>`;
  }

  let acoes = "";
  if (link.phase === "confirm") {
    acoes = `<div class="account-link__actions">
      <button class="btn btn--primary btn--sm" data-action="account-link-confirm" ${busy ? "disabled" : ""}>${svgIcon("upload", 15)} Juntar dados</button>
      <button class="btn btn--secondary btn--sm" data-action="account-link-dismiss" ${busy ? "disabled" : ""}>Manter separados</button>
      <button class="link-btn" data-action="account-link-later">Agora não</button>
    </div>`;
  } else if (link.phase === "pending") {
    acoes = `<div class="account-link__actions">
      <button class="btn btn--secondary btn--sm" data-action="account-link-confirm" ${busy ? "disabled" : ""}>${svgIcon("refresh", 15)} Tentar novamente</button>
      <button class="link-btn" data-action="account-link-later">Agora não</button>
    </div>`;
  } else if (link.phase === "dismissed" || link.phase === "waiting") {
    acoes = `<div class="account-link__actions">
      <button class="btn btn--secondary btn--sm" data-action="account-link-review" ${busy ? "disabled" : ""}>Vincular dados deste aparelho</button>
    </div>`;
  }

  return `<div class="card account-sync account-link">
    <div class="account-sync__head">
      <span class="account-sync__icon account-sync__icon--${escapeHtml(link.phase)}">${svgIcon(view.icon, 18)}</span>
      <div>
        <p class="card-title">${escapeHtml(view.title)}</p>
        ${corpo}
      </div>
    </div>
    ${acoes}
  </div>`;
}

function accountSignedIn() {
  const a = state.account;
  return `<div class="card account-profile">
    <div class="account-profile__head"><span class="account-profile__icon">${svgIcon("shieldCheck", 22)}</span><div><p class="eyebrow">Conta conectada</p><h2 class="card-title">${escapeHtml(a.email)}</h2><p class="card-subtitle">A sessão fica em cookie protegido e não entra nos backups financeiros.</p></div></div>
    <button class="btn btn--secondary" data-action="account-logout" ${a.busy ? "disabled" : ""}>Sair desta conta</button>
  </div>
  ${accountSyncCard()}
  ${accountGuestLinkCard()}
  ${a.mode === "password" ? `<div class="card"><p class="card-title">Definir nova senha</p><div class="field"><label class="field__label" for="account-new-password">Nova senha</label><input id="account-new-password" class="input" type="password" data-field="auth-new-password" minlength="10" maxlength="128" value="${escapeHtml(a.form.newPassword)}" autocomplete="new-password" /></div><button class="btn btn--primary" data-action="account-submit" data-value="password" ${a.busy ? "disabled" : ""}>Salvar nova senha</button></div>` : ""}
  ${accountDevicesCard(a)}
  ${accountDangerCard(a)}`;
}

// O ABERTO/FECHADO MORA NO ESTADO, NÃO NO `<details>`.
//
// Este bloco era um `<details>` nativo. Como `render()` refaz o DOM inteiro e a
// própria tela de conta redesenha sozinha (volta periódica da sincronização,
// atualização da lista de aparelhos, qualquer aviso), o painel se fechava no
// meio da digitação da senha. Quem tentava apagar a conta via o formulário
// sumir sem explicação e concluía, com razão, que o botão não funcionava.
function accountDangerCard(a) {
  const aberto = !!state.accountDangerOpen;
  const pronto = a.form.deleteText === "APAGAR CONTA" && a.form.deletePassword.length >= 10;
  return `<section class="card account-danger${aberto ? " account-danger--open" : ""}">
    <button type="button" class="account-danger__summary" data-action="account-danger-toggle" aria-expanded="${aberto ? "true" : "false"}" aria-controls="account-danger-body">
      <span class="account-danger__row">
        <span class="account-danger__icon">${svgIcon("trash", 18)}</span>
        <span class="account-danger__heading"><span class="card-title">Apagar conta e dados</span><span class="card-subtitle">Exclua a conta e os dados guardados no servidor e neste aparelho.</span></span>
        <span class="account-danger__chevron">${svgIcon("chevronDown", 18)}</span>
      </span>
    </button>
    <div class="account-danger__body" id="account-danger-body" ${aberto ? "" : "hidden"}>
      <p class="card-subtitle">A cópia deste aparelho também será apagada. Outros aparelhos perderão o acesso ao servidor, mas manterão o que já estiver salvo neles.</p>
      <div class="field"><label class="field__label" for="account-delete-password">Senha atual</label><input id="account-delete-password" class="input" type="password" data-field="auth-delete-password" maxlength="128" value="${escapeHtml(a.form.deletePassword)}" autocomplete="current-password" /></div>
      <div class="field"><label class="field__label" for="account-delete-text">Digite APAGAR CONTA</label><input id="account-delete-text" class="input" data-field="auth-delete-text" maxlength="20" value="${escapeHtml(a.form.deleteText)}" autocomplete="off" /></div>
      ${a.deleteHint ? `<p class="account-danger__hint" role="alert">${svgIcon("alertTriangle", 15)} ${escapeHtml(a.deleteHint)}</p>` : ""}
      <button class="btn btn--danger" data-action="account-delete-request" ${a.busy ? "disabled" : ""}>Apagar conta e dados</button>
      ${pronto ? "" : `<p class="card-subtitle account-danger__requisito">Preencha a senha da conta (10 caracteres ou mais) e digite APAGAR CONTA para liberar a exclusão. A frase seguinte, na confirmação, também precisa vir em maiúsculas.</p>`}
    </div>
  </section>`;
}

function renderAccountScreen() {
  const status = accountStatusCard();
  return `<div class="screen screen--narrow">${renderBackHeader("Conta e acesso")}${status}
    ${state.account.configured === false || state.account.loading ? "" : accountPendingCard()}
    ${state.account.configured === false || state.account.loading ? "" : (state.account.authenticated ? accountSignedIn() : accountGuestForm())}
    ${state.account.error ? `<div class="form-error-summary" role="alert">${svgIcon("alertTriangle", 16)} ${escapeHtml(state.account.error)}</div>` : ""}
    ${state.account.message ? `<div class="account-message" role="status">${svgIcon("checkCircle", 16)} ${escapeHtml(state.account.message)}</div>` : ""}
    <p class="footnote">Com a conta conectada, seus lançamentos passam a ser sincronizados entre os aparelhos onde você entrar. A fusão é por união: nada é apagado de um lado pelo outro, e o que você excluir continua excluído em todos.</p>
  </div>`;
}

// source: js/screens/modals.js
// js/screens/modals.js. Camadas sobrepostas: seletor de subcategoria, leitor de QR e resumo do mês.
//
// Fatiado de app.js. Carregado como script global (sem módulos ES), então
// todas as funções continuam visíveis para o restante do app.
"use strict";

function renderAssistantLauncher() {
  if (state.contextualAssistant.open || state.calculationDetail || state.confirmation) return "";
  return `<button class="assistant-launcher" data-action="assistant-open" aria-label="Abrir o Assistente financeiro">${svgIcon("sparkles", 20)}<span>Assistente financeiro</span></button>`;
}

function renderContextualAssistantModal() {
  const model = buildContextualAssistant(state.data, state.tab, { simId:state.sim.id });
  const selected = model.items.find((item) => item.id === state.contextualAssistant.responseId);
  return `<div class="modal-overlay" data-action="assistant-close">
    <div class="modal-sheet assistant-dialog" data-stop-close="1" role="dialog" aria-modal="true" aria-labelledby="assistant-title">
      <div class="modal-header"><span class="icon-bubble">${svgIcon("sparkles",18)}</span><div><p class="card-title" id="assistant-title">Assistente financeiro em ${escapeHtml(model.screenLabel)}</p><p class="card-subtitle">Respostas calculadas neste aparelho</p></div><button class="icon-btn" data-action="assistant-close" aria-label="Fechar">${svgIcon("x",16)}</button></div>
      <div class="assistant-questions">${model.items.map((item) => `<button class="assistant-question ${selected && selected.id === item.id ? "is-selected" : ""}" data-action="assistant-question" data-id="${item.id}">${escapeHtml(item.question)}${svgIcon("chevronRight",14)}</button>`).join("")}</div>
      ${selected ? `<div class="assistant-answer" role="status"><p class="field__label">Resposta local</p><p>${escapeHtml(selected.answer)}</p>${selected.action ? `<button class="btn btn--primary btn--sm" data-action="assistant-action" data-id="${selected.id}">${svgIcon(selected.action.kind === "calculation" ? "info" : "arrowRight",14)} ${escapeHtml(selected.action.label)}</button>` : ""}</div>` : `<p class="assistant-hint">Escolha uma pergunta. O Assistente financeiro usa somente os dados que já estão no aplicativo.</p>`}
      <p class="footnote">Este painel não envia dados para uma IA externa. A análise externa, quando usada, continua pedindo sua confirmação.</p>
    </div>
  </div>`;
}

function renderCalculationModal() {
  const detail = state.calculationDetail || { id:"net-worth" };
  let context = {};
  if (detail.id === "forecast") context.forecast = forecastModel();
  if (detail.id === "goals") context.goals = goalsModel();
  if (detail.id === "debts") context.debts = debtsModel();
  if (detail.id === "simulator") {
    const spec = simSpecOf(state.sim.id);
    context = {
      title: `${spec.label}: como foi calculado`,
      premises: (spec.options || []).concat(spec.fields || []).map((field) => `${field.label}: ${simRaw(state.sim.id, field.key)}${field.suffix ? ` ${field.suffix}` : ""}`),
    };
  }
  const explanation = calculationExplanation(state.data, detail.id, context);
  return `<div class="modal-overlay" data-action="calculation-close">
    <div class="modal-sheet calculation-dialog" data-stop-close="1" role="dialog" aria-modal="true" aria-labelledby="calculation-title">
      <div class="modal-header"><span class="icon-bubble">${svgIcon("info",18)}</span><div><p class="card-title" id="calculation-title">${escapeHtml(explanation.title)}</p><p class="card-subtitle">Método, atualização e premissas</p></div><button class="icon-btn" data-action="calculation-close" aria-label="Fechar">${svgIcon("x",16)}</button></div>
      ${renderCalculationKinds(explanation.kinds)}
      <p class="calculation-summary">${escapeHtml(explanation.summary)}</p>
      <dl class="calculation-facts"><div><dt>Atualizado</dt><dd>${escapeHtml(formatMovementTimestamp(explanation.updatedAt))}</dd></div><div><dt>Fórmula</dt><dd>${escapeHtml(explanation.formula)}</dd></div></dl>
      <div class="calculation-premises"><p class="field__label">Premissas utilizadas</p><ul>${explanation.premises.map((premise) => `<li>${escapeHtml(premise)}</li>`).join("")}</ul></div>
      <div class="calculation-legend">${explanation.kinds.map((id) => { const meta = CALCULATION_KIND[id]; return `<p>${svgIcon(meta.icon,13)} <b>${meta.label}:</b> ${escapeHtml(meta.note)}</p>`; }).join("")}</div>
    </div>
  </div>`;
}

function renderConfirmationModal() {
  const c = state.confirmation;
  if (!c) return "";
  return `<div class="modal-overlay confirmation-overlay" data-action="confirmation-cancel">
    <div class="modal-sheet confirmation-dialog" data-stop-close="1" role="alertdialog" aria-modal="true" aria-labelledby="confirmation-title" aria-describedby="confirmation-message">
      <span class="confirmation-dialog__icon ${c.tone === "danger" ? "confirmation-dialog__icon--danger" : ""}" aria-hidden="true">${svgIcon(c.icon, 22)}</span>
      <div class="confirmation-dialog__copy">
        <p class="card-title" id="confirmation-title">${escapeHtml(c.title)}</p>
        <p class="card-subtitle" id="confirmation-message">${escapeHtml(c.message)}</p>
        ${c.requiredText ? `<div class="field" data-ui-css="margin-top:14px">
          <label class="field__label" for="confirmation-required-input">Digite ${escapeHtml(c.requiredText)} para confirmar</label>
          <input id="confirmation-required-input" class="input" data-field="confirmation-required" value="${escapeHtml(c.typedText || "")}" autocomplete="off" data-validate="text" aria-describedby="confirmation-required-help" />
          <p class="field-hint" id="confirmation-required-help">${c.typedText === c.requiredText
            ? "Confirmação conferida."
            : `O botão libera quando o campo tiver exatamente ${escapeHtml(c.requiredText)}.`}</p>
        </div>` : ""}
      </div>
      <div class="confirmation-dialog__actions">
        <button type="button" class="btn btn--ghost" data-action="confirmation-cancel" autofocus>${escapeHtml(c.cancelLabel)}</button>
        ${c.alternateLabel ? `<button type="button" class="btn btn--secondary" data-action="confirmation-alternate">${svgIcon(c.alternateIcon, 15)} ${escapeHtml(c.alternateLabel)}</button>` : ""}
        <button type="button" class="btn ${c.tone === "danger" ? "btn--danger" : "btn--primary"}" data-action="confirmation-accept" ${c.requiredText && c.typedText !== c.requiredText ? "disabled" : ""}>${svgIcon(c.tone === "danger" ? "trash" : "check", 15)} ${escapeHtml(c.confirmLabel)}</button>
      </div>
    </div>
  </div>`;
}

function renderMovementDetailModal() {
  const entry = movementEntries(state.data).find((item) => item.id === state.movementDetailId);
  if (!entry) return "";
  const source = movementSourceMeta(entry.source, entry.origin);
  const actionLabels = { created: "Criado", edited: "Editado", reviewed: "Revisado", converted: "Convertido" };
  const fieldLabels = { type: "tipo", amount: "valor", categoryId: "categoria", date: "data", payment: "pagamento", description: "descrição", recurring: "recorrência", accountId: "conta", creditCardId: "cartão", goalId: "meta", debtId: "dívida" };
  const history = entry.changeLog || [];
  return `<div class="modal-overlay" data-action="movement-detail-close">
    <div class="modal-sheet movement-detail" data-stop-close="1" role="dialog" aria-modal="true" aria-labelledby="movement-detail-title">
      <div class="modal-header"><span class="icon-bubble">${svgIcon(source.icon, 18)}</span><div><p class="card-title" id="movement-detail-title">Origem e histórico</p><p class="card-subtitle">${escapeHtml(entry.description)}</p></div><button class="icon-btn" data-action="movement-detail-close" aria-label="Fechar">${svgIcon("x", 16)}</button></div>
      <dl class="movement-detail__facts"><div><dt>Origem</dt><dd>${escapeHtml(source.label)}</dd></div>${entry.origin && entry.origin.reference ? `<div><dt>Referência</dt><dd>${escapeHtml(entry.origin.reference)}</dd></div>` : ""}<div><dt>Criado em</dt><dd>${escapeHtml(formatMovementTimestamp(entry.createdAt))}</dd></div><div><dt>Atualizado em</dt><dd>${escapeHtml(formatMovementTimestamp(entry.updatedAt))}</dd></div></dl>
      <p class="card-title">Alterações</p>
      ${history.length ? `<ol class="movement-history">${[...history].reverse().map((item) => `<li><span class="movement-history__dot"></span><div><b>${actionLabels[item.action] || "Alterado"}</b><small>${escapeHtml(formatMovementTimestamp(item.at))}${item.fields && item.fields.length ? `, ${escapeHtml(item.fields.map((field) => fieldLabels[field] || "decisão de revisão").join(", "))}` : ""}</small></div></li>`).join("")}</ol>` : renderEmptyState("clock", "Sem alterações registradas")}
    </div>
  </div>`;
}

// UMA DATA PURA NÃO TEM HORA, E NÃO É UTC.
//
// Esta função recebe dois formatos: carimbos completos (`createdAt`,
// `updatedAt`, `changeLog[].at`) e datas puras (`lastMovementAt`, que guarda o
// `date` do lançamento). `new Date("2026-08-20")` é lido como meia-noite UTC e,
// em qualquer fuso brasileiro, volta um dia: o lançamento de 20/08 aparecia
// como "19/08/2026, 21:00". A hora, além de deslocada, era inventada: o campo
// nunca teve hora. Agora data pura é formatada como data, e só carimbo completo
// mostra horário. O meio-dia local preserva o dia em qualquer fuso, inclusive
// nas viradas de horário de verão.
function formatMovementTimestamp(value) {
  const bruto = String(value == null ? "" : value).trim();
  if (!bruto) return "Data não disponível";
  const somenteData = /^\d{4}-\d{2}-\d{2}$/.test(bruto);
  const date = new Date(somenteData ? `${bruto}T12:00:00` : bruto);
  if (Number.isNaN(date.getTime())) return "Data não disponível";
  return somenteData
    ? date.toLocaleDateString("pt-BR", { dateStyle: "short" })
    : date.toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" });
}

function renderReviewCardPaymentModal() {
  const draft = state.movementReviewCard;
  if (!draft || !draft.txId) return "";
  const tx = state.data.transactions.find((item) => item.id === draft.txId);
  if (!tx) return "";
  const accounts = (state.data.accounts || []).filter((account) => !account.archived);
  const cards = (state.data.creditCards || []).filter((card) => !card.archived);
  return `<div class="modal-overlay" data-action="review-card-payment-close">
    <div class="modal-sheet" data-stop-close="1" role="dialog" aria-modal="true" aria-labelledby="review-card-title">
      <div class="modal-header"><span class="icon-bubble">${svgIcon("creditCard", 18)}</span><div><p class="card-title" id="review-card-title">Converter em pagamento de fatura</p><p class="card-subtitle">${escapeHtml(tx.description)}, ${fmtBRL(tx.amount)}</p></div><button class="icon-btn" data-action="review-card-payment-close" aria-label="Fechar">${svgIcon("x", 16)}</button></div>
      ${accounts.length && cards.length ? `<div class="field"><label class="field__label" for="review-payment-account">Conta usada no pagamento</label><select id="review-payment-account" class="input" data-action-select="review-payment-account">${accounts.map((account) => `<option value="${account.id}" ${draft.accountId === account.id ? "selected" : ""}>${escapeHtml(account.name)}</option>`).join("")}</select></div><div class="field"><label class="field__label" for="review-payment-card">Cartão pago</label><select id="review-payment-card" class="input" data-action-select="review-payment-card">${cards.map((card) => `<option value="${card.id}" ${draft.creditCardId === card.id ? "selected" : ""}>${escapeHtml(card.name)}</option>`).join("")}</select></div><p class="health-note">O lançamento importado será substituído pelo pagamento de fatura. As compras no cartão continuam sendo as despesas reais.</p><div class="modal-actions"><button class="btn btn--ghost" data-action="review-card-payment-close">Cancelar</button><button class="btn btn--primary" data-action="review-card-payment-confirm">Converter</button></div>` : `<div class="inline-alert">Cadastre ao menos uma conta e um cartão ativos antes de converter.</div><button class="btn btn--secondary btn--block" data-action="review-card-payment-close">Fechar</button>`}
    </div>
  </div>`;
}

// Modal/dropdown flutuante para escolher a subcategoria de uma categoria principal,
// evitando poluir a tela de lançamento com todas as subcategorias de uma vez.
function renderCategoryPickerModal() {
  const parent = categoryById(state.data, state.categoryPickerFor);
  if (!parent) return "";
  const children = childCategories(state.data, parent.id);
  const f = state.form;
  return `<div class="modal-overlay" data-action="close-category-picker">
    <div class="modal-sheet cat-picker-sheet" role="dialog" aria-modal="true" aria-label="Escolher subcategoria de ${escapeHtml(parent.name)}">
      <div class="cat-picker-header">
        <span class="icon-bubble" data-ui-css="background:color-mix(in srgb, ${parent.color} 14%, transparent); color:${parent.color}">${svgIcon(parent.icon, 18)}</span>
        <div class="cat-picker-header__text">
          <p class="card-title" data-ui-css="margin:0">${escapeHtml(parent.name)}</p>
          <p class="card-subtitle" data-ui-css="margin:2px 0 0">Escolha uma subcategoria</p>
        </div>
        <button class="icon-btn icon-btn--muted" data-action="close-category-picker" aria-label="Fechar">${svgIcon("x", 16)}</button>
      </div>
      <div class="cat-picker-list">
        <button class="cat-picker-option ${f.categoryId === parent.id ? "active" : ""}" data-action="select-category" data-id="${parent.id}">
          <span class="icon-bubble" data-ui-css="background:color-mix(in srgb, ${parent.color} 14%, transparent); color:${parent.color}">${svgIcon(parent.icon, 16)}</span>
          <span>Geral <span class="cat-picker-option__hint">(sem subcategoria)</span></span>
          ${f.categoryId === parent.id ? svgIcon("checkCircle", 16) : ""}
        </button>
        ${children.map((c) => `
          <button class="cat-picker-option ${f.categoryId === c.id ? "active" : ""}" data-action="select-category" data-id="${c.id}">
            <span class="icon-bubble" data-ui-css="background:color-mix(in srgb, ${c.color} 14%, transparent); color:${c.color}">${svgIcon(c.icon, 16)}</span>
            <span>${escapeHtml(c.name)}</span>
            ${f.categoryId === c.id ? svgIcon("checkCircle", 16) : ""}
          </button>`).join("")}
      </div>
    </div>
  </div>`;
}

